/* ÇEVİRİ nl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("nl","olay",{
"OLAYLAR:1299-01:0":{"b": ["Stichting van het Osmaanse beylik", "9f0b7c0a"], "d": ["Het moment waarop Osman Gazi van de Kayı-stam rond Söğüt en Domaniç zelfstandig begon op te treden, geldt traditioneel als het begin van de Osmaanse staat; sommige historici beschouwen de overwinning bij Bapheus in 1302 als het eigenlijke keerpunt. Dankzij zijn ligging aan de Byzantijnse grens groeide het beylik snel in macht door ghazi-strooptochten. In de context van het uiteenvallen van de Seltsjoekse erfenis verzamelde Osman Gazi ahi's, ghazi's en nomadische Turkmenen om zich heen; zijn band met sjeik Edebali wordt beschouwd als de basis van de morele legitimiteit van het beylik. Andere plaatsen die op dezelfde datum werden toegevoegd: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Verovering van Bursa", "98c727fa"], "d": ["Bursa, dat jarenlang geblokkeerd was, gaf zich over aan Orhan Gazi, die de laatste fase van het beleg leidde; de stad werd de eerste grote hoofdstad van het beylik. Volgens de overlevering werd het nieuws van de verovering aan de stervende Osman Gazi gebracht; Osman Gazi werd conform zijn testament in Bursa begraven. De stad werd snel voorzien van moskeeën, imarets en madrasa's en werd het model voor het vroege Osmaanse stedenbouwkundige beleid.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Verovering van İznik", "a846a811"], "d": ["İznik (Nicaea), een van de belangrijkste centra van Byzantium in Anatolië, gaf zich na de overwinning bij Pelekanon in 1329 over aan Orhan Gazi omdat het alle hoop op verzet had verloren. Hier werd de eerste Osmaanse madrasa gesticht en geleerden zoals Dâvûd-i Kayserî begonnen er les te geven; de stad werd het wetenschappelijk centrum van de vroege periode. De Hagia Sophia-kerk werd tot moskee omgevormd, een vroeg voorbeeld van de veroveringstraditie.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Verovering van İzmit", "06a35035"], "d": ["Met de val van İzmit (Nicomedia) kwam ook de laatste belangrijke vesting van Byzantium aan de Anatolische kant onder Osmaans bestuur; het hele schiereiland Kocaeli tot aan de overkant van Constantinopel werd Osmaans grondgebied. Zo beheerste het beylik de gehele zuid- en oostkust van de Zee van Marmara en legde het de basis voor de oversteek naar Rumelië.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Burcht Çimpe — oversteek naar Rumelië", "c2f0a07d"], "d": ["Süleyman Pasja, zoon van Orhan Gazi, had de burcht Çimpe, die hem tijdens de Byzantijnse burgeroorlog was gegeven, in 1352 als basis genomen; na de grote aardbeving die Gallipoli in maart 1354 verwoestte, werden de verlaten vestingen snel versterkt en werd het schiereiland een blijvende Osmaanse bruggenhoofd. Deze stap, ondersteund door de vestiging van uit Anatolië overgebrachte Turkmeense bevolking, vormt het begin van de Osmaanse aanwezigheid op het Europese continent, die meer dan 550 jaar zou duren.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Verovering van Edirne", "2f54ebb0"], "d": ["De inname van Edirne (Adrianopel), de sleutelstad van Thracië, bepaalde de hoofdbasis en de richting van de Balkanveroveringen; de datum van verovering is in de bronnen omstreden tussen 1361 en 1369. De stad werd kort daarna tot hoofdstad gemaakt, wat aankondigde dat het zwaartepunt van de staat naar Rumelië verschoof; het bleef ongeveer 90 jaar lang zetel van het rijk, tot de verovering van Constantinopel.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I besteeg de troon", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), die na de dood van Orhan Gazi de troon besteeg, voerde de staat tijdens zijn regering van 27 jaar van een grensbeylik naar het skelet van een keizerrijk. Met het pençik-systeem werd de basis gelegd voor het Janitsarenkorps, het timar-stelsel werd verbreed, het beylerbeylik van Rumelië werd opgericht en de vizierschap werd versterkt. De Balkanveroveringen werden onder zijn bewind een systematische staatspolitiek.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Eerste Slag bij Kosovo — martelaarschap van Murad I", "10b8ddc9"], "d": ["De Balkanalliantie onder leiding van vorst Lazar werd op het Merelveld (Kosovo Polje) beslissend verslagen; Servië kwam onder Osmaanse opperheerschappij. Murad I, die het slagveld bezocht, werd door de Servische edelman Miloš Obilić met een dolk gedood — hij is de enige Osmaanse sultan die op het slagveld is omgekomen. In het legerkamp werd Yıldırım Bayezid in zijn plaats op de troon gezet; zijn broer Yakub Çelebi werd gewurgd, een van de eerste bekende voorbeelden van de praktijk van broedermoord.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Overwinning bij Nikopolis", "75716e96"], "d": ["Het grote kruisvaardersleger dat op oproep van de Hongaarse koning Sigismund was bijeengekomen, waaraan ook Frans-Bourgondische ridders deelnamen, werd bij Nikopolis aan de Donau door Yıldırım Bayezid zwaar verslagen. De overwinning bevestigde de Osmaanse overheersing over Bulgarije; gedurende een generatie kon er in Europa geen grote kruistocht meer worden georganiseerd.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Slag bij Ankara — begin van het Interregnum", "b4a99d96"], "d": ["In de zware nederlaag tegen het leger van Timur op de vlakte van Çubuk werd Yıldırım Bayezid gevangengenomen en hij stierf enkele maanden later in gevangenschap. Timur liet de Anatolische beyliks herrijzen; het Osmaanse grondgebied werd verdeeld onder de zonen van Bayezid en een 11 jaar durende troonstrijd (het Interregnum, Fetret Devri) begon. Deze periode, de zwaarste crisis sinds de oprichting van de staat, prentte het belang van een gecentraliseerde structuur in het Osmaanse geheugen. Andere plaatsen die op dezelfde datum verloren gingen: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delčev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofia, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Nikopol, Rusçuk, Thessaloniki, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed herstelde de eenheid", "03413dfd"], "d": ["In de laatste afrekening tussen de broers versloeg Mehmed I Mûsâ Çelebi bij Çamurlu en verenigde het grondgebied van het land onder één bestuur; daarom wordt hij beschouwd als de 'tweede stichter van de staat'. Tijdens zijn regering werd de aangetaste staatsstructuur hersteld, werden de betrekkingen met de Anatolische beyliks in evenwicht gebracht en werd in Rumelië een omzichtig vredesbeleid gevoerd.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Opstand van sjeik Bedreddin", "e0a072ca"], "d": ["De religieus-maatschappelijke beweging rond sjeik Bedreddin, een groot jurist en mysticus die tijdens het Interregnum kazasker was geweest, brak gelijktijdig uit met de opstanden van Börklüce Mustafa in Karaburun en Torlak Kemal in Manisa. De opstanden werden bloedig neergeslagen; Bedreddin werd in Deliorman gevangengenomen en in Serres geëxecuteerd. De gebeurtenis liet diepe sporen na in de literatuur en geschiedschrijving als de vroegste grote sociaal-messiaanse opstand in de Osmaanse geschiedenis.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Overwinning bij Varna", "f739eedc"], "d": ["Het Hongaars-Poolse kruisvaardersleger, dat het verdrag van Szeged had verbroken en naar het zuiden was getrokken, werd bij Varna vernietigd door Murad II, die was teruggekeerd aan het hoofd van het leger terwijl hij van de troon had afgezien; de jonge koning Ladislaus III sneuvelde op het slagveld. De overwinning nam de laatste grote kans op buitenlandse interventie om de Osmaanse aanwezigheid op de Balkan te liquideren weg en verzekerde de weg naar de verovering van Constantinopel.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Tweede Slag bij Kosovo", "ebe0b662"], "d": ["Het leger van János Hunyadi, dat wraak wilde nemen voor Varna, werd na een driedaagse verbeten strijd door Murad II beslissend verslagen. Dit is de laatste grote veldslag die de kruisvaarders op de Balkan tegen de Osmanen aangingen; met deze overwinning werd de Osmaanse heerschappij ten zuiden van de Donau onomkeerbaar gevestigd.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Verovering van Constantinopel", "583d5e3e"], "d": ["Na een beleg van vierenvijftig dagen (6 april–29 mei 1453) drong het Osmaanse leger op de ochtend van 29 mei over de muren de stad binnen; de laatste keizer Constantijn XI sneuvelde in de gevechten en het 1100 jaar oude Oost-Romeinse Rijk verdween uit de geschiedenis. De jonge sultan nam de titel 'Fâtih' (de Veroveraar) aan, maakte de stad tot hoofdstad en veranderde de Hagia Sophia in een moskee; de stad werd binnen korte tijd door vestiging en wederopbouw nieuw leven ingeblazen. Volgens de TDV werden Silivri en Vize pas in 1453 definitief veroverd; volgens het TDV-lemma Limnos kwam het eiland onmiddellijk na de verovering onder Osmaans bestuur en werd het onder voorwaarde van schatting aan de familie Gattilusio gelaten. In de atlas staan Silivri, Vize en Limnos vanaf deze dag van Byzantium naar het Osmaanse Rijk geschreven (Limnos als schatplichtig). Het gieten van reusachtige kanonnen, het over land slepen van schepen en de belegeringsopstelling voor de muren worden beschouwd als het toppunt van de militaire techniek van die tijd. De verovering geldt in de Europese geschiedschrijving als een van de symbolische data voor het einde van de Middeleeuwen.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Verovering van Trebizonde", "15f52403"], "d": ["Na een moeizame Zwarte Zee-veldtocht van Mehmed de Veroveraar, die gelijktijdig met leger en vloot werd gevoerd, gaf het Keizerrijk Trebizonde zich over; met het opruimen van dit laatste Byzantijnse restant in Anatolië kwam de gehele zuidkust van de Zwarte Zee onder Osmaanse heerschappij. Het beëindigen van de Komnenen-dynastie versterkte de aanspraak van de Veroveraar als 'heerser van twee zeeën en twee continenten'. Andere plaatsen die op dezelfde datum werden toegevoegd: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Definitieve verovering van Silifke — breken van het laatste verzet van de Karamanoğulları", "d988bee4"], "d": ["De burcht Silifke had zich in 1472 eenmaal overgegeven aan Gedik Ahmed Pasja, maar datzelfde jaar had Karamanoğlu Kasım Bey met hulp van de kruisvaardersvloot in de Middellandse Zee de burcht heroverd. Na de overwinning bij Otlukbeli droeg de Veroveraar zijn zoon en Gedik Ahmed Pasja op de regio definitief in te nemen; met hulp van de oude Osmaanse artilleristen werd het kruitmagazijn in brand gestoken en de burcht snel ingenomen. Zo werd het laatste verzet van de Karamanoğulları in het Taşeli-İçel-gebergte gebroken; de liquidatie van het beylik zou in 1474 worden voltooid.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Slag bij Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, de heerser van de Akkoyunlu, die in het oosten een grote macht was geworden en een bondgenootschap met Venetië had gesloten, werd bij Otlukbeli zwaar verslagen door het met vuurwapens uitgeruste leger van de Veroveraar. De overwinning bevestigde de Osmaanse superioriteit in Anatolië en was tevens een vroeg bewijs van de superioriteit van een centraal leger dat kanonnen en geweren gebruikte tegenover een klassiek leger. Volgens het TDV-lemma Gümüşhane stond de stad sinds 1467 onder Akkoyunlu-heerschappij; deze heerschappij eindigde met de nederlaag bij Otlukbeli en Gümüşhane kwam definitief onder Osmaanse heerschappij.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Krim komt onder Osmaanse bescherming", "44e3f7c8"], "d": ["De vloot onder bevel van Gedik Ahmed Pasja veroverde de zuidelijke kuststeden van de Krim, met name het Genuese Kaffa; deze kusten werden rechtstreeks Osmaanse sandjak. Het Krim-khanaat werd onder Mengli Giray een bevoorrechte vazalstaat die de Osmaanse opperheerschappij erkende en drie eeuwen lang een hoeksteen van de noordelijke politiek; de Zwarte Zee veranderde feitelijk in een Osmaanse binnenzee. Andere plaatsen die op dezelfde datum werden toegevoegd: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Dood van de Veroveraar — kwestie Cem Sultan", "190ecf01"], "d": ["Bij de plotselinge dood van de Veroveraar tijdens de veldtocht besteeg Bayezid II de troon; zijn broer Cem Sultan liet in Bursa op eigen aanspraak op het sultanaat de khutba in zijn naam lezen en munten slaan. Na zijn nederlaag vond hij eerst onderdak bij de Mamelukken en daarna bij de ridders van Rhodos; in handen van de ridders en het pausdom werd Cem een pasmunt in de Europese diplomatie en hij stierf in 1495 in Napels. Dit voorval dwong het Osmaanse buitenlandse beleid vijftien jaar lang tot voorzichtigheid.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Overwinning bij Çaldıran", "fea64ebb"], "d": ["Yavuz Sultan Selim, die de door de Safawidische propaganda in Anatolië ontstane dreiging bij de wortel wilde oplossen, bracht het leger van sjah Ismail op de vlakte van Çaldıran met zijn overwicht aan kanonnen en geweren een zware nederlaag toe. Tabriz werd binnengetrokken; Oost- en Zuidoost-Anatolië en de lijn Mosul–Diyarbakır werden bij het Osmaanse bestuur gevoegd. De aansluiting van de Koerdische beys bij de Osmanen dankzij de inspanningen van İdrîs-i Bitlisî legde het kader van de oostgrens vast dat eeuwenlang zou standhouden.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Overwinning bij Marj Dabiq", "07d254d3"], "d": ["Het Mamelukse leger werd binnen enkele uren bij Marj Dabiq, ten noorden van Aleppo, uiteengeslagen; de oude sultan Qansuh al-Ghawri stierf tijdens de slag. Met de overwinning, die de poorten van Aleppo en Damascus wijd opende, kwamen Syrië, Libanon en Palestina onder Osmaans bestuur; de weg naar de Egyptische veldtocht, die het einde van de Mamelukkenstaat zou betekenen, lag open.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniya — verovering van Egypte en het kalifaat", "caf378d6"], "d": ["Het Osmaanse leger stak snel de Sinaïwoestijn over, doorbrak de verdedigingslinie van Tumanbay bij Ridaniya en trok Caïro binnen; Tumanbay, die het verzet voortzette, werd gevangengenomen en geëxecuteerd en de Mamelukkenstaat verdween uit de geschiedenis. Egypte, de Hidjaz en de heilige steden kwamen onder Osmaans bestuur; de Abbasidische kalief en de heilige relieken werden naar Constantinopel gebracht. Met de overgang van het kalifaat naar de Osmaanse dynastie namen de sultans de aanspraak op het leiderschap van de islamitische wereld op zich; de controle over de Specerijenroute bezorgde het rijk ook grote inkomsten. Andere plaatsen die op dezelfde datum werden toegevoegd: Akko, Ma'an, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Süleyman de Wetgever besteeg de troon", "f6512269"], "d": ["De 46 jaar durende regering van Süleyman I, die na de dood van Yavuz als enige mannelijke erfgenaam de troon besteeg, wordt beschouwd als het politieke, militaire, juridische en culturele hoogtepunt van het rijk. Zijn kanunnames, die het gewoonterecht systematiseerden, bezorgden hem de titel 'Kanunî' (de Wetgever); in het Westen werd hij bekend als 'de Prachtige' (Magnificent). De werken van architect Sinan, de gouden eeuw van de divanliteratuur en de Middellandse Zee-overmacht van de vloot zijn de symbolen van deze periode.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Verovering van Belgrado", "59ef5cec"], "d": ["Belgrado, dat de Veroveraar in 1456 niet had kunnen innemen en dat gold als 'het slot van Midden-Europa', viel tijdens de eerste veldtocht van Süleyman na een beleg bij de samenvloeiing van Donau en Sava. De zuidelijke verdedigingslinie van Hongarije was daarmee ingestort; met deze verovering ging de deur open naar de Midden-Europese campagne die vijf jaar later naar Mohács en twintig jaar later naar de annexatie van Boeda zou leiden.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Verovering van Rhodos", "807bbb1e"], "d": ["Rhodos, de basis van de Johannieters die de zeeroutes van de oostelijke Middellandse Zee en de pelgrimsroute bedreigden, gaf zich na een maandenlang bloedig beleg bij verdrag over; de ridders kregen toestemming om de eilanden vrij te verlaten (later vestigden zij zich op Malta). De veiligheid van de Anatolische kusten was verzekerd en de zeeroute tussen Constantinopel en Egypte kwam onder ononderbroken Osmaanse controle.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Slag bij Mohács", "f3418b0d"], "d": ["Het Hongaarse leger werd op de vlakte van Mohács binnen ongeveer twee uur vernietigd door kanonvuur en manoeuvreeroverwicht; koning Lodewijk II kwam om in een moeras terwijl hij vluchtte. Mohács, een van de snelst gewonnen grote veldslagen uit de Osmaanse geschiedenis, maakte feitelijk een einde aan het onafhankelijke Hongaarse koninkrijk en opende het tijdperk van de Osmaans-Habsburgse rivaliteit in Midden-Europa.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Eerste Beleg van Wenen", "dc49ea4f"], "d": ["Tijdens de veldtocht die werd ondernomen tegen de Habsburgse aanspraken op de Hongaarse troon, belegerde het Osmaanse leger Wenen; omdat de zware kanonnen onderweg waren achtergelaten, de winter vroeg inviel en er bevoorradingsproblemen waren, werd het beleg na drie weken opgeheven. Hoewel de stad niet werd ingenomen, bleef de Osmaanse invloed in Hongarije behouden; Wenen markeerde de grens van de logistische reikwijdte van het rijk in Midden-Europa.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Verovering van Bagdad — Irakeyn-veldtocht", "897092c3"], "d": ["Tijdens de veldtocht naar 'de twee Irak' (Arabisch Irak en Perzisch Irak) werd eerst Tabriz en daarna zonder strijd Bagdad binnengetrokken; de inname van de oude hoofdstad van de Abbasiden bezorgde de Osmaanse heerser groot aanzien in de islamitische wereld. Het mausoleum van Imam-ı Âzam Ebû Hanîfe werd hersteld; met de toevoeging van Bagdad en Basra bereikte het Osmaanse grondgebied de Perzische Golf. Andere plaatsen die op dezelfde datum werden toegevoegd: Kirkoek, Kerbela.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Zeeslag bij Preveza", "30dc0f97"], "d": ["De door de paus aangevoerde kruisvaardersvloot werd ondanks haar numerieke overwicht bij Preveza uiteengeslagen door Barbarossa's tactiek, waarbij hij wind en kust meesterlijk benutte; Andrea Doria verliet het slagveld. De overwinning vestigde de onbetwiste Osmaanse zeemacht in de Middellandse Zee, die ongeveer 33 jaar zou duren; zij is de symbolische datum van de dag van de marine in de Turkse zeevaartstraditie. Andere plaatsen die op dezelfde datum werden toegevoegd: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annexatie van Boeda — Hongarije Osmaanse provincie", "db53b244"], "d": ["Nadat Süleyman op een veldtocht was uitgetrokken vanwege de Habsburgse belegering van Boeda, nam hij na de bevrijding van de stad Midden-Hongarije rechtstreeks onder Osmaans bestuur en stichtte het beylerbeylik Boeda; Transsylvanië werd een autonoom prinsdom onder Osmaanse bescherming. Deze driedeling van Hongarije duurde ongeveer 150 jaar en vormde het blijvende Osmaanse bestuurlijke skelet in Midden-Europa.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Vrede van Amasya", "a5afe0d1"], "d": ["Dit is het eerste officiële vredesverdrag dat een einde maakte aan de jarenlange Osmaans-Safawidische oorlogen. Bagdad en Irak bleven Osmaans, de grens in Oost-Anatolië werd voor het eerst wederzijds erkend; de Safawiden namen op zich de sjiitische propaganda in Osmaans gebied te staken, de Osmanen de veiligheid van Iraanse pelgrims bij doorreis. Het verdrag werd het eerste voorbeeld van een juridisch kader voor de betrekkingen tussen beide staten.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — overlijden van Süleyman de Wetgever", "e2917ed2"], "d": ["De 72-jarige Süleyman stierf in zijn tent, enkele uren voor de val van de burcht Szigetvár die hij tijdens zijn dertiende veldtocht belegerde; Sokollu Mehmed Pasja hield de dood weken geheim opdat het leger niet uiteen zou vallen. De burcht werd ingenomen, maar de staat had zijn langstregerende en meest luisterrijke sultan verloren; zijn zoon Selim II besteeg de troon en het gewicht van de grootveziers in het staatsbestuur begon toe te nemen.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Verovering van Cyprus", "e364a2b3"], "d": ["In 1570 werd een landing uitgevoerd op het door Venetië bestuurde Cyprus; Nicosia viel snel, Famagusta gaf zich pas na een beleg van elf maanden over in augustus 1571. Het eiland, cruciaal voor de veiligheid van de handels- en pelgrimsroutes in de oostelijke Middellandse Zee, werd als beylerbeylik georganiseerd en met bevolking uit Anatolië bevolkt; de verovering was ook de aanleiding voor de grote kruisvaardersalliantie die tot Lepanto zou leiden.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Nederlaag bij Lepanto (İnebahtı)", "6a1d44a9"], "d": ["De kruisvaardersvloot, die zich na de verovering van Cyprus had verenigd, onderschepte de Osmaanse vloot in de baai van Lepanto en vernietigde het grootste deel ervan; kapudan pasja Müezzinzâde Ali Pasja sneuvelde en alleen de vloot van Uluç Ali bleef gespaard. Na de ramp benoemde grootvizier Sokollu Mehmed Pasja Uluç Ali Pasja tot kapudan pasja met de opdracht de verspreide vloot te verzamelen en liet hij op alle scheepswerven van Constantinopel tot Alanya een nieuwe vloot bouwen; toch was de absolute superioriteit in de Middellandse Zee psychologisch aangetast.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Slag bij Mezőkeresztes", "da308ec5"], "d": ["In de grootste veldslag van de Lange Oorlog (1593–1606) herstelde het leger, waarvan Mehmed III zelf het bevel voerde, zich op het punt van uiteenvallen dankzij de aansporing van Hoca Sâdeddin Efendi en bracht het het Habsburgse leger een nederlaag toe. Zij geldt als de laatste grote klassieke veldslag die de Osmanen wonnen; dat de slag het algemene verloop van de oorlog niet veranderde, werd echter gezien als een teken van de slijtage van het militaire stelsel.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Vrede van Zsitvatorok", "39c01142"], "d": ["Met het verdrag dat een einde maakte aan de dertien jaar durende uitputtingsoorlog werd de Habsburgse heerser voor het eerst als 'Romeins keizer' als gelijke van de sultan beschouwd en werd de jaarlijkse schatting afgeschaft. Het gebiedsverlies was nagenoeg nihil; maar deze verandering in diplomatiek taalgebruik wordt gelezen als symbool van het einde van de Osmaanse aanspraak op absolute superioriteit tegenover Europa.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Verdrag van Qasr-i Shirin", "c1acf3af"], "d": ["Het verdrag dat werd gesloten nadat Murad IV Bagdad had heroverd (1638), beëindigde de meer dan honderd jaar durende Osmaans-Safawidische oorlogen. Bagdad en Irak bleven definitief Osmaans, Revan werd aan de Safawiden gelaten; de getrokken lijn werd met kleine wijzigingen de basis van de huidige grens tussen Turkije en Iran en geldt als een van de langstlevende grenzen ter wereld. Het verdrag liet Badra, Jassan, Mandali, Derteng en Derna aan de Osmanen; de grensvesting Zencir zou worden afgebroken, de dorpen ten westen ervan bleven Osmaans, die ten oosten ervan Iraans. De omgeving van de Zalim-burcht bij Şehrizor en Kızılca Kale bleven Osmaans, Avroman en Mihriban bleven Iraans; de burchten Kotur, Makû en Mağazberd zouden door beide partijen worden afgebroken.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Verovering van Kreta voltooid", "e0d85604"], "d": ["Het beleg van Candia, het laatste bedrijf van de Kretenzische oorlog die in 1645 begon, werd afgesloten met de driejarige vastberaden campagne van Fâzıl Ahmed Pasja; de Venetiaanse commandant Morosini droeg de stad bij verdrag over. De strijd van ongeveer een kwart eeuw ging de geschiedenis in als het langste beleg uit de Osmaanse geschiedenis; ook het laatste grote Latijnse bolwerk van de oostelijke Middellandse Zee kwam onder Osmaans bestuur. Drie kleine rotsvestingen aan de noordkust van het eiland — Souda, Spinalonga en Grambousa — bleven nog Venetiaans; omdat zij op afzonderlijke eilandjes liggen, kunnen zij op de kaart niet los van de rest van Kreta worden weergegeven.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Verdrag van Buczacz — grootste uitgestrektheid", "b17b6e5a"], "d": ["Met het Verdrag van Buczacz, gesloten na de verovering van Kamjanets-Podilsky tijdens de Poolse veldtocht, werd Podolië bij het Osmaanse Rijk gevoegd en een deel van Oekraïne onder bescherming genomen. Het rijk bereikte zo zijn grootste uitgestrektheid in Europa; dit punt wordt beschouwd als het hoogtepunt van het tijdperk van expansie en tegelijk als de laatste schakel ervan.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Mislukking van het Tweede Beleg van Wenen", "7d889252"], "d": ["Het twee maanden durende beleg van Wenen door Merzifonlu Kara Mustafa Pasja eindigde in een nederlaag door de plotselinge aanval die de Poolse koning Jan Sobieski vanaf de Kahlenberg inzette; het leger trok zich terug en liet zijn bagage achter, Merzifonlu werd in Belgrado geëxecuteerd. De oorlog die volgde op de na deze overwinning gevormde Heilige Liga duurde 16 jaar; deze nederlaag wordt aangewezen als het beginmoment van de grote achteruitgang in de Osmaanse geschiedenis.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Verovering van de burcht Grambousa — een van de rotsvestingen van Kreta die Venetiaans bleven", "3ddf9eeb"], "d": ["Hoewel de verovering van Kreta met de overgave van Candia in 1669 grotendeels voltooid werd geacht, bleef de rotsachtige eilandvesting Grambousa aan de noordwestpunt van het eiland nog drieëntwintig jaar in Venetiaanse handen. Met de inname ervan in 1692 werd een van de drie Venetiaanse overblijfselen op Kreta opgeruimd; Souda en Spinalonga zouden de Morea-veldtocht van 1715 moeten afwachten.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Vrede van Karlowitz — eerste grote gebiedsverlies", "8f7e2546"], "d": ["Met Karlowitz, dat een einde maakte aan de zestien jaar durende oorlogen van de Heilige Liga, werden Hongarije en Transsylvanië aan Oostenrijk, Podolië aan Polen en de Morea en de kust van Dalmatië aan Venetië gelaten. Voor het eerst in de Osmaanse geschiedenis ging grondgebied op deze schaal aan de onderhandelingstafel en blijvend verloren; het verdrag wordt beschouwd als het inleidende document van het nieuwe tijdperk waarin het rijk tegenover Europa in de verdediging ging, en is ook een keerpunt in de Osmaanse diplomatieke geschiedenis. Plaatsen die op dezelfde dag in de atlas van hand wisselden: Kostajnica en Jasenovac (van de Osmanen naar de Habsburgers; de verdragstekst laat Castanoviz in handen van de keizer, de overdrachtsdag van Jasenovac staat niet in de bron, de verdragsdag is ingevuld) en Preveza (van Venetië naar de Osmanen; TDV karlofca: volgens de bepaling die op 24 Receb 1110 / 26 januari 1699 werd ondertekend, werden de door Venetië bezette plaatsen ten noorden van de Golf van Lepanto teruggegeven). De atlas schrijft Kostajnica en Jasenovac bovendien aan de Habsburgse kant toe, Uman en Vinnytsia in Rechteroever-Oekraïne van de Osmanen aan Polen (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: 1672-99 Turkse heerschappij) en Nadin in Dalmatië aan Venetië (een plaatsspecifieke overdrachtsdag staat niet in de bron, de verdragsdag is ingevuld; de periodegrenzen van Nadin zijn niet met een bron bevestigd — verklaarde benadering). Ook Vonitsa ten noorden van de Golf van Lepanto wordt van Venetië aan de Osmanen teruggegeven (TDV karlofca); in Dalmatië behoort Vrana (Urana) tot de plaatsen die Venetiaans bleven (periodegrens niet bevestigd — verklaard).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Overwinning bij de Proet", "2583572f"], "d": ["Vanwege de kwestie van de Zweedse koning, die na de nederlaag bij Poltava bij de Osmanen onderdak had gezocht, werd in de oorlog die uitbrak het leger van tsaar Peter I aan de oever van de Proet omsingeld en gedwongen zich over te geven. Met het gesloten verdrag werd Azak teruggenomen; dat het leger niet werd vernietigd en de tsaar vrij werd gelaten, ging de geschiedenis in als een beslissing waarover tot op de dag van vandaag wordt gediscussieerd.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Verovering van de burchten Souda en Spinalonga — uitwissing van het laatste Venetiaanse spoor op Kreta", "7261f7ba"], "d": ["Drieëntwintig jaar na de val van Grambousa in 1692 werden met een zijtak van de Morea-veldtocht ook de burchten Souda en Spinalonga, de laatste twee steunpunten van Venetië op Kreta, veroverd. Zo was de verovering van Kreta, die in 1645 begon, na zesenveertig jaar tot op de laatste centimeter van het eiland voltooid.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Opstand van Patrona Halil", "100941a4"], "d": ["De mislukking aan het Iraanse front, de belastingen en de woede over de weelde in de kringen rond het paleis ontaardden onder leiding van de badhuisknecht Patrona Halil in een grote opstand. Grootvizier İbrahim Pasja werd gedood, Ahmed III werd afgezet en het Tulpentijdperk kwam ten einde; dat de opstandelingen maandenlang over de stad heersten, toonde op treffende wijze de kwetsbaarheid van het centrale gezag.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Verdrag van Belgrado — herovering van Belgrado, Smederevo en Noord-Servië", "ba7f8e46"], "d": ["Aan het einde van de oorlog die aan twee fronten tegen Oostenrijk en Rusland werd gevoerd (1736–1739) werden Belgrado en Noord-Servië heroverd; Rusland nam op zich Azak te ontmantelen en geen vloot op de Zwarte Zee te hebben. Het verdrag, beschouwd als het laatste grote succes van de Osmaanse diplomatie en het Osmaanse leger in de 18e eeuw, bezorgde het rijk een vredesperiode van een kwart eeuw. Andere plaatsen die op dezelfde dag in de atlas van Oostenrijk naar de Osmanen terugkeerden: Hisarcık (Grocka) (abi-centrumketen van Belgrado; TDV belgrad), Craiova, Râmnicu Vâlcea (Rimnik) en Turnu Severin (terugkeer van Klein-Walachije naar de Osmanen, naar het vazalschap van Walachije). Bosanski Brod en Bosanska Dubica in de Sava-strook keren in de atlas op 28 september 1739 terug naar de Osmanen (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 september 1739). Ook Târgu Jiu in Klein-Walachije keert op dezelfde dag terug naar de Osmanen.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Overval bij Çeşme", "840b30bd"], "d": ["De Russische vloot, die met Engelse steun de Middellandse Zee had bereikt, overviel de Osmaanse vloot in de haven van Çeşme waar zij beschutting had gezocht met brandschepen en verbrandde haar nagenoeg volledig. Rusland verscheen voor het eerst als grote zeemacht in de Middellandse Zee; de ramp was een van de slagen die het lot van de oorlog naar Küçük Kaynarca in 1774 bepaalden en maakte de behoefte aan een grondige hervorming van de vloot duidelijk.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Verdrag van Küçük Kaynarca", "2776dcdb"], "d": ["Met Küçük Kaynarca, dat de oorlog van 1768–1774 beëindigde en geldt als een van de zwaarste verdragen uit de Osmaanse geschiedenis, kreeg het Krim-khanaat 'onafhankelijkheid' — in feite werd een Russische invloedssfeer geschapen. Rusland vestigde zich aan de Zwarte Zeekust, verkreeg het doorvaartrecht door de Zeestraten voor koopvaardijschepen en een permanente ambassade in Constantinopel; de vage bepaling over bescherming van de orthodoxe onderdanen opende de deur naar de interventiegronden van de volgende eeuw. Voor het eerst werd een gebied met een islamitische bevolking aan de Osmaanse heerschappij onttrokken.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annexatie van de Krim door Rusland", "bdf6faa8"], "d": ["De door Küçük Kaynarca geschapen 'onafhankelijke' Krim werd, onder het voorwendsel van de onrust tijdens de regering van de laatste khan Şahin Giray, bij manifest van Catharina II door Rusland geannexeerd. Het driehonderd jaar durende Osmaans-Krim-partnerschap kwam ten einde; het verlies van de noordelijke steppen nam de verdedigingsdiepte van Constantinopel weg en zette de eerste grote migratiegolf van tienduizenden Krimtataren naar Osmaans grondgebied in gang. Op deze dag werd het Krim-schiereiland (Alushta, Kaffa, Soedak, Jalta, Balaklava, Inkerman, Mangoep, Arabat) bij Rusland gevoegd; Taman en Koeban gingen bij dezelfde annexatie ook naar Rusland (TDV Kırım: 8 april 1783 Juliaans = 19 april Gregoriaans).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III en de Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, die midden in de oorlog de troon besteeg, begreep dat de nederlagen structureel waren en startte onder de naam 'Nizâm-ı Cedîd' (Nieuwe Orde) een omvattend hervormingsprogramma: een nieuw leger dat naar Europees model werd getraind, een afzonderlijke schatkist om dit te financieren (Îrâd-ı Cedîd), versterking van de ingenieursscholen en de eerste permanente ambassades in de Europese hoofdsteden. Het programma wordt beschouwd als het begin van de moderne Turkse hervormingstraditie; door het verzet van de korpsen en de ayans zou het in 1807 ten val komen.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidatie van de Maltezer ridders — tussenstop van de Franse vloot", "d62f901d"], "d": ["De Franse vloot op weg naar Egypte deed Malta aan; de Sint-Jansridders (Malta) droegen het eiland zonder veel verzet over. De laatste burcht van de ridderorde die in 1522 uit Rhodos was verdreven en zich hier had gevestigd, kwam zo ten einde. Malta zou twee jaar later in Britse handen vallen, terwijl Napoleon vanaf het eiland rechtstreeks naar Alexandrië koers zette.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Napoleons bezetting van Egypte", "93fede5f"], "d": ["Het leger van generaal Bonaparte landde bij Alexandrië en bezette Egypte; deze veldtocht, gericht op de Britse route naar India, was de eerste directe aanval van een Europese mogendheid op het kerngebied van het Osmaanse Rijk. Nelsons overval bij Aboukir en Cezzâr Ahmed Pasja's verdediging van Akko braken de Franse opmars; de bezetting eindigde in 1801, maar in het vacuüm dat zij achterliet begonnen de opkomst van Mehmed Ali Pasja van Kavala en het tijdperk van de 'Oosterse kwestie'.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Document dat onder leiding van Alemdar Mustafa Pasja, de ayan van Rusçuk die Mahmud II op de troon bracht, werd ondertekend tussen het paleis en de machtige ayanfamilies in de provincie; de ayans beloofden de sultan trouw en militaire steun, terwijl de staat hun bestaan en rechten erkende. Omdat het het eerste voorbeeld in de Osmaanse geschiedenis was van beperking van het gezag van de sultan door een document, wordt het door sommige historici beschouwd als het verre begin van de constitutionele traditie; in de praktijk raakte het binnen enkele maanden buiten werking.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Griekse opstand begon", "a7293715"], "d": ["De opstand die door de organisatie Filiki Eteria werd voorbereid brak eerst uit in Walachije en vervolgens, met zijn eigenlijke kracht, in de Morea; de staat, die bezig was met de kwestie van Tepedelenli Ali Pasja, reageerde aanvankelijk te laat. Dankzij de intense Griekse sympathie in de Europese publieke opinie (filhellenisme) groeide de opstand snel uit tot een internationale zaak; zo werd de lont ontstoken voor de eerste succesvolle onafhankelijkheidsbeweging op Osmaans grondgebied in het tijdperk van het nationalisme. Andere plaatsen die op dezelfde datum verloren gingen: Athene, Balyabadra (Patras), İstefe (Thebe), Livadya, Eleusis (Attica), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Eerste gewapende opstand in de Morea", "77e6250f"], "d": ["Na de oversteek van de Proet sloeg de opstand over naar de Morea: de gewapende actie die in Kalavryta begon (Juliaans 21 maart) werd gevolgd door bewegingen in Patras, Kalamata en Mani; de Morea veranderde snel in een algemene opstand en het Osmaanse bestuur verloor het grootste deel van het schiereiland. Andere plaatsen die op dezelfde datum verloren gingen: Athene, Balyabadra (Patras), İstefe (Thebe), Livadya, Eleusis (Attica), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — Janitsarenkorps afgeschaft", "08c9372a"], "d": ["De janitsaren, die de ketels omkeerden tegen de training van het nieuw gevormde Eşkinci-korps, werden in hun kazernes op het Etmeydanı vernietigd door het kanonvuur van de door Mahmud II van tevoren voorbereide getrouwe troepen; het korps werd samen met al zijn takken en de verbonden Bektashi-tekkes opgeheven. Deze operatie, die onder de naam 'Gelukkige Gebeurtenis' de geschiedenis inging, liquideerde een vier eeuwen oude instelling en maakte de weg vrij voor het leger van de Asâkir-i Mansûre-i Muhammediyye en alle latere centralisatiehervormingen.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Overval bij Navarino", "ee579e7f"], "d": ["De Osmaans-Egyptische vloot, die bezig was de Griekse opstand neer te slaan, werd bij Navarino verbrand door de gecombineerde Brits-Frans-Russische vloot die zonder oorlogsverklaring de haven binnenvoer; bijna zestig schepen en duizenden zeelieden gingen verloren. De overval, die in de Europese diplomatie werd weggewuifd als een 'ongelukkig voorval', waarborgde feitelijk de Griekse onafhankelijkheid en opende de weg naar de Osmaans-Russische oorlog van 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Edict van Tanzimat", "5042ce7b"], "d": ["Met het in Gülhane voorgelezen Hatt-ı Hümâyun werden de veiligheid van leven, eigendom en eer van alle onderdanen, zonder onderscheid van godsdienst, onder staatsgarantie gebracht; de beginselen van rechtvaardigheid in de belasting, ordelijkheid in de dienstplicht en geen straf zonder proces werden afgekondigd. Het edict, het werk van Mustafa Reşid Pasja, wordt beschouwd als het eerste grote document van constitutionele aard van de Osmaanse modernisering en gaf zijn naam aan het hervormingstijdperk 'Tanzimat-periode' (1839–1876); in dit kader werden grondige herstructureringen doorgevoerd in bestuur, recht, onderwijs en financiën.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Krimoorlog begon", "3b9ca3c8"], "d": ["De crisis, begonnen met de kwestie van de heilige plaatsen en de Russische aanspraak op bescherming van de orthodoxe onderdanen, ontaardde in open conflict met de Osmaanse oorlogsverklaring; na de overval bij Sinope traden Engeland en Frankrijk (later Piëmont) aan Osmaanse zijde in de oorlog. De oorlog werd met de landing van de geallieerde legers op de Krim en de inname van Sebastopol gewonnen met het Verdrag van Parijs in 1856; maar de eerste buitenlandse lening, in de oorlogsjaren aangegaan (1854), bracht het rijk in een spiraal van financiële afhankelijkheid die een halve eeuw zou duren.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Hervormingsedict (Islahat Fermanı)", "78ff234d"], "d": ["Het edict, afgekondigd voor de vredesonderhandelingen van Parijs, breidde de beginselen van de Tanzimat uit en kende aan niet-moslimonderdanen brede gelijkheidsrechten toe, waaronder ambtenarenposten, militaire dienst en het openen van scholen; de gemeenschapsorganisaties werden herordend. Met het daarna ondertekende Verdrag van Parijs werd de Osmaanse staat formeel toegelaten tot de familie van het Europese volkenrecht en kwam zijn territoriale integriteit onder de gezamenlijke garantie van de grote mogendheden — in de praktijk zou deze garantie een nieuwe deur voor interventies worden.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — Eerste Constitutionele Periode", "0fe052c1"], "d": ["Op de dag dat de internationale conferentie die in Constantinopel bijeen was gekomen om de Balkancrisis te bespreken werd geopend, werd met kanonschoten de eerste Osmaanse grondwet afgekondigd; met de Kanûn-ı Esâsî, het werk van de beweging van de 'Jonge Osmanen' onder leiding van Midhat Pasja, werd een tweekamerparlement gevormd. De Meclis-i Meb'ûsan werd in maart 1877 geopend; maar Abdülhamid II schorste het parlement in februari 1878 voor onbepaalde tijd met de Oorlog van '93 als reden en de grondwet bleef dertig jaar opgeschort.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Oorlog van '93 (Osmaans-Russische oorlog van 1877–78)", "5bd96af7"], "d": ["In de oorlog die de 'Oorlog van '93' werd genoemd omdat hij overeenkwam met het jaar 1293 van de Rûmî-kalender, vielen de Russische legers aan twee fronten aan; hoewel Gazi Osman Pasja's verdediging van Plevna en de Kaukasische veldslagen van Ahmed Muhtar Pasja legendarisch werden, bezweek het front en rukten de Russen op tot Yeşilköy (San Stefano). De oorlog zette de grote golven van moslimmigratie van de Balkan en de Kaukasus naar Constantinopel in gang, waarvan de gevolgen tot op heden doorwerken; de demografische en financiële structuur van het rijk kwam nooit meer terug in de oude staat.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Verdrag van Berlijn", "47f76a49"], "d": ["Het Congres van Berlijn, dat het door San Stefano ontstane 'Groot-Bulgarije' in naam van het evenwicht tussen de grote mogendheden herzag, liet toch een zwaar beeld achter: Servië, Montenegro en Roemenië werden onafhankelijk; het autonome Prinsdom Bulgarije werd gesticht; Bosnië-Herzegovina werd aan de Oostenrijkse bezetting, Cyprus aan het Britse bestuur en Kars-Ardahan-Batoem aan Rusland gelaten. De vijfhonderd jaar oude Osmaanse orde in Rumelië viel grotendeels uiteen; de 'Oosterse kwestie' werd een permanent onderwerp op de agenda van de Europese diplomatie. Andere plaatsen die op dezelfde datum verloren gingen: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Boekarest, Iași, Köstence. Roemenië, dat Bessarabië aan Rusland moest afstaan, kreeg Tulcea en Dobroedzja: Tulcea, Babadag, Măcin, Isaccea, Hârșova en Mangalia in Noord-Dobroedzja gingen over naar Roemenië.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Bezetting van Tunesië en Düyûn-ı Umûmiyye", "c7e25598"], "d": ["Frankrijk bezette Tunesië onder voorwendsel van de incidenten aan de Algerijnse grens en nam het met het Verdrag van Bardo onder zijn bescherming; de Osmaanse aanwezigheid in Noord-Afrika werd teruggebracht tot Tripolitanië. Met het Muharrem-decreet, uitgevaardigd in hetzelfde jaar, werd de Düyûn-ı Umûmiyye-administratie opgericht voor het beheer van de bankroete buitenlandse schulden, waarin de schuldeisers vertegenwoordigd waren: basisinkomsten zoals zout, tabak en zijde werden rechtstreeks aan dit buitenlandse bestuur gekoppeld en de financiële soevereiniteit werd zwaar beperkt. Andere plaatsen die op dezelfde datum verloren gingen: Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Britse bezetting van Egypte", "f1269768"], "d": ["De Urabi Pasja-beweging, die in Egypte opkwam tegen het financiële faillissement en buitenlandse controle, werd na het bombardement op Alexandrië verpletterd door de overwinning bij Tel el-Kebir van het aan land gegane Britse leger en Caïro werd bezet. Hoewel Egypte juridisch aan het Osmaanse Rijk gebonden bleef, kwam het feitelijk onder Brits bestuur; de controle over het Suezkanaal werd het middelpunt van de Britse imperiale strategie.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Afkondiging van de Tweede Constitutionele Periode", "95ee2fd2"], "d": ["Tegenover de beweging die groeide doordat officieren van het Comité voor Eenheid en Vooruitgang in Macedonië de bergen introkken, herstelde Abdülhamid II de Kanûn-ı Esâsî; de 'afkondiging van de vrijheid' werd met enthousiasme ontvangen en er werden verkiezingen gehouden. Toch kwam er geen stabiliteit: nadat het Incident van 31 maart (april 1909) was onderdrukt, werd Abdülhamid afgezet; ook de onafhankelijkheid van Bulgarije, de annexatie van Bosnië en de oriëntatie van Kreta op Griekenland vonden in deze roerige maanden plaats.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Italiaans-Turkse Oorlog (Tripolitaanse Oorlog)", "ed441994"], "d": ["Het koloniaal ingestelde Italië verklaarde de oorlog aan Tripolitanië, het laatste Osmaanse gebied in Noord-Afrika, en bezette de kusten; toen de staat zonder vloot geen reguliere troepen kon sturen, trokken jonge officieren zoals Mustafa Kemal en Enver Bey in het geheim naar de regio en organiseerden met de Senoessi-stammen een effectief verzet. Met het Verdrag van Ouchy (18 oktober 1912), dat werd ondertekend na het uitbreken van de Balkanoorlog, werd Libië aan Italië gelaten; Italië bezette bovendien Rhodos en de Dodekanesos.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Verdrag van Londen — verlies van Rumelië", "f3f976df"], "d": ["Met het Verdrag van Londen, dat de Eerste Balkanoorlog beëindigde, gingen alle gebieden ten westen van de lijn Midye-Enez en de Egeïsche eilanden verloren; Albanië werd onafhankelijk. Van Rumelië, dat al meer dan vijfhonderd jaar het demografische, economische en culturele zwaartepunt van het rijk was, zou alleen Oost-Thracië overblijven (Edirne werd in de Tweede Balkanoorlog heroverd); het verlies verhardde het oorlogs- en vestigingsbeleid van het Unionistische bestuur ingrijpend. De volgende plaatsen ten westen van de lijn Midye-Enez gingen verloren: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Debar), Prizren, Priştine, Peç (Peja), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje); Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); op Kreta Chania, Candia, Kreta (Rethymno), Sitia (Sitiye) en Sfakia (İsfakiye).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Toetreding tot de Eerste Wereldoorlog", "05a0252e"], "d": ["Dat de aan Engeland ontsnapte pantserschepen Goeben en Breslau als gekocht werden voorgesteld en de Zeestraat binnen mochten, trok de staat stap voor stap naast Duitsland; toen de vloot onder bevel van admiraal Souchon Russische havens bombardeerde (29 oktober) begon de oorlog feitelijk, en de wederzijdse verklaringen volgden begin november. Ondanks de afkondiging van de Grote Jihad bleef het verwachte effect uit; het rijk raakte vier jaar lang op vijf afzonderlijke fronten, van de Kaukasus tot Palestina, verwikkeld in een strijd om het bestaan.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Overwinning bij Çanakkale (Gallipoli)", "95d888e8"], "d": ["De geallieerde armada, die Constantinopel wilde laten vallen en Rusland wilde bereiken, werd op 18 maart door het vuur van de mijnenvelden en forten uit de Zeestraat teruggeslagen; de door het mijnenlegger Nusret gelegde mijnenlinie bepaalde het lot van de strijd. Ook de landoperatie op Gallipoli, begonnen in april, werd bij Anafartalar en Conkbayırı tot staan gebracht; de geallieerden ontruimden het schiereiland in januari 1916 volledig. Luitenant-kolonel Mustafa Kemal maakte zich aan dit front een naam; de overwinning, behaald tegen een prijs van ongeveer een kwart miljoen gesneuvelden en vermisten, wordt beschouwd als de geboorteplaats van de kaders en de geest van de Nationale Strijd.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Opstand van sjerif Hoessein", "75f7c58c"], "d": ["De emir van Mekka, sjerif Hoessein, kwam na geheime briefwisseling met de Britten in opstand met de belofte van een onafhankelijk Arabisch koninkrijk; de Hidjaz-spoorlijn werd doelwit van aanvallen. Hoewel Fahreddin Pasja's legendarische verdediging van Medina, die tot na de wapenstilstand voortduurde, een symbool van verzet bleef, versnelde de opstand, in combinatie met de Britse opmars aan het Palestijnse front, het uiteenvallen van de Osmaanse heerschappij in de Arabische provincies. Andere plaatsen die op dezelfde datum verloren gingen: Ta'if.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Wapenstilstand van Moudros", "9e87c767"], "d": ["De Osmaanse staat, wiens fronten door de ineenstorting van Bulgarije van elkaar waren afgesneden, trok zich terug uit de oorlog met de wapenstilstand die aan boord van het pantserschip Agamemnon werd getekend. Artikel 7, dat de opening van de Zeestraten toestond en de bezetting van plaatsen die de veiligheid bedreigden mogelijk maakte, werd binnen korte tijd het juridische deksel op de feitelijke verdeling: Mosul, Iskenderun, daarna Smyrna en Constantinopel werden bezet. De wapenstilstand wordt beschouwd als het document van het feitelijke einde van het rijk. Andere plaatsen die op dezelfde datum verloren gingen: Hama, Damascus, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal in Samsun — Nationale Strijd", "09a8f784"], "d": ["In het klimaat van verontwaardiging door de bezetting van Smyrna ging Mustafa Kemal Pasja, in de hoedanigheid van inspecteur van het 9e Leger, in Samsun aan land en richtte zijn officiële taak op het organiseren van het verzet in Anatolië. De Circulaire van Amasya en de congressen van Erzurum en Sivas zijn het vervolg van deze stap; het beginsel 'de onafhankelijkheid van de natie zal opnieuw door de vastberadenheid en het besluit van de natie worden gered' werd de kern van het politieke programma van de Nationale Strijd.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Opening van de TBMM en Sèvres", "2008feec"], "d": ["Na de formele bezetting van Constantinopel en de ontbinding van de Meclis-i Meb'ûsan werd op 23 april 1920 in Ankara de Grote Nationale Vergadering geopend; de vergadering, die buitengewone bevoegdheden in zich verenigde, werd de kern van de nieuwe staat gebaseerd op de nationale wil. Het in augustus door de regering van Constantinopel ondertekende Verdrag van Sèvres verdeelde Anatolië; de TBMM verklaarde de ondertekenaars tot vaderlandsverraders en Sèvres werd nooit uitgevoerd.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Slag aan de Sakarya", "f2f970a6"], "d": ["Het Griekse offensief, dat tot op 50 kilometer van Ankara naderde, werd gebroken in de 22 dagen en 22 nachten durende slag die werd gevoerd onder het bevel 'er is geen verdedigingslinie, er is een verdedigingsvlak' van Mustafa Kemal Pasja, die de bevoegdheid van opperbevelhebber had overgenomen. Het Griekse leger ging voor het eerst over op strategische verdediging; de overwinning bezorgde Mustafa Kemal de titels gazi en müşir (maarschalk) en opende de deur naar het Verdrag van Ankara met Frankrijk en erkenning door het buitenland.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Groot Offensief en bevrijding van Smyrna", "172a50c4"], "d": ["Het offensief dat op de ochtend van 26 augustus vanaf Kocatepe werd ingezet, bereikte op 30 augustus bij Dumlupınar met de Slag van de Opperbevelhebber de vernietiging van de belangrijkste Griekse strijdkrachten; met de achtervolging onder het bevel 'Legers, uw eerste doel is de Middellandse Zee, vooruit!' werd Smyrna op 9 september bevrijd. Met de Wapenstilstand van Mudanya (11 oktober) werd Oost-Thracië zonder strijd teruggenomen; de militaire overwinning bepaalde de onderhandelingskracht van de nieuwe staat die in Lausanne zou worden gevestigd.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Afschaffing van het sultanaat", "9f36a9f6"], "d": ["Nadat ook de regering van Constantinopel was uitgenodigd voor de besprekingen in Lausanne, schafte de TBMM op 1 november 1922 het sultanaat af door sultanaat en kalifaat te scheiden; de 623 jaar durende Osmaanse dynastieke heerschappij kwam juridisch ten einde. Mehmed VI Vahideddin verliet op 17 november met een Brits oorlogsschip het land; Abdülmecid Efendi werd bij besluit van de TBMM tot het kalifaat benoemd en ook dit ambt zou op 3 maart 1924 worden afgeschaft.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Verdrag van Lausanne", "38c27f7d"], "d": ["Met het Vredesverdrag van Lausanne, ondertekend na acht maanden moeizame onderhandelingen, werden de grenzen, de volledige onafhankelijkheid en de soevereiniteit van de nieuwe Turkse staat internationaal erkend; de capitulaties werden afgeschaft, de Düyûn-ı Umûmiyye werd in liquidatie gebracht en de bevolkingsuitwisseling werd geregeld. Lausanne, dat Sèvres feitelijk nietig maakte, wordt beschouwd als de diplomatieke overwinning van de Nationale Strijd en als het stichtende buitenlandse document van de Republiek.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Uitroeping van de Republiek", "d5bfcdfb"], "d": ["Nadat de TBMM met een grondwetswijziging de bepaling 'de regeringsvorm van de Turkse Staat is de republiek' had aangenomen, werd de Republiek uitgeroepen; Mustafa Kemal Pasja werd tot eerste president gekozen. Het 624 jaar durende Osmaanse avontuur, dat in 1299 als grensbeylik was begonnen, was zo gesloten en de nieuwe staat, waarin de soevereiniteit onvoorwaardelijk aan de natie toebehoort, was gebouwd op de erfenis van het rijk.", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["Ontslag van Tepedelenli Ali Pasja en begin van het beleg van Ioannina", "e8a6530b"], "d": ["De politiek van Mahmud II om de lokale machten uit te schakelen bereikte Tepedelenli Ali Pasja, die al drieëndertig jaar Ioannina bestuurde en Thessalië en Epirus feitelijk in handen had. De pasja werd ontslagen als hoofd van de bergpassen en zijn zoon Veli als pasja van Trikala; omdat werd verwacht dat hij zich daaraan niet zou houden, werd een macht tegen hem gestuurd. Hurşid Ahmed Pasja, die hiermee werd belast, was tegelijk gouverneur van de Morea en kreeg ook het seraskerschap van Rumelië; alle civiele en militaire bestuurders in het gebied werden belast met het gevangennemen van Tepedelenli. Dat wil zeggen dat toen de Griekse opstand uitbrak, de bevelhebber die de Morea had moeten besturen en de troepen onder zijn bevel het fort van Ioannina belegerden. Ali Pasja hield op 23 mei 1820 in Ioannina een bijeenkomst met de Grieken, probeerde onder zijn bestuur een Grieks eyalet te stichten en gaf hen geld- en wapenhulp. Aan de andere kant was er geen te onderschatten macht: Ali Pasja had een leger van 30-40.000 man, waarvan 7.000 vast, en een kleine vloot; de bevolking onder zijn bestuur werd geschat op 1,5-2 miljoen en zijn jaarinkomen op 4-5 miljoen kuruş.", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["De Ottomaans-Perzische oorlog begint - verlies van Kars en Bayezid, beleg van Erzurum", "570b27bd"], "d": ["In het tweede jaar van de Griekse opstand veranderde de oostgrens van het rijk in een oorlogsgebied. De Qajar-kroonprins Abbas Mirza stak met een grote militaire macht de grens over onder het voorwendsel dat de karavaan waarin de met de sjah getrouwde vrouw naar de hadj reisde door Ottomaanse vertegenwoordigers was doorzocht; hij nam de provincies Kars en Bayezid in en sloeg het beleg om Erzurum. De macht tegenover hem was geen gewone grensdivisie: Abbas Mirza had het leger van Azerbeidzjan volgens Europese methoden getraind en in Tabriz een buskruitfabriek en kanongieterijen laten oprichten. Het Ottomaanse Rijk was ondertussen in het westen bezig met de opstand in de Morea, in het noordwesten met het verzet van Tepedelenli Ali Pasja in Ioannina en had geen volgens Europese methoden getraind leger; het Janitsarenkorps zou tot 1826 bestaan.", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["Perzische bezetting van Sulaymaniyah en Bagdad - beleg van Kirkuk", "384d74e4"], "d": ["Tegelijk met de operatie in Oost-Anatolië voerden de Perzische troepen een grootschalige aanval uit op Noord-Irak en de provincie Bagdad onder Ottomaans bestuur. Bagdad werd toen bestuurd door Kölemen Dâvud Pasja, sinds 1817 gouverneur; de pasja beschikte over een infanterie- en artilleriemacht van 10.000 man die hij had laten trainen door Deveaux, een voormalige adjudant van Napoleon. In het centrum van het rijk was er nog geen dergelijk leger - volgens Europese methoden getrainde eenheden waren in die jaren alleen in handen van krachtige gouverneurs in de provincie. Wat de oorlog beëindigde was geen Ottomaanse overwinning: het Ottomaanse verzet en de epidemie die Azerbeidzjan trof dwongen de Perzische troepen tot terugtrekking.", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["De moord op Tepedelenli Ali Pasja - het einde van het beleg van Ioannina", "da679150"], "d": ["Het verzet in Ioannina duurde bijna twee jaar en juist in deze tijd kreeg de Griekse opstand een algemene verbreiding. Toen Hurşid Pasja spionnen naar het fort stuurde en rang en gratificaties uitdeelde aan wie vluchtten, daalde het aantal soldaten rond Ali Pasja tot veertig à vijftig; de pasja trok zich, met de garantie dat hem bij overgave niets zou gebeuren, terug in het klooster van Pandeleimon op het meer. In die tijd was de familie van Hurşid Pasja in handen van de Griekse opstandelingen gevallen; om zo snel mogelijk naar de Morea terug te kunnen keren, negeerde hij de verleende veiligheidsbelofte en liet hij een vals executiebevel opstellen. Toen men zijn kamer binnentrad, antwoordde Ali Pasja met wapens en kwam om in het gevecht dat uitbrak; zijn hoofd werd op 24 februari naar Constantinopel gebracht. Het beleg had ook de scheur binnen het Ottomaanse commando blootgelegd: toen de opstand in de Morea gevaarlijker werd dan de kwestie Tepedelenli, was Seyyid Ali Pasja benoemd tot zelfstandig seraskier van de Morea; Hurşid Pasja, die dat niet prettig vond, wees zijn verzoeken om hulp af en probeerde hem zelfs in de ogen van de staat als mislukt voor te stellen. Aan het einde van het jaar waarin Ali Pasja werd uitgeschakeld, viel Nauplion, de sterkste vesting van de Morea.", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["Verdrag van Erzurum - de Perzische troepen trekken zich binnen zestig dagen terug", "166373c3"], "d": ["De oorlog van twee jaar eindigde met het in Erzurum getekende vredesverdrag. Krachtens het verdrag zouden de Perzische troepen zich binnen zestig dagen terugtrekken uit de bezette gebieden. Het verdrag trok geen nieuwe grens en bracht de toestand van vóór de oorlog terug; de grensgeschillen tussen de twee staten zouden in 1833-1842 weer in gevechten overgaan en pas in 1847 met een tweede, eveneens in Erzurum getekend verdrag worden geregeld. Het sluiten van het oostfront was een voorwaarde opdat het rijk al zijn gewicht aan de Griekse opstand kon geven.", "7c54983b"]},
"OLAYLAR_2S1019:0330-05-11:0":{"b": ["Constantinopel wordt geopend als hoofdstad van Byzantium (het Oost-Romeinse Rijk)", "9d155dd6"], "d": ["Byzantion, dat door Constantijn was herbouwd, werd met dagenlange plechtigheden geopend als nieuwe hoofdstad van het rijk. Het Byzantijnse (Oost-Romeinse) register van de atlas voor Istanbul begint met deze dag.", "c4468b48"]},
"OLAYLAR_2S1019:0969-07-06:0":{"b": ["De Fatimiden nemen Egypte in: Jawhar al-Siqillī trekt Fustat binnen, de grondslag van Caïro wordt gelegd", "500aef7a"], "d": ["De Fatimidische bevelhebber Jawhar al-Siqillī maakte een einde aan de Ikhshididische heerschappij in Egypte, trok Fustat binnen en liet in Manāh in het noorden het paleis en de muren van de nieuwe hoofdstad, Caïro, bouwen.", "d9599f90"]},
"OLAYLAR_2S1019:0990-03-31:0":{"b": ["De Uqayliden nemen Mosul in: oprichting van de Uqaylidische dynastie van Mosul", "49eb93a6"], "d": ["Abū l-Zawwād doodde Abū Tāhir Ibrāhīm en zijn zoon en nam Mosul in; in de stad werd de van de Buyiden afhankelijke Uqaylidische dynastie gesticht.", "affdc0ec"]},
"OLAYLAR_2S1019:1084-12-12:0":{"b": ["Süleyman Shah, zoon van Kutalmış, neemt Antiochië van Byzantium", "17d1c6f0"], "d": ["Antiochië, dat meer dan een eeuw in Byzantijnse handen was geweest, werd ingenomen door de Seltsjoekse heerser van Anatolië, Süleyman Shah; de weerstand biedende citadel gaf zich op 12 januari 1085 over.", "a6f1f783"]},
"OLAYLAR_2S1019:1098-06-03:0":{"b": ["De kruisvaarders nemen Antiochië in: het vorstendom Antiochië wordt gesticht", "c9f47942"], "d": ["Antiochië, dat een lang beleg had doorstaan, kwam door het verraad van Fīrūz, een bevelhebber van Yaghi-Siyan, in handen van de kruisvaarders. Het gestichte vorstendom Antiochië omvatte ook Iskenderun.", "f6409190"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["Ghiyath al-Din Kaykhusraw verovert Antalya: de Seltsjoeken bereiken de Middellandse Zee", "9812e629"], "d": ["Antalya, dat na de inname van Constantinopel door de Latijnen in handen was gekomen van de Italiaan Aldobrandini, werd ingenomen door de Seltsjoekse sultan van Anatolië Ghiyath al-Din Kaykhusraw I, mede met steun van de Grieken die ontevreden waren over het Latijnse bestuur.", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["Izz al-Din Kaykaus herovert Antalya op de Cyprioten", "ec2446f9"], "d": ["Izz al-Din Kaykaus I heroverde Antalya, dat in 1212 door een opstand met steun van de koning van Cyprus verloren was gegaan, en gaf het gouverneurschap opnieuw aan Mubariz al-Din Ertokuş.", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["Baibars neemt Jaffa in op de kruisvaarders: de heerschappij van het koninkrijk Jeruzalem in Jaffa eindigt", "c7629d70"], "d": ["De Mamelukse sultan Baibars I maakte een einde aan de kruisvaardersheerschappij in Jaffa en liet de stad verwoesten; het hout en het marmer van de citadel stuurde hij voor de bouw van zijn moskee in Caïro.", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["Baibars neemt Antiochië in: het einde van het vorstendom Antiochië", "da2b511a"], "d": ["Het Mamelukse leger overschreed met een algemene aanval de muren van Antiochië; het kruisvaardersvorstendom van 170 jaar eindigde en ook Iskenderun werd weer bij het islamitische gebied gevoegd.", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["De Karamanoğulları heroveren Konya op de Ilkhaniden", "057ec073"], "d": ["Na de vlucht naar Egypte van Demirtaş, de Ilkhanidische gouverneur van Anatolië, kwam Konya weer in handen van de Karamanoğulları. De stad zou in 1350 overgaan naar Eretna.", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["Koning Alfons XI van Castilië neemt Algeciras in: na een beleg van twintig maanden eindigt de Meriniedische heerschappij", "5de2a877"], "d": ["Na het ongeveer twintig maanden durende beleg van koning Alfons XI van Castilië meldde de Meriniedische heerser Abū l-Hasan, aan het einde van de onderhandelingen die op 21 maart 1344 begonnen, de moslims dat zij de stad moesten verlaten; op 26 maart werd Villa Nueva en de dag daarna Villa Vieja ontruimd en de Castilianen namen de stad over. Alfons XI trok op 28 maart 1344 (Palmzondag) met een plechtigheid de stad binnen. Algeciras bleef tot 1369 bij Castilië.", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["Stefan Dušan neemt Serres in op Byzantium", "2cc79d36"], "d": ["De Servische koning Stefan Dušan, die gebruikmaakte van de Byzantijnse burgeroorlog, nam Serres in en maakte de stad de hoofdstad van het Servische Rijk.", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["Het graafschap Feldkirch wordt aan Habsburgs Oostenrijk verkocht", "fe4a0306"], "d": ["Rudolf, de laatste graaf van de Montfort-Feldkirch-tak, verkocht in 1375 al zijn bezit aan de Habsburgers, de hertogen van Oostenrijk; de feitelijke overdracht werd met zijn dood (1390) voltooid. Feldkirch werd het eerste grote deel van Vorarlberg dat in Habsburgse handen kwam.", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["Balčik en de kust van de Dobroedzja komen onder Ottomaans bestuur", "dfd348b9"], "d": ["Na de overwinning bij Kosovo kwam Balčik aan de kust van de Dobroedzja onder Ottomaans bestuur. Het gebied zou direct daarna door Mircea, woiwode van Walachije, worden bezet; de Ottomaanse heerschappij zou in 1393 worden hersteld.", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["De Mar'ashi-sayyids geven zich bij Mahaneser over aan Timoer: Mazandaran gaat naar de Timoeriden", "125dbed8"], "d": ["Timoer, die tijdens zijn vijfjarige veldtocht Mazandaran binnentrok, drong de Mar'ashi's, die hem bij Karatogan tegemoet traden, terug in de vesting Mahaneser en nam hen over. In Sari en Amul werd een groot bloedbad aangericht; Sari werd gegeven aan Iskender Sheykhi, zoon van Kiya Efrasiyab.", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["Šibenik komt opnieuw onder bestuur van de Republiek Venetië", "9b7998bf"], "d": ["Šibenik, dat weerstand had geboden nadat Ladislaus van Napels zijn rechten op Dalmatië in 1409 aan Venetië had verkocht, kwam in 1412 opnieuw onder Venetiaans bestuur. De stad bleef tot de val van de Republiek in 1797 een Dalmatisch bezit van Venetië.", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["Veldtocht van Çelebi Mehmed tegen de Candaroğulları: Çankırı wordt gegeven aan Kasım Bey onder Ottomaanse bescherming", "da03b919"], "d": ["Çelebi Mehmed, die optrok tegen İsfendiyar Bey van de Candaroğulları, die Sheikh Bedreddin had geholpen naar Walachije over te steken, rukte op naar Kastamonu en belegerde Sinop, waarheen İsfendiyar zich had teruggetrokken. İsfendiyar erkende de Ottomaanse soevereiniteit; met het Ilgaz-gebergte als grens werd Çankırı en omgeving gegeven aan zijn zoon Kasım Bey, die bij de Ottomanen was gevlucht.", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["Met de inname van Smederevo gaat ook Grocka over naar de Ottomanen", "ab724ec9"], "d": ["Smederevo werd na een beleg van drie maanden ingenomen. Grocka, 17 km van Smederevo, volgt in de atlas het lot van zijn oudere centrum Smederevo en gaat op dezelfde dag van het Servische despotaat over naar de Ottomanen (het zal in 1444 worden teruggegeven).", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["De eerste helft van het graafschap Bregenz wordt aan Habsburgs Oostenrijk verkocht", "3a9598db"], "d": ["Elisabeth van Hochberg, erfgename van Montfort-Bregenz, verkocht in 1451 de helft van het graafschap Bregenz aan de Habsburgers; de resterende helft werd in 1523 verworven. Bregenz werd zo een deel van het Habsburgse Vorarlberg.", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["Met de overgave van Korinthe gaat ook Sicyon over naar de Ottomanen", "c7b0d22d"], "d": ["Fatih nam tijdens de veldtocht in de Morea Korinthe na een beleg van drie maanden langs vreedzame weg in. Sicyon, 17 km van Korinthe, volgt in de atlas het lot van zijn oudere centrum Korinthe en gaat op dezelfde dag over naar de Ottomanen.", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["Met de overgave van Smederevo gaat ook Grocka over naar de Ottomanen", "e3d76f5c"], "d": ["Helena, weduwe van Lazar Branković, leverde de vesting Smederevo uit aan de Ottomanen; het Servische despotaat eindigde. Grocka, dat Smederevo als centrum had, gaat op dezelfde dag over naar de Ottomanen.", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["Overgave van Kaffa en onderworpenheid van de khan van de Krim: de kust van Circassië (Sotsji, Tuapse, Maikop) wordt als los beschermd gebied aan het Khanaat van de Krim gebonden", "e99eb8e8"], "d": ["Na een beleg van vier dagen gaf Kaffa zich over aan Ahmed Pasja en aanvaardde Mengli Giray de onderworpenheid aan de Ottomaanse sultan. De omgeving van Sotsji, Tuapse en Maikop, het land van de Circassische stammen die de khans van de Krim als hun heren erkenden, wordt in de atlas vanaf deze datum getoond als los beschermd gebied verbonden aan het Khanaat van de Krim.", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["Moskou neemt Brjansk van het Groothertogdom Litouwen", "fb1c3a61"], "d": ["In de Moskovisch-Litouwse oorlog van 1500-1503 nam het Russische leger Brjansk in en de stad werd bij de Moskovische staat gevoegd; het bestand van 1503 erkende deze winst.", "8e507991"]},
"OLAYLAR_2S1019:1500-04-12:0":{"b": ["De laatste graaf van Görz, Leonhard, sterft: Lienz en het Pustertal gaan over naar Habsburgs Oostenrijk (Tirol)", "93331339"], "d": ["Leonhard, de laatste vertegenwoordiger van de graven van Görz (Gorizia), stierf op 12 april 1500 in Lienz. Volgens de vooraf gesloten erfopvolgingsovereenkomst ging het voorgraafschap, dat Lienz en het Pustertal omvatte, over naar Maximiliaan I en werd bij Tirol gevoegd.", "996079fc"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["Bıyıklı Mehmed Pasja neemt Mosul, Sinjar en Imadiya op de Safaviden", "3039d6af"], "d": ["Bıyıklı Mehmed Pasja, die Kara Han bij Koçhisar had verslagen, nam tijdens het beleg van Mardin de omliggende vestingen op de Safaviden in: Mosul, Urfa, Birecik en Sinjar werden veroverd, Imadiya en de andere Koerdische heersers aanvaardden de Ottomaanse onderworpenheid. De vesting Mardin zou pas na de terugkeer van de Pasja uit Marj Dabiq worden overgenomen.", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["Gustav Vasa wordt in Strängnäs tot koning gekozen: het koninkrijk Zweden maakt zich los van de Unie van Kalmar", "a6e95f4c"], "d": ["Gustav Eriksson Vasa, die na het Stockholmse bloedbad (1520) in opstand kwam tegen koning Christiaan II van Denemarken, werd op 6 juni 1523 tot koning gekozen op de in mei 1523 in Strängnäs bijeengekomen Zweedse Riksdag. Zweden en het daaraan gebonden Finland kwamen zo definitief los van de Unie van Kalmar, die sinds 1397 had geduurd, en het Vasa-tijdperk van het onafhankelijke koninkrijk Zweden begon.", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["De Silezische standen erkennen Ferdinand I als koning: Silezië gaat over naar Habsburgs Oostenrijk", "a28e10c2"], "d": ["De Boven- en Neder-Silezische standen erkenden de Habsburger Ferdinand, die in oktober 1526 was gekozen tot de door de dood van Lodewijk II bij Mohács vacante Boheemse kroon, op 5 december 1526 in een algemene vergadering als koning, onder bevestiging van hun privileges, en zijn vrouw Anna als koningin. De Silezische hertogdommen kwamen zo samen met de Boheemse kroon onder Habsburgs bestuur.", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["De Zweedse koning Gustav Vasa sticht Helsinki", "43468b54"], "d": ["De Zweedse koning Gustav Vasa liet in 1550 aan de monding van de rivier Vantaa Helsinki stichten als nieuwe handelsstad, om in de Baltische handel te wedijveren met Reval (Tallinn). De stad werd in 1640 naar haar huidige plek, richting de zee, verplaatst.", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["De Omaanse Ya'rubi-imam Nasir b. Murshid neemt Julfar van de Portugezen", "6ca9fb0c"], "d": ["De Portugezen, die zich ook na de val van Hormuz in 1622 in Julfar hadden gehandhaafd, werden in 1633 door de verovering van de Omaanse Ya'rubi-imam Nasir b. Murshid uit het gebied verdreven.", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["Verlies van de vesting Sinj aan Venetië: het binnenland van Dalmatië", "3af8e103"], "d": ["Tijdens de Morea-oorlog namen Venetiaanse troepen in 1686 de vesting Sinj in het Dalmatische binnenland op de Ottomanen in; de vesting weerstond ook het Ottomaanse beleg van 1715 en bleef bij Venetië.", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["Varaždin en Bač vallen in handen van het koninkrijk Hongarije (Habsburgse kroon): terugtocht uit de Bačka na Harkány", "6bc2b1ac"], "d": ["Het leger van Sarı Süleyman Pasja, dat zich na de nederlaag van Harkány terugtrok, trok op 1 september 1687 door Varadin en liet de vesting aan Câfer Pasja; kort daarna kwamen Varadin en Bač in de Bačka in handen van de geallieerde Habsburgse troepen. Toen in Karlowitz de Sava als grens werd aanvaard, bleef Varadin aan Oostenrijkse zijde.", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["Osijek komt in handen van het koninkrijk Hongarije (Habsburgse kroon): het verlies van Slavonië begint", "7af97ffe"], "d": ["Na de nederlaag van Harkány ging de brugvesting Osijek aan de Drava op 26 september 1687 over naar de Habsburgse troepen. De Ottomaanse militaire aanwezigheid en de Turkse bevolking in Slavonië trokken zich tussen 1686 en 1688 geleidelijk terug; het gebied kwam onder Habsburgs bestuur.", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["Verlies van Herceg Novi aan Venetië: de monding van de Baai van Kotor", "b88046d8"], "d": ["Tijdens de Morea-oorlog belegerden en namen de Venetiaanse vloot en haar bondgenoten in 1687 de vesting Herceg Novi aan de monding van de Baai van Kotor in; de stad bleef bij Venetië tot de val van de Republiek in 1797.", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["Corsica wordt aan de Britse kroon gebonden: het Anglo-Corsicaanse Koninkrijk", "10f18bde"], "d": ["Paoli, die in opstand kwam tegen het revolutionaire Frankrijk, zuiverde met steun van de Britse vloot het eiland van Franse garnizoenen; de in Corte bijeengekomen consulta nam een grondwet aan die Corsica aan de Britse koning bond. Het eiland bleef twee jaar als Anglo-Corsicaans Koninkrijk onder bestuur van de Britse gouverneur-generaal Gilbert Elliot.", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["De Britten ontruimen Corsica: het eiland wordt weer Frans", "c9f986fe"], "d": ["Engeland, dat door de Italiaanse overwinningen van Bonaparte en de overgang van Spanje naar de Franse zijde in het nauw kwam in de Middellandse Zee, ontruimde Corsica. Het Anglo-Corsicaanse Koninkrijk eindigde en het eiland werd weer aan Frankrijk gebonden.", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["Het Oostenrijks-Hongaarse leger breekt het verzet en neemt Bihać in", "ffec53e0"], "d": ["Oostenrijk-Hongarije, dat met het Verdrag van Berlijn het recht kreeg Bosnië-Herzegovina te bezetten, stuitte in Bihać op het verzet van de lokale moslims. De troepen onder bevel van generaal Wilhelm von Reinländer namen de stad op 18 september 1878 in; ook het garnizoen van Ostrovica in de Unavallei ging bij dezelfde operatie voor de Ottomanen verloren.", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["De Britten bezetten Sokoto: het kalifaat van Sokoto verliest zijn hoofdstad", "e744f986"], "d": ["Lugard, de gouverneur van Engeland, dat Noord-Nigeria in 1900 tot kolonie had verklaard, versloeg na de emiraten een voor een te hebben ingenomen het leger van Sokoto zwaar en bezette op 15 maart 1903 de hoofdstad. Met de moord op de gevluchte kalief Tāhir in juli bij Burmi eindigde de politieke heerschappij van het kalifaat.", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["Ibn Saud verslaat de Rashidi-emir: Qasim gaat van het emiraat der Shammar over naar de Saoedi's", "a32201dd"], "d": ["ʿAbd al-ʿAzīz b. Saʿūd, die Riyad in 1902 had heroverd, versloeg en doodde op 13 april 1906 de Rashidi-emir ʿAbd al-ʿAzīz b. Mitʿab. Na deze strijd nam hij de regio Qasim (Buraydah, Unayzah) in; de Rashidi's regeerden daarna alleen nog in Ha'il en omgeving.", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["Het eiland Kamaran wordt door de Britten bezet", "c514bb66"], "d": ["Het eiland Kamaran in de Rode Zee voor de kust van Jemen werd in 1915 tijdens de Eerste Wereldoorlog door de Britten bezet en begon vanuit Aden te worden bestuurd.", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["Bezetting van Nablus door de Britten: de ineenstorting van het Palestijnse front", "b5e85950"], "d": ["In september 1918 versloeg het grote offensief van Allenby aan het Palestijnse front het Ottomaanse 7e en 8e leger; Nablus kwam in handen van de Britten en de Ottomaanse heerschappij van vier eeuwen in de stad eindigde. De stad bleef tot 1920 onder Brits militair bestuur.", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["De Britten trekken Mosul binnen: bezetting van de provincie Mosul in strijd met de wapenstilstand", "ed5e8e33"], "d": ["Toen de wapenstilstand van Moedros werd getekend, was Mosul in handen van de Turkse troepen. De Britten trokken op grond van artikel 7 van de wapenstilstand op 8 (of 10) november 1918 de stad binnen en op 15 november moesten de Turkse eenheden zich uit de provincie terugtrekken. De kwestie-Mosul kon ook in Lausanne niet worden opgelost en werd overgelaten aan het Verdrag van Ankara van 1926.", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["Verdrag van Lausanne: Patmos wordt aan Italië gelaten, de Griekse soevereiniteit over de Egeïsche eilanden wordt bevestigd", "185960b3"], "d": ["Met artikel 15 van Lausanne deed Turkije afstand van alle rechten en titels op de Dodekanesos, Patmos inbegrepen, ten gunste van Italië; de eilanden waren sinds 1912 feitelijk onder Italiaanse bezetting. Artikel 12 bevestigde de Griekse soevereiniteit over Lemnos, Samothrake, Lesbos, Chios, Samos en Ikaria. Agios Efstratios en Fourni waren sinds 1912 in Griekse handen en bleven ook na Lausanne bij Griekenland; deze twee namen zelf worden niet genoemd in artikel 12 van Lausanne.", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["Tunceli-wet: de provincie Tunceli wordt gevormd in plaats van het sandjak Dersim (centrum Kalan)", "1ae9ad50"], "d": ["Met wet nr. 2885 werd besloten in het gebied Dersim een nieuwe provincie genaamd Tunceli te vormen; het bestuurlijke centrum van de provincie werd de nederzetting Kalan en die nederzetting nam later de naam Tunceli aan. Het gebied bleef binnen de Republiek Turkije; wat veranderde was de bestuurlijke status en de naam.", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["Onafhankelijkheid van Marokko: het Franse protectoraat eindigt, Salé en Rabat blijven bij het Koninkrijk Marokko", "a62a3fdb"], "d": ["Met het op 2 maart 1956 getekende onafhankelijkheidsverdrag eindigde het Franse protectoraat, dat sinds 1912 had geduurd; Salé en Rabat werden grondgebied van het onafhankelijke Koninkrijk Marokko. Spanje erkende de onafhankelijkheid van Marokko op 5 april 1956.", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["De Nieuwe Hebriden worden onafhankelijk: de Republiek Vanuatu wordt gesticht", "cc93330f"], "d": ["Het Condominium van de Nieuwe Hebriden, onder gezamenlijke soevereiniteit van Frankrijk en het Verenigd Koninkrijk, werd op 30 juli 1980 onafhankelijk onder de naam Vanuatu. De hoofdstad Port Vila op het eiland Efate en de nederzetting Teouma gingen van het bestuur van het condominium over naar Vanuatu.", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["Zuid-Afrika draagt Walvisbaai (Walvis Bay) over aan Namibië", "96bb0184"], "d": ["De Republiek Zuid-Afrika droeg op 1 maart 1994 de haven van Walvisbaai en twaalf eilanden voor de kust over aan de regering van Namibië; de Zuid-Afrikaanse controle van vierentachtig jaar eindigde.", "fdd93117"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Jaghbub, het woestijncentrum van de Senoessi, gebonden aan de Osmaanse orde — firman van vrijstelling van Abdülmecid", "039fce6d"], "d": ["Muhammad b. Ali as-Senussi, die jarenlang in Mekka had verbleven, vestigde zich na zijn terugkeer naar Tripolitanië in de oase Jaghbub aan de Egyptische grens en liet op een dominante rots een grote zawiya bouwen; de plek, die uit enkele barakken bestond, veranderde snel in een stad. In 1856 werden met een firman van sultan Abdülmecid de bezittingen van de aanhangers van de orde van belasting vrijgesteld en kregen de murids de bevoegdheid om zakat te innen. Deze firman maakte de oase aan de karavaanroute die West-Afrika en Soedan met Caïro verbond tot een deel van de Osmaanse financiële en administratieve orde en versterkte Jaghbub als handelscentrum. De trouw van de bevolking van de regio aan de kalief wordt ook bevestigd door het reisverslag van kolonel Sâdık al-Mu'ayyad, die de plaats in 1884 en 1893 bezocht.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Begin van het graven van het Suezkanaal en stichting van Port Said", "cef0be8d"], "d": ["De graafwerkzaamheden van het project-Lesseps, dat de Hoge Porte op 5 januari 1856 goedkeurde, begonnen op 25 april 1859; het kanaal zou tien jaar later, op 16 november 1869, worden voltooid. Aan het Middellandse Zee-uiteinde van de uitgraving vormde het barakkendorp van vijf huizen voor arbeiders op de kuststrook tussen het Manzala-meer en de zee de kern van Port Said. De stad kreeg in 1860 door toedoen van de functionarissen van de kanaalmaatschappij deze naam, die 'haven van Said' betekent, ter ere van de toenmalige gouverneur van Egypte, Said Pasja. Zo ontstond op de Osmaanse kaart een nieuwe haven aan een kuststrook waar eerder geen enkele nederzetting had gelegen.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Bezoek van sultan Abdülaziz aan Egypte en stichting van Ismailia op de landengte van Suez", "bcfacf38"], "d": ["Sultan Abdülaziz ging op 3 april 1863 op aansporing van grootvizier Yûsuf Kâmil Pasja naar Egypte en werd met groot vertoon ontvangen; het doel was de band met het centrum van de provincie te versterken die sinds de opstand van Mehmed Ali van Kavala feitelijk een afzonderlijke staat begon te worden. In hetzelfde jaar werd op de landengte, op de heuvels van Tell el-Gisr aan de oever van het Timsah-meer, het bestuurscentrum van de kanaalmaatschappij gevestigd: eerst werden voor de ingenieurs de dorpen Qaryat at-Timsah en daarna voor de arbeiders het dorp Qaryat al-Arab gebouwd. Toen khedive İsmâil Pasja zich nauw bezighield met het zoetwaterkanaal en zich op deze heuvel een paviljoen liet bouwen, werd de nederzetting naar hem Ismailia genoemd. De stichting van de stad wordt gedateerd op het jaar 1863; de precieze dag is niet bekend.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Gouverneurschap van Midhat Pasja in Bagdad en vestiging van stammen — stichting van Ramadi en Nasiriyah", "0fa98f06"], "d": ["Midhat Pasja, die van het voorzitterschap van de Şûrâ-yı Devlet werd ontheven en uit Constantinopel verwijderd, bestuurde tussen 1869 en 1872 de provincie Bagdad, die ook Mosul en Basra omvatte, met brede bevoegdheden, ook als bevelhebber van het Zesde Leger. Hij paste hier de Land-kanunname en de nieuwe vilayet-wet toe, verdeelde het land bij tapu en bond de nomadische stammen aan een gevestigde levenswijze en het staatsgezag. Als product van dit vestigingsbeleid werd in 1869 aan de oever van de Eufraat Ramadi voor de Dulaym-stam gesticht en in het zuiden Nasiriyah door toedoen van de mutasarrıf van Muntafiq, Nasir Pasja as-Sa'dun; beide ontstonden op plaatsen waar tot dan toe geen nederzetting was en kwamen voor het eerst op deze datum op de kaart.", "7babb36f"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["Koenraad II wordt tot Duits koning gekozen en in Mainz gekroond: de Salische dynastie begint", "c88123e8"], "d": ["Na de dood van Hendrik II kwamen de Duitse vorsten op 4 september 1024 samen in Kamba aan de rechteroever van de Rijn; de verkiezing werd geleid door Aribo, aartsbisschop van Mainz. Koenraad de Oudere won van zijn neef Koenraad de Jongere en werd op het feest van Maria Geboorte (8 september) in Mainz door Aribo tot koning gekroond.", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["Keizer Koenraad II sterft in Utrecht", "f967406b"], "d": ["Koenraad II, de eerste keizer van de Salische dynastie, stierf op 4 juni 1039 in Utrecht na een korte en pijnlijke ziekte.", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["Concordaat van Worms: de Investituurstrijd eindigt", "8073e4a0"], "d": ["De vrede tussen keizer Hendrik V en paus Calixtus II, tot stand gekomen door bemiddeling van een pauselijke delegatie, werd op 23 september 1122 in Worms (in Lobwiesen, vlak bij de stad) afgekondigd. Hendrik zag af van investituur met ring en staf en aanvaardde de kerkelijke verkiezing van bisschoppen en abten.", "a915c2e7"]},
"OLAYLAR_ALM1115B:1125-05-23:0":{"b": ["Keizer Hendrik V sterft in Utrecht", "790cadc4"], "d": ["Keizer Hendrik V stierf op 23 mei 1125 in Utrecht; hij wordt herinnerd als de keizer van het Concordaat van Worms (1122).", "8402ca28"]},
"OLAYLAR_ALM1115B:1152-03-05:0":{"b": ["Frederik I Barbarossa wordt in Frankfurt tot Duits koning gekozen", "b91f29a3"], "d": ["De vorsten verhieven Frederik op 5 maart 1152 in Frankfurt tot koning; hij werd op 9 maart in Aken gekroond. Zo begon de Barbarossa-tijd van de Hohenstaufen-dynastie.", "26fcdb8c"]},
"OLAYLAR_ALM1115B:1156-09-17:0":{"b": ["Privilegium Minus: Oostenrijk wordt hertogdom, Beieren wordt aan Hendrik de Leeuw gegeven", "a64c125b"], "d": ["Bij uitspraak van de vorsten in Regensburg werd Oostenrijk tot hertogdom verheven en kregen Hendrik Jasomirgott bijzondere rechten; in dezelfde regeling gaf Hendrik Beieren terug aan de keizer en de keizer gaf Beieren als leen aan Hendrik de Leeuw.", "fe899d87"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["Met het uitsterven van het geslacht Zähringen wordt Bern een vrije rijksstad", "1473c219"], "d": ["Toen de dynastie van Zähringen in 1218 uitstierf, werd Bern een rechtstreeks aan het rijk gebonden vrije stad; in 1353 trad het als achtste lid toe tot de Zwitserse Confederatie.", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["Landgraafschap Hessen: Hendrik I van Brabant wordt de eerste Hessische landgraaf, vrede met Meißen in 1264", "57067f04"], "d": ["De geschiedenis van Hessen als zelfstandig land begint met Hendrik I ('het Kind'); de vrede met Meißen werd in 1264 gesloten. Hendrik liet in Kassel een kasteel bouwen, dat in de volgende jaren zijn gewone residentie werd; in 1292 werd hij in de rijksvorstenstand (Reichsfürstenstand) opgenomen.", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["Het graafschap Schwerin komt bij overeenkomst in handen van hertog Albrecht II van Mecklenburg", "013b6860"], "d": ["Albrecht II verwierf met de overeenkomst van 1 december 1358 het graafschap Schwerin door graaf Nicolaus 10.000 mark zilver te betalen; de stad werd vanaf die datum grondgebied van het hertogdom Mecklenburg (haar vestiging als hoofdstad werd in de 16e eeuw blijvend).", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["Landgraaf Filips 'de Grootmoedige' sterft in Kassel: Hessen wordt onder zijn vier zonen verdeeld", "c0cb27ed"], "d": ["Landgraaf Filips I van Hessen, een van de politieke leiders van de Reformatie, stierf op 31 maart 1567 in Kassel. Volgens zijn testament van 1562 werd het land onder zijn vier zonen verdeeld als Hessen-Kassel (Wilhelm IV), Hessen-Marburg (Lodewijk IV), Hessen-Rheinfels (Filips II) en Hessen-Darmstadt (Georg); het verenigde landgraafschap Hessen eindigde zo.", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["De laatste hertog van Pommeren, Bogislaw XIV, sterft in Stettin: de Griffioen-dynastie eindigt", "ab96746a"], "d": ["Bogislaw XIV, de laatste hertog van Pommeren, stierf op 10 maart 1637 in Stettin en met hem was de inheemse Pommerse dynastie uitgestorven. De feitelijke verdeling van het hertogdom (Brandenburg-Zweden) werd door de Vrede van Westfalen van 1648 bekrachtigd.", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["Ferdinand III verleent Bremen de privileges van een vrije rijksstad", "174142ee"], "d": ["Keizer Ferdinand III erkende in 1646 de privileges van een vrije rijksstad voor Bremen; Zweden verzette zich hiertegen en probeerde in 1666 de stad met wapengeweld te onderwerpen, zonder succes. Toen de keurvorst van Hannover het aartsbisdom verwierf (1720), erkende hij Bremen als vrije stad.", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["Bremen wordt bij het Franse Keizerrijk gevoegd: het wordt het centrum van het departement Monden van de Wezer", "d5d149ae"], "d": ["Bremen was in 1806 door de Fransen ingenomen en was van 1810 tot 1813 het centrum van het departement Monden van de Wezer (Bouches-du-Weser).", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["Napoleon voegt Lübeck bij het Franse Keizerrijk", "1ca78afe"], "d": ["Na de capitulatie van Blücher bij Lübeck in november 1806 was de stad door de Fransen geplunderd en in december 1810 voegde Napoleon de stad bij zijn rijk. Lübeck was tot die datum sinds 1226 een vrije rijksstad.", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["Lübeck komt in opstand tegen de Franse heerschappij en herwint de status van vrije stad", "84e70d49"], "d": ["Lübeck, dat in 1813 tegen het Franse bestuur in opstand kwam, werd in 1815 door het Congres van Wenen erkend als vrije stad en Hanzestad van de Duitse Bond.", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["De Franse heerschappij eindigt: Bremen herwint de status van vrije stad", "4afa71be"], "d": ["Het verblijf van Bremen onder Frans bestuur als centrum van het departement Monden van de Wezer eindigde in 1813; de stad kreeg in 1815 door het Congres van Wenen haar onafhankelijkheid terug en trad toe tot de Duitse Bond.", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["Het hertogdom Mecklenburg-Schwerin neemt de titel groothertogdom aan", "3f5d05eb"], "d": ["Hertog Frederik Frans I van Mecklenburg-Schwerin nam in 1815 de titel groothertog ('großherzogliche Würde') aan; het register van het hertogdom Mecklenburg (1348-1815) eindigt op dit punt, het land gaat verder als groothertogdom binnen de Duitse Bond.", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["De Groot-Hamburgwet treedt in werking: de status van Lübeck als zelfstandige deelstaat eindigt", "6df2f92a"], "d": ["De op 26 januari 1937 uitgevaardigde Groot-Hamburgwet trad op 1 april 1937 in werking; Lübeck verloor zijn autonomie van meer dan 700 jaar en werd gebonden aan de Pruisische provincie Sleeswijk-Holstein, de grenzen van Hamburg werden uitgebreid.", "b96594d2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["Raetia en Noricum worden bij Rome gevoegd: Tiberius en Drusus nemen het gebied voorbij de Alpen in", "be6f2a15"], "d": ["In 15 v.Chr. versloegen Tiberius en Drusus de Alpenstammen en voltooiden Raetia (en de annexatie van Noricum); de bovenloop van de Donau werd de Romeinse grens.", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["Met de dood van Amyntas wordt Galatië een Romeinse provincie", "e4250ad7"], "d": ["Toen de door Antonius benoemde Galatische koning Amyntas in Cilicië werd gedood (25 v.Chr.), maakte Augustus Galatië tot Romeinse provincie en voegde het samen met Pisidië en Lycaonië. De hoofdstad werd Ancyra (Ankara); het opschrift Res Gestae van Augustus (Monumentum Ancyranum) werd hier geschreven.", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["Octavianus neemt de titel \"Augustus\" aan: het tijdperk van het Principaat (keizerrijk) begint", "310297b6"], "d": ["Op 16 januari 27 gaf de Senaat Octavianus de titel Augustus; Octavianus kreeg voor lange tijd het bevel (imperium) over het grootste deel van de provincies. Deze datum geldt als het begin van het Romeinse Keizerrijk.", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["Bocchus II sterft; Mauretania komt onder controle van Octavianus", "414fa36c"], "d": ["Toen Bocchus II in 33 kinderloos stierf, kwam Mauretania onder Romeins bestuur doordat Octavianus het bij testament erfde; het bleef enige tijd rechtstreeks onder Romeins bestuur en werd in 25 aan Juba II gegeven.", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["Antonius maakt Archelaüs koning van Cappadocië", "1e83e691"], "d": ["Bij de herordening van het Oosten gaf Antonius de troon van Cappadocië aan Archelaüs; Archelaüs regeerde tot hij in 17 n.Chr. door Tiberius naar Rome werd geroepen. Cappadocië werd in 17 n.Chr. een Romeinse provincie (deze gebeurtenis is een afzonderlijk item in de kronologie).", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["Philippi: Octavianus en Antonius verslaan Brutus en Cassius", "4386016f"], "d": ["In oktober 42 werden bij Philippi twee afzonderlijke veldslagen geleverd; Cassius en Brutus pleegden zelfmoord en de republikeinse macht verdween. De triumviren verdeelden de Romeinse wereld onder elkaar.", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["Julius Caesar laat Korinthe als Romeinse kolonie herstichten", "283a5daa"], "d": ["Kort vóór de moord op Caesar werden in Korinthe Romeinse burgerkolonisten (meest vrijgelatenen) gevestigd; de stad werd een van de belangrijke centra van de Romeinse provincie Achaea. Het besluit tot herstichting dateert van 44 v.Chr., de vestiging van 44/43 v.Chr.", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["Burebista valt ten prooi aan een moordaanslag: het Dacische koninkrijk valt uiteen", "9b9edb14"], "d": ["Strabo schrijft dat Burebista vóór de dood van Caesar door een interne staatsgreep werd gedood en dat het koninkrijk in vijf en daarna vier delen werd verdeeld. De Dacische eenheid kon pas onder Decebalus (87 n.Chr.) worden hersteld.", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["Caesar wordt op de Iden van maart (15 maart) in de Senaat vermoord", "18649074"], "d": ["Caesar, die tot dictator voor het leven was uitgeroepen, werd op 15 maart 44 tijdens een vergadering van de Senaat in het Theater van Pompeius door een groep senatoren doodgestoken. Zijn dood bereidde de bodem voor nieuwe burgeroorlogen en de macht van Augustus.", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["Munda: Caesar verslaat de zonen van Pompeius", "e1e93362"], "d": ["Op 17 maart 45 versloeg Caesar bij Munda het leger van Gnaeus Pompeius en Sextus Pompeius; Hispania bleef in handen van Caesar. Het is de laatste grote veldslag van de burgeroorlog.", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["Thapsus: Caesar verslaat Juba I; Oost-Numidië wordt de provincie Africa Nova", "77b28c50"], "d": ["In het voorjaar van 46 versloeg Caesar bij Thapsus het leger van Scipio en Juba I; Juba pleegde zelfmoord. Het oostelijke deel van Numidië werd de provincie Africa Nova, bestuurd door Sallustius, het westelijke deel werd aan Bocchus en Sittius gegeven.", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["Zela: Caesar verslaat Pharnaces II (\"veni vidi vici\")", "11bf082a"], "d": ["Pharnaces II, zoon van Mithridates, probeerde van de burgeroorlog gebruik te maken om Pontus terug te nemen; Caesar versloeg hem in 47 bij Zela en herordende Pontus onder Romeinse controle. Pharnaces vluchtte naar het Bosporanenrijk en stierf daar.", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["Pharsalus: Caesar verslaat Pompeius", "e821abe8"], "d": ["Caesar versloeg na de terugtocht bij Dyrrhachium bij Pharsalus het grotere leger van Pompeius. Pompeius vluchtte naar Egypte en werd gedood; de oostelijke provincies stonden open voor Caesar.", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["Alesia: Caesar belegert en verslaat Vercingetorix, het Gallische verzet wordt gebroken", "d57cab9f"], "d": ["In 52 v.Chr. werd de Gallische opstand onder leiding van de Arverner Vercingetorix neergeslagen door Caesars beleg van Alesia en de verdediging van zijn belegeringslinie; Vercingetorix gaf zich over. Gallië kwam het volgende jaar geheel onder Romeinse controle.", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["Caesars Gallische veldtocht begint: de Helvetii worden verslagen", "1e594bb3"], "d": ["In 58 v.Chr. stopte Caesar als gouverneur van Gallia Cisalpina en Transalpina de migratie van de Helvetii bij Bibracte; daarna versloeg hij de Germanen van Ariovistus. De veldtocht zou acht jaar duren en Gallië bij Rome voegen.", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["Mithridates VI sterft in Pantikapaion; het Bosporanenrijk blijft aan Pharnaces", "0831b871"], "d": ["Mithridates, die voor Pompeius gevlucht was, pleegde na de opstand van zijn zoon Pharnaces zelfmoord in de vesting Pantikapaion (63). Pharnaces leverde het Bosporanenrijk aan Pompeius uit en werd erkend als bevriend koning van Rome.", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["Pompeius verenigt Bithynië met het westen van Pontus en sticht de provincie Bithynia et Pontus", "b2865ea8"], "d": ["Bij de Oost-regeling (65-63) schiep Pompeius de provincie Bithynia et Pontus door Bithynië te verenigen met de westelijke helft van Pontus; de binnenlandse gebieden van Pontus in het oosten werden aan lokale vorsten gegeven.", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["Pompeius erkent Commagene als vriend en bondgenoot van Rome", "a48ba55c"], "d": ["Bij de Oost-regeling bevestigde Pompeius het koninkrijk van Antiochus I en een deel van het gebied van Seleucia (Zeugma) en maakte zo van Commagene een bondgenootschappelijke bufferstaat tussen Rome en Parthië. Het koninkrijk werd in 17 n.Chr. en definitief in 72 n.Chr. bij de Romeinse provincie gevoegd (deze gebeurtenissen zijn afzonderlijke items in de kronologie).", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["Pompeius verslaat Mithridates; Pontus wordt aan Rome gebonden", "8f3f50a6"], "d": ["Pompeius versloeg in 66 in de vlakte van de Lycus 's nachts het leger van Mithridates; Mithridates vluchtte via Colchis naar het Bosporanenrijk. De kuststeden van Pontus kwamen onder Romeinse controle en in 63 werd de provincie, verenigd met Bithynië, gevormd.", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["Antiochus I Theos bestijgt de troon van Commagene", "b1680d3f"], "d": ["Antiochus I, koning van Commagene, liet het grafheiligdom op de Nemrut Dağı bouwen dat Perzische en Macedonische afkomst verenigt. Het koninkrijk lag als buffer tussen Rome en Parthië.", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["Cyrene wordt Romeinse provincie (Cyrenaica)", "f9993ffb"], "d": ["Twintig jaar nadat Ptolemaeus Apion zijn koninkrijk aan Rome had nagelaten (96), bracht Rome Cyrenaica onder het provinciale stelsel; in 67 werd het met Kreta verenigd.", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["Nicomedes IV laat zijn koninkrijk aan Rome na", "e29d9fbc"], "d": ["Met de dood van Nicomedes IV (75/74) kwam Bithynië bij testament aan het Romeinse Volk; Mithridates VI aanvaardde dit niet en de Derde Mithridatische Oorlog begon. Bithynië werd een rechtstreekse Romeinse provincie.", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["Burebista verenigt de Dacische en Getische stammen", "3648f92e"], "d": ["Volgens Strabo bracht Burebista de Geten en Daciërs samen in één koninkrijk en voerde hij veldtochten ten zuiden van de Donau tot aan de grenzen van Thracië en Illyrië. Het koninkrijk begon langs de Donau een bedreiging voor Rome te vormen.", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["Vrede van Dardanos: Mithridates trekt zich terug uit Asia en Bithynië", "535818ed"], "d": ["In de vrede van Dardanos met Sulla stemde Mithridates ermee in al zijn veroveringen (Asia, Bithynië, Cappadocië, Paphlagonië) te ontruimen en 70 schepen en 2000-3000 talenten te geven. Maar het feit dat in Rome de vijanden van Sulla de overhand kregen, leidde tot de Tweede Mithridatische Oorlog.", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["Mithridates valt de provincie Asia binnen; de Efesische Vespers (bloedbad onder 80.000 Romeinen)", "3986833b"], "d": ["Aan het begin van de Eerste Mithridatische Oorlog (89/88) viel Mithridates Bithynië en de provincie Asia binnen; op zijn bevel in Efeze werden Romeinse burgers massaal gedood. Ook Athene koos de zijde van Pontus (Aristion).", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia: Rome verleent burgerrecht aan de Italische bondgenoten (Bondgenotenoorlog)", "f72ba27d"], "d": ["Na de opstand van de Italische bondgenoten van Rome (91-88) verleenden de Lex Iulia (90) en de Lex Plautia Papiria (89) het Romeinse burgerrecht aan de trouwe en onderworpen bondgenoten. Zo werd het Italische schiereiland tot aan de Po één burgergemeenschap.", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["Sulla zet Ariobarzanes op de troon van Cappadocië", "8bdd078c"], "d": ["Tegen het feit dat Mithridates VI Cappadocië via een kindkoning in handen hield, liet Rome tijdens Sulla's gouverneurschap van Cilicië Ariobarzanes tot koning uitroepen. Cappadocië werd in de volgende eeuw de buffer in de Romeins-Perzisch-Pontische twisten.", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["Ptolemaeus Apion laat Cyrene aan Rome na", "5edef477"], "d": ["Ptolemaeus Apion, die over Cyrene regeerde, liet bij zijn kinderloze dood zijn koninkrijk aan het Romeinse Volk na (96); de Senaat liet de steden vrij en stelde de omvorming tot provincie door Rome uit tot 74.", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["Bocchus levert Jugurtha aan Rome uit; het westen van Numidië wordt bij Mauretania gevoegd", "7619ad15"], "d": ["Bocchus I, koning van Mauretania en schoonvader van Jugurtha, verzoende zich met Rome door Jugurtha aan Sulla uit te leveren; in ruil daarvoor werd het westelijke deel van Numidië aan hem gelaten. Jugurtha stierf in 104 in de gevangenis in Rome.", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["Pairisades V laat zijn koninkrijk aan Mithridates VI na: het Bosporanenrijk wordt aan Pontus gebonden", "835bbe74"], "d": ["Pairisades V, onder Scythische druk, droeg met hulp van Mithridates' bevelhebber Diophantos het koninkrijk over aan Mithridates; het Bosporanenrijk werd zo de noordelijke uitloper van Pontus. De graanhandel van de Zwarte Zee ging als bron van Mithridates op deze datum naar Pontus over.", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["Mithridates' bevelhebber Diophantos verslaat de Scythen op de Krim", "d8d48c68"], "d": ["Diophantos versloeg het leger van Palakos, zoon van de Scythische koning Skilouros, en nam de omgeving van Neapolis in Taurica in; het Bosporanenrijk en Chersonesos werden aan Pontus gebonden.", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["Jugurtha neemt Cirta in: Rome grijpt in in de Numidische aangelegenheden", "660eb34a"], "d": ["In 112 v.Chr. belegerde Jugurtha Cirta en doodde Adherbal; de in de stad gedode Italische kooplieden dreven Rome ertoe Jugurtha de oorlog te verklaren. De oorlog duurde tot 105.", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["Narbo Martius wordt gesticht: Zuid-Gallië (Gallia Transalpina) wordt Romeinse provincie", "20c4bdfa"], "d": ["Rome, dat op verzoek van Massalia om hulp (125) Gallië was binnengetrokken, nam met de overwinningen bij Aquae Sextiae (122) en op de Allobroges de Rhônevallei in; in 118 v.Chr. werd Narbo Martius als eerste Romeinse kolonie in Gallië gesticht. Het gebied werd de provincie Gallia Transalpina.", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["Mithridates VI Eupator bestijgt de troon van Pontus", "c2d5fd41"], "d": ["Mithridates VI, die met de dood van Mithridates V (120/119) als kind de troon besteeg, maakte na enkele jaren voogdij van Pontus een macht rond de Zwarte Zee die met Rome wedijverde.", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["Op verzoek van Massalia trekt Rome Gallië binnen", "eaf7eb0a"], "d": ["Toen Massalia, onder druk van de Salluvii en Liguren, Rome om hulp vroeg, zond Rome in 125 een leger naar Zuid-Gallië. Deze interventie leidde tot de stichting van Narbo Martius (118) en de inname van Gallia Transalpina.", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["Aristonicus wordt verslagen; uit het grondgebied van Pergamon wordt de provincie Asia gesticht", "7ccdc59e"], "d": ["Aristonicus, die onder de naam Eumenes III aanspraak maakte op de troon, werd door het Romeinse leger verslagen en gevangengenomen (129); door de regeling van Manius Aquillius werd het voormalige koninkrijk Pergamon de provincie Asia. Het belastingstelsel van de provincie (publicani) was voor Rome een grote inkomstenbron.", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["Numantia valt: Keltiberië wordt bij Rome gevoegd", "ced07244"], "d": ["Scipio Aemilianus dwong Numantia na een beleg van acht maanden door uithongering tot overgave (133); de stad werd verwoest. De Keltiberische oorlogen eindigden en het binnenland van Hispania Citerior werd bij Rome gevoegd.", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["Achaeïsche Oorlog: de Achaeïsche Bond wordt door Rome verslagen, de verbonden worden ontbonden", "e434cfe0"], "d": ["De Achaeïsche Bond, die wegens een grensgeschil met Sparta tegen Rome in opstand kwam, werd in 146 bij Leukopetra verslagen; Korinthe werd verwoest en de Bond feitelijk ontbonden, een deel van Griekenland kwam onder toezicht van de provincie Macedonië.", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["De Derde Punische Oorlog eindigt: Carthago wordt verwoest, de provincie Africa wordt gesticht", "522515b4"], "d": ["Na een beleg van drie jaar nam P. Cornelius Scipio Aemilianus in het voorjaar van 146 Carthago in; de stad werd in brand gestoken en verwoest, het grondgebied werd bij Rome gevoegd. Het achterland van Carthago werd de provincie Africa; het Numidië van Masinissa bleef in het westen buur.", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["Macedonië wordt Romeinse provincie", "dc6d2352"], "d": ["Na de neerslaging van de opstand van Andriscus (148) werden de vier districten van Macedonië verenigd tot één Romeinse provincie (146); ook de controle over Griekenland in het zuiden van de provincie werd onder toezicht van de gouverneur van Macedonië geplaatst. De Via Egnatia werd in de volgende jaren aangelegd van de Adriatische Zee naar Thessaloniki.", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["Opstand van Andriscus: het koninkrijk Macedonië wordt kort hersteld en door Metellus neergeslagen", "0119ff73"], "d": ["Andriscus, die beweerde de zoon van Perseus te zijn, verenigde in 150/149 Macedonië opnieuw en versloeg de eerste Romeinse troepen; in 148 nam Metellus Macedonië terug. De opstand werd de reden dat Macedonië rechtstreeks aan Romeins bestuur werd gebonden.", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["Rome verklaart Carthago de oorlog: de Derde Punische Oorlog begint", "2e34c235"], "d": ["Dat Carthago zich tegen de aanvallen van Masinissa verdedigde, werd als een schending van het verdrag beschouwd; Rome verklaarde in 149 de oorlog en bond Utica aan zich. De stad Carthago hield drie jaar lang stand onder belegering.", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["Masinissa valt het grondgebied van Carthago aan: de Numidisch-Carthaagse oorlog", "b47559a5"], "d": ["Nadat Masinissa Carthaags grondgebied had ingenomen (151/150), verklaarde Carthago de oorlog en werd door Masinissa verslagen; Rome beschouwde dit als schending van het verdrag en verklaarde in 149 de oorlog. Masinissa stierf in 148 op negentigjarige leeftijd.", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["Rome beveelt Rhodos zijn gouverneurs uit Lycië en Carië terug te trekken; de Lycische Bond (Patara) komt los van Rhodische heerschappij", "6bbe2b54"], "d": ["Na de Derde Macedonische Oorlog beval de Romeinse Senaat Rhodos zijn gouverneurs in Lycië en Carië vóór een bepaalde dag terug te trekken; Rhodos aanvaardde dit verlies, dat het lichter achtte dan de dreiging van oorlog. De Lycische Bond (met Patara als centrum) kwam zo los van Rhodische heerschappij en bleef bestaan als Lycische Bond onder Romeinse bescherming.", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["Epirus wordt door Rome geplunderd: zeventig steden worden verwoest", "456fb461"], "d": ["Na de Derde Macedonische Oorlog werden de Molossische steden van Epirus die aan de kant van Perseus waren gebleven, op bevel van Aemilius Paullus geplunderd en werden ongeveer 150.000 mensen tot slaaf gemaakt. Epirus bleef in de volgende eeuw onder Romeinse heerschappij arm.", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["Macedonië wordt door Rome verdeeld in vier autonome districten (merides)", "7a795ba0"], "d": ["Bij besluit van de Senaat (167 v.Chr.) werd het koninkrijk Macedonië verdeeld in vier districten met Amphipolis, Thessalonike (Thessaloniki), Pella en Pelagonia als centra; huwelijken en eigendomsverwerving tussen de districten werden verboden, de mijnbouw beperkt.", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["Rome neemt Lycië en Carië van Rhodos af; Delos wordt tot vrijhaven verklaard", "09c8143f"], "d": ["De poging van Rhodos in de Derde Macedonische Oorlog om te bemiddelen tussen Rome en Perseus werd gestraft: de Senaat nam Lycië en Carië van Rhodos af en verklaarde ze vrij, gaf Delos aan Athene en maakte er een haven zonder douanerechten van. De handelsinkomsten van Rhodos daalden sterk.", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["Pydna: Aemilius Paullus verslaat Perseus; het Antigonidische koninkrijk eindigt", "a59c5270"], "d": ["Op 22 juni 168 versloegen de Romeinse legioenen bij Pydna de Macedonische falanx en beëindigden de Derde Macedonische Oorlog; Perseus gaf zich over bij Samothrake en werd naar Rome gebracht voor de triomftocht. De Antigonidische dynastie eindigde.", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["Vrede van Apameia: Eumenes II verwerft voor Pergamon de Thracische Chersonesos, Frygië, Lydië en het grootste deel van Mysië", "f25ed9af"], "d": ["Na de nederlaag bij Magnesia sloot Antiochus III in 188 vrede met Rome: hij liet het gebied ten noorden van het Taurusgebergte over. Het grootste deel van dit gebied werd gegeven aan het Pergamon van de bondgenoot Eumenes II (de Thracische Chersonesos, Groot-Frygië, Lydië, Mysië, een deel van Ionië).", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["Vrede van Apameia: Rhodos krijgt Lycië en het zuiden van Carië", "aa5173c6"], "d": ["Na Magnesia gaf Rome aan de bondgenoot Rhodos Lycië en het deel van Carië ten zuiden van de Meander. Rhodos verloor deze gebieden in 167.", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["Manlius Vulso verslaat de Galatische stammen: de onafhankelijkheid van de Galaten komt onder Romeins toezicht", "30ae73d7"], "d": ["Na Magnesia viel Cn. Manlius Vulso Galatië binnen en versloeg bij Olympos en Magaba de Tolistoagii en Tectosagen; bij verdrag stemden de Galaten ermee in hun buren niet aan te vallen. Galatië bleef grotendeels onafhankelijk, maar werd gebonden aan het Romeins-Pergamenische evenwicht.", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["Aetolië sluit vrede met Rome: het verliest Ambracia en Oeniadae en erkent de suprematie van Rome", "f332c6bf"], "d": ["Aetolië, dat in de Antiochische Oorlog aan de kant van Antiochus had gestaan, sloot na het beleg van Ambracia door Fulvius Nobilior vrede met Rome; het erkende de \"majesteit\" van Rome, betaalde een schadevergoeding en liet steden als Ambracia en Oeniadae over.", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["Magnesia ad Sipylum: Rome en Pergamon verslaan Antiochus III", "f650ef21"], "d": ["In de winter van 190/189 versloegen L. Scipio en Eumenes II bij Magnesia het leger van Antiochus III. De na de overwinning gesloten vrede van Apameia (188) leidde ertoe dat Antiochus het gebied ten noorden van de Taurus liet varen.", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["Sparta treedt toe tot de Achaeïsche Bond: Philopoemen bindt Laconië na Nabis aan de bond", "2629b6e1"], "d": ["Na de moord op de Spartaanse tiran Nabis (192) voegde de Achaeïsche strateeg Philopoemen Sparta met geweld bij de Achaeïsche Bond. Sparta verloor zijn onafhankelijkheid in 188 volledig met de sloop van de muren.", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["Flamininus verkondigt op de Isthmische Spelen de vrijheid van de Grieken", "3d850bf2"], "d": ["Na Kynoskephalai verkondigde de Romeinse bevelhebber T. Quinctius Flamininus op de Isthmische Spelen van 196 v.Chr. dat de Macedonische garnizoenen in Korinthe, Chalkis en Demetrias zouden worden teruggetrokken en dat de Griekse steden \"vrij, belastingvrij en gebonden aan hun eigen wetten\" waren. Rome vestigde zich zo als scheidsrechter van Griekenland.", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["Kynoskephalai: Rome verslaat Philippus V; Macedonië moet zich uit Griekenland terugtrekken", "9cb44ca6"], "d": ["In juni 197 versloegen de Romeinse legioenen van Flamininus bij Kynoskephalai de Macedonische falanx. In de vrede van 196 liet Philippus alle posities in Griekenland (Demetrias, Chalkis, Korinthe) varen, leverde zijn vloot uit en betaalde 1000 talenten.", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["In Hispania worden twee Romeinse provincies gevormd: Citerior en Ulterior", "1baa8383"], "d": ["De van Carthago afgenomen gebieden van Hispania werden in 197 voor het eerst verdeeld in twee afzonderlijke provincies, elk bestuurd door een praetor. Na deze datum werden de Keltiberische en Lusitaanse oorlogen op het schiereiland gevoerd om het Romeinse provinciestelsel uit te breiden.", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["Vrede na Zama: Carthago verliest Hispania en de Middellandse-Zee-eilanden en zijn vloot, en aanvaardt een schadevergoeding van 10.000 talenten", "8654422d"], "d": ["Na Zama (202) perste Rome Carthago terug tot zijn eigen gebied in Afrika: de voorwaarden waren het afstaan van Hispania en de Middellandse-Zee-eilanden, het uitleveren van de vloot (op 10 schepen na), het betalen van 10.000 talenten gedurende 50 jaar en het niet voeren van oorlog zonder toestemming van Rome. Het Numidië van Masinissa werd een onafhankelijke buur.", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["Rome beloont Masinissa met het koninkrijk van Syphax", "54ba7a64"], "d": ["In de vrede van Zama benoemde Rome Masinissa tot heerser over het koninkrijk van Syphax en de van Carthago afgenomen grensgebieden; Masinissa's aanspraken op het gebied \"Emporia\" en de grens met Carthago werden later oorzaak van oorlog.", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["Zama: Scipio en Masinissa verslaan Hannibal", "52e188e6"], "d": ["In de slag bij Zama, na de terugroeping van Hannibal naar Afrika, versloegen de legioenen van Scipio en de Numidische cavalerie van Masinissa het Carthaagse leger. De Tweede Punische Oorlog eindigde met deze strijd definitief in het voordeel van Rome.", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["Syphax wordt verslagen en gevangengenomen; Masinissa verenigt Numidië", "a42a3cb0"], "d": ["Scipio en Masinissa versloegen in 203 het leger van Syphax en namen Syphax gevangen; Masinissa nam met steun van Rome Cirta en het koninkrijk van Syphax in. Numidië werd door de vereniging van het oostelijke en westelijke deel een sterk koninkrijk.", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["Ilipa en Gades: Hispania gaat van Carthago over naar Rome", "31e5a50c"], "d": ["Scipio versloeg in 206 bij Ilipa het leger van Hasdrubal Gisco en Mago en maakte een einde aan de Carthaagse controle in Hispania; ook Gades ging kort daarna over naar Rome. Carthago verloor de zilvermijnen en het soldatenreservoir van Hispania.", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["Fabius Maximus herovert Tarente op Hannibal", "bd605091"], "d": ["Tarente, dat zich in 212 aan Hannibal had overgegeven, ging in 209 door verraad over naar Q. Fabius Maximus. Met de val van de stad ging Hannibals waardevolste haven in Zuid-Italië verloren.", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["Capua valt aan Rome: Hannibals basis in Campanië gaat verloren", "cfcb9c9a"], "d": ["Rome belegerde twee jaar lang Capua, dat na Cannae naar Hannibal was overgegaan, nam de stad ondanks Hannibals mars op Rome in en strafte haar zwaar; de autonomie van Capua werd opgeheven. Hannibal trok zich in Zuid-Italië in de verdediging terug.", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["Cannae: Hannibal omsingelt en vernietigt het Romeinse leger; Zuid-Italië begint naar Carthago over te gaan", "94f5110a"], "d": ["In 216 vernietigde Hannibals omsingelingsopstelling bij Cannae in Apulië een Romeins leger van ongeveer zeventigduizend man. Capua, Tarente en vele steden van Zuid-Italië gingen over naar Carthago.", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["Een Romeins leger landt in Hispania: eerste Romeinse basis in Emporion", "8cb47853"], "d": ["Na Hannibals mars naar Italië landde Cn. Cornelius Scipio in 218 v.Chr. bij Emporion en begon zo de Romeinse aanwezigheid in Hispania langs de Ebro; het schiereiland werd het tweede front van de Tweede Punische Oorlog.", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["Hannibal steekt de Alpen over en trekt Italië binnen", "a1d3bf5a"], "d": ["Hannibal stak de Ebro, de Pyreneeën en de Rhône over, trok in de herfst over de Alpen en daalde af naar Noord-Italië; hij versloeg de Romeinse legers bij de Ticinus en de Trebia. Het centrum van de Carthaagse oorlog in Italië werd zo in het hart van Rome verplaatst.", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["Hannibal neemt Saguntum in: de lont van de Tweede Punische Oorlog wordt aangestoken", "a497a334"], "d": ["Hannibal nam na een beleg van acht maanden Saguntum, een bondgenoot van Rome, in (219 v.Chr.); Rome zond gezanten en eiste de uitlevering van Hannibal, en toen dit werd geweigerd, werd de oorlog verklaard. De oorlog duurde zeventien jaar in Italië, Hispania en Afrika.", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["Sellasia: Antigonus Doson verslaat Cleomenes, Sparta wordt voor het eerst door een buitenlandse macht bezet", "dc64a8db"], "d": ["In de zomer van 222 versloeg het Macedonisch-Achaeïsche bondgenootschap bij Sellasia het Spartaanse leger van Cleomenes; Cleomenes vluchtte naar Egypte. Doson trok Sparta binnen en bracht het terug naar de orde van Lycurgus; de Spartanen maakten voor het eerst in hun geschiedenis de bezetting door een buitenlands leger mee.", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["Mediolanum (Milaan) valt aan Rome: de Insubres worden verslagen, Noord-Italië wordt voor Rome opengesteld", "d3ec639f"], "d": ["Rome, dat de Galliërs bij Telamon (225) had verslagen, bracht in 222 v.Chr. met de overwinning van Marcellus bij Clastidium en de inname van Mediolanum het grootste deel van de Povlakte onder controle. Het gebied werd georganiseerd als Gallia Cisalpina.", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["De Achaeïsche Bond draagt Acrocorinthus over aan Antigonus Doson: Korinthe keert terug naar Macedonië", "c8ec9d0c"], "d": ["De Achaeïsche Bond, onder druk van Cleomenes III, vroeg via Aratus hulp aan Macedonië en droeg Acrocorinthus en Korinthe over aan Antigonus Doson; Doson stichtte de Helleense Bond (Hellenikos symmachia).", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["Verdrag van de Ebro: Carthago stemt ermee in niet ten noorden van de Ebro te komen", "a199de0b"], "d": ["Hasdrubal, die de door Hamilcar begonnen verovering van Hispania voortzette, sloot met Rome het Verdrag van de Ebro: Carthago zou de Ebro niet gewapend oversteken. Hannibals aanval op Saguntum in 219 werd op de interpretatie van dit verdrag gebaseerd.", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["Rome neemt Sardinië en Corsica van Carthago af", "4f7295ee"], "d": ["Toen de opstandige huurlingen van Carthago op Sardinië Rome om hulp vroegen, bezette Rome het eiland; Carthago moest onder dreiging van oorlog de eilanden laten varen en nog eens 1200 talenten betalen. Rome schiep zijn tweede provincie (Sardinia et Corsica).", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["Aegatische Eilanden: de Carthaagse vloot wordt vernietigd; Sicilië wordt de eerste Romeinse provincie", "8bd16e8f"], "d": ["Lutatius Catulus versloeg in maart 241 voor de Aegates de Carthaagse vloot van Hanno; daarna ontruimde Carthago met de vrede van Lutatius Sicilië en stemde ermee in 3200 talenten oorlogsschadevergoeding te betalen. Sicilië (behalve het Syracuse van Hiero) werd de eerste provincie van Rome.", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["Aratus overrompelt Acrocorinthus: Korinthe gaat van Macedonië over naar de Achaeïsche Bond", "a88dfda6"], "d": ["Aratus van Sicyon schakelde met een nachtelijke overval het garnizoen van Antigonus Gonatas op Acrocorinthus uit en voegde Korinthe bij de Achaeïsche Bond; ook Megara, Troizen en Epidaurus gingen over naar de bond. Macedonië verloor zijn sleutelvesting op de Peloponnesos.", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["Aratus voegt Sicyon bij de Achaeïsche Bond", "6f413f9c"], "d": ["De jonge Aratus wierp de tiran van Sicyon omver en bond de stad aan de Achaeïsche Bond; deze stap breidde de Bond uit naar de noord- en zuidkust van de Golf van Korinthe en leidde ertoe dat Aratus tot strateeg werd gekozen.", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["Hiero II sluit een bondgenootschap met Rome: Oost-Sicilië wordt bondgenoot van Rome", "5e95a134"], "d": ["Hiero had aan het begin van de Eerste Punische Oorlog wegens de kwestie Messana een bondgenootschap met Carthago tegen Rome gesloten; in 263 sloot hij vrede en een bondgenootschap met Rome en bleef zijn leven lang (tot 215) een trouwe bondgenoot van Rome. Syracuse werd de bondgenootschappelijke staat buiten de provincie van het Romeinse Sicilië.", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["Nicomedes I sticht Nicomedia (İzmit)", "a89ed42a"], "d": ["Nicomedes stichtte na de verwoesting van Astacus Nicomedia aan het oostelijke uiteinde van de baai; de stad werd in de volgende eeuwen het centrum van Bithynië en in de tijd van Diocletianus de oostelijke hoofdstad van Rome.", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["De Eerste Punische Oorlog begint: Appius Claudius steekt over naar Messana", "636e1533"], "d": ["Toen de Mamertijnen van Messana tegen koning Hiero van Syracuse na Carthago ook Rome om hulp vroegen, stak de Romeinse consul Appius Claudius Caudex in 264 over naar Sicilië en nam Messana in op het Carthaagse garnizoen. Zo voerde Rome voor het eerst oorlog buiten Italië.", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["Volsinii valt: de laatste onafhankelijke grote stad van Etrurië gaat naar Rome", "b6aed092"], "d": ["Volsinii, dat wegens een slavenopstand Rome om hulp had gevraagd, werd in 264 door Rome ingenomen, waarna de inwoners naar een nieuwe plaats werden overgebracht. Etrurië kwam hierna feitelijk onder Romeinse heerschappij.", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["Pyrrhus sterft in Argos", "2b4996fa"], "d": ["Tijdens de veldtocht op de Peloponnesos werd Pyrrhus in het straatgevecht van Argos door een dakpan getroffen en stierf (272). Epirus verloor zijn gewicht tegenover Macedonië en herstelde de betrekkingen met Rome.", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["Tarente geeft zich over aan Rome: Zuid-Italië wordt bij Rome gevoegd", "6e87c924"], "d": ["Na het vertrek van Pyrrhus werd het Epirotische garnizoen van Tarente teruggetrokken en gaf de stad zich over aan Rome (272). Samen met Bruttium en Lucanië werden de Griekse steden van Zuid-Italië bondgenoten van Rome; zo werd Rome meester over het Italische schiereiland tot aan de Povlakte.", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["Maleventum (Beneventum): Pyrrhus trekt zich terug uit Italië", "ab67e9f5"], "d": ["Pyrrhus' nieuwe aanval op Rome na zijn terugkeer van zijn Siciliaanse veldtocht mislukte bij Maleventum tegen Manius Curius Dentatus; Pyrrhus keerde in 275 terug naar Epirus. Hij liet een klein garnizoen achter in Tarente; Rome bleef in Italië zonder rivaal.", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["Antiochus I verslaat de Galaten in de \"Olifantenslag\"", "1e88c2d0"], "d": ["Antiochus I versloeg de Galaten met zijn olifanten en nam de bijnaam Soter (\"redder\") aan; de Galaten keerden terug naar een stelsel van gevestigde tribuutheffing en strooptochten in Centraal-Anatolië. In de volgende eeuwen gingen de botsingen met Pergamon en Bithynië door.", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["Antigonus Gonatas wordt koning van Macedonië: de Antigonidische dynastie wordt bestendigd", "4b907dd6"], "d": ["Gonatas verwierf roem door in 277 bij Lysimachia de Galaten te verslaan en vestigde zich in 276 op de Macedonische troon. De dynastie regeerde Macedonië tot 168; in Griekenland hield zij de vestingen Korinthe, Chalkis en Piraeus in handen.", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["Nicomedes I laat de Galaten naar Anatolië oversteken", "9e5ab10b"], "d": ["Koning Nicomedes I van Bithynië liet Galatische (Keltische) stammen via de Bosporus oversteken en nam hen in dienst tegen zijn broer Zipoetes en de druk van de Seleuciden; de Galaten vestigden zich later in Centraal-Anatolië; de tak der Tectosagen maakte Ankara (Ancyra) tot hoofdstad (TDV «Ankara»: «tussen 278 en 189 v.Chr. werd het de hoofdstad van de tak der Tectosagen van de uit Thracië gekomen Galaten»). Datum van de overtocht 278/277.", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["De Aetolische Bond verdedigt Delphi tegen de Galatische inval", "5488966a"], "d": ["Het Galatische leger van Brennus trok over de Thermopylen naar Delphi; het verzet van de Aetoliërs en Phocidiërs verstrooide de inval. Het gewicht van Aetolië in de Delphische Amfictyonie groeide door deze overwinning.", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["Pyrrhus steekt over naar Italië ter hulp van Tarente; hij verslaat de Romeinen bij Heraclea", "55f18e85"], "d": ["Pyrrhus, die in 280 op verzoek van Tarente tegen Rome in Italië landde, versloeg bij Heraclea het leger van Valerius Laevinus met olifanten en cavalerie, maar leed zware verliezen. In 279 won hij opnieuw bij Asculum, in 278-276 trok hij naar Sicilië.", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["De Achaeïsche Bond wordt hersticht: Patrae, Dyme, Tritaea, Pharae", "81bba071"], "d": ["In het onder Antigonidische controle staande Achaea herstichtten vier steden (Dyme, Patrae, Tritaea, Pharae) in 280 v.Chr. een federale bond; in de volgende jaren sloten Aigion en andere steden zich aan. De Bond werd onder leiding van Aratus een grote macht van de Peloponnesos.", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["Philetaerus gaat na Korupedion over naar Seleucus; Pergamon stichtte feitelijk een onafhankelijke dynastie", "ac6b3e31"], "d": ["Na de val van Lysimachus voegde Philetaerus zich met de schatkist bij Seleucus en bewaakte en verrijkte Pergamon; met de dood van Seleucus (281) werd hij feitelijk onafhankelijk. Livius geeft dat de Attalidische dynastie Pergamon van 283 tot 129 bestuurde.", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["Lysimachus verdrijft Pyrrhus uit Macedonië en wordt de enige koning van Macedonië", "a83e6c64"], "d": ["Na de winter van 285, waarin Demetrius zich aan Seleucus overgaf, verdreef Lysimachus Pyrrhus uit Macedonië en regeerde het land alleen. Zijn staat bereikte een groot gebied dat Thracië, Macedonië en West-Anatolië omvatte.", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["Pyrrhus en Lysimachus verdelen Macedonië; Demetrius Poliorcetes wordt ten val gebracht", "63371ab8"], "d": ["Toen Demetrius in de zomer van 287 naar Azië overstak, verdeelden Pyrrhus en Lysimachus samen Macedonië in twee delen; Demetrius werd ten val gebracht. Deze verdeling duurde slechts twee jaar.", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["Samnium wordt bij Rome gevoegd: de Derde Samnitische Oorlog eindigt", "bede9942"], "d": ["Manius Curius Dentatus bracht de Samnieten en Sabijnen een beslissende nederlaag toe; Samnium werd een bondgenoot van Rome. Rome werd meester van Midden-Italië en kwam tegenover de Griekse steden van Zuid-Italië (Tarente) te staan.", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["Demetrius Poliorcetes wordt tot koning van Macedonië uitgeroepen", "a2b1eba3"], "d": ["Demetrius, die gebruikmaakte van de troonstrijd in de dynastie van Cassander, werd in de herfst van 294 door het leger tot koning van Macedonië uitgeroepen. Het is de eerste heerschappij van het geslacht van Antigonus in Macedonië; zij stortte in 288 in en Gonatas bestendigde haar in 276.", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["Sentinum: het bondgenootschap van Etrusken, Umbriërs, Samnieten en Galliërs wordt door Rome verslagen", "b5affc1b"], "d": ["Deze slag bij Sentinum in de Derde Samnitische Oorlog vernietigde het laatste grote anti-Romeinse bondgenootschap in Italië; de Etruskische steden werden een voor een gedwongen tot bondgenootschap met Rome.", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["Pyrrhus keert met steun van Ptolemaeus terug op de troon van Epirus", "6288bf69"], "d": ["Pyrrhus, die na Ipsus als gijzelaar in Egypte was gebleven, keerde met hulp van Ptolemaeus terug naar Epirus en nam de troon terug. Epirus kreeg hierna een stem in de aangelegenheden van Macedonië en Italië.", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["Lysimachus plaatst zijn schatkist in Pergamon; Philetaerus wordt bewaker van de vesting", "e1b4ab77"], "d": ["Na Ipsus liet Lysimachus zijn schatkist bewaren in de vesting Pergamon op de heuvel en gaf de bewaking aan de eunuch Philetaerus. Philetaerus ging in 281 over naar Seleucus en legde het fundament van de dynastie.", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["Mithridates I Ktistes sticht de dynastie van Pontus", "490c338c"], "d": ["Mithridates, die Antigonus Monophthalmus was genaderd, ontsnapte in 302 aan het gevaar gedood te worden en nam zijn toevlucht tot Kimiata in het bergachtige gebied van Pontus in Cappadocië, waar hij de kern van het koninkrijk Pontus vormde. De dynastie duurde tot 63.", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["Het beleg van Rhodos door Demetrius Poliorcetes eindigt mislukt", "dae6f4d6"], "d": ["Demetrius omsingelde in 305 met reusachtige belegeringsmachines Rhodos, dat tegen Antigonus aan de kant van Ptolemaeus was gebleven; de Rhodiërs hielden een jaar stand en in de zomer van 304 kwam er vrede. Met het geld van deze overwinning werd in de stad de Kolossos van de zonnegod Helios opgericht.", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["Salamis op Cyprus: Demetrius verslaat Ptolemaeus; Antigonus en Demetrius nemen de koningstitel aan", "cc308941"], "d": ["In het voorjaar van 306 versloeg Demetrius Poliorcetes voor Cyprus de vloot van Ptolemaeus en bracht Cyprus in handen van Antigonus; in de zomermaanden namen Antigonus en Demetrius de koningstitel aan en de andere Diadochen namen kort daarna dezelfde titel aan. Ptolemaeus nam Cyprus in 294 terug.", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["Lysimachus sticht Lysimachia: hoofdstad op de Thracische Chersonesos", "83b83160"], "d": ["Lysimachus maakte Lysimachia, dat hij op de nek van het schiereiland Gallipoli had gesticht, de hoofdstad van het Thracische koninkrijk; de overgang over de Bosporus en de Dardanellen werd in zijn hand verenigd. De stad werd in de 3e eeuw v.Chr. door een aardbeving verwoest.", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["Vrede van de Diadochen: Antigonus, Cassander en Ptolemaeus erkennen elkaars bestuur over Azië, Europa en Egypte", "811c80f0"], "d": ["In de in december 311 gesloten vrede werd Antigonus erkend als bevelhebber van Azië, Cassander als strateeg van Europa, Lysimachus van Thracië en Ptolemaeus als bestuurder van Egypte en omgeving; het beginsel van de vrijheid van de Griekse steden werd aanvaard. Het Babylon van Seleucus bleef buiten deze vrede.", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["Tyrus gaat over naar Antigonus: Fenicië wordt Ptolemaeus afgenomen", "30f78257"], "d": ["Antigonus trok in 315 Syrië binnen, nam Fenicië in en belegerde Tyrus; de stad viel in 314. De Fenicische kust en de kust tot aan Gaza kwamen in zijn handen (Gaza werd bij de slag bij Gaza in 312 aan Ptolemaeus teruggegeven).", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["Cassander sticht Thessaloniki", "7043bd8a"], "d": ["Cassander verenigde meer dan twintig nederzettingen ten noorden van de Thermaïsche Golf en stichtte een stad naar zijn vrouw Thessalonike (dochter van Philippus II). Thessaloniki werd de volgende duizend jaar de belangrijkste haven van Macedonië.", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["Cassander laat Thebe herstichten", "0167e784"], "d": ["Thebe, dat door Alexander was verwoest, werd met steun van Cassander en met hulp uit Athene en Euboea herbouwd, met herstelde muren. Daarmee kreeg de Boeotische Bond weer een centrum.", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["Gabiene: Antigonus verslaat Eumenes en wordt heerser over Azië tot aan Iran", "d2990dfd"], "d": ["In de winter van 316/5 werd het leger van Eumenes bij Gabiene verslagen; zijn bevelhebber werd door zijn eigen soldaten aan Antigonus uitgeleverd en geëxecuteerd. Antigonus werd de enige heerser over een groot gebied van het Perzische plateau tot Anatolië; Seleucus vluchtte naar Egypte.", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["Regeling van Triparadisus: Antigonus Monophthalmus wordt strateeg van Azië", "69f6fafb"], "d": ["Na de moord op Perdiccas in Egypte (mei 320) verdeelde Antipater in Triparadisus de satrapieën opnieuw; Antigonus werd aan het hoofd van de Aziatische strijdkrachten geplaatst, Seleucus nam Babylon in. Vanuit deze positie begon Antigonus zijn eigen rijk te stichten.", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["Crannon: de Lamische Oorlog wordt verloren; een Macedonisch garnizoen trekt Athene binnen, de democratie wordt opgeschort", "6931c4f6"], "d": ["Op 5 september 322 werd het Griekse bondgenootschap bij Crannon door Antipater en Craterus verslagen; Athene stemde ermee in een Macedonisch garnizoen in Munychia op te nemen en het burgerschapscriterium te beperken tot bezitters. Demosthenes pleegde zelfmoord; de klassieke Atheense democratie eindigde feitelijk.", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["Lamische Oorlog: de Griekse steden komen na de dood van Alexander in opstand tegen de Macedonische hegemonie", "c31c7da4"], "d": ["Met het bericht van Alexanders dood (juni 323) kwamen Athene en de Aetolische Bond in opstand tegen Antipater; Antipater werd in Lamia belegerd. De oorlog eindigde bij Crannon (september 322) met een Macedonische overwinning en de Macedonische suprematie in het kader van de Korinthische Bond werd hersteld.", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["Hydaspes: Porus wordt verslagen; de Punjab wordt aan Alexander gebonden", "abab206b"], "d": ["In mei 326 stak Alexander met steun van Ambhi, de raja van Taxila, de Jhelum over en versloeg Porus; het koninkrijk van Porus werd als vazal aan Alexander gelaten. Vanaf dit punt trok Alexander verder naar het oosten, maar hij hield halt bij de Hyphasis door het verzet van het leger.", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["Aan de oever van de Hyphasis (Beas) weigert het leger verder te trekken: Alexanders oostgrens", "17b23afc"], "d": ["Door de moessonregens en vermoeidheid weigerde het Macedonische leger voorbij de Hyphasis te trekken; Alexander liet twaalf altaren oprichten en moest terugkeren. De Hyphasis werd het oostelijke uiteinde van de Macedonische veroveringen in India.", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["Bactrië en Sogdiana onderwerpen zich aan Alexander; Alexander trouwt met Roxane", "a050508d"], "d": ["Tussen 329 en 327 werd het gebied voorbij de Oxus ingenomen met zware guerrillastrijd; Spitamenes werd gedood, de Sogdische Rots en de vesting van Chorienes gaven zich over. Alexander trouwde met de Bactrische prinses Roxane en bond zo de lokale edelen aan het bestuur.", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["De West-Anatolische kust gaat over naar Alexander: Efeze, Milete en Halicarnassus", "f67084a4"], "d": ["Efeze opende de poorten met een democratisch regime, Milete werd na een beleg ingenomen (zomer 334); het beleg van Halicarnassus eindigde in de herfst met de val van de stad en de satrapie Carië werd aan Ada gegeven. Alexander paste zo zijn strategie toe de havens van de Perzische vloot te veroveren vanaf het land.", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["Thebe wordt op bevel van Alexander verwoest", "26c4193c"], "d": ["Alexander nam in de herfst Thebe in, dat na de dood van Philippus in opstand was gekomen; hij plaatste een Macedonisch garnizoen in de Cadmea, liet de stad slopen en maakte de bevolking tot slaaf (behalve het huis van Pindarus). De Boeotische Bond eindigde door deze verwoesting feitelijk (in 316 herstichtte Cassander de stad).", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["Philippus II wordt in Aigai vermoord; Alexander bestijgt de troon", "417d909e"], "d": ["Philippus werd tijdens het huwelijksfeest van zijn dochter Cleopatra in het theater door zijn lijfwacht Pausanias gedood; in zijn plaats werd zijn zoon Alexander door het leger tot koning uitgeroepen. De Perzische veldtocht en de controle over Griekenland kwamen aan Alexander toe.", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["De Korinthische Bond wordt gesticht: de Griekse steden worden verenigd onder de hegemonie van Philippus II", "c38074dc"], "d": ["Na Chaeronea bracht Philippus de Griekse steden in Korinthe samen onder een algemene vrede (koine eirene) en een gemeenschappelijk verdedigingspact; troepen voor de veldtocht tegen Perzië en het bevel van de hegemon werden vastgesteld. Alleen Sparta nam niet deel.", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["Chaeronea: Philippus verslaat het Atheense en Thebaanse leger en neemt de controle over Griekenland over", "5e5d77e7"], "d": ["In augustus 338 werd het Atheens-Thebaanse leger op de vlakte van Chaeronea verslagen door een cavalerieaanval onder bevel van de jonge Alexander; in Thebe werd een Macedonisch garnizoen geplaatst, Athene werd mild gespaard. De overwinning maakte een einde aan de onafhankelijkheid van de Griekse steden en effende de weg naar de Korinthische Bond.", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["De Latijnse Bond wordt ontbonden: Latium wordt aan Rome gebonden", "58849f84"], "d": ["Aan het einde van de Latijnse Oorlog (340-338) ontbond Rome de Latijnse Bond; de steden werden bij het Romeinse burgerrecht gevoegd of een voor een aan Rome gebonden, onderlinge bondgenootschappen tussen hen werden verboden. Dit is de basis van Romes expansiemodel in Italië.", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["Philippus II verslaat de Scythische koning Ateas", "e4dee658"], "d": ["De oorlog van koning Ateas met Philippus aan de oevers van de Istros (Donau) eindigde met de dood van Ateas; Philippus werd op de terugweg aangevallen door de Triballi. De Scythische macht verschoof naar het westen, voorbij de Donau.", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["Philippus onderwerpt Thracië samen met de Odrysische dynastie", "b543427a"], "d": ["Philippus drong in de veldtochten van 342-341 v.Chr. door tot diep in Thracië, maakte de Odrysische koning Kersobleptes schatplichtig en stichtte steden als Philippopolis (Plovdiv). Thracië werd een oostelijke uitloper van Macedonië.", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["De verwoesting van Olynthus: de Chalcidische Bond gaat over aan Macedonië", "89d77301"], "d": ["Hoewel Olynthus Athene om hulp had gevraagd, nam Philippus de stad door verraad in en verwoestte haar; het schiereiland Chalcidice werd bij Macedonië gevoegd. De Olynthische redevoeringen van Demosthenes zijn op dit verzoek gebaseerd.", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["De Bondgenotenoorlog eindigt: Byzantium, Chios, Rhodos en Kos scheiden zich af van de Tweede Atheense Bond", "856a9763"], "d": ["De in 357 v.Chr. begonnen opstand eindigde toen de Atheense bevelhebbers bij Chios werden verslagen en de Perzische steun tegen Athene werd gekeerd, waarna Athene de vrede aanvaardde; vier belangrijke leden kregen hun onafhankelijkheid. De Bond verzwakte en bleef weerloos tegenover Macedonië.", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["Philippus neemt Amphipolis in op Athene", "2c793bc6"], "d": ["Philippus, die Amphipolis, de Atheense stad aan de monding van de Strymon, belegerde en innam, kreeg toegang tot de goud- en zilvermijnen en de houtbronnen van de stad en opende zich naar de Thracische kust. Deze verovering begon het conflict tussen Athene en Macedonië.", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["Philippus II wordt koning van Macedonië", "d557268d"], "d": ["Toen Perdiccas III in de strijd tegen de Illyriërs sneuvelde (360/359 v.Chr.), werd Philippus eerst regent en daarna koning; hij wendde de dreigingen van Illyrië, Paeonië en Thracië af en voerde de legerhervorming (sarissa-falanx) door. De opkomst van Macedonië begint met dit koningschap.", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["Mantineia: Epaminondas sterft, de Boeotische hegemonie eindigt", "94be8d5c"], "d": ["Het Thebaanse leger won de slag, maar Epaminondas raakte gewond en stierf; Xenofon besluit met \"meer onzekerheid en verwarring in Griekenland dan tevoren\". De korte hegemonie van Thebe eindigde in hetzelfde jaar, het evenwicht tussen Athene, Sparta en Thebe bleef behouden.", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["De Arcadische Bond wordt gesticht: dit deel van de Peloponnesische Bond valt uiteen", "42fdc676"], "d": ["Na Leuctra stichtten de Arcadische steden met Thebaanse steun een federale bond en bouwden de nieuwe hoofdstad Megalopolis. Zo viel de Peloponnesische Bond van Sparta feitelijk uiteen; Sparta trok zich terug op Laconië alleen.", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["Messenië maakt zich los van Sparta; Messene wordt gesticht", "e4ef9302"], "d": ["Tijdens de veldtocht van Epaminondas op de Peloponnesos na Leuctra (winter 370/69) werden de Messenische heloten vrijgelaten en werd aan de voet van de berg Ithome de sterk ommuurde stad Messene gesticht. Sparta verloor voor het eerst in eeuwen het land van Messenië, dat zijn economische basis vormde.", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["Leuctra: het Thebaanse leger verslaat de Spartanen; Sparta verliest zijn landsuperioriteit", "e7829597"], "d": ["Epaminondas' opstelling met diepe concentratie op de rechtervleugel bracht de Spartaanse strijdmacht van koning Cleombrotus bij Leuctra een nederlaag toe; met de dood van ongeveer 400 Spartiaten kon Sparta zijn bevolkingsverlies niet meer goedmaken. Een tijdperk van hegemonie onder leiding van Thebe begon.", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["De Tweede Atheense Bond wordt gesticht (decreet van Aristoteles)", "0e5dcaf2"], "d": ["Athene riep de Egeïsche steden tegen Sparta op tot een bond op grond van autonomie en het niet innen van tribuut; het decreet kwam op voorstel van Aristoteles tot stand en de lijst van de lidsteden werd in steen gegrift. De stichting van de Bond maakte Athene opnieuw tot zeemacht.", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["Pelopidas bevrijdt Thebe; het Spartaanse garnizoen wordt uit de Cadmea verdreven", "eb15a9d7"], "d": ["De Cadmea van Thebe, die Sparta in 382 v.Chr. had ingenomen en van een garnizoen had voorzien, werd door een nachtelijke overval van de ballingen heroverd; Thebe werd opnieuw het centrum van de Boeotische Bond. De gebeurtenis is het begin van het uiteenvallen van de Spartaanse hegemonie.", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["Allia: de Galliërs verslaan het Romeinse leger en plunderen de stad", "db864bc9"], "d": ["Aan de oever van de Allia, een zijrivier van de Tiber, versloegen de Senonische Galliërs het Romeinse leger; Rome werd buiten het Capitool bezet en geplunderd. Livius schrijft dat de \"dag van de Allia\" (18 juli) voor de Romeinen als ongelukkig gold.", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["Korinthe verenigt zich met Argos (isopolitie Argos-Korinthe)", "135a3d3a"], "d": ["Tijdens de Korinthische Oorlog (395-387 v.Chr.) sloot Korinthe met Argos een gemeenschappelijke burgerschapsunie; een Argivisch garnizoen bleef in Korinthe. Sparta liet deze vereniging met de Koningsvrede (386) ongedaan maken.", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["Veii valt aan Rome: de eerste grote stad van Etrurië in het zuiden gaat verloren", "0d1c4fe4"], "d": ["Na een beleg van tien jaar nam Camillus Veii in (volgens de traditie 396 v.Chr.); de bevolking werd tot slaaf gemaakt, het gebied werd bij Rome gevoegd en de ager Romanus van Rome verdubbelde bijna. De macht van de Etruskische steden ten zuiden van de Tiber werd gebroken.", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["Athene geeft zich over aan Sparta; het Atheense zeerijk en de Delische Bond eindigen", "43f2ddf9"], "d": ["Athene, dat zijn vloot bij Aegospotami had verloren, gaf zich over door hongersnood; de Lange Muren werden gesloopt, het zeerijk viel uiteen en in de stad kwam het door de Spartanen gevestigde bewind van de Dertig. Op de eilanden en de Thracische kusten die vroeger lid van de Bond waren, vestigden zich door Lysander opgerichte decarchieën en Spartaanse garnizoenen.", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["Dionysius I wordt tiran van Syracuse", "1ad10305"], "d": ["In de jaren dat Carthago Akragas en Gela innam, werd Dionysius in 405 strateeg en daarna tiran van Syracuse; hij sloot vrede met Carthago (405) en bond de Griekse steden van Sicilië aan zich. De heerschappij van Dionysius, die 38 jaar zou duren, maakte Sicilië tot een van de grote machten van de Middellandse Zee.", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["Aegospotami: de Atheense vloot wordt vernietigd; de Delische Bond staat op instorten", "ce62187c"], "d": ["In september 405 nam Lysander bij Aegospotami de voor anker liggende Atheense vloot door een overval in; bijna de gehele vloot en duizenden gevangenen gingen verloren. De weg naar de Hellespont werd gesloten en de graanaanvoer van Athene afgesneden; enkele maanden later gaf Athene zich over.", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["De stad Rhodos wordt gesticht: Lindos, Ialysos en Kameiros verenigen zich", "2de55901"], "d": ["In 408 v.Chr. vormden de drie steden van het eiland Rhodos een gemeenschappelijke staat en verenigden zich in de nieuwe stad Rhodos; de volgens het plan van Hippodamus gebouwde stad werd een van de belangrijkste marinebases en handelscentra van de Hellenistische wereld.", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["Hannibal Mago verwoest Selinus en Himera: Carthago vestigt zich in West-Sicilië", "358f4417"], "d": ["Hannibal Mago, die op verzoek van Segesta naar Sicilië overstak, nam in 409 v.Chr. Selinus en Himera in; het gebied werd de epikratia van Carthago. Het conflict tussen Carthago en Syracuse duurde twee eeuwen.", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["De Siciliaanse expeditie eindigt in een catastrofe: het Atheense leger wordt voor Syracuse vernietigd", "b363df0d"], "d": ["De in 415 v.Chr. door Athene begonnen Siciliaanse expeditie eindigde, nadat Syracuse niet kon worden belegerd, bij de terugtocht van Nicias en Demosthenes aan de oever van de rivier Assinaros met overgave (herfst 413 v.Chr.). Athene verloor zijn leger en het grootste deel van zijn vloot.", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["Sitalces sluit een bondgenootschap met Athene: het Odrysische Rijk neemt deel aan de Peloponnesische Oorlog", "4562f13d"], "d": ["Athene maakte de zoon van Sitalces Atheens burger en sloot een bondgenootschap met hem; Sitalces viel in 429 Macedonië aan. De Odrysische macht bereikte in deze periode haar hoogtepunt.", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["De Peloponnesische Oorlog begint: de Peloponnesische Bond mobiliseert tegen Athene", "2adee4a1"], "d": ["Met de nachtelijke overval van Thebe op Plataeae (voorjaar 431) werd de vrede feitelijk verbroken; aan het begin van de zomer viel het leger van de Peloponnesische Bond onder koning Archidamus Attica binnen. De oorlog duurde 27 jaar tussen het zeerijk van Athene en de landbond van Sparta.", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["Sybota: de oorlog tussen Korinthe en Korkyra trekt Athene in een interventie", "dc07b0ac"], "d": ["In de zeeslag die Korinthe om Epidamnus met zijn kolonie Korkyra voerde, steunde Athene Korkyra. De woede van Korinthe op Athene werd een van de directe oorzaken van de Peloponnesische Oorlog.", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["Spartocus wordt archont in het Bosporanenrijk: de dynastie der Spartocieden", "ddc76f79"], "d": ["De dynastie der Archeanactiden in Pantikapaion werd vervangen door de van Thracische afkomst zijnde Spartocus (438/7); de dynastie der Spartocieden stichtte het koninkrijk van het Bosporanenrijk en beheerde de graanexport naar Athene. De dynastie duurde tot 109 v.Chr.", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["Dertigjarige Vrede: Athene verliest zijn landrijk (Boeotië, Megara, Achaea)", "4f33ff13"], "d": ["Na de overwinning van de Boeotiërs op het Atheense leger bij Coronea (447), vervolgens de opstanden van Euboea en Megara en de Spaanse inval in Attica, sloot Athene de Dertigjarige Vrede. Athene liet Megara, Nisaea, Pegae en Troizen en Achaea op de Peloponnesos varen; alleen het zeerijk bleef behouden.", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["Teres sticht het Odrysische koninkrijk: de eerste grote staat van Thracië", "83caf189"], "d": ["Thucydides schrijft dat Teres in Thracië het eerste grote koninkrijk stichtte; zijn zoon Sitalces liet het koninkrijk reiken van de Donau tot de Egeïsche Zee. Het Odrysische koninkrijk voerde een evenwichtspolitiek tussen Athene, Macedonië en Perzië.", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["De schatkist van de Bond wordt van Delos naar Athene overgebracht", "173f2e5b"], "d": ["Met als redenen de nederlaag in de Egyptische veldtocht en de vrees voor de Perzische vloot werd de gemeenschappelijke schatkist van Delos naar Athene gebracht; de lijsten van het \"zestigste\" deel dat aan de godin Athena werd gegeven, beginnen in dit jaar. Deze stap wordt geïnterpreteerd als teken dat de Bond in de praktijk was veranderd in een Atheens rijk.", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["De opstand van Thasos wordt neergeslagen; de Delische Bond verandert in een rijk waaruit leden niet kunnen vertrekken", "d24bd124"], "d": ["Thasos kwam om de mijnen in conflict met Athene en probeerde de bond te verlaten; na een beleg van twee jaar (463 v.Chr.) sloopte het zijn muren, leverde zijn vloot uit en verloor het mijngebied aan de Thracische kust. De gebeurtenis is het eerste precedent dat toont dat het lidmaatschap van de Bond niet kon worden opgezegd.", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["Zeeslag bij Cumae: Syracuse verslaat de Etruskische vloot, de Etruskische zeemacht wordt gebroken", "2e81670b"], "d": ["Op verzoek van Cumae om hulp versloeg Hiero I, tiran van Syracuse, de Etruskische vloot voor Cumae; Hiero vierde de overwinning met een helm als geschenk aan Delphi (de door Livius vermelde Etruskische helm). De Etruskische heerschappij in Campanië werd geschokt.", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["De Delische Bond wordt gesticht: Egeïsch bondgenootschap onder leiding van Athene", "f0de153a"], "d": ["Na de bestuursstijl van Pausanias vroegen de Ionische steden Athene om leiding; met het door Aristides vastgestelde tribuut (460 talenten) werd op Delos een gemeenschappelijke schatkist gevormd. De Bond verschafte Athene een permanente vloot en belastingbasis op de Egeïsche Zee.", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["Salamis (29 september 480) en Plataeae: de Perzische invasie wordt afgeslagen", "479b17e6"], "d": ["Nadat Xerxes Athene had ingenomen en in brand gestoken, werd de Perzische vloot door de list van Themistocles in de straat van Salamis verslagen (29 september 480); het jaar daarop versloeg het Griekse landleger onder Pausanias bij Plataeae Mardonius en maakte een einde aan de invasie. Zo werd het Egeïsche Griekenland van de Perzische overheersing bevrijd.", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["Himera: de Sicilische Grieken verslaan het Carthaagse leger", "ece09580"], "d": ["Het bondgenootschap van Gelon en Theron versloeg voor Himera het Carthaagse leger van Hamilcar; Carthago kon een halve eeuw lang geen grote veldtocht meer naar Sicilië ondernemen. Volgens Herodotos en Diodorus werd op dezelfde dag Salamis gewonnen (traditie).", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["Marathon: Athene stuit de Perzische aanval", "0967ce7c"], "d": ["De Atheense en Plataeïsche hoplieten onder Miltiades versloegen de Perzische strijdmacht op de vlakte van Marathon en verhinderden de landing in Attica. De overwinning voedde het zelfvertrouwen van de Atheense democratie en de zeepolitiek die zich later uitstrekte tot de Delische Bond.", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["Mardonius onderwerpt Macedonië aan Perzië", "7bde569c"], "d": ["Mardonius, schoonzoon van Darius, trok door Thracië en bracht Macedonië onder Perzische heerschappij; de Macedonische koning gaf aarde en water aan Perzië. Macedonië wierp deze afhankelijkheid na Plataeae (479) af.", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum: Rome sluit een bondgenootschap met de Latijnse Bond", "56db407d"], "d": ["Met het verdrag dat de naam van Spurius Cassius draagt, sloten Rome en de Latijnse Bond een bondgenootschap op basis van onderlinge verdediging, verdeling van de buit en een gezamenlijk leger. Dit verdrag is het kader van de betrekkingen tussen Rome en Latium tot aan de Latijnse Oorlog (340-338).", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["Door de terugtrekking van Korinthe valt de veldtocht van de Peloponnesische Bond tegen Athene uiteen", "b44adf6b"], "d": ["Sparta stuurde het leger van de Peloponnesische Bond naar Attica tegen het democratische Athene van Cleisthenes; de terugtrekking van het Korinthische leger bij Eleusis en het meningsverschil tussen de twee Spartaanse koningen deden de veldtocht mislukken. De gebeurtenis geldt als het eerste bekende voorbeeld waarin het stemrecht van de bondgenoten in de bondsvergadering begon te werken.", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["Hervorming van Cleisthenes: de institutionele basis van de Atheense democratie wordt gelegd", "b2421c86"], "d": ["Na de val van Hippias organiseerde Cleisthenes de burgers via de demen, de nederzettingseenheden, en tien nieuwe stammen; de Raad van Vijfhonderd werd het centrum van deze orde. Het is de regeling waarin de begrippen isonomia/demokratia ontstonden.", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["De laatste koning Tarquinius Superbus wordt verdreven; het koningschap eindigt, de Republiek begint", "5a4a9061"], "d": ["Volgens Livius werden Tarquinius Superbus en zijn familie in 509 v.Chr. uit de stad verdreven en werden de eerste consuls (Brutus, Collatinus) gekozen. Polybius verbindt het eerste verdrag tussen Rome en Carthago met het jaar van de eerste consuls; hoewel de datum in de moderne geschiedschrijving als \"traditie\" geldt, ligt zij aan het einde van de 6e eeuw v.Chr.", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["Eerste verdrag tussen Rome en Carthago (Polybius 3.22)", "cdef940f"], "d": ["Polybius geeft met de tekst het verdrag weer dat in het jaar van de eerste consuls tussen Rome en Carthago werd gesloten en dat de kusten van Latium aan Rome toekende en Carthago het westen van Sicilië en Libië. Rome wordt als meester van Latium vermeld.", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["Zeeslag bij Alalia: de Etrusken en Carthagers verdrijven de Phocaeërs uit Corsica", "25efbea8"], "d": ["De Phocaeïsche Grieken behaalden bij Alalia op papier een overwinning, maar verloren het grootste deel van hun vloot; zij lieten Corsica varen en trokken zich terug naar Elea in Zuid-Italië. Op het eiland werd de Etruskische (Caere) heerschappij gevestigd.", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["Verdrag Sparta-Tegea: de kern van de Peloponnesische Bond ontstaat", "57098e47"], "d": ["Sparta versloeg Tegea in Arcadië en liet het een eeuwig bondgenootschap (symmachia) aanvaarden in ruil voor het niet aantasten van zijn gebied; hetzelfde patroon breidde zich uit over de steden van de Peloponnesos en onder leiding van Sparta ontstond de Peloponnesische Bond. De Bond functioneerde intern in de vorm van Sparta en de bondgenotenvergadering (onder bevel van Sparta).", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["De Phocaeërs stichten Massalia (Marseille)", "5d46bdf2"], "d": ["Phocaeïsche kolonisten stichtten omstreeks 600 v.Chr. Massalia aan de monding van de Rhône; de stad werd in de westelijke Middellandse Zee het centrum van de Griekse handel en van het contact met de Keltische wereld.", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["Battus van Thera sticht Cyrene", "67fd477f"], "d": ["Kolonisten uit Thera stichtten Cyrene onder leiding van Battus volgens een Delphisch orakel; de dynastie der Battiaden regeerde tot 440. Livius geeft de stichtingsdatum als \"ca. 630\".", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["Sparta wint de Eerste Messenische Oorlog: Messenië wordt bij Sparta gevoegd", "74ad461c"], "d": ["In de door Pausanias overgeleverde traditie duurde de Eerste Messenische Oorlog twintig jaar en ging met de val van Ithome de vlakte van Messenië over naar Sparta; de bevolking werd teruggebracht tot helotenstatus. Deze verovering gold als de fundamentele gebeurtenis die Sparta's agrarische kracht en militaire samenleving bepaalde.", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["Syracuse wordt gesticht door de Korinthiër Archias", "10217104"], "d": ["Volgens Thucydides stichtte de Korinthiër Archias Syracuse een jaar na Naxos. De stad werd de grootste Griekse stad van Sicilië.", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["De traditionele stichting van Carthago (Timaeus: 814/813 v.Chr.)", "908099b5"], "d": ["Volgens Timaeus werd Carthago in 814/813 v.Chr. door kolonisten uit Tyrus gesticht; Justinus geeft 825. Archeologische lagen wijzen op het einde van de 8e eeuw v.Chr.", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["De Myceense paleiscentra worden verwoest: de palatiale orde stort in op de Peloponnesos", "d2c79152"], "d": ["Aan het einde van Laat-Helladisch IIIB / begin IIIC vertonen de paleiscentra in Pylos, Tiryns en Mycene een verwoestings- of verlatingslaag; de op Lineair B-schrift gebaseerde paleiseconomie eindigt. De oorzaak van de verwoesting (aardbeving, interne strijd, Zeevolken, droogte) is omstreden; de verwoestingslagen beslaan niet één jaar maar enkele decennia.", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["Verwoesting van de Minoïsche paleizen op Kreta; Myceense controle begint in Knossos", "1a7f7f2b"], "d": ["Aan het einde van Laat-Minoïsch IB (midden 15e eeuw v.Chr.) worden de paleiscentra en villa's op Kreta verwoest; de Lineair B-tabletten in de latere fase van Knossos tonen een in het Grieks geschreven paleisbestuur, dat wil zeggen Myceense controle. Zo eindigt de Minoïsche heerschappij op Kreta.", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["Teutoburger Woud: de drie legioenen van Varus worden vernietigd; Rome laat de Elbelijn varen", "1684ae43"], "d": ["In 9 n.Chr. vernietigde de Germaanse coalitie onder leiding van Arminius in het Teutoburger Woud het XVII, XVIII en XIX legioen van P. Quinctilius Varus. Augustus zag af van veroveringen voorbij de Rijn en de Rijngrens werd blijvend.", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["Augustus sterft; Tiberius wordt keizer", "0221344d"], "d": ["Augustus stierf op 19 augustus 14 in Nola; Tiberius volgde hem op. Het beginsel van opvolging in het Principaat (adoptie binnen de familie) werd zo bestendigd.", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["Koning Ptolemaeus wordt door Caligula gedood; de onafhankelijkheid van Mauretania eindigt", "11337627"], "d": ["Ptolemaeus, zoon van Juba II, werd in 40 n.Chr. in Lugdunum op bevel van Caligula gedood; daarna brak in Mauretania de opstand van Aedemon uit en Claudius verdeelde het land in 44 in twee provincies, Tingitana en Caesariensis.", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["Claudius valt Britannia binnen", "f42ba7f7"], "d": ["In 43 n.Chr. landden vier legioenen onder bevel van Aulus Plautius aan de kust van Kent; Camulodunum (Colchester) werd ingenomen en Claudius was korte tijd in de stad aanwezig. Het zuiden van Britannia werd een nieuwe Romeinse provincie.", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["Rome maakt Thracië een provincie: de Odrysische dynastie eindigt", "af2ba1b2"], "d": ["Nadat koning Rhoemetalces III van Thracië door zijn vrouw was gedood en er daarna wanorde ontstond, maakte Claudius Thracië in 46 tot Romeinse provincie. Het is een van de laatste stappen die de Romeinse provinciale orde in het oosten van de Balkan voltooiden.", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["Trajanus verovert Dacië: Sarmizegetusa valt, Decebalus sterft, de provincie Dacia wordt gesticht", "a9277172"], "d": ["In de Tweede Dacische Oorlog (105-106) nam Trajanus Sarmizegetusa in; Decebalus pleegde zelfmoord om gevangenneming te ontlopen. Dacië werd een Romeinse provincie en de goudmijnen werden aan de Romeinse economie gebonden. De eerdere fasen van de oorlog (101-105) zijn afzonderlijke items in de kronologie.", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["Hadrianus begint in Britannia de bouw van de Muur aan de noordgrens", "f4a886ec"], "d": ["Na zijn bezoek aan Britannia in 122 n.Chr. liet Hadrianus een grensmuur bouwen langs de lijn Tyne-Solway. De Muur symboliseert Romes op verdediging gerichte grenspolitiek; verder oprukken werd beproefd met de Muur van Antoninus (142), maar werd niet blijvend.", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["Septimius Severus maakt Mesopotamië een provincie; Ctesiphon wordt geplunderd", "df466924"], "d": ["In de Parthische Oorlog (195-198) nam Severus Nisibis in, plunderde Ctesiphon en richtte Boven-Mesopotamië in als Romeinse provincie. De provincie droeg Romes verste oostelijke opmars over naar de 3e eeuw.", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana: Romeins burgerrecht voor alle vrije inwoners van het Rijk", "dd4e4024"], "d": ["Caracalla maakte in 212 n.Chr. de vrije inwoners van de provincies Romeins burger; in het Rijk verdween het onderscheid tussen burger en vreemdeling. De regeling verbreedde ook de belastingbasis.", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["Postumus sticht in Gallië het afscheidingsrijk, het Gallische Keizerrijk", "4dcda41d"], "d": ["Nadat Valerianus door de Parthen was gevangengenomen (260), riep Postumus met de Rijnlegers in Gallië een keizerrijk uit; Gallië, Britannia en het grootste deel van Hispania maakten zich tot 274 los van Rome. Gallienus kon de afscheiding niet ongedaan maken.", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["Aurelianus ontruimt Dacia: het gebied ten noorden van de Donau wordt prijsgegeven", "db2ca714"], "d": ["Door de druk van de Goten ontruimde Aurelianus de provincie Dacia en trok de legioenen en de burgerbevolking terug naar het zuiden van de Donau (Dacia Ripensis). Rome liet na 165 jaar het eerste grote gebied ten noorden van de Donau varen.", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["Aurelianus verslaat het Palmyreense Rijk: de oostelijke gebieden van Zenobia keren terug naar Rome", "0a358790"], "d": ["Aurelianus versloeg in 272 bij Antiochië en Emesa het leger van Zenobia en belegerde Palmyra; Zenobia werd gevangengenomen. Syrië, Egypte en het zuiden van Anatolië werden opnieuw aan Rome gebonden.", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["Aurelianus verslaat het Gallische Keizerrijk: Rome wordt opnieuw verenigd", "c1a6a642"], "d": ["Aurelianus versloeg in 274 bij Catalaunum Tetricus; Gallië, Britannia en Hispania keerden terug naar Rome. Het Rijk werd na veertien jaar deling weer één en Aurelianus nam de titel \"Restitutor Orbis\" (\"hersteller van de wereld\") aan.", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["Julianus vestigt de Salische Franken in Toxandria als Romeinse foederati", "0fb618fe"], "d": ["Caesar Julianus versloeg in 358 de Salische Franken en stond hun toe zich op Romeins grondgebied in Toxandria (de huidige Nederlands-Belgische grens) te vestigen. Het is het begin van de vestiging onder Romeinse bescherming in het gebied waar het Frankische koninkrijk zou ontstaan.", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["De Hunnen steken de Don over en vallen de Alanen en Ostrogoten aan: begin van de Volksverhuizing", "659eb875"], "d": ["Volgens Ammianus staken de Hunnen in 375 de Don over en versloegen de Alanen, waarna zij het koninkrijk van de Ostrogotische koning Ermanaric vernietigden; het Visigotische (Tervingi) volk kwam daarop aan de Donau te staan. Zo begon in Europa het tijdperk van Hunnische heerschappij.", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["De Tervingische Goten steken de Donau over en vestigen zich op Romeins grondgebied", "3e9de0e6"], "d": ["Onder druk van de Hunnen kregen de Tervingische Goten van Fritigern in 376 van Valens toestemming om de Donau over te steken en zich op Romeins grondgebied te vestigen; problemen met bevoorrading en bestuur liepen uit op een opstand. Het gevolg was de nederlaag bij Adrianopel (Edirne) in 378.", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["Vandalen, Alanen en Sueven steken de Rijn over en trekken Gallië binnen", "2b3354ba"], "d": ["Op de traditionele datum van 31 december 406 (over de bevroren Rijn) trokken Vandalen, Alanen en Sueven Romeins Gallië binnen; de Rijnverdediging stortte in. Hun overtocht naar Spanje (409) daarna rukte fundamentele provincies van het West-Romeinse Rijk los.", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["Vandalen, Alanen en Sueven trekken Spanje binnen: Hispania wordt verdeeld", "b7036608"], "d": ["De Vandaalse, Alaanse en Suevische groepen die in de herfst van 409 vanuit Gallië de Pyreneeën overstaken, verdeelden in 411 het schiereiland onder elkaar: de Hasdingen en Sueven namen Gallaecia, de Siling-Vandalen Baetica, de Alanen Lusitania en Carthaginensis. De Visigoten (416-418) verpletterden de Silingen en Alanen en bereidden zo de overtocht van de Vandalen naar Afrika voor.", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["Rome vestigt de Visigoten in Aquitania Secunda: Visigotisch koninkrijk met Toulouse als centrum", "38a7699e"], "d": ["Rome onder bevel van Constantius vestigde de Visigoten van Wallia in 418, nadat het hen in Hispania tegen de Vandalen-Alanen had gebruikt, als foederati in Aquitania Secunda in de Garonnevallei. Het Visigotische koninkrijk met Toulouse als centrum geldt als het eerste Germaanse koninkrijk op Romeinse bodem.", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["Verdrag van Margus: de Hunnen ontvangen jaarlijks 700 pond goud van Rome", "833d8854"], "d": ["Na de dood van de Hunnenkoning Rua (433/4) sloten Attila en Bleda bij Margus een verdrag met het Oost-Romeinse Rijk: het jaarlijkse tribuut werd van 350 verhoogd tot 700 pond goud, Hunnische vluchtelingen werden teruggegeven. De Hunnen verwierven handelsrecht aan de Donaugrens.", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["Verdrag van Hippo: Rome erkent de Vandalen als foederati in een deel van Numidië en Mauretania", "f7dba59f"], "d": ["Nadat de Vandaalse koning Geiserik in 429 naar Afrika was overgestoken, sloot hij in 435 het verdrag van Hippo met Rome; de Vandalen hielden een deel van Numidië en Mauretania als foederati. Het verdrag werd in 439 verbroken met de inname van Carthago.", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["Attila neemt de Donauvestingen in: Viminacium en Singidunum (Belgrado) vallen aan de Hunnen", "0abb2c54"], "d": ["Toen het Oost-Romeinse leger op de veldtocht naar Sicilië en tegen de Vandalen was, stak Attila in 441 de Donau over; Margus, Viminacium en Singidunum werden ingenomen. Ook Sirmium viel tijdens deze veldtochten en de Hunnen bereikten het binnenland van de Balkan.", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["Rome en de Vandalen sluiten een nieuw verdrag: Africa Proconsularis, Byzacena en een deel van Numidië blijven aan de Vandalen", "e5700ddc"], "d": ["Geiserik, die Carthago innam (439), maakte met het verdrag met Valentinianus III in 442 Africa Proconsularis, Byzacena, Abaritana en een deel van Numidië rechtens tot Vandaals gebied; Rome hield alleen Mauretania en het westen van Numidië in handen.", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["Vrede van Anatolius: een brede strook ten zuiden van de Donau wordt aan de Hunnen overgelaten", "ee8ad838"], "d": ["Na de Oost-Romeinse nederlaag bij de Utus sloot Anatolius in 447 vrede met Attila: Rome liet de Hunnen een strook ten zuiden van de Donau, vijf dagreizen breed, van Singidunum tot Novae, en het jaarlijkse tribuut werd verhoogd tot 2100 pond goud.", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["Slag op de Catalaunische Velden (Châlons): Aetius en Theodorik I drijven Attila uit Gallië", "80f10e32"], "d": ["In 451 trok Attila Gallië binnen en belegerde Orléans; de coalitie van Aetius en de Visigotische koning Theodorik I dreef hem terug op de Catalaunische Velden (waar Theodorik sneuvelde). Zo kwam de opmars van de Hunnen in West-Europa tot stilstand.", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["Attila trekt Italië binnen; Aquileia wordt verwoest", "1349c67a"], "d": ["In 452 trok Attila vanuit het gebied voorbij de Alpen Noord-Italië binnen, maakte Aquileia met de grond gelijk en plunderde de Povlakte; hij trok zich terug door ziekte en de tegenaanval van het Oost-Romeinse Rijk. De gevluchte bevolking van Aquileia vormde in de lagunes de kern van Venetië.", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["Attila sterft; de Hunnenstaat valt uiteen", "47009384"], "d": ["Attila stierf in 453 op zijn bruiloftsnacht; de verdeling tussen zijn zonen en de opstand van de Germaanse onderdanen maakten een jaar later bij de Nedao (454) een einde aan de Hunnische suprematie. De Hunnen trokken zich terug naar Oost-Europa.", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["Het Visigotische koninkrijk van Eurik maakt zich feitelijk los van Rome: Auvergne wordt aan de Visigoten overgelaten", "4bbe7b0c"], "d": ["Eurik breidde sinds 466 zijn koninkrijk uit door veroveringen in Hispania en Gallië; in 475 liet Julius Nepos Auvergne varen en erkende zo feitelijk diens onafhankelijke soevereiniteit. Het Visigotische koninkrijk controleerde de West-Romeinse gebieden van de Loire tot de Middellandse Zee.", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["Julius Nepos wordt in Dalmatië vermoord: de laatste legitieme keizer van het West-Romeinse Rijk", "3b965f33"], "d": ["Nepos, die zich na de val van Romulus naar Dalmatië had teruggetrokken, werd in 480 vermoord; na zijn dood was er niemand meer die aanspraak maakte op de West-Romeinse troon en Odoaker zette zijn feitelijke macht in Italië voort in de naam van Zeno.", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["Theodorik voert de Ostrogoten Italië binnen: Odoaker wordt verslagen bij de Isonzo en bij Verona", "6a998bf8"], "d": ["Met instemming van de Oost-Romeinse keizer Zeno trok Theodorik in 489 Italië binnen en versloeg Odoaker bij de Isonzo en bij Verona; Odoaker sloot zich op in Ravenna. Het beleg van drie jaar eindigde in 493 met de overgave van Ravenna.", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["Theodorik laat Odoaker in Ravenna doden; Italië wordt van het Ostrogotische koninkrijk", "5a2db0ed"], "d": ["Het einde van het koninkrijk Italië van Odoaker: heel Italië (inclusief steden als Genua, Brindisi en Aricia) ging over naar het Oost-Gotische (Ostrogotische) koninkrijk. Na het driejarige beleg van Ravenna kwamen Odoaker en Theodorik in maart 493 overeen gezamenlijk te regeren; daarna doodde Theodorik Odoaker tijdens een banket. Italië werd met instemming van het Oost-Romeinse Rijk een Ostrogotisch koninkrijk met Ravenna als hoofdstad.", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["Vrede van Samos: Kushitische gezanten krijgen van Augustus vrede; Rome heft de van Kush geëiste schatting op, de grens wordt in Beneden-Nubië (Hiera Sykaminos) getrokken", "c3c4c20d"], "d": ["De gezanten van de Kandake gingen op aanwijzing van Petronius naar Samos, waar ze Augustus vonden; Augustus stemde in met al hun verzoeken en heft ook de door Petronius aan Kush opgelegde schattingen op. Als gevolg van de vrede kwam de Romeins-Kushitische grens ten zuiden van Philae op de lijn Hiera Sykaminos (Maharraqa) te liggen en gedurende ongeveer driehonderd jaar waren er geen ernstige conflicten.", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["Petronius voert een veldtocht tegen Kush en neemt Pselkis, Premnis en Napata in; hij legt een garnizoen in Ibrim", "4884ed51"], "d": ["Prefect Petronius versloeg met ongeveer tienduizend voetknechten en achthonderd ruiters dertigduizend Kushitische soldaten, nam Pselkis in, veroverde het fort Premnis (Qasr Ibrim) bij de eerste aanval en verwoestte Napata, waar het paleis van de Kandake stond. Omdat hij verder oprukken moeilijk vond, liet hij bij zijn terugkeer in Premnis een garnizoen van vierhonderd man met proviand voor twee jaar achter. Toen de Kandake Premnis probeerde terug te nemen, kwam Petronius op tijd en verdedigde het fort.", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["Kush neemt onder leiding van de Kandake Elephantine, Syene en Philae in; Augustus' standbeelden worden omvergeworpen", "aa665fad"], "d": ["Toen een deel van de Romeinse troepen in Egypte werd teruggetrokken voor de Arabische veldtocht van Aelius Gallus, trokken de Kushieten de Thebaïs binnen; ze versloegen het garnizoen van drie cohorten in Syene en namen Syene, Elephantine en Philae in, voerden de bevolking weg als gevangenen en wierpen de standbeelden van Caesar omver. Strabo schrijft dat de koningin die toen over Kush regeerde een eenogige vrouw was met de titel 'Kandake'.", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["Cornelius Gallus wordt de eerste prefect van Egypte; hij slaat de opstanden in Heroonpolis en Thebe neer, de grens met Kush wordt veiliggesteld", "9f688855"], "d": ["Octavianus maakte Egypte tot een aan belasting onderworpen bijzondere provincie en liet het bestuur niet aan een senator maar aan een prefect uit de ridderstand; de eerste prefect was Cornelius Gallus. Strabo schrijft dat Gallus een opstandige stad bij Heroonpolis met weinig soldaten innam en de opstand in Thebe vanwege belastingen snel neersloeg. De stèle van Gallus in Philae meldt dat de gezanten van de Kushitische vorst daar werden ontvangen en dat de regio Triakontaschoinos onder bescherming werd gesteld.", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["Octavianus trekt Alexandrië binnen; het Ptolemaeïsche rijk eindigt, Egypte gaat naar Rome", "553804ca"], "d": ["Nadat de vloot en cavalerie van Antonius naar Octavianus waren overgelopen, trok Octavianus Alexandrië binnen; Antonius pleegde zelfmoord en ook Cleopatra stierf kort daarna. Octavianus spaarde de bevolking van Alexandrië, bezocht de graven van de Ptolemaeën niet met de woorden 'ik wilde een koning zien, geen doden', en gaf Egypte als belastingplichtig land aan Cornelius Gallus. Met deze datum kwam het driehonderd jaar durende Ptolemaeïsche koninkrijk ten einde.", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["Zeeslag bij Actium: Octavianus verslaat Antonius en Cleopatra", "7e46cc73"], "d": ["De vloot van Octavianus versloeg bij Actium de vloot van Antonius en Cleopatra; het paar trok zich terug naar Egypte. Dio, een auteur die het vermijdt data te geven, vermeldt deze dag speciaal omdat Octavianus vanaf toen het rijk alleen in handen hield en zijn regeringsjaren vanaf deze dag werden geteld.", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["De Schenkingen van Alexandrië: Antonius roept Cleopatra en haar kinderen uit tot heersers van de oostelijke koninkrijken", "24e24981"], "d": ["Antonius liet in het gymnasium gouden tronen opstellen voor de verzamelde menigte en riep Cleopatra uit tot koningin van Egypte, Cyprus, Libië en Coele-Syrië, Caesarion tot haar medeheerser en haar kinderen tot koning van Armenië, Medië, Parthië en Fenicië-Syrië-Cilicië. In Rome werd deze ceremonie propaganda tegen Antonius en versnelde de burgeroorlog.", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["Antonius schenkt Cleopatra Cyprus, Fenicië, Coele-Syrië en een deel van Cilicië", "cf19a357"], "d": ["Volgens Plutarchus gaf Antonius, toen hij in Syrië kwam, Cleopatra Fenicië, Coele-Syrië, Cyprus, het grootste deel van Cilicië, het balsemproducerende deel van Judea en het aan zee grenzende deel van Nabatea. Zo controleerde de Ptolemaeïsche staat voor het eerst sinds Ptolemaeus III (ondanks de woede van Rome) een groot gebied in de oostelijke Middellandse Zee.", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["Alexandrijnse oorlog: Caesar verslaat Ptolemaeus XIII en laat Egypte aan Cleopatra", "96c9b516"], "d": ["Toen Caesar in Alexandrië kwam en als arbiter tussen Cleopatra en Ptolemaeus XIII wilde optreden, omsingelden de paleistroepen hem; in de straatgevechten die de hele winter duurden kwam hulp voor Caesar en in de slag aan de Nijl verdronk Ptolemaeus XIII. Caesar gaf Egypte aan Cleopatra en haar jonge broer Ptolemaeus XIV; Romeinse legioenen bleven in Alexandrië.", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["Gabinius zet Ptolemaeus XII met een Romeins leger weer op de Egyptische troon; in Alexandrië blijft een Romeins garnizoen", "41d8f47d"], "d": ["De verdreven Ptolemaeus XII (Auletes) kocht met een grote omkoping bij Gabinius, gouverneur van Syrië, toegang tot Egypte; Gabinius liet de Parthische veldtocht varen, trok vanuit Pelusium Egypte binnen en bracht Auletes terug op de troon. Dit is het moment waarop Egyptes onafhankelijkheid feitelijk afhankelijk werd van Romeinse garantie. Gabinius werd later in Rome berecht.", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["Rome neemt Cyprus op de Ptolemaeën en annexeert het; Cato wordt naar het eiland gestuurd", "678b2115"], "d": ["De koning van Cyprus, de broer van Ptolemaeus XII, verzette zich niet tegen het feit dat Rome het eiland innam op voorstel van Clodius; Cato werd gestuurd om het eiland over te nemen. De Ptolemaeïsche staat verloor Cyprus en de laatste zeebasis aan de kust. Plutarchus vermeldt Cato's 'zending naar Cyprus' in de levensbeschrijving van Pompeius.", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["«Dag van Eleusis»: de Romeinse gezant Popilius Laenas dwingt Antiochus IV zich uit Egypte terug te trekken", "e6883e6a"], "d": ["Direct na de slag bij Pydna (22 juni 168 v.Chr.) bracht de Romeinse gezant Gaius Popilius Laenas Antiochus, die Alexandrië belegerde, het bevel van de Senaat de oorlog te staken over; hij trok een cirkel om de koning heen opdat hij zijn antwoord zou overwegen. Antiochus trok zich terug. Egypte behield zijn onafhankelijkheid onder Romeinse bescherming zonder haar te verliezen.", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["Antiochus IV valt Egypte aan; in de Zesde Syrische Oorlog rukt hij op naar Memphis en Naucratis", "b85e6712"], "d": ["Antiochus IV, als antwoord op Ptolemaeus VI's voorbereiding om Coele-Syrië terug te nemen, trok Egypte binnen en kwam via Pelusium naar de Nijl; hij verdedigde zijn recht op Coele-Syrië en behandelde de bevolking van Naucratis goed. De oorlog eindigde een jaar later door Romes tussenkomst zonder Egypte te vernietigen maar de staat verzwakt achterlatend.", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["De opstand van Thebe wordt neergeslagen: Komanos brengt Boven-Egypte terug onder Ptolemaeïsche heerschappij", "4c0e4f10"], "d": ["Na ongeveer twintig jaar separatistisch bestuur nam de Ptolemaeïsche bevelhebber Komanos Thebe terug van de inheemse farao Ankhwennefer en werd Boven-Egypte opnieuw aan de Ptolemaeïsche staat gebonden.", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["De Synode van Memphis vaardigt het Decreet van Rosetta uit: Ptolemaeus V verleent belastingschenkingen aan tempels", "5643b91f"], "d": ["De door de Egyptische priesters in Memphis bijeengeroepen synode bevestigde de troonsbestijging van Ptolemaeus V en riep de belastingschenkingen van de koning aan de tempels, de onderdrukking van opstanden en de instelling van de koningscultus uit. Het decreet werd in het Grieks, Demotisch en hiërogliefen geschreven; de Steen van Rosetta is deze drietalige tekst. De tekst verwijst ook naar de onderdrukking van de rebellen in de Delta (Lykopolis).", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["Slag bij Panion: Antiochus III verslaat Scopas; Coele-Syrië gaat van de Ptolemaeën naar de Seleuciden", "97e30e58"], "d": ["In de Vijfde Syrische Oorlog versloeg Antiochus III de Ptolemaeïsche bevelhebber Scopas de Aetoliër bij Paneion; volgens Josephus nam Antiochus de door Scopas ingenomen steden van Coele-Syrië terug en nam ook Samaria in, de Joden sloten zich uit eigen beweging bij Antiochus aan. Coele-Syrië (Syrië-Palestina) kwam hierna onder Seleucidisch bestuur; de Ptolemaeïsche staat trok zich uit de regio terug.", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["In Thebe verschijnen separatistische inheemse farao's: Boven-Egypte komt los van Ptolemaeïsche heerschappij", "d10abb36"], "d": ["De na de overwinning bij Raphia bewapende inheemse Egyptenaren raakten, in de woorden van Polybius, opgeblazen door de overwinning en luisterden niet meer naar bevelen van de koning; in de Delta en Boven-Egypte braken opstanden uit. In Thebe hielden inheemse farao's (Horwennefer, later Ankhwennefer) ongeveer twintig jaar Boven-Egypte tegen de Ptolemaeën in handen.", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["Slag bij Raphia: Ptolemaeus IV verslaat Antiochus III; Coele-Syrië blijft bij de Ptolemaeën", "34362178"], "d": ["Bij Raphia versloeg het leger van Ptolemaeus IV, met zijn grote aantal inheemse Egyptische falanx-soldaten (hopliten), het leger van Antiochus III; Antiochus trok zich terug uit Coele-Syrië en de regio bleef tot 200 in Ptolemaeïsche handen. De bewapening van de inheemse Egyptenaren voedde later de separatistische opstanden in Boven-Egypte.", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["Antiochus III herovert Seleucia Pieria van de Ptolemaeën", "39ee3a52"], "d": ["Antiochus III belegerde Seleucia Pieria, dat in Ptolemaeïsche handen was, en nam het in door officieren om te kopen; Polybius schrijft dat de stad sinds de tijd van Ptolemaeus III werd gehouden door een garnizoen van de Egyptische koningen. Met deze overwinning verkregen de Seleuciden de haven van Antiochië en maakten zich gereed voor de mars naar Coele-Syrië (Vierde Syrische Oorlog).", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["Ptolemaeus III bezet in de Laodice-oorlog Syrië en Mesopotamië; Seleucia Pieria komt in Ptolemaeïsche handen", "04472253"], "d": ["Ptolemaeus II stierf op 28 januari 246 v.Chr.; Ptolemaeus III viel de Seleucidische staat aan om zijn zus Berenice te beschermen. Hij werd ontvangen in Seleucia Pieria en Antiochië; de Babylonische Kroniek (BCHP 11) meldt dat zijn leger vanaf december 246 v.Chr. voor Babylon stond. De Adulis-inscriptie beweert dat hij het gebied ten westen van de Eufraat, Cilicië, Pamfylië en Thracië veroverde. Seleucia Pieria bleef vele jaren in Ptolemaeïsche handen.", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["Na Ipsos bezet Ptolemaeus Coele-Syrië; Seleucus protesteert (wortel van de Syrische Oorlogen)", "a109388f"], "d": ["Na de slag bij Ipsos (301 v.Chr.) kwamen Seleucus, Lysimachus en Cassander overeen heel Syrië aan Seleucus te geven; Ptolemaeus bezette Coele-Syrië echter met zijn leger en hield het. Dit geschil leidde tot zes Syrische Oorlogen in de volgende twee eeuwen. Antiochus III verdedigde dit standpunt later zoals Polybius het overlevert.", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["Ptolemaeus roept zichzelf uit tot koning; de dynastie der Ptolemaeën wordt officieel gesticht", "008c723a"], "d": ["Nadat Antigonus en Demetrius de koningstitel hadden aangenomen (306 v.Chr.), nam ook Ptolemaeus de koningstitel aan; Egypte begon te worden genoemd als onafhankelijk Hellenistisch koninkrijk. Het feit dat de dynastie zich als farao's van Egypte presenteerde, bespoedigde ook het akkoord met de inheemse priesterstand.", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["Slag bij Gaza: Ptolemaeus en Seleucus verslaan Demetrius (Syrië korte tijd bij Ptolemaeus)", "ea0d264f"], "d": ["Demetrius, zoon van Antigonus, werd voor Gaza verslagen door het gecombineerde leger van Ptolemaeus en Seleucus; Ptolemaeus trok Coele-Syrië binnen. Door een tegenzet van Antigonus ging het gebied kort daarna weer verloren; de vrede (311 v.Chr.) legde dit vast.", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["De Egyptische veldtocht van Perdiccas mislukt bij de oversteek van de Nijl; Perdiccas wordt door zijn leger gedood", "c1792117"], "d": ["In de oorlog van de Diadochen trok Perdiccas, regent van Alexander, Egypte binnen tegen Ptolemaeus, die de lijkstoet van Alexander had ontvoerd, maar kon de Nijl niet oversteken, verloor veel mannen en werd door zijn officieren gedood. Ptolemaeus hield Egypte in handen.", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["Ptolemaeus voegt Cyrene (Cyrenaica) bij Egypte", "65316c50"], "d": ["Ptolemaeus greep in in de interne twisten in Cyrene en bond onder bevel van Ophellas de Libische regio Cyrenaica aan Egypte. Zo breidde Ptolemaeïsch Egypte zich ook naar het westen uit; Cyrenaica bleef in de volgende eeuwen in handen van een tak van de Ptolemaeïsche dynastie.", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["Alexander raadpleegt in de oase Siwa het Orakel van Ammon", "c437ced0"], "d": ["Alexander trok van de kust de woestijn in naar de oase Siwa, waar de Ammontempel staat, en raadpleegde het orakel; Arrianus schrijft dat hij het antwoord kreeg dat hem behaagde. Dit bezoek voedde Alexanders legitimiteit in Egypte en de latere verhalen over zijn zoonschap van de god.", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["Alexander trekt Egypte binnen; de Perzische satraap Mazakes geeft zich over, Egypte komt onder Macedonisch bestuur", "c4a5f014"], "d": ["Alexander, vertrokken uit Gaza, kwam op de zevende dag in Pelusium aan, ook zijn vloot had daar aangelegd. De satraap Mazakes, die na Issos geen Perzische steun meer had, bood geen weerstand en ontving Alexander vriendelijk in de steden. Alexander legde een garnizoen in Pelusium en trok verder naar Memphis; hij liet het bestuur over aan twee inheemse (Doloaspis, Petisis) gouverneurs en stelde Macedonische bevelhebbers aan in Memphis en Pelusium. Egypte kwam los van Perzische heerschappij en werd bij het rijk van Alexander gevoegd.", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["Artaxerxes III verovert Egypte opnieuw; Nectanebo II vlucht naar Nubië", "55d78a8d"], "d": ["Toen Artaxerxes III na de inname van Sidon naar Egypte optrok, stortte de verdediging van Pelusium in; Nectanebo II vluchtte zonder in Memphis het beleg af te wachten naar Boven-Egypte en Nubië. Egypte werd voor de tweede keer een Perzisch satrapie; het lot van de laatste inheemse farao is onbekend.", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["Takhos voert een veldtocht naar Syrië; Nectanebo II grijpt met een staatsgreep de troon, Agesilaus wisselt van kamp", "4e1e9804"], "d": ["Takhos verzamelde Griekse huurlingen (de Spartaanse koning Agesilaus en de Athener Chabrias) om Perzisch Syrië aan te vallen; tijdens de veldtocht riep zijn neef Nectanebo II zichzelf uit tot koning. Agesilaus koos de zijde van Nectanebo; Plutarchus schrijft dat het in Griekenland werd bekritiseerd dat Agesilaus op hoge leeftijd tegen betaling vocht voor een 'barbaarse rebel'.", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["Nectanebo I slaat de Perzische invasie (Pharnabazus-Iphicrates) af", "0a8bc67d"], "d": ["Nectanebo I, stichter van de 30e Dynastie, keerde de landing van het Perzische leger onder bevel van Pharnabazus en van de Athener Iphicrates in de Delta af dankzij de overstroming van de Nijl en onenigheid tussen de bevelhebbers. Dit succes verlengde Egyptes onafhankelijkheid met nog 30 jaar.", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["De opstand van Inaros: de door Athene gesteunde Egyptische opstand brengt de Perzen in Memphis in het nauw, stort in 454 in bij Prosopitis", "0cd93c33"], "d": ["De Libiër Inaros bracht bijna heel Egypte in opstand tegen Artaxerxes en vroeg de Atheners om hulp; de Atheense vloot voer de Nijl op en nam twee derde van Memphis in, en belegerde het resterende 'Witte Fort'. De Perzische bevelhebber Megabyzus belegerde de Atheners anderhalf jaar op het eiland Prosopitis (door het kanaal droog te leggen) en vernietigde hen; Inaros werd gevangengenomen en gekruisigd. Amyrtaeus in de moerassen van de Delta kon echter niet worden gegrepen.", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["Egypte komt in opstand tegen de Perzische heerschappij; Xerxes I slaat de opstand neer en bestuurt Egypte strenger", "9d3d7462"], "d": ["De Egyptische opstand die voor de dood van Darius I begon, werd in de eerste jaren van Xerxes I neergeslagen; Xerxes benoemde zijn broer Achaemenes tot satraap en begon Egypte strenger te besturen dan in de tijd van Darius.", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["Cambyses' Kushitische veldtocht mislukt door gebrek aan water en voedsel; Egyptes zuidgrens blijft bij Elephantine", "4ebbad8c"], "d": ["Na Egypte plande Cambyses een veldtocht tegen de 'Langlevende Ethiopiërs' (Kush); volgens Herodotus stuurde de Kushitische koning de Perzische gezanten zijn boog en liet zeggen dat ze moesten aanvallen 'wanneer ze de boog gemakkelijk konden spannen'. Het leger bleef zonder proviand in de woestijn en keerde terug. Ook Strabo vermeldt de plaats waar het leger van Cambyses in een storm in de woestijn omkwam. Kush bleef onafhankelijk; de Perzische zuidgrens stopte bij Elephantine.", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["Amasis verslaat Apries en bestijgt de Egyptische troon; Griekse kooplieden worden in Naucratis gevestigd", "75a24b0b"], "d": ["Apries, die met Griekse huurlingen terugkeerde van de Libische veldtocht, werd bij Momemphis verslagen door Amasis, die aan het hoofd van de inheemse troepen in het leger was gekomen; Amasis bestuurde Egypte vanuit Sais en wees de Grieken Naucratis als enige handelshaven toe. Aan het einde van zijn bewind (526 v.Chr.) groeide de Perzische dreiging.", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["Psammetichus II voert een veldtocht naar Nubië: de druk van Kush op de Egyptische grens wordt gebroken", "8f0aaf9d"], "d": ["De Nubische veldtocht van Psammetichus II wordt bij Herodotus genoemd als 'veldtocht naar Ethiopië'; het Egyptische leger en Griekse/Karische huurlingen lieten Griekse inscripties achter in Abu Simbel. De stèle van het 3e jaar in Thebe (Karnak) meldt dat het koninkrijk Kush een zware nederlaag werd toegebracht en de overwinningsstèle van Kalabsha herdenkt dit; de veldtocht zou tot de Derde of Vierde Cataract zijn opgerukt. Volgens de bronnen verschoof het politieke centrum van Kush in de volgende periode (Aspelta, ca. 591 v.Chr.) naar het zuiden, naar Meroë.", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["Nebukadnezar valt de Egyptische grens aan; in een open veldslag lijden beide partijen zware verliezen, Babylon trekt zich terug", "45655313"], "d": ["De Babylonische koning Nebukadnezar trok in zijn 4e jaar naar Egypte; de Egyptische koning verzamelde zijn leger en trof hem, in de open veldslag putten beide partijen elkaar zwaar uit. Nebukadnezar keerde terug naar Babylon om zijn leger opnieuw uit te rusten. Egypte verdedigde zijn grens, maar Syrië-Palestina was aan Babylon gevallen.", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["Slag bij Karkemish: Nebukadnezar verslaat het Egyptische leger; Egypte verliest Syrië", "ba486ac1"], "d": ["Kroonprins Nebukadnezar stak met het Babylonische leger de Eufraat over tegen het Egyptische leger bij Karkemish en versloeg het, vernietigde de vluchtelingen in het gebied van Hamat en nam het hele gebied van Hamat in. Egypte trok zich terug uit Syrië tot achter de Sinaï-grens; Babylon werd heer van Syrië-Palestina.", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["Necho II trekt Syrië-Palestina binnen; hij verslaat Josia bij Megiddo en rukt op naar de Eufraat", "f887d6fd"], "d": ["Necho II, die de westelijke provincies van het ineenstortende Assyrië wilde innemen, trok naar Syrië; hij liet Josia, koning van Juda, die op zijn weg stond, bij Megiddo doden. Herodotus zegt 'Necho versloeg de Syriërs bij Magdolos en nam de grote Syrische stad Kadytis in'. Zo controleerde Egypte korte tijd Syrië-Palestina tot de Eufraat.", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["Psammetichus I brengt Boven-Egypte onder controle door zijn dochter Nitocris te laten adopteren door de Godsvrouw van Thebe", "bf768452"], "d": ["Psammetichus I liet in zijn 9e jaar zijn dochter Nitocris als adoptiefdochter naar Thebe sturen van Shepenwepet, dochter van de Kushitische koning Taharqa (Godsvrouw van Thebe); Shepenwepet droeg haar bezit over aan Nitocris en zo kwam het tempelbezit van Thebe in handen van de Saïeten. De adoptiestèle toont dat Psammetichus in zijn 9e jaar de volledige controle over Thebe kreeg en dat Tantamani Boven-Egypte tot dan toe had verloren.", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["Het Assyrische leger plundert Thebe; Tantamani trekt zich terug naar het zuiden, de Kushitische heerschappij in Egypte stort in", "777fc1a5"], "d": ["De legers van Assurbanipal achtervolgden Tantamani vanuit Memphis tot Thebe en plunderden de stad; de tempelschatten van Thebe werden naar Nineve gebracht. Tantamani trok zich terug naar Nubië; de Kushitische heerschappij in Boven-Egypte loste op. Deze plundering wordt in het Oude Testament 'No-Amon' (Nahum 3:8) genoemd.", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["De 26e Dynastie begint: Psammetichus I komt in Sais als Assyrische vazal aan de macht in Beneden-Egypte", "f270eac3"], "d": ["Van de door Assyrië in Egypte gevestigde Delta-prinsen begon de heerser van Sais, Psammetichus I, de 26e (Saïtische) Dynastie. Volgens Herodotus ontsnapte Psammetichus aan de 'twaalf koningen', werd naar het moeras verdreven en verwierf de Delta opnieuw. Na Assyrië en Kush kwam Egypte weer in handen van een inheemse dynastie; het duurde enkele jaren om Thebe en Boven-Egypte te winnen.", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["Tantamani daalt van Kush af en neemt Thebe en Memphis opnieuw in; hij belegert de Assyrische vazallen", "f84c87a4"], "d": ["Tantamani, opvolger van Taharqa, voer volgens de Droomstèle na zijn kroning in Napata noordwaarts langs de rivier: hij bracht een offer aan Khnum in Elephantine, kwam naar Thebe en Memphis, nam de stad in door wie zich tegen hem verzette over de kling te jagen, terwijl de heren van de Delta zich verborgen of onderwierpen. Deze onderneming bedreigde de Delta-orde van Psammetichus I en Assyrië en leidde tot de Assyrische strafexpeditie.", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["Esarhaddon trekt Egypte binnen en neemt Memphis in; Taharqa trekt zich terug naar het zuiden", "a138bcac"], "d": ["De Assyrische koning Esarhaddon trok in zijn 10e jaar naar Egypte; het Assyrische leger richtte in Egypte een groot bloedbad aan en de Kushitische koning Taharqa vluchtte naar het zuiden. De vorstendommen in de Delta werden Assyrische vazallen, Memphis en Noord-Egypte kwamen tijdelijk in Assyrische handen. Esarhaddon stierf twee jaar later onderweg op een nieuwe veldtocht.", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["Sanherib ontmoet tijdens zijn Judese veldtocht het Kushitisch-Egyptische leger bij Eltekeh", "7f423351"], "d": ["Tijdens de Kanaänitische veldtocht van de Assyrische koning Sanherib kwam het Kushitische Egyptische leger Juda te hulp en raakte bij Eltekeh slaags met Assyrië; het Assyrische leger trok zich terug zonder Jeruzalem in te nemen. Josephus vertelt dat Sanherib, toen hij hoorde dat de Kushitische koning Tirhaka met een groot leger kwam, Pelusium verliet. Dit is de eerste directe botsing tussen Kush-Egypte en Assyrië.", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["Piye (Piankhi) daalt af naar Egypte: hij verslaat de coalitie van Tefnakht en onderwerpt de heersers van Memphis en de Delta", "bb36f7c4"], "d": ["Tefnakht van Sais had een bondgenootschap gevormd dat zich uitstrekte van de Delta tot Memphis en Midden-Egypte en had Herakleopolis belegerd. Piye, die vanuit Napata een veldtocht ondernam, daalde in zijn 21e jaar naar het noorden af, nam de bondgenootsteden (Hermopolis, Memphis, Heliopolis) in en aanvaardde de overgave van de Delta-prinsen; daarna keerde hij terug naar Napata. Zo werd Kush het hoofd van heel Egypte (25e Dynastie).", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["De koning van Kush (Napata), Kashta, rukt op naar Boven-Egypte; hij dringt door tot Elephantine en Thebe", "b0f5be7f"], "d": ["De Kushitische koningen in Napata groeiden naar het noorden sterker door gebruik te maken van Egyptes versnippering in de Derde Tussenperiode. Uit monumenten blijkt dat Kashta tot Elephantine invloed in Boven-Egypte vestigde; Amenirdis I (zus van Piye) uit de Kushitische dynastie werd in Thebe geïnstalleerd met de titel 'Godsvrouw' van Amon en dit ambt werd Kush' instrument in Thebe. Zo werd de grond bereid voor de stichting van de 25e Dynastie.", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["Shoshenq voert een veldtocht naar Kanaän: Jeruzalem en de steden van Israël-Juda komen in de lijst van Karnak", "1607ae3a"], "d": ["Shoshenqs Kanaänitische veldtocht komt overeen met het bijbelverhaal (1 Koningen 14:25) dat meldt dat hij in het 5e jaar van koning Rehabeam schatting van Jeruzalem ontving; op de Bubastitische Poort in Karnak staan ongeveer 150 stadsnamen (grofweg vijftig tot zestig van Israël, honderd van Juda). Ook Josephus vertelt dat Shishak Jeruzalem innam en de schat meenam. Deze veldtocht is Egyptes langste buitenlandse operatie in de Derde Tussenperiode.", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["Shoshenq I (van Meshwesh/Libische afkomst) sticht de 22e Dynastie; hoofdstad Bubastis", "dae122c7"], "d": ["Libische Meshwesh-generaals hadden zich na het Nieuwe Rijk in de Delta gevestigd; onder hen herenigde Shoshenq I Egypte na de 21e Dynastie in Tanis. Door zijn zoon hogepriester van Amon te maken, bond hij ook Thebe aan de dynastie. Dit tijdperk bracht een korte opleving die Egypte weer op buitenlands beleid (de Kanaänitische veldtocht) richtte.", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["Het Nieuwe Rijk eindigt: in de laatste jaren van Ramses XI zijn Smendes (Tanis) in de Delta en de hogepriester van Amon in Thebe feitelijk onafhankelijk", "1828ceb0"], "d": ["In de laatste periode van Ramses XI stortte de centrale staat in: in Thebe beheerst hogepriester van Amon Herihor Boven-Egypte, in de Delta bestuurt Nesubanebdjed (Smendes) vanuit Tanis; het Verhaal van Wenamon legt deze verdeling vast (Wenamons reis van Herihor naar Smendes). Smendes stichtte uiteindelijk de 21e Dynastie; ook Nubië kwam in deze onrust los van Egyptische controle.", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["Ramses III verslaat de Zeevolken te land (Djahy) en op zee in de Delta", "9068ae7b"], "d": ["In het 8e jaar van Ramses III trokken Peleset, Tjeker, Denyen, Sherden en andere Zeevolken over land en zee naar de Egyptische grens; het Egyptische leger hield hen eerst aan de Kanaänitische grens, daarna in de zeeslag bij de Deltamondingen tegen. De reliëfs van Medinet Habu documenteren dit. Egypte hield Kanaän weer in handen, maar na dit tijdperk begon zijn invloed in de oostelijke Middellandse Zee af te nemen.", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["Merneptah verslaat het bondgenootschap van Libiërs en Zeevolken in de westelijke Delta; in Kanaän wordt de naam «Israël» voor het eerst genoemd", "e512311e"], "d": ["In het 5e jaar van Merneptah vielen de Meshwesh onder leiding van de Libu en de «Volkeren van de Zee» (Ekwesh, Teresh, Lukka, Shardana, Shekelesh) de westelijke Delta binnen; het Egyptische leger verstrooide hen in een zesuur durende slag bij Perire. De overwinningsstèle die dezelfde gebeurtenissen beschrijft noemt in Kanaän Ashkelon, Gezer, Yenoam en «Israël»; dit is de oudst bekende vermelding van de naam Israël.", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["«Eeuwig Verdrag» tussen Ramses II en Hattusili III: Egyptisch-Hettitische oorlog eindigt", "100f2a75"], "d": ["In het 21e jaar van Ramses II brachten Hettitische gezanten de verdragstablet naar Pi-Ramesse. Het verdrag beëindigde de ongeveer vijftien jaar durende Syrische oorlog: beide partijen zagen af van verdere veroveringsplannen in Syrië, sloten een defensief bondgenootschap en kwamen overeen vluchtelingen uit te leveren en elkaar wederzijds te helpen. Volgens Breasteds samenvatting wordt de grens in de tekst niet vermeld; de invloedssfeer van beide staten bleef in de feitelijke toestand (de strook Kadesh-Amurru bij Hatti, Kanaän bij Egypte).", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["Ramses II treft bij Kadesh de Hettieten van Muwatalli II; de uitkomst blijft onbeslist", "f5ad96db"], "d": ["Ramses II ontmoette voor Kadesh aan de Orontes het Hettitische leger; doordat de Hettitische strijdwagens een hinderlaag legden, kwam het Egyptische leger op het punt uiteen te vallen; Ramses voerde met zijn eigen lijfwacht een tegenaanval uit en keerde het. De slag bracht geen beslissing; Kadesh en Amurru bleven onder Hettitische controle, Egyptes noordgrens bleef weer aan de kust van Kanaän.", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["Seti I voert een veldtocht van Zuid-Kanaän tot de Fenicische kust: Egypte krijgt Kanaän en de Libanese kust weer in zijn macht, neemt Kadesh in", "ad7bf1cd"], "d": ["Volgens de reliëfs van Karnak onderwierp Seti I's veldtocht van het 1e jaar eerst de Shasu-bedoeïenen, trok daarna via Palestina naar het noorden en onderwierp Peher en Beth-Shean, Yenoam, Tyrus en de Libanese beys. In de bovenste rij van de reliëfs wordt ook de inname van Kadesh afgebeeld. Breasted merkt op dat de blijvende noordgrens zich niet verder uitstrekte dan de oost-westlijn langs de Fenicische kust en dat de Hettitische macht niet werd gebroken; dit is de achtergrond van Ramses II's slag bij Kadesh.", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["In de Amarna-tijd lost Egyptes heerschappij in Noord-Syrië op; Amurru en Kadesh verschuiven naar de Hettitische invloedssfeer", "90d00c5a"], "d": ["De Amarna-brieven (EA) tonen dat de vazallen van Noord-Syrië (Aziru van Amurru, de heersers van Kadesh) speelden tussen Egypte, Mitanni en Hatti en dat Egypte niet in de regio kon ingrijpen. Als gevolg van de veldtochten van de Hettitische koning Suppiluliuma I, die Mitanni uitputtten, kwamen Amurru en Kadesh onder Hettitische invloed; zo trok Egyptes noordgrens in Syrië zich terug tot Kanaän.", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["Amenhotep IV (Achnaton) verplaatst Egyptes hoofdstad naar Achetaton (Amarna)", "53cadac3"], "d": ["Achnaton maakte de Aton-verering tot staatsgodsdienst en riep een nieuwe stad (Achetaton) in de woestijn in Midden-Egypte uit tot hoofdstad; de «Grensstèles» die de grenzen van de stad bepalen dateren uit het 4e-5e jaar. De Amarna-brieven tonen dat de Syrische vazallen in deze tijd om hulp vroegen maar Egypte niet reageerde.", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["Amenhotep II bereikt in Nubië Napata en plaatst een zuidgrensstèle: Egyptes zuidelijkste punt", "2f61f824"], "d": ["Amenhotep II trok bij zijn terugkeer van de Syrische veldtocht (juli) naar Nubië; volgens de tempelinscripties in Elephantine en Amada liet hij zes van de zeven uit Syrië meegebrachte prinsen aan de muren van Thebe en de zevende aan de muren van Napata ophangen. Volgens Breasted plaatste de koning in of vlak boven Napata een stèle die de zuidgrens aangaf: Egyptes feitelijke heerschappij in Nubië strekte zich zo voorbij Tombos (Derde Cataract) uit tot het gebied van de Vierde Cataract.", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["Thutmosis III steekt de Eufraat over en trekt het land van Mitanni binnen; hij plaatst een grensstèle in Naharin", "ebdbeebe"], "d": ["In het 33e jaar rukte Thutmosis III vanuit Retenu op, stak de Eufraat over, plunderde de plaatsen van Naharin en plaatste ten oosten van de rivier een grensstèle; naast de stèle van zijn vader plaatste hij een tweede. Deze veldtocht is het verste punt in het noorden van Egyptes invloed en toont de drempel van een rechtstreeks conflict met Mitanni.", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["Thutmosis III verslaat bij Megiddo de Kanaänitische coalitie onder leiding van Kadesh; Kanaän-Syrië komt onder Egyptische heerschappij", "439dc6e8"], "d": ["Thutmosis III versloeg in het 23e jaar, 1e Shemu-maand, 21e dag voor Megiddo de Kanaänitische coalitie onder leiding van de heerser van Kadesh; de vijand vluchtte de stad in en Megiddo gaf zich na een lang beleg over. Deze in de Annalen van Karnak vastgelegde veldtocht maakte Egyptes afhankelijkheid van Kanaän en Zuid-Syrië blijvend en was het begin van de uitbreiding van het rijk.", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["Thutmosis I voert een Aziatische veldtocht tot aan de oever van de Eufraat (Naharin)", "50ce0679"], "d": ["Volgens de inscripties van Ahmose-Pennekhbet en Ahmose-Ebana voerde Thutmosis I na de Nubische veldtocht een grote veldtocht naar Naharin; Thutmosis III voegde later naast de door zijn vader aan de Eufraat geplaatste grensstèle zijn eigen stèle toe. Dit is de eerste geregistreerde periode waarin Egyptes invloed tot de Eufraat reikte.", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["Ahmose voert een veldtocht naar Beneden-Nubië en onderdrukt de Nubische bergbewoners", "dbbd94b7"], "d": ["Ahmose voer na de Aziaten te hebben verslagen de rivier op naar het zuiden, naar Khent-hen-nefer, en onderdrukte de Nubische bergbewoners. Deze veldtocht is de eerste stap in het proces waarbij Beneden-Nubië, sinds de fortenlijn van het Middenrijk in handen van Kerma, bij Egypte werd gevoegd.", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["Ahmose neemt Avaris, de hoofdstad van de Hyksos, in en belegert en neemt Sharuhen", "b7bb3099"], "d": ["Ahmose belegerde en nam Avaris in de Oostelijke Delta in; de Hyksos vluchtten naar Azië en hij achtervolgde hen tot Sharuhen in Zuid-Kanaän. De inscriptie van Ahmose, zoon van Ebana, meldt dat Sharuhen zes jaar werd belegerd. Zo kwam Egyptes Delta los van Hyksos-controle en kwam Egypte in een positie om politieke invloed op Kanaän uit te oefenen.", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["Ahmose I bestijgt in Thebe de troon; de 18e Dynastie en het Nieuwe Rijk beginnen", "0798cfa3"], "d": ["Ahmose, broer van Kamose, de laatste koning van de 17e Dynastie in Thebe, besteeg de troon als kind; in zijn bewind zou hij de Hyksos uit Egypte verdrijven en de heerschappij over Nubië en Kanaän herstellen en de 18e Dynastie en het Nieuwe Rijk beginnen. De troonsbestijging is niet het einde van de Hyksos, maar het begin van de laatste fase van de strijd.", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["Egypte wordt in tweeën gedeeld: de Hyksos (15e Dynastie) besturen vanuit Avaris Beneden- en Midden-Egypte, de 17e Dynastie in Thebe Boven-Egypte", "cd743737"], "d": ["De in Avaris in de Oostelijke Delta gevestigde «vreemde heersers» (Hyksos) van Kanaänitische afkomst stichtten de 15e Dynastie en bestuurden Beneden-Egypte en Midden-Egypte tot Cusae (Kusiye); de inheemse 17e Dynastie in Thebe hield Boven-Egypte in handen. Ten zuiden van Thebe stond het koninkrijk Kerma als onafhankelijke macht. Dat Avaris de Hyksos-hoofdstad was, wordt bij Breasted bevestigd door het beleg-verhaal van Ahmose.", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["Senwosret III trekt bij Semna Egyptes zuidgrens terug tot de Tweede Cataract; hij verbiedt Nubiërs de doorgang", "753ef5fd"], "d": ["De Semna-stèle uit het 8e jaar van Senwosret III bepaalt de «zuidgrens»: Nubiërs mogen deze lijn, behalve wie voor handel naar Iken komt, niet over land of via de rivier overschrijden. De koning vestigde in Beneden-Nubië een reeks forten (Buhen, Semna, Kumma, Uronarti e.a.) en stopte Kerma's uitbreiding naar het noorden. Dit is de zuidelijkste blijvende grens van het Middenrijk in Nubië.", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["Amenemhat I sticht de 12e Dynastie; hoofdstad verplaatst naar Itj-tawy", "26c43dad"], "d": ["Amenemhat I, die als vizier koning werd, stichtte de 12e Dynastie en verplaatste de hoofdstad van Thebe naar de nieuwe stad (Itj-tawy) tussen Memphis en de Fayoem. Deze dynastie kende het meest stabiele tijdperk van het Middenrijk en vestigde het fortensysteem in Nubië.", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["Mentuhotep II verslaat Herakleopolis en herenigt Egypte (Sematawy)", "dbc6136f"], "d": ["Tegen het 39e jaar van zijn bewind schakelde Mentuhotep II Herakleopolis uit, bracht Boven- en Beneden-Egypte onder één bestuur en voegde de naam «Hij die de Twee Landen verenigt» (Sematawy) aan zijn titel toe. Het centrale bestuur werd naar Thebe verplaatst; de bevoegdheden van de nomarchen werden beperkt.", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["Mentuhotep II bestijgt in Thebe de troon; het Middenrijk begint en de strijd tegen Herakleopolis wordt intenser", "edde038d"], "d": ["Het lange bewind van Mentuhotep II (51 jaar) geldt als het begin van het Middenrijk. In de eerste helft van zijn bewind verkeerde Thebe in oorlog met Herakleopolis; toen in zijn 14e jaar de Herakleopolitaanse troepen de heilige begraafplaats in Abydos schonden, stuurde de koning een leger naar het noorden. De feitelijke eenwording van Egypte kwam veel later, rond het 39e jaar van zijn bewind (zie het volgende item).", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["In Thebe begint de 11e Dynastie: de Intef-dynastie sticht een onafhankelijk koninkrijk in Boven-Egypte", "0e021743"], "d": ["De nomarchen van Thebe uit het geslacht Intef namen de koningstitel aan en stichtten in het zuidelijke uiteinde van Boven-Egypte (van Elephantine tot Abydos) hun eigen koninkrijk. Een latere Intef meldt in zijn inscriptie dat hij de nomos Thinis, waar Abydos ligt, innam en «al zijn forten opende»; zo werd de grens Thebe-Herakleopolis rond Abydos getrokken.", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["In Herakleopolis (Henen-nesut) 9e-10e Dynastie: de Kheti-dynastie bestuurt Noord-Egypte", "9dde2d0c"], "d": ["In de Eerste Tussenperiode vulde de dynastie in Herakleopolis de leegte van Memphis op; trouwe nomarchen als Tefibi, gouverneur van Siut in Midden-Egypte, streden aan de zijde van dit koninkrijk tegen het zuiden (Thebe). De grafinscriptie van Siut vertelt dat de Zuiderlingen vanuit Elephantine naar het noorden oprukten en tot aan de «zuidgrens» werden teruggedreven. Zo viel Egypte uiteen in twee hoofdmachten: Herakleopolis (Noord) en Thebe (Zuid).", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["Het Oude Rijk stort in: na Pepi II valt de centrale staat uiteen, de Eerste Tussenperiode begint", "0339e96b"], "d": ["Na het zeer lange bewind van Pepi II kwam de 6e Dynastie ten einde; het koninkrijk viel uiteen in gebieden waar de nomarchen (provinciegouverneurs) feitelijk onafhankelijk bleven. De grafinscripties (Siut, Elephantine e.a.) tonen dat de lokale gouverneurs in eigen naam dateerden en hun eigen soldaten mobiliseerden. De kortlevende 7e-8e Dynastieën in Memphis konden niet het hele land beheersen.", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["De gouverneur van Elephantine, Harkhuf, onderneemt tochten naar het land Yam: diplomatieke en handelsband voorbij Nubië", "705b9808"], "d": ["Harkhuf, gouverneur van Elephantine, maakte voor Merenre en Pepi II enkele tochten naar het zuiden, naar het land Yam; zijn inscriptie beschrijft de weg die hij beheerste en de producten die hij meebracht. De brief die het kindkoning Pepi II hem schreef is ook in de grafinscriptie bewaard gebleven. Deze tochten zijn verslagen van het contact met de pre-Kerma/Oud-Kerma-gemeenschappen aan de zuidgrens van het Oude Rijk.", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["In de 6e Dynastie een grote veldtocht onder Weni naar de Kanaänitische grens met Nubische eenheden", "69c94c55"], "d": ["Volgens de autobiografie van Weni verzamelde de koning tegen de «Aziatische Zandbewoners» een leger van tienduizenden mannen; het leger bestond uit eenheden uit Zuid-Egypte (tot Elephantine), uit het Noorden en ook uit Nubische stammen (Irtjet, Medja, Yam, Wawat, Kau). De tekst toont dat het Oude Rijk Nubië als soldatenreservoir gebruikte en veldtochten tot Zuid-Kanaän kon uitvoeren.", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["De Grote Piramide van Chufu (Cheops) in Gizeh wordt gebouwd", "282359fc"], "d": ["De piramide van Chufu, heerser van de 4e Dynastie, in Gizeh is het symbool van de mobilisatie van arbeidskracht en middelen in het Oude Rijk. Het door Herodotus overgeleverde verhaal van Egyptische priesters tekent Chufu als de tiran die tempels sloot en het volk dwong stenen te slepen; dit is als zodanig de blik van een latere tijd, geen eigentijds document.", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["Djoser (3e Dynastie) bestijgt de troon; het Oude Rijk en de Trappenpiramide van Saqqara", "23e99ef4"], "d": ["Met de regering van Djoser (Netjerikhet) begint het Oude Rijk met Memphis als centrum; voor hem werd de Trappenpiramide gebouwd, het eerste grote voorbeeld van steenarchitectuur. In deze periode bestuurt de staat de Nijlvallei en de Delta vanuit het centrum; de mijnen van de Sinaï en de grens met Nubië (Elephantine) staan onder staatscontrole.", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["Narmer (Menes) verenigt Boven- en Beneden-Egypte; de 1e Dynastie begint en Memphis wordt hoofdstad", "cd3fadb1"], "d": ["Narmer, heerser van Boven-Egypte (omgeving van Thinis/Abydos), is volgens de meeste egyptologen dezelfde persoon als Menes. Doordat hij Beneden-Egypte onder zijn bestuur bracht, werden de Nijlvallei en de Delta voor het eerst één staat. Volgens het oude verhaal stichtte Menes de plaats van Memphis door de loop van de Nijl af te leiden; de eenwording is geen enkele gebeurtenis maar het resultaat van een lang proces dat sinds Naqada III voortduurde.", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["Vespasianus wordt in Alexandrië tot keizer uitgeroepen: Egyptes graanbron beslist het lot van de burgeroorlog", "02b78348"], "d": ["De Egyptische prefect Tiberius Alexander liet de legioenen in Alexandrië de eed van trouw zweren aan Vespasianus; de eed werd op 1 juli afgelegd en Vespasianus beschouwde deze dag als zijn troonsbestijging. Het Joodse leger zwoer twee dagen later in aanwezigheid van Vespasianus de eed. Egyptes graanproductie geldt als het strategische fundament van deze onderneming.", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["Joodse opstand in Egypte, Cyrene en Cyprus: onder Trajanus onderdrukt Rome de regio met moeite", "54787782"], "d": ["Terwijl Trajanus' Parthische veldtocht voortduurde, doodden Joden in Cyrene onder leiding van Andreas Romeinen en Grieken; volgens Dio vonden in Egypte en Cyprus soortgelijke gebeurtenissen plaats en het aantal doden werd in honderdduizenden uitgedrukt. Lusius Quietus, door Trajanus gestuurd, onderdrukte de opstand; Joden werd de toegang tot Cyprus verboden.", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["Bucolenopstand: een opstand in de Delta bedreigt Alexandrië, Avidius Cassius onderdrukt hem", "5f94e6bf"], "d": ["De bevolking van de Delta, de Bucolen (herders) genoemd, kwam onder leiding van een priester genaamd Isidorus in opstand; volgens Dio versloegen de opstandelingen een Romeinse eenheid en stonden ze op het punt Alexandrië in te nemen. Cassius, uit Syrië gestuurd, onderdrukte de opstand door de eenheid van de rebellen te breken.", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["Avidius Cassius roept zichzelf uit tot keizer in Syrië en Egypte; hij wordt na drie maanden vermoord", "ce33ca9d"], "d": ["Cassius, bevelhebber van de oostelijke provincies, riep bij het bericht van de dood van Marcus Aurelius het keizerschap uit; de opstand breidde zich uit naar Syrië en Egypte (bij Dio staat dat de Egyptische gouverneur Flavius Calvisius, vanwege zijn banden met de opstand, later niet werd gedood maar naar een eiland verbannen). Cassius werd volgens Dio na een 'keizersdroom' van drie maanden en zes dagen door een van zijn eigen officieren gedood; Marcus Aurelius bezocht Egypte en Syrië en strafte niemand.", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["Palmyra (Zenobia) bezet Egypte; de Romeinse generaal Probus wordt verslagen", "54568441"], "d": ["De Palmyreense generaal Zabdas, optredend namens Zenobia, trok met zijn leger van zeventigduizend man Egypte binnen; de Romeinse generaal Tenagino Probus herovert Alexandrië een tijd maar werd verslagen en sloot zich op in het fort Babylon; toen hij gevangen werd genomen, pleegde hij zelfmoord. Egypte gold een of twee jaar namens Zenobia als deel van de Palmyreense staat.", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["Domitius Domitianus wordt in Egypte tot keizer uitgeroepen; Diocletianus onderdrukt de opstand door Thebe en daarna Alexandrië te belegeren", "3c765005"], "d": ["Uit protest tegen de belastinghervorming en de terugtrekking van Romeinse eenheden naar het Parthische front werd Domitius Domitianus in Egypte in juli-augustus 297 tot Augustus uitgeroepen; een groot deel van Egypte, inclusief Alexandrië, erkende hem. Diocletianus onderdrukte in de herfst de rebellen in Thebe en belegerde Alexandrië; Domitianus stierf in december 297, Aurelius Achilleus zette de verdediging van de stad voort en de stad gaf zich na een beleg van ongeveer acht maanden hoogstwaarschijnlijk in maart 298 over.", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["Diocletianus trekt Egyptes zuidgrens terug tot de lijn Elephantine/Philae; Beneden-Nubië wordt aan de Nobatae gelaten", "725574bb"], "d": ["Procopius vertelt dat Diocletianus, de kosten van het behoud van de uitgestrekte woestijn in het uiterste zuiden van Egypte (Dodekaschoinos) inziend, het gebied ten zuiden van Elephantine aan de Nobatae en Blemmyes liet en de grens bij Elephantine vastlegde (er wordt ook overgeleverd dat daartegenover een jaarlijkse betaling werd vastgesteld). Het Romeinse bestuur trok zich zo terug van de door Augustus getrokken grens bij Hiera Sykaminos.", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["De Aksumitische koning Ezana verslaat Kush; het koninkrijk Meroë komt ten einde (ca. 350 n.Chr.)", "7c9d95d7"], "d": ["Het door Noba- en Blemmyes-druk verzwakte koninkrijk Kush werd aangevallen door de Aksumitische koning Ezana; Ezana's inscripties beschrijven zijn veldtocht tegen de Noba en Kasu (Kush) en in Meroë zijn twee fragmentarische Griekse inscripties van de Aksumitische overwinning gevonden. De laatste piramiden in Meroë dateren uit het midden van de 4e eeuw; de Kushitische staat viel uiteen in de koninkrijken Nobatia, Makuria en Alodia.", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["Theophilos laat het Serapeum in Alexandrië slopen: het heidense cultuscentrum in Egypte wordt gesloten", "119a26c7"], "d": ["Na de edicten van Theodosius I die heidense culten verboden, liet Theophilos, bisschop van Alexandrië, de tempel van Serapis (Serapeum) slopen; de spanning tussen christenen en heidenen in de stad bereikte bij deze gebeurtenis een hoogtepunt. Het lot van de heilige teksten en boekencollecties is omstreden.", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["Theodosius I sterft; het rijk wordt blijvend in tweeën gedeeld, Egypte blijft in het Oost-Romeinse (Arcadius) deel", "54a12472"], "d": ["Na de dood van Theodosius namen zijn zonen Arcadius het Oosten en Honorius het Westen; Egypte, hoewel de belangrijkste leverancier van Romes graanbehoefte, bleef provincie van het Oostelijke Rijk (Byzantium) en werd in de volgende eeuwen de graanbron van Constantinopel.", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["Concilie van Chalcedon: Dioscorus, patriarch van Alexandrië, wordt veroordeeld; de Egyptische Kerk scheidt zich van de keizerlijke Kerk", "5d2d05c6"], "d": ["Toen het Concilie van Chalcedon Egyptes patriarch van Alexandrië Dioscorus veroordeelde, aanvaardden de meeste Egyptische christenen de besluiten niet; zo scheidden zich in Egypte de Koptische (Egyptische) Kerk en de keizerlijke Kerk (Melkieten). Deze splitsing bereidde in de volgende eeuwen de grond voor Egyptes politieke verwijdering van Byzantium.", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["Verdrag tussen Augustus en Phraates IV: de Romeinse standaarden van Crassus worden teruggegeven", "be5f8bda"], "d": ["De verloren gegane Romeinse standaarden van Crassus en Antonius werden door Phraates IV als diplomatiek gebaar aan Augustus teruggegeven. Het verdrag bekrachtigde de Eufraat als Romeins-Parthische grens en liet Armenië als buffer.", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["Pacorus en Labienus bezetten Syrië en Palestina", "68669aa1"], "d": ["De Parthische prins Pacorus en Labienus, die uit Rome naar Parthië was gevlucht, bezetten de Romeinse provincies in Syrië, namen Antiochië en Palestina in. Ventidius, generaal van Antonius, versloeg in 38 de Parthen bij Gindarus en nam het gebied terug.", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["Slag bij Carrhae (Harran): Surena vernietigt het Romeinse leger van Crassus", "3a91cd75"], "d": ["De Romeinse legioenen van Crassus werden bij Harran verslagen door de Parthische cavalerie en ruiterboogschutters; Crassus werd gedood. De slag is een van Romes zwaarste nederlagen in het Oosten en bekrachtigde de Eufraatgrens ten gunste van Parthië.", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["Sulla ontmoet de Parthische gezant Orobazus aan de Eufraat; eerste Romeins-Parthische diplomatieke contact", "f8913f2b"], "d": ["Sulla, gouverneur van Cappadocië, ontmoette de gezant Orobazus van de Parthische koning Mithridates II aan de oever van de Eufraat; Rome en Parthië legden voor het eerst officieel contact. De Eufraat zou later de grens van beide staten worden.", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["Antiochus VII Sidetes sterft tijdens de veldtocht tegen Parthië; de Seleuciden kunnen Mesopotamië niet terugwinnen", "e5897112"], "d": ["Antiochus VII Sidetes nam in 130-129 Mesopotamië en Medië terug van Parthië, maar verloor in de winterkwartieren door een opstand en een Parthische aanval zijn leger en zijn leven. Deze mislukking maakte een einde aan de Seleucidische oostelijke aanspraak.", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["Parthië neemt Demetrius II Nicator gevangen; de Seleuciden verliezen Babylon en Mesopotamië definitief", "94a764ce"], "d": ["Het Parthische leger van Mithridates I nam de Seleucidische koning Demetrius II gevangen en hield hem vast aan het Parthische hof. Mithridates voegde Mesopotamië bij het Parthische Rijk; de Seleucidische staat werd naar de kust gedrukt en trok zich terug naar Syrië.", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["Makkabeese Opstand: in Judea begint een opstand tegen de religieuze verboden van Antiochus IV", "41c25b76"], "d": ["Toen Antiochus IV Epiphanes de Tempel van Jeruzalem aan Zeus Olympios wijdde en Joodse religieuze praktijken verbood, kwamen Mattathias en zijn zonen in Modein in opstand. Judas Makkabeüs nam in 164 de Tempel terug en reinigde die (Chanoeka); de Hasmonese staat ontstond.", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["Mithridates I bestijgt de Parthische troon; het tijdperk van uitbreiding van het Parthische rijk begint", "cc77639b"], "d": ["Mithridates I maakte Parthië tot een rijk: hij nam Medië (147), Babylon en Seleucia (141) in en vestigde zijn heerschappij over Elymais en Persis. Ctesiphon zou later winterhoofdstad worden.", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["Vrede van Apamea: de Seleuciden trekken zich terug ten westen van het Taurusgebergte en betalen een schadevergoeding", "f5197a70"], "d": ["Het verdrag tussen Rome en Antiochus III gaf Anatolië ten westen van de Taurus aan de bondgenoten van Rome (Pergamon, Rhodos); de Seleucidische vloot en het aantal olifanten werden beperkt, 15.000 talenten schadevergoeding werden betaald. De Seleuciden werden voortaan een Syrisch-Mesopotamische staat.", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["Oostelijke veldtocht van Antiochus III (209-204): de koningen van Parthië en Bactrië worden schatplichtig aan de Seleuciden", "5c81f302"], "d": ["Antiochus III trok om de verloren oostelijke gebieden van de Seleuciden terug te nemen naar Medië, Parthië en Bactrië: Arsaces II en Euthydemus werden schatplichtig. Na deze veldtocht nam Antiochus de titel 'de Grote' aan.", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["Arsaces I en Tiridates nemen Parthava in en stichten de Parthische (Arsacidische) staat", "2cd572ca"], "d": ["Arsaces, leider van de nomadenstam der Parni, wierp de Seleucidische satraap Andragoras omver, nam Parthava in en werd de eerste koning van het Parthische koninkrijk; zijn hoofdstad was Hekatompylos. De Parthische staat zou de volgende drie eeuwen heer zijn over Mesopotamië en Iran.", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["De satraap van Bactrië, Diodotus, scheidt zich af van de Seleuciden; het Grieks-Bactrische Koninkrijk ontstaat", "52faafa6"], "d": ["Diodotus, satraap van Bactrië en Sogdiana, maakte gebruik van de zwakte van Antiochus II en riep zijn onafhankelijkheid uit. Grieks-Bactrië dwong de oostgrens van de Seleucidische staat terug te wijken uit Parthava en Bactrië.", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["Eerste Syrische Oorlog (274-272): Seleucidische troepen nemen Damascus terug; vrede gesloten", "0c17ee3d"], "d": ["Nadat Antiochus I de Galaten met de 'olifantenslag' (275) had verslagen en veiliggesteld, voerde hij opnieuw oorlog met Ptolemaeus II: de Seleucidische generaal nam Damascus terug, Magas viel Egypte aan, uiteindelijk werd in 272 vrede gesloten. De oorlog is het begin van het Ptolemaeïsch-Seleucidische geschil over Coele-Syrië.", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["Carische Oorlog: Ptolemaeus II neemt Ionië, Caria, Lycië, Pamfylië en een deel van Cilicië op Antiochus I", "afe190ca"], "d": ["Ptolemaeus II nam in een korte succesvolle veldtocht de zuid- en westkust van Anatolië in en bereikte Damascus; toen Antiochus zag dat zijn macht niet onderdeed voor die van zijn vader, sloot hij een bestand. Antiochus aanvaardde het verlies, omdat hij de veroveringen van zijn vader in het binnenland van Anatolië moest ordenen.", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["Seleucus I wordt door Ptolemaeus Keraunos vermoord; Antiochus I bestijgt de troon", "4703b674"], "d": ["Seleucus, die bij Koroupedion Lysimachus had verslagen en Anatolië had ingenomen, werd bij de oversteek naar Europa door Ptolemaeus Keraunos neergestoken. Zijn zoon Antiochus I nam de staat over maar zou in West-Anatolië moeite hebben.", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["Seleucus I sticht Antiochië (Antakya)", "f4b98967"], "d": ["Seleucus stichtte na Ipsos in Syrië aan de Orontes Antiochië, genoemd naar zijn vader; de stad werd de westelijke hoofdstad van het Seleucidische Koninkrijk en een van de grootste steden van de Oudheid. Seleucia aan de Tigris was eerder als oostelijke hoofdstad gesticht.", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["Slag bij Ipsos: Seleucus en Lysimachus verslaan Antigonus; Syrië gaat naar Seleucus", "93bf2aa9"], "d": ["In de beslissende slag van de Diadochenoorlogen versloegen Seleucus en Lysimachus Antigonus (Antigonus sneuvelde in de slag). Het hele Oosten en Syrië vielen Seleucus toe; Ptolemaeus bezette echter Coele-Syrië en legde zo de oorzaak voor de eerste Syrische oorlogen.", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["Seleucus I sticht Seleucia aan de Tigris", "032efabd"], "d": ["Seleucus stichtte Seleucia aan de oever van de Tigris bij Babylon en begon de bevolking van Babylon daarheen te verplaatsen. Seleucia werd met ongeveer 300 duizend inwoners de grootste Hellenistische stad van het Oosten en later hoofdstadsbuur van het Parthische rijk.", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["Seleucus I sluit in India een verdrag met Chandragupta Maurya; Arachosië, Gedrosië en Paropamisadae worden aan de Maurya's gelaten", "3ef3bdee"], "d": ["Seleucus trok naar India om de Indiase satrapieën van Alexander terug te nemen, maar sloot een akkoord met Chandragupta en ruilde een deel van de oostelijke gebieden voor 500 oorlogsolifanten. Het verdrag bracht de westgrens van het Maurya-rijk naar de Hindoekoesj en verschafte Seleucus olifanten voor het Westen.", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0309-01-01:0":{"b": ["Alexander IV wordt met zijn moeder Roxane vermoord; de Argeaden-dynastie komt ten einde", "3be9d974"], "d": ["Na de vrede van 311 werden op bevel van Cassander (volgens Diodorus was de beul Glaucias) de twaalfjarige Alexander IV en zijn moeder Roxane gedood. Het Rijk van Alexander had geen nominale heerser meer; de Diadochen gingen over tot het uitroepen van hun eigen koninkrijken (306-305 v.Chr.).", "46aa8fb2"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["Alexander bereikt Persepolis; de stad en de schatkist vallen in Macedonische handen", "c1dbaada"], "d": ["Alexander, die na Susa de Perzische Poorten was gepasseerd, bereikte eind januari 330 Persepolis; de stad gaf zich zonder verzet over. Het Achaemenidische bezit van Persepolis eindigt dit jaar (het paleis werd in mei 330 in brand gestoken).", "de8726c8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:1":{"b": ["De paleizen van Persepolis worden in brand gestoken (april)", "6e6cdfe0"], "d": ["Alexander liet in april 330 in Persepolis enkele paleisgebouwen in brand steken; als redenen worden opgegeven dat de schatkist niet in vijandelijke handen mocht vallen en dat hij nog geen enige heerser was. Archeologisch is te zien dat ook het Paleis van Xerxes brandde; de hele stad werd verlaten.", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-07-01:0":{"b": ["Darius III wordt vermoord door de mannen van de satraap van Bactrië, Bessus; de Achaemenidische dynastie komt ten einde", "bedcca87"], "d": ["Darius III, die uit Ecbatana naar het oosten was gevlucht, werd in juli 330 in Parthië door Bessus en zijn aanhangers gewond achtergelaten en stierf; Alexander stuurde zijn lichaam naar Persepolis. Het feitelijke einde van het Achaemenidische Rijk.", "dc8ceef3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["Slag bij Gaugamela: Alexander verslaat definitief het leger van Darius III", "a5b082d7"], "d": ["Bij Gaugamela werd Darius' leger, bestaande uit een groot aantal strijdwagens en cavalerie, verstrooid in de aanval waarbij Alexander de verdediging van de linkerflank doorbrak; Darius vluchtte opnieuw. De slag bepaalde het einde van het Perzische Rijk; Babylon en Susa openden hun poorten.", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-22:0":{"b": ["Alexander trekt Babylon binnen; Mazaeus geeft de stad over en de satrapie Babylon gaat naar Alexander", "c8d2afb3"], "d": ["Na Gaugamela opende Mazaeus, satraap van Babylon, de poorten voor Alexander; Alexander beval het herstel van de Marduktempel en gebruikte de stad 34 dagen. Babylon ging van Perzisch over naar Macedonisch bestuur.", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-12-15:0":{"b": ["Alexander neemt Susa in; de Perzische schatkist wordt buitgemaakt", "fbf417db"], "d": ["Alexander vertrok uit Babylon en trok Susa binnen; satraap Abulites gaf de stad en de grote schat over. Susa werd de financiële basis voor Macedoniës oostelijke veldtocht.", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["Beleg van Tyrus: Alexander neemt de stad op het eiland in door een dam aan te leggen en verwoest haar", "89ede146"], "d": ["Alexander nam het eiland Tyrus, de basis van de Perzische vloot, in zeven maanden in door een kunstmatige dam aan te leggen; de stad werd geplunderd, het grootste deel van de bevolking werd gedood of tot slaaf gemaakt. De Perzische zeemacht stortte zo in en de weg naar Egypte lag open.", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["Slag bij Issos: Alexander verslaat Darius III; Darius laat zijn gezin achter en vlucht", "3803fc30"], "d": ["In een smalle kustvlakte werd het grote leger van Darius III door Alexander verslagen; de Perzische koning liet zijn gezin en schatten achter en vluchtte. De overwinning bij Issos zorgde ervoor dat Syrië en de Fenicische kust, daarna Egypte, aan Alexander vielen.", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["Slag bij de Granicus: Alexander verslaat de Perzische satrapen", "1aae30d4"], "d": ["De Macedonische koning Alexander stak in mei 334 over naar Azië en versloeg begin juni bij de Granicus de Perzische satrapen. De poorten van West-Anatolië gingen open; Sardes en de Ionische steden gaven zich aan Alexander over.", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["Darius III bestijgt de Perzische troon (moord op Arses)", "706f8a9f"], "d": ["De hofbeambte Bagoas doodde Artaxerxes IV; Artašata, satraap van Armenië, werd koning onder de naam Darius III (Codomannus). In oktober 336 werd Filips in Macedonië vermoord en besteeg Alexander de troon.", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["Artaxerxes III sterft; Artaxerxes IV (Arses) bestijgt de troon", "d38e2edc"], "d": ["Artaxerxes III stierf in de zomer van 338 een natuurlijke dood (ondanks Diodorus' vergiftigingsverhaal); Arses besteeg de troon. De Egyptische en Babylonische opstanden en de Anatolische voorbereidingen van de Macedonische koning Filips vallen in dezelfde periode.", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["Artaxerxes III neemt Sidon in en verwoest het; de opstand van Tennes wordt neergeslagen", "d1b533cc"], "d": ["Tijdens de door Egypte gesteunde anti-Perzische opstand van Tennes, koning van Sidon, nam Artaxerxes III de stad in; Tennes verraadde de Perzen, de stad stak zichzelf in brand en velen kwamen om. De Fenicische steden kwamen weer onder Perzische controle en de weg naar de verovering van Egypte lag open.", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["Koningsvrede (Antalcidas): de Griekse steden van Anatolië en Cyprus worden aan Perzië gelaten", "17e871ad"], "d": ["Met de door de Perzische koning Artaxerxes II gedicteerde vrede werden de Griekse steden in Azië en Cyprus als Perzisch beschouwd en kregen de Griekse steden autonomie. Sparta voerde de vrede uit als woordvoerder van Perzië.", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["Slag bij Cunaxa: Cyrus de Jongere wordt verslagen door zijn oudere broer Artaxerxes II en sneuvelt", "90346087"], "d": ["Cyrus de Jongere trok met de Tienduizend, bestaande uit Griekse huurlingen, naar Babylon en werd bij Cunaxa door zijn oudere broer Artaxerxes II verslagen en kwam in de slag om. De terugmars van de Tienduizend naar de Zwarte Zee wordt beschreven in Xenophons Anabasis.", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["Xerxes steekt de Hellespont over; Thermopylae en de inname van Athene", "9bf22df1"], "d": ["Xerxes versloeg met zijn grote leger bij Thermopylae de Spartaans-geallieerde eenheid van Leonidas en trok Attica binnen; Athene werd ontruimd en samen met de Akropolis in brand gestoken. Het Perzische leger rukte op tot het midden van Griekenland.", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["Zeeslag bij Salamis: de Griekse vloot brengt de Perzische vloot een nederlaag toe", "010e3aab"], "d": ["De Griekse vloot onder bevel van Themistocles versloeg bij Salamis de Perzische vloot in de zeestraat en verwierf de zeeheerschappij. Xerxes keerde met het grootste deel van het landleger terug naar Azië, Mardonius bleef in Griekenland.", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["De opstanden van Bêl-shimânni en Shamash-eriba in Babylon worden door Xerxes I neergeslagen", "ebcef5a9"], "d": ["In het begin van de regering van Xerxes I braken in Babylon twee opstanden uit (Bêl-shimânni, Shamash-eriba). Xerxes sloeg de opstanden neer; hij splitste de satrapie Babylon en verminderde de privileges van de stad.", "015c253c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0493-01-01:0":{"b": ["Zeeslag bij Lade: de Perzische vloot verslaat de Ionische vloot; Milete valt", "86396cf1"], "d": ["De door Feniciërs gedomineerde Perzische vloot bracht bij Lade de Ionische vloot een nederlaag toe; Milete werd belegerd en verwoest, de bevolking werd naar Mesopotamië verbannen. De Ionische Opstand eindigde en Ionië kwam weer onder Perzische controle.", "b72ba00d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0497-01-01:0":{"b": ["De Ioniërs steken Sardes in brand", "adf677bd"], "d": ["De Ioniërs en de Atheense-Eretrische eenheden trokken naar het Perzische satrapiecentrum Sardes en staken de stad in brand. Darius besloot daarna Athene te straffen; de gebeurtenis is de aanleiding voor de veldtocht naar Marathon.", "32e33dce"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0498-01-01:0":{"b": ["De Ionische Opstand begint: nadat Aristagoras' veldtocht naar Naxos mislukt, komen de Griekse steden van Ionië in opstand tegen Perzië", "aab8ff2f"], "d": ["Toen de veldtocht van de Milesische tiran Aristagoras naar Naxos instortte, wierpen de steden van Ionië hun tirannen omver en vroegen Athene en Eretria om hulp. Deze opstand is de lont van de Perzisch-Griekse oorlogen.", "7d70c2ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0512-01-01:0":{"b": ["Darius steekt de Ister (Donau) over en voert een Scythische veldtocht; Thracië wordt bij de Perzische satrapie gevoegd", "a5891101"], "d": ["Darius stak via een brug over de Bosporus Thracië in, onderwierp de Geten, stak de Donau over en trok tegen de Scythen op. Hoewel hij de Scythen niet kon verslaan, bracht Megabazus Thracië en de kust van Macedonië onder Perzische heerschappij.", "f464fbf8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-05-08:0":{"b": ["Darius' leger verslaat de Medische opstandeling Fravartish (Phraortes)", "4a9c4633"], "d": ["Het leger van Fravartish, die zich in Medië tot koning uit het geslacht van Cyaxares had uitgeroepen, werd verslagen; Fravartish werd op de vlucht bij Ragai (nabij Teheran) gegrepen en onder marteling gedood. Medië werd weer een Perzische provincie.", "efea5aea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-12-28:0":{"b": ["Darius' generaal verslaat de opstandeling Frada uit Margiana; de laatste grote opstand wordt neergeslagen", "76e0ea1c"], "d": ["Dâdarshi, satraap van Bactrië, marcheerde 300 km door de Karakum-woestijn en versloeg de opstandeling Frada uit Margiana op 28 december 521. In het eerste regeringsjaar van Darius werden alle opstanden in negentien veldslagen neergeslagen.", "5c0c9cfa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-03-11:0":{"b": ["Gaumata (Bardiya) grijpt de Perzische troon; Cambyses sterft op de terugweg uit Egypte", "1606d9c1"], "d": ["Volgens de Behistun-inscriptie riep de priester Gaumata zichzelf uit tot Bardiya (Smerdis), zoon van Cyrus, en besteeg in maart 522 de troon; Cambyses stierf in Syrië. Darius en zes edelen doodden Gaumata op 29 september 522.", "f143e726"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-09-29:0":{"b": ["Darius en zes edelen doodden Gaumata; Darius I bestijgt de Perzische troon", "08897d54"], "d": ["Darius doodde met zijn zes edele bondgenoten de valse Bardiya in het fort Sikayauvati in Medië. De dood van Gaumata lokte op veel plaatsen in het rijk opstanden uit; Darius onderdrukte die binnen een jaar in negentien veldslagen.", "daebf974"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-12-18:0":{"b": ["Darius herovert Babylon; Nidintu-Bêl (Nebukadnezar III) wordt gevangengenomen en gedood", "365cdd51"], "d": ["Na de dood van Gaumata riep Nidintu-Bêl zichzelf uit tot zoon van Nabonidus en Nebukadnezar III en rukte Babylon los van Perzië. Dariusʼ leger stak op 13 december met opgeblazen leren zakken de Tigris over en versloeg het opstandige leger; op 18 december werd Babylon heroverd en Nidintu-Bêl gedood. De Elamitische opstand in Susa werd in die tijd neergeslagen.", "4bd29dc6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0529-01-01:0":{"b": ["Cyrus sterft; zijn zoon Cambyses bestijgt de troon", "de69f4d5"], "d": ["Cyrus stierf volgens Herodotos in de strijd in het land van de Massageten (volgens Xenofon stierf hij in zijn paleis); het bericht van zijn dood bereikte Babylon in december 530 en documenten werden gedateerd als «eerste jaar van Cambyses». Cambyses breidde het rijk uit met de verovering van Egypte.", "9900a295"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:0":{"b": ["Edict van Cyrus: de Joden in Babylonische ballingschap mochten naar Jeruzalem terugkeren en de herbouw van de Tempel werd toegestaan", "715eac6b"], "d": ["Cyrus, die Babylon had ingenomen, stuurde de godenbeelden van de verbannen volken terug en liet hen naar hun land terugkeren (Cyruscilinder). De Tora (Ezra 1:1-4) vermeldt dit edict afzonderlijk voor de Joden: de ballingen mochten naar Jeruzalem terugkeren en de Tempel herbouwen. De regio werd de Perzische satrapie «Yehud».", "a8c7f81c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:1":{"b": ["De Fenicische stadstaten (Tyrus, Sidon, Byblos) aanvaarden Perzisch gezag; zij vormen de kern van de Perzische vloot", "d9f7f277"], "d": ["Met de val van Babylon kwam de Fenicische kust onder Perzisch bestuur, binnen de satrapie «Overzijdse» (Ebir-Nari). De Fenicische vloten werden de ruggengraat van de Perzische zeemacht; Sidon en Tyrus behielden een bevoorrecht recht op intern bestuur.", "bb0c17fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-01-01:0":{"b": ["Slag bij Opis: Cyrus verslaat het Babylonische leger aan de oever van de Tigris", "d91708c6"], "d": ["Cyrusʼ Perzen troffen het Akkadische leger bij Opis aan de Tigris en versloegen het; de Babyloniërs trokken zich terug, er werd geplunderd en gemoord. De slag effende de weg voor de val van Babylon twee weken later.", "20739fbd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-10:0":{"b": ["Sippar gaat zonder strijd over aan de Perzen; Nabonidus vlucht", "47f6d3a5"], "d": ["Na de slag bij Opis viel Sippar op 14 Tašritu zonder strijd in handen van Cyrus en Nabonidus vluchtte. De Perzen zullen twee dagen later Babylon binnentrekken.", "5a23a85c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-12:0":{"b": ["Het Perzische leger onder Gobryas (Ugbaru) trekt zonder strijd Babylon binnen; het Nieuw-Babylonische Rijk eindigt", "f67bf0e3"], "d": ["De gouverneur van Gutium, Ugbaru (Gobryas), en het leger van Cyrus trokken op 16 Tašritu zonder gevecht Babylon binnen; Nabonidus werd gevangengenomen. De riten in de Esagila werden niet onderbroken. Cyrus betrad de stad op 3 Arahsamnu (29 oktober) en het Babylonische Rijk kwam onder Perzische heerschappij.", "891c267b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-29:0":{"b": ["Cyrus betreedt Babylon; de controle over Babylon gaat over op de Achaemeniden en Gobryas wordt tot gouverneur benoemd", "fd45fa83"], "d": ["Cyrus betrad Babylon op 3 Arahsamnu; hij begroette de bevolking van de stad en maakte Gubaru (Gobryas) tot gouverneur van de stad. De Akkadische godenbeelden die Nabonidus in de stad had verzameld, werden in Kislîmu-Addaru teruggebracht naar hun plaatsen. Zijn zoon Cambyses nam als kroonprins deel aan de Nabû-ritus.", "17d2bc46"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0546-01-01:0":{"b": ["Croesus steekt de Halys over en neemt Pteria in; de slag bij Pteria tegen Cyrus eindigt onbeslist", "eee7aef1"], "d": ["Croesus vertrouwde op het orakel van Delphi, stak de Halys over, belegerde Pteria en voerde de Syriërs van Cappadocië weg. Toen de bloedige strijd met Cyrus onbeslist bleef, keerde Croesus terug naar Sardes en verzamelde bondgenotenlegers; Cyrus viel onverwacht aan, versloeg hem bij Thymbra en Sardes viel.", "419ac6ed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0551-01-01:0":{"b": ["Nabonidus vestigt zich in de oase Tayma (Arabië) en komt niet naar Babylon; het Akitu-feest kon niet worden gehouden", "2ce93701"], "d": ["Terwijl Nabonidus in de oase Tayma bleef, wachtte kroonprins Belsazar met het leger in Akkad; omdat de koning in de maand Nisan niet kwam, trok Marduk Babylon niet binnen en kon het Nieuwjaarsfeest (Akitu) niet worden gehouden. Dit was een van de redenen waarom de tempelpriesters Cyrus tegen Nabonidus steunden.", "d1e857db"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0555-01-01:0":{"b": ["Nabonidus bestijgt de Babylonische troon door een staatsgreep", "b7ab73ce"], "d": ["Na de dood van Nebukadnezar (562) waren Amel-Marduk, Neriglissar (559-556) en de kortstondige Labaši-Marduk gevolgd; Nabonidus, hoewel niet van koninklijke afkomst, pleegde in 556 een staatsgreep. Zijn bijzondere toewijding aan de maangod Sin verbitterde de priesters van Marduk.", "6b2f9204"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0559-01-01:0":{"b": ["Croesus bestijgt de Lydische troon; hij maakt Efeze en de Ionische Griekse steden schatplichtig", "5544cfa4"], "d": ["Na de dood van zijn vader Alyattes maakte Croesus Efeze en daarna de andere Ionische, Aeolische en Carische Griekse steden schatplichtig. Lydië is een enkele politieke eenheid van West-Anatolië tot aan de Halys; de schat van Croesus en zijn geschenken aan Delphi werden legendarisch.", "88136bde"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0584-01-01:0":{"b": ["Slag aan de Halys (Kızılırmak): na een zonsverduistering sluiten Alyattes en Cyaxares vrede; de Halys wordt de Lydisch-Medische grens", "9ababdd3"], "d": ["De vijfjarige oorlog tussen Alyattes en de Medische koning Cyaxares eindigde in vrede na een zonsverduistering overdag; Syennesis, koning van Cilicië, en de Babylonische koning «Labynetos» bemiddelden. De rivier Halys werd de grens tussen de twee koninkrijken en Medië gold als uitgestrekt tot diep in Anatolië.", "ddab1c12"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:0":{"b": ["Nebukadnezar begint het beleg van Tyrus; het beleg duurt dertien jaar", "5b753ca0"], "d": ["Volgens Josephus (Contra Apionem 1.156) belegerde Nebukadnezar Tyrus dertien jaar onder koning Ithobaal. Het beleg eindigde uiteindelijk met een vredes- of vazalliteitsregeling; Tyrus kwam onder Babylonische invloed, maar het bestuur van de stad op het eiland bleef onafhankelijk.", "0975583d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:1":{"b": ["Jeruzalem wordt verwoest, de Tempel van Salomo brandt af; het koninkrijk Juda eindigt, het volk wordt naar Babylon weggevoerd", "c9f78b2a"], "d": ["Na de opstand van Zedekia tegen Babylon nam Nebukadnezar Jeruzalem voor de tweede keer in en stak het in brand; de Tempel werd verwoest en het grootste deel van het volk werd naar Babylon weggevoerd (Babylonische ballingschap). Het bestaan van Juda als onafhankelijke staat eindigde.", "f53414ac"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0596-03-16:0":{"b": ["Nebukadnezar neemt Jeruzalem in; koning Jojakin wordt gevangen weggevoerd, Zedekia volgt hem op", "55b14c31"], "d": ["Het Babylonische leger belegerde de «stad Juda» en nam die op 2 Addaru in; koning Jojakin werd gevangengenomen en naar Babylon gevoerd, en in zijn plaats werd Zedekia (Mattanja), door Babylon gekozen, aangesteld. De stad kwam voor het eerst onder Babylonische heerschappij.", "12a9d088"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0599-01-01:0":{"b": ["De Urartese vestingen worden verwoest en verbrand; de staat stort in", "6be90688"], "d": ["De brandlaag in vestingen zoals Karmir-blur wijst erop dat Urartu vóór 600 v.Chr. werd verwoest door een inval van Scythen/Cimmeriërs, door de Meden of door een andere vijand. Doordat de Assyrische bronnen ophouden, is de datering na de laatste koning Rusa III onzeker; Urartu werd enige tijd later een Achaemenidische satrapie (Armina).", "1e7ff200"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0603-12-01:0":{"b": ["Nebukadnezar II neemt Ascalon in, voert de koning gevangen weg en legt de stad in puin", "7429839d"], "d": ["In het eerste regeringsjaar van Nebukadnezar brachten «alle koningen van het land Hatti» hem tribuut; alleen Ascalon verzette zich. De stad werd in de maand Kislîmu ingenomen, de koning werd gevangengenomen en de stad werd veranderd in een ruïneheuvel.", "a455db32"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0604-09-07:0":{"b": ["Nabopolassar sterft, Nebukadnezar II bestijgt de Babylonische troon", "bce88c5a"], "d": ["De Babylonische koning Nabopolassar stierf na een regering van 21 jaar op 8 Abu (15 augustus 605); Nebukadnezar, die bij Karkemis had gezegevierd, keerde terug naar het land en besteeg op 1 Ulûlu (7 september 605) de troon. Vier jaar van veldtochten bond het land Hatti (Syrië-Palestina) aan Babylon.", "b519ffaa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:0":{"b": ["Harran valt; Aššur-uballit II trekt zich terug naar Egypte", "b2d122c2"], "d": ["Na de val van Nineve had de laatste Assyrische koning Aššur-uballit II zich in Harran teruggetrokken; toen de Meden en Babyloniërs naar Harran optrokken, verlieten de Assyrische en Egyptische troepen de stad en trokken zich terug voorbij de Eufraat. Nabopolassar nam Harran in en plunderde het.", "cb81464b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:1":{"b": ["Alyattes bestijgt de Lydische troon; hij verdrijft de Cimmeriërs uit Anatolië en breidt het koninkrijk uit", "160e291d"], "d": ["Tijdens zijn lange regering zuiverde Alyattes West-Anatolië van de Cimmeriërs en voerde hij oorlog met Milete; hij verlegde de grenzen van het koninkrijk naar het midden van Anatolië, tot hij Medië aan de Halys ontmoette.", "54aee50b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0613-01-01:0":{"b": ["Cyaxares en Nabopolassar sluiten een bondgenootschapsverdrag bij Assur", "650f0e5a"], "d": ["Toen de Meden Assur innamen, ontmoette de Babylonische koning Nabopolassar, die te laat was, de Medische koning bij de stad en sloot een bondgenootschap. Volgens Berossos werd de band versterkt door het huwelijk van Nebukadnezar met Amytis, de dochter van Cyaxares.", "450ae215"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0624-01-01:0":{"b": ["Cyaxares (Umakištar) bestijgt de Medische troon", "67896ea0"], "d": ["Volgens de overlevering van Herodotos regeerde Cyaxares veertig jaar, verenigde hij Medië en trok hij tegen Assyrië ten strijde. Het bondgenootschap met Babylon (614) en de inname van Nineve (612) vallen in zijn regering; Medië bereikte in die jaren zijn grootste omvang.", "4094aac8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0630-01-01:0":{"b": ["Assurbanipal sterft; in Assyrië begint een troonstrijd en een Babylonische opstand", "dbe19d8c"], "d": ["De dood van Assurbanipal liet Assyrië verdeeld tussen twee troonopvolgers achter. De Babylonische gouverneurs kwamen in opstand tegen Sin-šumu-lišir en Sin-šar-iškun; binnen tien jaar begon de ineenstorting van het rijk.", "9537e9f3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0644-01-01:0":{"b": ["Assurbanipal verwoest Susa; het Nieuw-Elamitische Rijk stort in", "cb341293"], "d": ["Als straf voor de opstand van Elam samen met Babylon tegen Assyrië nam Assurbanipal Susa in en plunderde het, verwoestte de tempels en voerde de godenbeelden naar Nineve. Elam kwam als verzameling van halfonafhankelijke vorstendommen onder Perzische/Anšanitische invloed.", "327f1322"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0647-01-01:0":{"b": ["Babylon onderwerpt zich aan Assurbanipal na de opstand van Šamaš-šuma-ukin", "d6964932"], "d": ["Šamaš-šuma-ukin, de broer van Assurbanipal en koning van Babylon, kwam in 652 tegen Assyrië in opstand; zijn Elamitische en Arabische bondgenoten boden tijdelijk steun. De vier jaar durende oorlog eindigde met de val van Babylon en de dood van Šamaš-šuma-ukin.", "b038173f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0651-01-01:0":{"b": ["De Cimmeriërs plunderen Sardes; Gyges sterft", "950e5f80"], "d": ["De Cimmerische inval strekte zich na Gordion (696/695) ook uit tot Lydië en plunderde de benedenstad van Sardes. Assyrische bronnen melden dat de Lydische koning Gugu (Gyges) Assyrische hulp zocht tegen de Cimmeriërs; Gyges stierf tijdens of na deze oorlogen.", "93736177"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0652-01-01:0":{"b": ["Slag bij Til-Tuba/Ulai: Assurbanipal verslaat en doodt de Elamitische koning Teumman", "177e87cf"], "d": ["Assurbanipal versloeg de Elamitische koning Teumman aan de oever van de Ulai (Karun/Karkheh) bij Susa en doodde hem; zijn hoofd werd naar Nineve gebracht. De slag bereidde het einde voor van de rol die Elam speelde in het Assyrisch-Babylonische conflict.", "3aa28a86"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0663-01-01:0":{"b": ["Assurbanipal plundert Thebe", "179269c7"], "d": ["Toen na de dood van Esarhaddon in Egypte de Koesjitische opstand onder Tanutamun opnieuw oplaaide, drong Assurbanipal Boven-Egypte binnen en plunderde Thebe. Assyrië had moeite Egypte feitelijk in handen te houden en trok zich binnen korte tijd terug.", "c292bcf0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0676-01-01:0":{"b": ["Esarhaddon verwoest Sidon en sticht het opnieuw onder de naam Kar-Esarhaddon", "bd713ae6"], "d": ["Toen de koning van Sidon, Abdi-Milkutti, tegen Assyrië in opstand kwam, verwoestte Esarhaddon de stad, liet de koning onthoofden en stichtte op de plaats van de stad Kar-Esarhaddon («Haven van Esarhaddon»), een Assyrisch provinciecentrum.", "2a506319"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0684-01-01:0":{"b": ["Gyges onttroont Kandaules en sticht de dynastie der Mermnaden", "37e46a38"], "d": ["Volgens Herodotos greep Gyges als lijfwacht van het paleis de Lydische troon door koning Kandaules te onttronen en stichtte hij de dynastie der Mermnaden. Na de ineenstorting van Frygië door de Cimmerische aanval begon Lydië de hoofdmacht van West-Anatolië te worden.", "e477b6b5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0688-01-01:0":{"b": ["Sanherib verwoest Babylon, plundert de tempels en laat de Eufraat over de stad stromen", "82265d98"], "d": ["Na de herhaalde opstanden van Babylon nam Sanherib de stad in en verwoestte haar, voerde het beeld van Marduk weg en liet het water van de kanalen over de stad stromen. Babylon bleef een halve eeuw in puin, tot het herstel door Esarhaddon; de verwoesting is de hardste stap van de Assyrische Babylon-politiek.", "e4312fee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:0":{"b": ["Sanherib valt Juda binnen; hij neemt Lachis in en belegert Jeruzalem", "dc11fa2d"], "d": ["Sanherib, die de opstand van Hizkia tegen Assyrië neersloeg, nam zesenveertig steden van Juda in, veroverde Lachis en belegerde Jeruzalem. Hizkia redde de stad door zware tribuutbetaling; de reliëfs van Lachis in Nineve tonen deze veldtocht.", "ebc2ce02"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:1":{"b": ["Sanherib neemt Sidon in; koning Luli vlucht naar Cyprus", "41bb1358"], "d": ["Sanherib bracht in 701 de Fenicische steden onder het juk: de koning van Sidon, Luli (Elulaios), vluchtte naar Cyprus en de van Sidon en Tyrus afhankelijke steden vielen aan Assyrië toe. Met deze veroveringen werd de westkust veiliggesteld vóór de veldtocht tegen Juda.", "3b2c6518"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0704-01-01:0":{"b": ["Sargon II sneuvelt bij Tabal; Sanherib bestijgt de troon", "2f6ae581"], "d": ["Sargon II kwam om tijdens een veldtocht tegen koning Gurdi van Tabal in Anatolië en zijn lichaam kon niet worden geborgen. Zijn zoon Sanherib verplaatste zijn paleis naar Nineve; de stad van zijn vader, Dur-Šarrukin, werd verlaten en veel provincies kwamen in opstand.", "21ee2771"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0711-01-01:0":{"b": ["Sargon II neemt Melid (Malatya) in; Gunzinanu wordt verbannen", "3ef6a5c9"], "d": ["Gunzinanu, koning van Melid (Malatya), werd door Sargon verslagen omdat hij met Tabal en Urartu samenwerkte, en zijn koninkrijk werd een Assyrische provincie. Daarmee eindigde de Neo-Hettitische overheersing in Oost-Anatolië.", "281f75fd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0713-01-01:0":{"b": ["Sargon II valt Urartu binnen: Rusa I wordt verslagen, Musasir wordt geplunderd en het beeld van Haldi weggevoerd", "38992d24"], "d": ["Sargons achtste veldtocht plunderde Urartu vanaf het gebied rond het Urmiameer naar het zuiden; de tempel van Haldi in Musasir werd leeggeroofd. Koning Rusa I pleegde volgens de overlevering zelfmoord na de zware nederlaag. Urartu kon nooit meer een grote onderneming tegen Assyrië aangaan.", "7d05af4c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0716-01-01:0":{"b": ["Sargon II neemt Karkemis in; het koninkrijk van Pisiris wordt een Assyrische provincie", "cfcc3ee4"], "d": ["Pisiris, koning van Karkemis, probeerde een bondgenootschap met Midas (Mita) te sluiten tegen Assyrië; Sargon nam de stad in en voerde bewoners weg. De onafhankelijkheid van Karkemis, die anderhalve eeuw had geduurd, eindigde en de Eufraatgrens kwam aan Assyrië.", "87f1f2e6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0719-01-01:0":{"b": ["Sargon II verslaat Hamath, doodt Yau-bidi bij Qarqar en maakt het koninkrijk een provincie", "aeca8edc"], "d": ["Yau-bidi, koning van Hamath, stond aan het hoofd van de Syrisch-Palestijnse coalitie tegen Sargon; Sargon versloeg hem bij Qarqar en verwoestte de stad, en Hamath werd een Assyrische provincie.", "70e2d509"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0732-01-01:0":{"b": ["Tiglatpileser III neemt Galilea en Gilead van Israël en maakt er Assyrische provincies van", "0b59ead2"], "d": ["Toen het Israël van Pekach samen met Damascus tegen Assyrië in opstand kwam, maakte Tiglatpileser III van Noord-Israël (Galilea, Gilead, de omgeving van Megiddo) Assyrische provincies en voerde bewoners weg; Hosea volgde Pekach op. Het koninkrijk Israël werd teruggebracht tot Samaria en het omliggende bergland.", "28d3a30e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0733-01-01:0":{"b": ["Tiglatpileser III neemt Gaza in; de Palestijnse kust komt onder Assyrische controle", "1c89131f"], "d": ["Tiglatpileser trok naar de Palestijnse kuststrook, joeg koning Hanunu van Gaza naar Egypte en bracht de stad onder zijn gezag. De Palestijnse stadstaten werden in de daaropvolgende jaren een Assyrische vazalstrook.", "ff623a4d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0742-01-01:0":{"b": ["Tiglatpileser III verslaat de Urartese koning Sarduri II bij Arpad", "7478a232"], "d": ["De poging van Sarduri II om de Syrische staten naar onafhankelijkheid te leiden, eindigde met de overwinning van Tiglatpileser III. Urartu verloor zijn invloed in Syrië; Assyrië liet voor Anatolië en Syrië geen enkele rivaal over.", "b851f23b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0744-01-01:0":{"b": ["Tiglatpileser III bestijgt de troon; het Assyrische provinciestelsel wordt gevestigd", "b5889059"], "d": ["Tiglatpileser III, die in Kalhu door een opstand aan de macht kwam, vestigde het provinciestelsel door Assyrische gouverneurs in de plaats van vazalkoninkrijken te zetten; hij bond Babylon in personele unie en voerde veldtochten tegen Damascus, Gaza en Israël. Het bestuurssysteem dat latere rijken (Babylon, Perzië, Seleuciden) gebruikten, gaat hierop terug.", "7deb8187"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0795-01-01:0":{"b": ["Adad-nirari III verslaat Mari, de koning van Damascus, en eist tribuut", "3e01dbfa"], "d": ["Adad-nirari III versloeg Mari (Bar-Hadad), de koning van Damascus, en nam groot tribuut; de innerlijke kracht van Aram-Damascus verzwakte en Israël kreeg enige tijd verlichting.", "c5c0a66d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0809-01-01:0":{"b": ["Minua breidt Urartu uit van het Vanmeer tot de Araxesvallei en het Urmiameer", "d77231e4"], "d": ["Onder Minua en zijn zoon Argišti I groeide Urartu uit tot een koninkrijk met het hele hooggelegen land, van het centrum bij het Vanmeer tot de omgeving van de Araxes en het Urmiameer. Tušpa (Van) werd uitgebreid met nieuwe nederzettingen en irrigatiewerken.", "289fc554"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0839-01-01:0":{"b": ["Mesa, koning van Moab, verklaart zich onafhankelijk van Israël (Mesa-stèle)", "e9c264b2"], "d": ["De Mesa-stèle beschrijft de bevrijding van koning Mesa van Moab uit de Israëlitische voogdij en zijn overwinningen op de dynastie van Omri. De Tora en de stèle samen tonen de periode waarin de dynastie van Omri verzwakte.", "ffefe5fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0840-01-01:0":{"b": ["Salmanasser III verslaat Hazaël en belegert Damascus; koning Jehu van Israël betaalt tribuut", "93aacc56"], "d": ["Salmanasser III versloeg Hazaël, koning van Aram-Damascus, op de berg Senir (Hermon) en belegerde Damascus; koning Jehu van Israël wordt op de Zwarte Obelisk afgebeeld terwijl hij Assyrië tribuut aanbiedt. De coalitie van Qarqar viel uiteen en Assyrië werd de heersende macht in het westen.", "2992ec0c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0852-01-01:0":{"b": ["Slag bij Qarqar: Salmanasser III treft de coalitie van Damascus, Hamath en Israël", "9a736e92"], "d": ["Salmanasser III streed bij Qarqar tegen een coalitie van twaalf koningen, onder wie Hadad-ezer (Adad-idri), koning van Damascus, Irhuleni, koning van Hamath, en Achab, koning van Israël. Hoewel de Assyrische documenten een overwinning claimen, moest hij zijn opmars staken; de coalitie hield Assyrië jarenlang tegen.", "524874c7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0857-01-01:0":{"b": ["Salmanasser III begint veldtochten tegen Urartu (Arame); Urartu verschijnt voor het eerst in Assyrische bronnen", "375ce993"], "d": ["In de eerste jaren van zijn regering trok Salmanasser III naar het land van koning Arame van Urartu; de Assyrische annalen noemen Urartu bij deze veldtochten voor het eerst «het land Urartu». Het is de eerste gedateerde vermelding van de staat die in de volgende eeuwen Assyriës belangrijkste rivaal in dit gebied zou worden.", "759a75b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0876-01-01:0":{"b": ["Assurnasirpal II steekt de Eufraat over en ontvangt tribuut van Karkemis en de Neo-Hettitische/Aramese staten", "5e385948"], "d": ["Tijdens zijn veldtocht naar het westen stak Assurnasirpal II de Eufraat over en bereikte Karkemis, Patina en de Fenicische kust, waar hij tribuut inde. Deze veldtocht is het begin van het proces waarin de Neo-Hettitisch-Aramese stadstaten aan Assyrië werden gebonden.", "8432c2ea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0878-01-01:0":{"b": ["Assurnasirpal II maakt Kalhu (Nimrud) de nieuwe hoofdstad van Assyrië", "fbb17248"], "d": ["Assurnasirpal II veranderde Kalhu, een klein stadje, met 47 duizend arbeiders in een grote hoofdstad; in de stad, zes keer zo groot als Assur, werd het Noordwestelijk Paleis gebouwd. Kalhu bleef tot 706 de hoofdstad van Assyrië.", "5a0f00b6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0879-01-01:0":{"b": ["Omri maakt Samaria tot hoofdstad en verovert Moab", "e060c4b7"], "d": ["Omri stichtte de eerste echte staat van Israël: hij veroverde het gebied ten oosten van de Jordaan (inclusief Moab), versterkte de grensvestingen en maakte Samaria de nieuwe hoofdstad. Zijn zoon Achab trouwde met Izebel, de dochter van Ethbaäl, koning van Sidon, en verbond Israël zo met de Fenicische handel.", "14f7df9d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0910-01-01:0":{"b": ["Adad-nirari II bestijgt de troon; het Neo-Assyrische herstel begint", "e6887ba9"], "d": ["Na een neergang van ongeveer anderhalve eeuw begon Adad-nirari II de Assyrische gebieden weer te verenigen; hij voerde veldtochten tegen de Arameeërs en de Babylonische grens. Onder zijn opvolgers Assurnasirpal II en Salmanasser III ontstond het Nieuw-Assyrische Rijk.", "beab377b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0929-01-01:0":{"b": ["Het koninkrijk van Salomo splitst; Jerobeam I sticht in het noorden het koninkrijk Israël", "cfbbc025"], "d": ["Volgens de Tora leidde na de dood van Salomo de belastingverhoging van zijn zoon Rehabeam tot de afscheiding van de tien noordelijke stammen; Jerobeam werd tot koning gekozen en maakte Tirza de hoofdstad. In het zuiden bleef Juda bestaan onder het Davidische huis. De afzonderlijke geschiedenis van de twee staten begint.", "7e2e066d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1099-01-01:0":{"b": ["Tiglatpileser I trekt naar het westen en ontvangt tribuut van de Fenicische steden aan de Middellandse Zeekust", "0b2822b7"], "d": ["Tiglatpileser I bereikte de wouden van Libanon en havens als Arvad, Byblos en Sidon, waar hij tribuut inde, en maakte op de Middellandse Zee een tocht per schip. Omdat er na de ineenstorting van de Hettieten in het westen geen macht was om hem te stoppen, vormen deze veldtochten het begin van de westwaartse koers van Assyrië.", "60dc7824"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1109-01-01:0":{"b": ["Nebukadnezar I (Isin II) trekt naar Elam en haalt het beeld van Marduk terug", "3c551c03"], "d": ["Nebukadnezar I van de tweede dynastie van Isin trok tegen Elam op en bracht het beeld van Marduk, dat Kutir-Nahhunte had weggevoerd, terug naar Babylon. De overwinning wordt in de Babylonische geschiedenis herinnerd als «de terugkeer van Marduk» en maakte de Marduk-cultus centraal.", "fdd1a6a4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1157-01-01:0":{"b": ["Šutruk-Nahhunte plundert het Babylonische land; hij voert de stèles van Hammurabi en Naram-Sin naar Susa", "3d499fcc"], "d": ["Šutruk-Nahhunte, koning van Midden-Elam, viel Babylon aan en plunderde steden als Sippar; buit zoals de stèle met de Wetten van Hammurabi en de Overwinningsstèle van Naram-Sin werd naar Susa gebracht. Zijn zoon Kutir-Nahhunte maakte in 1155 v.Chr. een einde aan de Kassietische dynastie.", "2179c21e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1174-01-01:0":{"b": ["In Karkemis zet Kuzi-Tešub het Hettitische erfgoed voort met de titel «Groot Koning»", "0bda7a64"], "d": ["Na de verwoesting van Hattuša bleef het koninkrijk Karkemis bestaan door een tak van de Hettitische dynastie; Kuzi-Tešub riep zichzelf uit tot «Groot Koning». Luwisch-Aramese stadstaten als Karkemis, Malatya (Melid) en Hamath vormden de «Neo-Hettitische» wereld.", "214de0bd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1179-01-01:0":{"b": ["Hattuša brandt af en wordt verlaten; het Hettitische Rijk stort in", "64d58b6b"], "d": ["De stad Hattuša werd in de tijd van de laatste Hettitische koning Šuppiluliuma II verbrand en verlaten; het is een onderdeel van de ineenstorting van de Late Bronstijd in de context van hongersnood, interne conflicten en de Zeevolken. De Hettitische staat maakte plaats voor Neo-Hettitische stadstaten als Karkemis en Malatya.", "34ee5436"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1224-01-01:0":{"b": ["De Assyrische koning Tukulti-Ninurta I verovert Babylon; hij voert het beeld van Marduk naar Assur", "2cc39251"], "d": ["Tukulti-Ninurta I (ca. 1243-1207) versloeg de Kassietische koning Kaštiliaš IV, nam Babylon in, liet de muren slopen en voerde het beeld van Marduk naar Assur. Babylon bleef ongeveer zeven jaar onder Assyrische controle; Assyrië werd de machtigste staat van de middeleeuwen van het Nabije Oosten.", "8abcb249"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1259-01-01:0":{"b": ["Salmanasser I sticht de stad Kalhu (Nimrud)", "e0bf279a"], "d": ["Salmanasser I stichtte Kalhu aan de oever van de Tigris; de stad zou in 883 door Assurnasirpal II opnieuw worden gesticht en de hoofdstad van Assyrië worden.", "8a213755"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1269-01-01:0":{"b": ["Salmanasser I annexeert Hanigalbat; Mitanni verdwijnt", "88620feb"], "d": ["Salmanasser I, die de opstand van Šattuara II, koning van Hanigalbat, neersloeg, voegde het land rechtstreeks bij Assyrië en voerde de bevolking weg. De staat Mitanni verdween van het toneel door de opeenvolgende slagen van de Hettieten en de Assyriërs.", "c6c8615e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1274-01-01:0":{"b": ["Untaš-Napiriša sticht de stad Dur-Untaš (Čogha Zanbil) en haar ziggurat", "117fbc13"], "d": ["Untaš-Napiriša, koning van Midden-Elam, stichtte bij Susa een cultusstad met een ziggurat voor de god Inšušinak; hoewel de stad onvoltooid bleef, werd zij meer dan twee eeuwen gebruikt. Čogha Zanbil is de best bewaarde ziggurat van Iran.", "fe8afd09"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1294-01-01:0":{"b": ["Adad-nirari I verslaat Hanigalbat (het restant van Mitanni) en maakt het vazal", "1adb5969"], "d": ["Adad-nirari I, kleinzoon van Aššur-uballit I, versloeg het koninkrijk Hanigalbat, wat restte van het door de Hettieten verslagen Mitanni, en maakte het vazal; onder de volgende koning Salmanasser I werd het land een Assyrische provincie. Assyrië reikte tot aan de Eufraat.", "24941786"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1317-01-01:0":{"b": ["Muršili II verslaat Arzawa (West-Anatolië) en verdeelt het", "4a204e42"], "d": ["Aan het begin van zijn regering versloeg Muršili II de machtige Arzawa-confederatie van West-Anatolië, verdeelde haar in kleinere koninkrijken en maakte haar tot Hettitische vazal. De Hettitische grens in West-Anatolië kwam dicht bij de Egeïsche kust.", "c2f9977c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1327-01-01:0":{"b": ["Šuppiluliuma benoemt zijn zonen aan het hoofd van de koninkrijken Karkemis en Aleppo", "1c5bc8b3"], "d": ["Šuppiluliuma liet het veroverde Syrië besturen door «koningen» uit de Hettitische dynastie: Karkemis en Aleppo werden aan zijn zonen gegeven. Het onderkoningschap van Karkemis zou zelfs na de ineenstorting van de Hettieten nog ongeveer 500 jaar blijven bestaan.", "40eeaf84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1344-01-01:0":{"b": ["Šuppiluliuma I verslaat Mitanni (Tušratta) en neemt Aleppo en Karkemis in; Noord-Syrië gaat naar de Hettieten", "52f9627a"], "d": ["Šuppiluliuma versloeg de Mitanni-koning Tušratta en nam Syrische steden in, waaronder Karkemis en Aleppo; het westen van het Mitanni-gebied werd bij het Hettitische Rijk gevoegd. De interne problemen van Egypte onder Achnaton vergemakkelijkten deze uitbreiding.", "c80de115"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:0":{"b": ["Kassitisch Babylon neemt in de diplomatie van Amarna deel als een grootmacht gelijk aan Egypte", "5e7b31a2"], "d": ["De Kassitische koningen Kadašman-Enlil I en Burna-Buriaš II behoorden tot de competitie van «grote koningen» die met de Egyptische farao's huwelijks- en geschenkendiplomatie voerden. De brieven van Amarna noemen de leden van deze competitie: Egypte, Babylon, Mitanni, Hatti en Assur.", "8ecd665d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:1":{"b": ["Šuppiluliuma I bestijgt de Hettitische troon; het Nieuwe Rijk begint", "58b301b7"], "d": ["Šuppiluliuma I is de stichter van het Hettitische Nieuwe Rijk en de schepper van het professionele strijdwagenleger. Zijn regering van vijfendertig jaar maakte van de Hettieten een rijk dat zich van Anatolië tot Syrië uitstrekte.", "72c7f3af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1362-01-01:0":{"b": ["Aššur-uballit I maakt zich los van Mitanni; Assyrië wordt onafhankelijk en een «groot koning»", "5f280058"], "d": ["Assur, vazal van Mitanni, werd onder Aššur-uballit I onafhankelijk door te profiteren van de slag die de Hettieten Mitanni toebrachten. De koning schreef de Egyptische farao met de titel «groot koning»; dit markeert het begin van de Midden-Assyrische periode.", "690fb956"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1399-01-01:0":{"b": ["Mitanni-Egyptisch bondgenootschap: vrede tussen Artatama I en Thoetmosis IV, een Mitanni-prinses gaat als bruid naar Egypte", "017f13d2"], "d": ["Na vijandschap sloot de Mitanni-koning Artatama I vrede met de Egyptische farao en stuurde zijn dochter naar Egypte. Het bondgenootschap vestigde in Noord-Syrië een Mitanni-Egyptisch evenwicht tegen de Hettitische dreiging en bereidde de diplomatie van de Amarna-tijd voor.", "72df719d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1499-01-01:0":{"b": ["Het koninkrijk Mitanni (Hanigalbat) wordt gesticht in het gebied van Khabur en Eufraat", "04920d91"], "d": ["Het Hurritisch-Mitanni-koninkrijk kwam op in Boven-Mesopotamië in het vacuüm van de ondergang van Oud-Babylon en de Hettitische neergang. De hoofdstad was Waššukanni; het koninkrijk maakte Assur en Noord-Syrië binnen enkele decennia tot vazal.", "c6aa0237"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1524-01-01:0":{"b": ["Telipinu bestijgt de troon en vaardigt een edict uit; de betrekkingen met Kizzuwatna worden bij verdrag geregeld", "e1f0895b"], "d": ["Telipinu hervormde het Hettitische recht met zijn edict, dat de erfopvolging regelt; het verdrag met Kizzuwatna erkende dat land als onafhankelijke partner en niet als afhankelijke. Met dit edict eindigt het Hettitische Oude Rijk.", "47b927f1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1569-01-01:0":{"b": ["De Kassitische dynastie herstelt Babylon onder Agum-kakrime; het beeld van Marduk keert terug uit Hettitische gevangenschap", "0d525e02"], "d": ["Na de plundering van Babylon door de Hettitische koning Muršili I (1595 v.Chr.) kwam de Kassitische dynastie in de stad aan de macht. De overlevering vertelt dat Agum-kakrime het beeld van Marduk van de Hettieten terugnam; de Kassieten namen snel de Babylonische cultuur over en stichtten de dynastie die ongeveer vier eeuwen zou duren.", "d91fcc1e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1589-01-01:0":{"b": ["Muršili I wordt door een moordaanslag gedood; het Hettitische koninkrijk verzwakt door interne twisten", "fa5a6ea9"], "d": ["Op de terugweg uit Babylon werd Muršili I gedood door zijn zwager Hantili en door Zidanta. Troonstrijd en de nieuwe Hurritische/Mitanni-macht lieten het koninkrijk een halve eeuw zwak; Telipinu kon pas omstreeks 1525 v.Chr. orde scheppen.", "90711b8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1599-01-01:0":{"b": ["Muršili I neemt Aleppo (Yamhad) in en verwoest het", "78c81e82"], "d": ["Muršili I, kleinzoon en opvolger van Hattušili, nam het koninkrijk Aleppo, dat tientallen jaren weerstand had geboden, in en verwoestte het. Het einde van Yamhad verzekerde de Hettitische suprematie in Noord-Syrië en effende de weg voor Muršilis veldtocht tegen Babylon.", "327a9d55"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1629-01-01:0":{"b": ["Hattušili I steekt de Taurus over en voert een veldtocht naar Noord-Syrië; Alalakh wordt verwoest, het koninkrijk Aleppo (Yamhad) aangevallen", "92b0d44b"], "d": ["Hattušili I (ca. 1650-1620) stak de Taurus over en voerde een veldtocht naar Noord-Syrië; Alalakh werd verwoest en het koninkrijk Aleppo (Yamhad) werd aangevallen, maar Aleppo werd niet ingenomen. De annexatie van Kizzuwatna (Cilicië) vond met deze veldtocht niet plaats: Kizzuwadna wisselde later heen en weer tussen Hatti en Mitanni en de Hettitische annexatie valt aan het begin van het Nieuwe Rijk.", "cf12effe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1749-01-01:0":{"b": ["Anitta, koning van Kuššara, maakt Kaneš tot hoofdstad en verwoest Hattuša", "1eea344b"], "d": ["Volgens de Anitta-tekst verenigde Anitta, koning van Kuššara, in Anatolië vele stadstaten, maakte Neša (Kaneš) tot hoofdstad en verwoestte Hattuša, waarna hij er een vloek over uitsprak. Het wordt herinnerd als de eerste Hettitische poging tot politieke eenheid.", "01d03ad4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1753-01-01:0":{"b": ["De stèle met de Wetten van Hammurabi wordt opgericht", "b4c80ab9"], "d": ["De rechtscodificatie van Hammurabi met 282 artikelen werd op een basalten stèle geschreven en in tempels opgesteld. De stèle werd in de 12e eeuw v.Chr. door de Elamitische koning Šutruk-Nahhunte naar Susa gebracht en daar in 1901 gevonden; zij bevindt zich nu in het Louvre.", "e37255ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1760-01-01:0":{"b": ["Hammurabi neemt Mari in; twee jaar later laat hij de muren slopen", "4f4114b4"], "d": ["Hammurabi, die Mari van zijn voormalige bondgenoot Zimri-Lim innam, liet ook de stadsmuren slopen. De verwoesting van Mari is het einde van het Amorietische koninkrijk in de Eufraatvallei; Babylon werd in het noorden de heersende macht tot aan Assur en Ešnunna.", "5bbc9e99"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1762-01-01:0":{"b": ["Hammurabi neemt Larsa in en verslaat Rim-Sin I; Zuid-Mesopotamië wordt bij Babylon gevoegd", "6f95399b"], "d": ["Hammurabi streed in hetzelfde jaar tegen Elam en Ešnunna, trok naar Larsa en versloeg Rim-Sin I. Zuid-Mesopotamië (Sumer) werd bij het koninkrijk Babylon gevoegd; dit gebied werd vanaf die dag «het land Akkad» (Babylonië) genoemd.", "4be6f89b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1793-01-01:0":{"b": ["Rim-Sin I, koning van Larsa, verovert Isin; de dynastie van Isin eindigt", "88964ca6"], "d": ["Rim-Sin I, koning van Larsa, veroverde zijn al lang bestaande rivaal Isin en maakte Larsa de enige grote macht van Zuid-Mesopotamië. Zo eindigde de dynastie van Isin na een heerschappij van 223 jaar.", "f1928082"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1794-01-01:0":{"b": ["Šamši-Adad neemt Mari in en benoemt zijn zoon Jasmah-Addu tot koning van Mari", "a428b4eb"], "d": ["Šamši-Adad, koning van Assur en Ekallatum, nam het koninkrijk Mari aan de Eufraat in, schakelde de dynastie van Jahdun-Lim uit en benoemde zijn jongste zoon Jasmah-Addu in Mari. Het «Koninkrijk van Boven-Mesopotamië» werd zo een Amorietisch rijk dat zich van de Zagros tot de Eufraat uitstrekte.", "8d0ec094"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1799-01-01:0":{"b": ["Aleppo wordt vermeld als hoofdstad van het koninkrijk Yamhad", "9ad40400"], "d": ["Aleppo verschijnt in de 18e eeuw v.Chr. als hoofdstad van het koninkrijk Yamhad; het exacte jaar van de stichting van het koninkrijk wordt in de bron niet gegeven.", "f9ad9832"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1821-01-01:0":{"b": ["Rim-Sin I bestijgt de troon van Larsa", "a24e891e"], "d": ["Rim-Sin I (ca. 1822-1763) bond tijdens zijn regering van 60 jaar Uruk, Isin en Nippur aan Larsa en maakte een dynastie van Elamitische oorsprong de enige heerser van het zuiden. Zijn regering eindigde met de verovering van Larsa door Hammurabi (1763 v.Chr.).", "dcc872e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1835-01-01:0":{"b": ["Laag II van de karum van Kaneš (Kültepe) wordt verwoest; tussen de Anatolische stadstaten komt Anitta op", "084f9472"], "d": ["De verwoesting van laag II van Kültepe is het einde van de eerste grote periode van de karums van Assyrische kooplieden. Daarna maakte Anitta, koning van Kuššara, Kaneš tot hoofdstad en effende hij de weg voor de politieke vestiging van de Hettieten.", "c3514f06"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1899-01-01:0":{"b": ["Assyrische kooplieden stichten de karum van Kaneš (Kültepe); het Oud-Assyrische handelsnetwerk reikt tot Anatolië", "b81b0cb9"], "d": ["De kooplieden van de stad Assur stichtten in Anatolië karums (handelskolonies) met Kaneš als centrum voor de handel in koper, tin en textiel. De tienduizenden spijkerschrifttabletten die in Kültepe zijn gevonden, vormen het begin van het schrift en de geschreven geschiedenis in Anatolië.", "2311e7a7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1924-01-01:0":{"b": ["Gungunum, koning van Larsa, neemt Ur in van Isin", "6c857c01"], "d": ["Gungunum (ca. 1932-1906) maakte Larsa voor het eerst tot een grote macht: in de jaarnamen worden de inname van Ur en een succes tegen Elam verkondigd. Met de overgang van Ur begon de beperking van Isin tot het noorden.", "0108b079"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1960-01-01:0":{"b": ["Naplânum sticht in Larsa een onafhankelijke Amorietische dynastie", "86a820f8"], "d": ["De Amorietische leider Naplânum riep zijn heerschappij in Larsa uit en stichtte de tweede grote dynastie van het zuiden na Ur III. In de eeuwenlange rivaliteit met Isin zal Larsa eerst Ur, daarna Uruk en Isin aan zich binden.", "ab808712"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2001-01-01:0":{"b": ["Išbi-Erra verdrijft het Elamitische garnizoen uit Ur; hij brengt Isin, Ur en Nippur onder zijn gezag", "a68018b2"], "d": ["Na de inname van Ur door Elam (ca. 2004) verdreef Išbi-Erra het Elamitische garnizoen uit Ur en bond Ur en Nippur aan Isin. Als politiek erfgenaam van Ur voerde Isin eeuwenlang de titel koning van Sumer en Akkad.", "77884c9c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2016-01-01:0":{"b": ["Išbi-Erra maakt zich in Isin los van Ur III; de dynastie van Isin wordt gesticht", "8d9e3116"], "d": ["Išbi-Erra, generaal van Ibbi-Sin, stichtte in Isin een onafhankelijke dynastie terwijl de staat Ur III instortte. Isin werd als dynastie met de titel «koning van Sumer en Akkad», die het culturele erfgoed van Ur voortzette, ongeveer 220 jaar lang een van de hoofdmachten van Zuid-Mesopotamië.", "b28db4ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2025-01-01:0":{"b": ["Ibbi-Sin bestijgt de troon als laatste koning van Ur III", "0afa3ef5"], "d": ["Ibbi-Sin (ca. 2028-2004) leidde als opvolger van Šu-Sin het ontbindingsproces van de staat: Amorietische druk, hongersnood, het verlies van Susa en de oostelijke provincies, de onafhankelijkheid van Išbi-Erra in Isin. Zijn regering eindigde met de plundering van Ur door een Elamitische/Šimaškische aanval.", "19e45ed0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2031-01-01:0":{"b": ["Šu-Sin bouwt de muur «Muriq-tidnim» tegen de Amorieten", "a09bfd57"], "d": ["De Ur III-koning Šu-Sin bouwde tussen Tigris en Eufraat een lange muurlijn (Muriq-tidnim, «die de Westerlingen op afstand houdt») om de uit het westen komende Amorietische nomaden (Martu) tegen te houden. De muur toont dat de Amorietische druk de staat onder spanning zette; Ur III stortte kort daarna in door deze druk en de Elamitische aanval.", "e5ec4e9a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2091-01-01:0":{"b": ["Šulgi bestijgt de troon van Ur III; hij vestigt het centrale bestuurssysteem van de staat", "06ea0c7b"], "d": ["Šulgi (ca. 2094-2047), zoon van Ur-Nammu, centraliseerde tijdens zijn regering van 48 jaar de staat Ur III: een stelsel van belasting en veeleveranties (Puzriš-Dagan), legerhervorming, stadsgouverneurs en een nieuwe kalender. Ur III geldt als de bureaucratisch meest ontwikkelde vroege staat in de geschiedenis van Mesopotamië.", "d6f42381"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2099-01-01:0":{"b": ["Puzur-Inšušinak, de laatste koning van Awan in Elam (Susa), maakt zich los van Akkadische voogdij", "cd91f4a2"], "d": ["Puzur-Inšušinak, de laatste koning van de dynastie van Awan, verenigde bij de ineenstorting van de Akkadische staat Susa en het Elamitische plateau en maakte zich los van Akkadische voogdij; hij liet naast spijkerschrift ook inscripties in «Lineair Elamitisch» na. Met de opkomst van Ur-Nammu kwam Elam opnieuw onder Mesopotamische controle.", "d16fe5e9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2110-01-01:0":{"b": ["Utu-hegal, koning van Uruk, verslaat Tirigan, koning van Gutium, en maakt een einde aan de Gutische heerschappij", "aa67620c"], "d": ["Utu-hegal, koning van Uruk, versloeg Tirigan, de koning van Gutium die over Sumer heerste, aan de oever van de Tigris en nam hem gevangen; de Guti trokken zich uit Sumer terug en in het zuiden werd onder leiding van Uruk de Sumerische heerschappij hersteld. Utu-hegals generaal Ur-Nammu zal kort daarna de dynastie van Ur III stichten.", "45b2db48"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2152-01-01:0":{"b": ["Gutium: volgens de Sumerische Koningslijst regeerden de Guti na Akkad over Sumer", "506ad1cb"], "d": ["De Guti, die uit de Zagros afdaalden, werden na de ineenstorting van de Akkadische staat heersers over het grootste deel van Mesopotamië. De Sumerische Koningslijst telt Gutium als dynastie tussen Akkad en Uruk V en Ur III (21 koningen, ongeveer 91-124 jaar); hoewel de bron vertekend is, wordt de heerschappij van de Guti gedocumenteerd als een zwak erfgenaamschap in plaats van een sterke externe dreiging.", "8ee58415"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2229-01-01:0":{"b": ["Naram-Sin verslaat de Lullubi-bergbewoners in de Zagros (Overwinningsstèle)", "de84161d"], "d": ["De reliëfstèle die de overwinning van Naram-Sin op het volk van de Lullubi (Zagros) toont, is het bekendste werk van de Akkadische kunst. De stèle werd later door de Elamitische koning Šutruk-Nahhunte naar Susa gebracht en daar in 1898 gevonden.", "5e6a3ff7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2249-01-01:0":{"b": ["Naram-Sin slaat de «Grote Opstand» neer: de coalitie van stadstaten onder leiding van Kiš en Uruk wordt verslagen", "6e9373e8"], "d": ["Aan het begin van de regering van Naram-Sin kwamen de steden in het zuiden onder leiding van Iphur-Kiš, koning van Kiš, tegen Akkad in opstand. Naram-Sin versloeg de opstandelingen in negen veldslagen en herstelde de Akkadische heerschappij; hij beschreef zijn overwinning in een inscriptie die hij aan de stadstempels wijdde.", "c9f67d8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2260-01-01:0":{"b": ["Naram-Sin bestijgt de troon van Akkad; hij neemt de titel «koning van de vier hoeken van de wereld» aan", "e9e5261d"], "d": ["Naram-Sin (ca. 2254-2218), kleinzoon van Sargon, leidde het Akkadische rijk op het hoogtepunt. Hij was de eerste Mesopotamische heerser die voor zichzelf de titel van vergoddelijkte koning en de titel «koning van de vier hoeken» gebruikte.", "b56983fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:0":{"b": ["Sargon onderwerpt Elam (Awan, Susa, Parahšum)", "1b7806f5"], "d": ["De jaarnamen en inscripties van Sargon melden de nederlaag van Elam (Awan, Parahšum); Susa werd een Akkadische stad die werd bestuurd door Akkadische gouverneurs en met documenten in het Akkadisch. Dit is de eerste keer dat Elam aan een Mesopotamisch gecentreerd rijk werd gebonden.", "7214e566"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:1":{"b": ["Sargon verslaat Lugalzagesi, koning van Uruk, en voegt de Sumerische stadstaten bij Akkad", "aad96bc9"], "d": ["Sargon, koning van Agade (Akkad), versloeg Lugalzagesi, koning van Uruk, en bracht de Sumerische steden (Uruk, Ur, Lagaš, Umma, de omgeving van Kiš) in één hand. Akkad werd het eerste rijk dat heel Zuid-Mesopotamië bestuurde.", "4ff76ffe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0231-01-01:0":{"b": ["Ardashir I valt Romeins Mesopotamië aan; de Romeins-Sassanidische oorlogen beginnen", "576ebb06"], "d": ["Ardashir I, die de Parthen had omvergeworpen, viel in 230-231 de omgeving van Nisibis en Carrhae aan en begon daarmee de eeuwenlange strijd met Rome; de veldtocht van Severus Alexander in 232 bleef zonder resultaat.", "7040e38b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0240-01-01:0":{"b": ["Hatra valt in handen van de Sassaniden (240-241)", "4f8a58ad"], "d": ["Hatra, een stad en vesting voor de woestijnhandel, werd na de lange Parthisch-Romeinse strijd in 240-241 door Ardashir I en Shapur I ingenomen en verwoest. De val van Hatra nam Rome een belangrijke bondgenoot in Mesopotamië af.", "12f25195"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0244-01-01:0":{"b": ["Gordianus III sterft bij Ctesiphon; Philippus Arabs sluit een zware vrede met Shapur", "25d270ee"], "d": ["Gordianus III werd na een aanvankelijk succesvolle veldtocht in Mesopotamië door Shapur verslagen en kwam om. Zijn opvolger Philippus Arabs sloot vrede met de Perzen; Shapur beschouwt in zijn eigen inscriptie (ŠKZ) de troonsbestijging van Philippus als zijn werk en meldt dat hij tribuut ontving.", "d975e0ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:0":{"b": ["Shapur I valt Syrië binnen en plundert Antiochië", "6f938d07"], "d": ["Shapur I voerde een grote veldtocht naar de Romeinse provincie Syrië, plunderde tientallen steden waaronder Antiochië en vestigde de gevangenen in Iran. De registratie van deze veldtocht staat in het ŠKZ-opschrift in Naqsh-e Rostam.", "17b20275"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:1":{"b": ["Dura-Europos wordt door de Sassaniden ingenomen", "c7f39e98"], "d": ["De Romeinse grensgarnizoensstad Dura-Europos aan de Eufraat viel na een lang beleg en werd verlaten; Sassanidische belegeringstunnels en Romeinse contratunnels zijn archeologisch gedocumenteerd. De stad werd nooit meer bewoond.", "889d9ece"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0260-01-01:0":{"b": ["Slag bij Edessa: Shapur I neemt de Romeinse keizer Valerianus gevangen", "654d57e3"], "d": ["Shapur I versloeg het leger van keizer Valerianus bij Edessa en nam de keizer persoonlijk gevangen. De reliëfs van Bishapur en Naqsh-e Rostam beelden deze overwinning uit; de dood van Valerianus in Sassanidische gevangenschap is de grootste vernedering in de Romeinse geschiedenis.", "2da6ab5d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0298-01-01:0":{"b": ["Verdrag van Nisibis: Galerius verslaat Narseh; het land voorbij de Tigris gaat naar Rome", "3046c0f4"], "d": ["Narsehs aanval op Romeins Mesopotamië eindigde met de overwinning van Galerius; bij de vrede van 298 werden vijf gebieden voorbij de Tigris (Transtigritania) en Nisibis aan Rome overgelaten. Het verdrag bepaalde een halve eeuw lang de Romeins-Sassanidische grens.", "4c01c338"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0309-01-01:0":{"b": ["Shapur II bestijgt vanaf zijn geboorte de Sassanidische troon (309-379)", "aeed05eb"], "d": ["Na de dood van Hormizd II werd Shapur II, geboren uit de zwanger achtergebleven koningin tijdens de troonstrijd, nog voor zijn geboorte gekroond en regeerde 70 jaar. Zijn regering is de periode van hernieuwde strijd met Rome en van de opname van de Kushanen in het Sassanidische bestuur.", "a2b5cb22"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0359-01-01:0":{"b": ["Shapur II belegert en neemt Amida in (augustus-oktober 359)", "0b812592"], "d": ["Shapur II nam met zijn Kushano-Chionitische bondgenoten Amida in na een beleg van 73 dagen en veroverde daarna Singara en Bezabde. Ammianus Marcellinus was bij het beleg aanwezig en beschrijft het gedetailleerd.", "a86e216d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-01-01:0":{"b": ["Verdrag van Jovianus: Nisibis en vijf gebieden voorbij de Tigris worden aan de Sassaniden afgestaan", "6e619831"], "d": ["Om zijn omsingelde leger te redden stemde Jovianus ermee in Nisibis, Singara en vijf gebieden voorbij de Tigris aan de Sassaniden af te staan; Rome verloor de winsten van 298, die een halve eeuw hadden geduurd. De bevolking van Nisibis trok zich terug naar Rome.", "21055f84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-06-26:0":{"b": ["Julianus sterft bij Samarra; de Sassanidische oorlog loopt ten einde", "86970a50"], "d": ["Nadat de veldtocht van Julianus naar Ctesiphon door overstromingen tot stilstand was gekomen, stierf de keizer, die tijdens de terugtocht van het Romeinse leger bij Maranga door een Sassanidische aanval gewond was geraakt. Jovianus, door het leger gekozen, moest een verdrag sluiten met Shapur II.", "9de62fd5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0387-01-01:0":{"b": ["Romeins-Sassanidisch verdrag over de verdeling van Armenië (Theodosius I – Shapur III)", "228f4d6b"], "d": ["Het grootste (oostelijke) deel van Armenië werd aan Sassanidische invloed overgelaten, het kleine westelijke deel aan Romeinse invloed; het Armeense koninkrijk der Arsaciden kwam feitelijk op weg naar zijn einde. De verdeling bepaalt ongeveer twee eeuwen de Romeins-Iraanse grens.", "d65941ae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0451-01-01:0":{"b": ["Slag bij Avarayr: Yazdegerd II slaat de Armeense opstand neer", "1bf1df2d"], "d": ["De Armeense edelen onder leiding van Vardan Mamikonian kwamen in opstand tegen het opleggen van het zoroastrisme door de Sassaniden; bij Avarayr werd het leger verslagen en Vardan kwam om. Ondanks de politieke nederlaag konden de Armeniërs hun christendom behouden.", "453512fe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0484-01-01:0":{"b": ["Peroz I sneuvelt in de strijd tegen de Hephthalieten; de Sassaniden gaan de Hunnen tribuut betalen", "a418d8ae"], "d": ["Peroz kwam met zijn leger om tegenover de Hephthalieten (Witte Hunnen) onder leiding van Akhshunwar. De Sassanidische staat onderwierp zich aan zwaar tribuut en aan het feit dat zijn zoon Kavad als gijzelaar aan het Hephthalitische hof bleef; de oostgrens werd blijvend verzwakt.", "0e4bc9f8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0496-01-01:0":{"b": ["Kavad I wordt wegens zijn pro-Mazdakitische beleid afgezet; hij komt in 498-499 met Hephthalitische hulp terug", "9101bfe7"], "d": ["Kavad I (koning sinds 488) werd door de reactie van de adel en de geestelijkheid ten val gebracht, vluchtte naar de Hephthalieten en keerde in 498-499 met hun militaire steun terug naar Ctesiphon en nam de troon terug. De Hephthalitische steun schiep het tribuut dat aan hen betaald moest worden; de oorlog met Rome van 502 kwam voort uit deze behoefte.", "06883ad8"]},
"OLAYLAR_AVMAC_A_1029:0009-01-01:0":{"b": ["Pannonië wordt georganiseerd als afzonderlijke Romeinse provincie", "2c130744"], "d": ["Nadat de in 6 n.Chr. begonnen opstand in Pannonië en Dalmatië was neergeslagen, werd het gebied in 9 n.Chr. ingericht als afzonderlijke provincie met een garnizoen van drie legioenen; in de tijd van Trajanus (omstreeks 106) werd het verdeeld in Boven- en Neder-Pannonië.", "98bf30e5"]},
"OLAYLAR_AVMAC_A_1029:0433-01-01:0":{"b": ["Het West-Romeinse Rijk laat Pannonië aan de Hunnen; de Hongaarse vlakte wordt bij het Hunnenrijk gevoegd", "62d960a0"], "d": ["In 433, toen het koningschap van Attila en Bleda begon, liet het West-Romeinse Rijk zijn gebieden in Pannonië aan de Hunnen (de datum van overdracht is omstreden: hypothesen van 425/431/433); EB11 'Attila': het eigen koninkrijk van Attila omvatte het huidige Hongarije en Transsylvanië.", "82917628"]},
"OLAYLAR_AVMAC_A_1029:0567-01-01:0":{"b": ["De Avaren vernietigen het Gepidische koninkrijk; het Avaarse kaganaat begint op de Hongaarse vlakte", "cd517799"], "d": ["De Avaren, bondgenoten van de Longobarden, verpletterden de Gepiden (567-568), de Longobarden trokken zich terug naar Italië; de Avaarse heerschappij strekte zich uit van het gebied tussen Donau en Tisza over het Karpatenbekken.", "5ae3fe4c"]},
"OLAYLAR_AVMAC_A_1029:0822-01-01:0":{"b": ["Laatste vermelding van het Avaarse kaganaat: de Hongaarse vlakte heeft geen enkele eigenaar meer (LEEGTE VERKLAARD)", "ea8d1f7b"], "d": ["De laatste politieke vermelding van de Avaarse staat is omstreeks 822 (Pohl; Curta); daarna wedijverden de heerschappijgebieden van Bulgaren, Oost-Franken en Groot-Moravië; voor het gebied tussen Donau en Tisza kon geen enkele bron met één eigenaar worden gevonden - de atlas laat dit deel als verklaarde leegte.", "09224326"]},
"OLAYLAR_AVMAC_A_1029:0895-01-01:0":{"b": ["De Hongaarse stammen vestigen zich in het Karpatenbekken (Honfoglalás): het Hongaarse vorstendom begint op de Hongaarse vlakte", "38cd1362"], "d": ["De Hongaarse stammen onder leiding van Árpád trokken in 895-896 over de Karpaten en vestigden zich in het Karpatenbekken; het gebied tussen Donau en Tisza ging over naar het Hongaarse vorstendom.", "c408bfe0"]},
"OLAYLAR_AVMAC_A_1029:0976-01-01:0":{"b": ["Otto II maakt Leopold van Babenberg markgraaf van de Oostmark: de Babenbergse heerschappij in Melk begint", "db5618ff"], "d": ["In 976 gaf Otto II de Oostmark aan Leopold van Babenberg; de mark was een grensmark met Melk als centrum en duurde tot 1156.", "65e477d3"]},
"OLAYLAR_AVMAC_A_1029:1129-01-01:0":{"b": ["Graz wordt voor het eerst vermeld (ca. 1129): de Mark Stiermarken onder de opperheerschappij van de hertog van Beieren binnen het Heilige Roomse Rijk", "5665e2f1"], "d": ["Graz wordt omstreeks 1129 onder die naam vermeld; Stiermarken was in deze tijd het gebied van markgraven onder de opperheerschappij van de hertog van Beieren.", "3de15106"]},
"OLAYLAR_AVMAC_A_1029:1135-01-01:0":{"b": ["De Babenbergers worden omstreeks 1135 heer van de stad Wenen (Wenen, Mark der Babenbergers)", "1be7d76c"], "d": ["AEIOU: de Babenbergers (976-1246) werden omstreeks 1135 heer van de stad Wenen; de stad, die in 881 voor het eerst wordt vermeld, stond hiervoor lange tijd onder Hongaarse invloed (het eindjaar wordt in de bron niet gegeven).", "61ad6f68"]},
"OLAYLAR_AVMAC_A_1029:1156-09-17:0":{"b": ["Privilegium minus (Regensburg): de Mark Oostenrijk wordt tot hertogdom verheven - Melk en Wenen in het hertogdom Oostenrijk", "aae53ec8"], "d": ["Op 17 september 1156 gaf Hendrik II Jasomirgott van Babenberg op de Rijksdag van Regensburg Beieren uit het hertogdom Beieren terug aan de keizer en werd de Mark Oostenrijk verheven tot een volledig van Beieren gescheiden hertogdom; Hendrik II had omstreeks 1155 zijn residentie van Klosterneuburg naar Wenen verplaatst.", "699d9349"]},
"OLAYLAR_AVMAC_A_1029:1180-01-01:0":{"b": ["Stiermarken wordt tot afzonderlijk hertogdom verheven (Ottokar IV hertog): Graz in het hertogdom Stiermarken", "c411776c"], "d": ["De Mark Stiermarken, onder de opperheerschappij van de hertog van Beieren, werd in 1180 een zelfstandig hertogdom; Graz was het centrum van dit hertogdom. De dag is in de bron niet vermeld (in de kunye wordt de Rijksdag van Gelnhausen genoemd).", "ba70cadc"]},
"OLAYLAR_AVMAC_A_1029:1192-05-08:0":{"b": ["De laatste Ottokar-hertog Ottokar IV sterft: Stiermarken (Graz) gaat krachtens het Pact van Georgenberg naar Leopold V van Babenberg, het hertogdom Oostenrijk", "e9a69d4d"], "d": ["Met de dood van de kinderloze Ottokar IV op 8 mei 1192 ging het hertogdom Stiermarken krachtens het Pact van Georgenberg van 17 augustus 1186 over naar Leopold V van Babenberg; de twee hertogdommen bleven bestaan als personele unie.", "6a7f7440"]},
"OLAYLAR_AVMAC_A_1029:1194-01-01:0":{"b": ["Wiener Neustadt wordt door de Babenbergse hertog Leopold V gesticht tegen de Hongaarse grens", "a5c1bd3f"], "d": ["De stad werd omstreeks 1192-94 door Leopold V gesticht tegen de Hongaarse grens; als stichtingsjaar is 1194 genomen.", "4a6b4cb3"]},
"OLAYLAR_AVMAC_A_1029:1254-04-03:0":{"b": ["Voorvrede van Ofen: Stiermarken (Graz) aan koning Bela IV van Hongarije, Oostenrijk aan Ottokar II", "06d3f258"], "d": ["Toen het geslacht Babenberg in 1246 uitstierf, streden koning Ottokar II van Bohemen en koning Bela IV van Hongarije om Oostenrijk en Stiermarken; in de op 3 april 1254 in Ofen getekende voorvrede hield Ottokar Oostenrijk en Noord-Stiermarken, terwijl Bela de rest van Stiermarken (Graz) nam.", "9926cc5c"]},
"OLAYLAR_AVMAC_A_1029:1260-07-12:0":{"b": ["Slag bij Kressenbrunn (Groißenbrunn): Ottokar II verslaat de Hongaren, Bela ziet af van Stiermarken (Graz)", "c2343628"], "d": ["Eind 1259 brak in Stiermarken een opstand uit tegen het Hongaarse bestuur; met steun van Ottokar II werd het Hongaarse leger op 12 juli 1260 bij Kroissenbrunn op het Marchfeld verslagen, Bela IV zag af van Stiermarken en Stiermarken werd onder Ottokar met Oostenrijk verenigd.", "3d598fe2"]},
"OLAYLAR_AVMAC_A_1029:1282-12-27:0":{"b": ["In Augsburg maakt koning Rudolf zijn zonen Albrecht en Rudolf hertog van Oostenrijk en Stiermarken: Wenen, Graz, Linz, Freistadt, Gmünd, Maribor, Hartberg en Wiener Neustadt in het leengoed van de Habsburgers", "c34bf152"], "d": ["Op de hofdag van Augsburg van 27 december 1282 beleende Rudolf I zijn zonen Albrecht en Rudolf met de hertogdommen Oostenrijk en Stiermarken (met Krain en de Windische Mark). De Oostenrijkse landen, die in 1276-1282 in handen van het Rijk waren, zijn vanaf deze dag Habsburgs gebied; de bijna 650 jaar durende Habsburgse heerschappij in Oostenrijk begint.", "97864694"]},
"OLAYLAR_AVMAC_A_1029:1363-01-26:0":{"b": ["Margarete Maultasch draagt Tirol over aan de Habsburgers: Innsbruck en Landeck worden Habsburgs gebied", "0b606d4e"], "d": ["De gravin van Tirol, Margarete 'Maultasch', droeg op 26 januari 1363 in Bozen haar rechten over het land over aan de Habsburgse hertog Rudolf IV en zijn broers; het graafschap Tirol eindigde, Innsbruck en Landeck werden gebonden aan de Habsburgse hertogdommen.", "96cae3e2"]},
"OLAYLAR_AVMAC_A_1029:1379-01-01:0":{"b": ["De overdracht van het graafschap Montfort-Feldkirch aan de Habsburgers is voltooid: Feldkirch in handen van hertog Leopold III (verkoop mei 1375)", "5fbe6055"], "d": ["Graaf Rudolf von Montfort-Feldkirch verkocht in mei 1375 het graafschap Feldkirch en zijn bezittingen aan hertog Leopold III; na de betaling vond in 1379 de overdracht plaats, de graaf behield levenslang het vruchtgebruik (Vogt); de lijn Montfort-Feldkirch stierf in 1390 uit.", "1af13fa1"]},
"OLAYLAR_AVMAC_A_1029:1500-04-12:0":{"b": ["Graaf Leonhard van Görz sterft in Lienz: de bezittingen van Görz (Lienz en Oost-Tirol) gaan naar de Habsburger Maximiliaan I", "0f63cdc0"], "d": ["Toen Leonhard, de laatste graaf van het geslacht der graven van Görz, op 12 april 1500 in Lienz stierf, gingen de bezittingen van Görz krachtens de kort voor zijn dood getekende erfovereenkomst (Erbvertrag) over naar het huis Habsburg (koning Maximiliaan I); Oost-Tirol (Lienz) werd bestuurd samen met het Land Tirol.", "2525327d"]},
"OLAYLAR_AVMAC_A_1029:1523-01-01:0":{"b": ["De tweede helft van Bregenz wordt aan aartshertog Ferdinand verkocht: Bregenz geheel Habsburgs gebied", "57fa353f"], "d": ["De helft van het graafschap Montfort-Bregenz was in 1451 aan hertog Sigmund verkocht; Hugo XVII von Montfort verkocht in 1523 de andere helft aan aartshertog Ferdinand (Ferdinand I) en Bregenz werd geheel Habsburgs.", "7e3168c4"]},
"OLAYLAR_AVMAC_B_1029:1363-01-26:0":{"b": ["Het graafschap Tirol gaat over naar de Habsburgers", "aeb497e3"], "d": ["De gravin van Tirol, Margarete Maultasch, liet na de dood van haar zoon Meinhard III (januari 1363) het land aan de Habsburgse hertogen; Tirol werd zonder strijd bij de gemeenschap van Habsburgse landen gevoegd. Op de kaart gaan Innsbruck en Landeck in dit jaar van het graafschap Tirol over naar Habsburgs Oostenrijk.", "0a7ec25a"]},
"OLAYLAR_AVMAC_B_1029:1526-10-23:0":{"b": ["Ferdinand I wordt tot koning van Bohemen gekozen: de Habsburgers verkrijgen de Boheemse kroon", "1fd034bc"], "d": ["Na de dood van Lodewijk II bij Mohács koos de Boheemse Landdag Ferdinand tot koning tegen verkiezingsvoorwaarden (bevestiging van privileges); de kroning vond plaats in februari 1527. Bohemen, Moravië en Silezië werden zo aan de Habsburgse kroon gebonden.", "d02cb97b"]},
"OLAYLAR_AVMAC_B_1029:1527-11-03:0":{"b": ["Ferdinand I wordt in Székesfehérvár tot koning van Hongarije gekroond", "3273aa8b"], "d": ["Ferdinand, die in september 1527 Boeda op Szapolyai had ingenomen, werd gekroond in Székesfehérvár, de kroningsstad van de Hongaarse koningen, en de periode van twee koningen met de rivaal Szapolyai werd bestendigd.", "6ac87b55"]},
"OLAYLAR_AVMAC_B_1029:1540-07-22:0":{"b": ["De dood van János Szapolyai: de poort naar de kwestie-Boeda en de deling van Hongarije", "6bfecba1"], "d": ["Szapolyai, de Ottomaanse vazalkoning van Oost-Hongarije, stierf en liet zijn kort tevoren geboren zoon als erfgenaam na. Süleyman de Grote's intocht in Boeda in 1541 en de driedeling van Hongarije (Koninklijk Hongarije, het eyalet Boeda, Transsylvanië) zijn het gevolg van deze dood.", "3506b4e8"]},
"OLAYLAR_AVMAC_B_1029:1555-01-01:0":{"b": ["Ptuj (Pettau) wordt op Salzburg teruggenomen en bij het Habsburgse Stiermarken gevoegd", "cfbd3d64"], "d": ["Ptuj, dat Maximiliaan I in 1511 met pand-/verkooprecht aan de aartsbisschop van Salzburg had gelaten, werd in 1555 door koning Ferdinand teruggekocht en gebonden aan het hertogdom Stiermarken; de heerlijkheid van Salzburg in het Dravsko polje eindigde.", "f23f6ca1"]},
"OLAYLAR_AVMAC_B_1029:1606-06-23:0":{"b": ["Vrede van Wenen: de opstand van Bocskai eindigt, de vorst van Transsylvanië wordt erkend", "30fced42"], "d": ["De Habsburgse heerser erkende Bocskai's erfelijk recht over Transsylvanië en het bestuur van vier provincies in Koninklijk Hongarije en bevestigde de constitutionele en confessionele voorrechten van de Hongaarse edelen. Het Verdrag van Zsitvatorok in november van hetzelfde jaar vulde deze vrede aan.", "691e8a43"]},
"OLAYLAR_AVMAC_B_1029:1711-04-29:0":{"b": ["Vrede van Szatmár: de vrijheidsoorlog van Rákóczi eindigt, Transsylvanië komt onder Habsburgs bestuur", "02940f3c"], "d": ["Het compromis tussen Sándor Károlyi, bevelhebber van het Kuruc-leger, en János Pálffy, opperbevelhebber van het keizerlijke leger, maakte een einde aan de sinds 1703 durende opstand van Rákóczi; de voorrechten van de Hongaarse edelen en het constitutionele bestaan van Transsylvanië bleven behouden, maar het land kwam feitelijk onder bestuur van de Habsburgse heerser. De Habsburgse periode van het Ottomaanse vazalvorstendom Transsylvanië, die in 1699 begon, werd zo definitief.", "27c9430c"]},
"OLAYLAR_AVMAC_B_1029:1803-02-25:0":{"b": ["Reichsdeputationshauptschluss: Brixen en Trient gaan naar Oostenrijk, Salzburg naar het keurvorstendom van hertog Ferdinand van Toscane", "84176083"], "d": ["Krachtens het eindbesluit dat de kerkelijke vorstendommen van het Heilige Roomse Rijk opheft, werden de prins-bisdommen Brixen en Trient bij Oostenrijk gevoegd; het prins-aartsbisdom Salzburg werd geseculariseerd en als keurvorstendom aan hertog Ferdinand van Toscane gegeven. Met dit besluit ging Trento (het bisdom Trient) over naar Oostenrijk.", "eed61208"]},
"OLAYLAR_AVMAC_B_1029:1804-08-11:0":{"b": ["Frans II roept het Keizerrijk Oostenrijk uit: erfelijk Oostenrijks keizerrijk", "a7a21bd4"], "d": ["Als antwoord op het feit dat Napoleon keizer der Fransen werd, vaardigde Frans II een patent uit en nam de titel erfelijk keizer van Oostenrijk voor de Habsburgse landen aan. Omdat hij nog de Heilige Roomse kroon bezat, liepen de twee keizertitels tot 1806 naast elkaar.", "c36c2b17"]},
"OLAYLAR_AVMAC_B_1029:1805-12-26:0":{"b": ["Plaatsdetail van de Vrede van Pressburg: Salzburg naar Oostenrijk; Brixen, Trient, Tirol en Vorarlberg naar Beieren", "89320189"], "d": ["Na Austerlitz liet Oostenrijk het graafschap Tirol (met de prins-bisdommen Brixen en Trient) en Vorarlberg aan de koning van Beieren. In ruil daarvoor werden het voormalige aartsbisdom Salzburg en Berchtesgaden bij het Oostenrijkse keizerrijk gevoegd.", "cc8f9ed7"]},
"OLAYLAR_AVMAC_B_1029:1806-08-06:0":{"b": ["Frans II legt de Heilige Roomse kroon neer: het Rijk eindigt", "4c2d7db6"], "d": ["Na de stichting van de Rijnbond verklaarde Frans de Heilige Roomse Rijk ontbonden en trad af van de kroon, waarna hij alleen keizer van Oostenrijk bleef.", "0adaf7b6"]},
"OLAYLAR_AVMAC_B_1029:1809-10-14:0":{"b": ["Plaatsdetail van de Vrede van Schönbrunn: Salzburg en Boven-Karinthië (Villach, Tarvis, Lienz) worden van Oostenrijk gescheiden", "cb38caa1"], "d": ["Na de nederlaag van 1809 liet Oostenrijk Salzburg, Boven-Karinthië (Villach en Lienz in Oost-Tirol inbegrepen) en Krain en Triëst; de delen van Karinthië en Krain vormden Napoleons Illyrische Provincies. Met deze vrede gingen Ljubljana (Kranj), Gradisca (Gorizia) en Karlovac (Kroatië ten zuiden van de Sava) naar Frankrijk; Krakau, Kielce, Radom, Chełm (Nieuw-Galicië) en Zamość naar het Groothertogdom Warschau.", "27b600e4"]},
"OLAYLAR_AVMAC_B_1029:1848-03-15:0":{"b": ["De Maartrevolutie begint in Pest: Hongaarse Revolutie van 1848-49", "8771df07"], "d": ["De demonstraties die in het Pilvax-koffiehuis begonnen, brachten in Pest, na de revolutie in Wenen (13 maart), de aanvaarding van de Twaalf Punten door de gouverneur teweeg; de Hongaarse nationale beweging tegen de Habsburgse monarchie begon.", "1a23901b"]},
"OLAYLAR_AVMAC_B_1029:1848-04-11:0":{"b": ["De Aprilwetten worden bekrachtigd: verantwoordelijke regering en onafhankelijke ministeries voor Hongarije", "93feca5f"], "d": ["De in maart door de Landdag van Pozsony aangenomen wetten werden door koning Ferdinand V bekrachtigd: een Hongaarse verantwoordelijke ministerraad, afgeschafte lijfeigenschapsverplichtingen en uitgebreid kiesrecht. Deze wetten werden opnieuw tot leven gebracht als constitutionele basis op weg naar het Ausgleich (1867).", "747be87a"]},
"OLAYLAR_AVMAC_B_1029:1848-09-11:0":{"b": ["Het Kroatische leger van Jelačić steekt de Drava over: de Hongaarse onafhankelijkheidsoorlog begint", "7b66436f"], "d": ["Jelačić, ban van Kroatië, stak met steun van het Habsburgse hof met zijn leger van ongeveer 50.000 man de Drava over, de Hongaars-Kroatische grens; dezelfde dag trad de regering van Batthyány af en het conflict veranderde in openlijke oorlog.", "50b29c18"]},
"OLAYLAR_AVMAC_B_1029:1849-04-14:0":{"b": ["Onafhankelijkheidsverklaring van Debrecen: de Habsburgse dynastie wordt onttroond, Kossuth wordt staatshoofd", "2510414e"], "d": ["De Hongaarse Landdag verklaarde in de Grote Gereformeerde Kerk de dynastie Habsburg-Lotharingen onttroond en Hongarije een onafhankelijke staat; Kossuth werd gekozen tot 'gouverneur-president'.", "451d3e00"]},
"OLAYLAR_AVMAC_B_1029:1849-08-13:0":{"b": ["Bij Világos geeft het Hongaarse leger zich over aan de Russen: de Hongaarse Revolutie wordt neergeslagen", "10218bca"], "d": ["Görgei, die door de Russische interventie was omsingeld, gaf zich na de overdracht van het gezag door Kossuth (11 augustus) bij Világos over aan de Russische troepen; dit geldt als het feitelijke einde van de revolutie. Kossuth en zijn kameraden zochten toevlucht bij de Ottomanen (zie 16 augustus 1849).", "f7f58bec"]},
"OLAYLAR_AVMAC_B_1029:1849-10-06:0":{"b": ["In Arad worden 13 Hongaarse generaals terechtgesteld, in Pest wordt Lajos Batthyány gefusilleerd", "962a8e24"], "d": ["Op bevel van Haynau werden dertien Hongaarse generaals in Arad terechtgesteld en werd Batthyány, de eerste Hongaarse premier, in Pest gefusilleerd. 6 oktober is in Hongarije de nationale rouwdag.", "ed583677"]},
"OLAYLAR_AVMAC_B_1029:1867-02-17:0":{"b": ["De Hongaarse constitutionele regering wordt hersteld: Gyula Andrássy premier", "6818a618"], "d": ["Franz Joseph liet de Hongaarse constitutionele orde van vóór 1848 weer functioneren door op voorstel van Ferenc Deák Gyula Andrássy tot premier van Hongarije te benoemen; de regering werd op 20 februari beëdigd. Deze stap effende de weg naar de aanvaarding van het Ausgleich.", "6138daea"]},
"OLAYLAR_AVMAC_B_1029:1867-05-29:0":{"b": ["Ausgleich (Compromis): de Hongaarse Landdag neemt wet 1867:XII aan - de dubbelmonarchie Oostenrijk-Hongarije", "02a1a703"], "d": ["De opnieuw bijeengekomen Hongaarse Landdag nam met 209 stemmen tegen 89 wet 1867:XII aan, die de gemeenschappelijke zaken (buitenlands beleid, leger en de financiën daarvan) regelt. De Habsburgse monarchie veranderde in een dubbele structuur van twee soevereine helften (het Keizerrijk Oostenrijk en het Koninkrijk Hongarije); Hongarije werd gelijkwaardig partner.", "3692683a"]},
"OLAYLAR_AVMAC_B_1029:1867-06-08:0":{"b": ["Franz Joseph en Elisabeth worden in Buda gekroond tot koning en koningin van Hongarije", "821b03d9"], "d": ["De kroon van Sint Stefanus werd in de Matthiaskerk op het hoofd van Franz Joseph gezet door de primaat en premier Andrássy; met deze plechtigheid werd het Ausgleich gebonden aan de bevoegdheid van de koning in het Hongaarse recht.", "7fdd290d"]},
"OLAYLAR_AVMAC_C_1029:1867-06-08:0":{"b": ["Franz Joseph I wordt in Boedapest gekroond tot koning van Hongarije: de dubbelmonarchie (Oostenrijk-Hongarije) is voltooid", "fb8bb53c"], "d": ["Het Compromis van 1867 (Ausgleich) gaf Hongarije een afzonderlijke regering en parlement voor de binnenlandse aangelegenheden; buitenlands beleid, leger en gemeenschappelijke financiën bleven gemeenschappelijk. Franz Joseph werd op 8 juni 1867 gekroond tot koning van Hongarije.", "aeaa3757"]},
"OLAYLAR_AVMAC_C_1029:1918-11-11:0":{"b": ["Keizer Karel I verklaart af te zien van deelname aan de staatszaken (voor Oostenrijk)", "bcf92744"], "d": ["Karel verklaarde op 11 november 1918 af te zien van deelname aan de staatszaken in Oostenrijk; hij deed niet openlijk afstand van de troon. De volgende dag riep de Voorlopige Nationale Vergadering de republikeinse staatsvorm uit. De afzonderlijke verklaring voor Hongarije (Eckartsau) is van 13 november.", "1e5db392"]},
"OLAYLAR_AVMAC_C_1029:1918-11-13:0":{"b": ["De verklaring van Karel uit Eckartsau: afzien van deelname aan de Hongaarse staatszaken, ontslaat de ambtenaren van hun eed van trouw", "dad220a1"], "d": ["De in Eckartsau geschreven verklaring is van 13 november 1918 gedateerd; zij werd op 14 november in Boedapest gepubliceerd. Karel deed alleen afstand van de uitoefening van de soevereine rechten en gebruikte niet het woord 'troonsafstand'. Op de kaart keren de Hongaarse ketens op 11 november terug, de uitroeping van de Volksrepubliek in de kunye op 16 november; 13 november is de juridische schakel tussen deze twee dagen.", "4bf52e81"]},
"OLAYLAR_AVMAC_C_1029:1918-11-16:0":{"b": ["De Hongaarse Nationale Raad roept de Hongaarse Volksrepubliek uit: onder leiding van Károlyi wordt de monarchie formeel afgeschaft", "aa84a13d"], "d": ["Károlyi was op 31 oktober 1918 (Asterrevolutie) door Karel tot premier benoemd. Op 16 november 1918 riepen de Nationale Raad en de regering de Volksrepubliek uit; op 11 januari 1919 werd Károlyi voorlopig president. De kunye's Hongarije-regentschap en Hongarije-volksrepubliek beginnen op deze dag. Met deze gebeurtenis gingen de steden van het Koninkrijk Hongarije buiten Kroatië, waaronder Aquincum-Óbuda-Pest, Esztergom, Eger, Szeged, Debrecen, Oradea en Opper-Hongarije, over naar de Hongaarse Volksrepubliek.", "22729026"]},
"OLAYLAR_AVMAC_C_1029:1919-03-21:0":{"b": ["De regering van Béla Kun roept de Hongaarse Radenrepubliek uit", "49fd405f"], "d": ["Toen de Vix-nota van de Entente (20 maart) de terugtrekking van de Hongaarse troepen eiste, trad de regering van Károlyi af; de communisten, verenigd met de sociaal-democraten, stichtten op 21 maart 1919 de Radenrepubliek. De republiek duurde 133 dagen (TDV: er is ook een formulering van 121 dagen); de kaart gebruikt in deze periode de identiteit Hongarije-regentschap.", "6ab3f507"]},
"OLAYLAR_AVMAC_C_1029:1919-08-04:0":{"b": ["Het Roemeense leger trekt Boedapest binnen: drie dagen na de vlucht van Kun", "cef2c6e5"], "d": ["Kun en zijn entourage vluchtten op 1 augustus 1919 naar Oostenrijk; het Roemeense leger bezette drie dagen later Boedapest en bleef tot midden november 1919 in de stad.", "d681e899"]},
"OLAYLAR_AVMAC_C_1029:1919-11-16:0":{"b": ["Horthy's Nationale Leger trekt Boedapest binnen: na het vertrek van Roemenië neemt de contrarevolutie de macht", "1612486e"], "d": ["De Roemeense troepen verlieten Boedapest op 14 november 1919; het Nationale Leger onder Horthy trok op 16 november 1919 de stad binnen. Zo werd de weg geëffend voor Horthy's benoeming tot regent op 1 maart 1920.", "0204b470"]},
"OLAYLAR_AVMAC_C_1029:1921-10-13:0":{"b": ["Protocol van Venetië: Hongarije stemt in met overdracht van Burgenland aan Oostenrijk en een volksstemming in Sopron", "b331d8e9"], "d": ["Aan het einde van de onderhandelingen van 11-13 oktober 1921 onder bemiddeling van Italië stemde Hongarije ermee in zijn troepen terug te trekken en Burgenland aan Oostenrijk te laten; Oostenrijk stemde in met een volksstemming in Sopron en acht dorpen in de omgeving. De eerste Oostenrijkse poging van 28 augustus 1921 was mislukt door Hongaarse benden (de gendarmerie keerde op 10 september terug naar de oude grens).", "d1394072"]},
"OLAYLAR_AVMAC_C_1029:1921-12-14:0":{"b": ["De volksstemming in Sopron begint: ongeveer 65 procent van de stemmen is voor Hongarije", "19a0e821"], "d": ["Op 14-15 december 1921 stemden Sopron en Brennbergbánya, op 16 december de acht omliggende dorpen. In de stad won Hongarije, in de meeste dorpen Oostenrijk; in totaal ongeveer 65 procent voor Hongarije. De Geallieerde Commissie van Generaals droeg het gebied op 1 januari 1922 over aan Hongarije (de keten Sopron op de kaart blijft Hongaars).", "d6835a9a"]},
"OLAYLAR_AVMAC_C_1029:1938-03-12:0":{"b": ["Duitse troepen trekken Oostenrijk binnen: de Anschlusswet wordt de volgende dag uitgevaardigd", "67bcdbe4"], "d": ["Schuschniggs oproep tot een volksstemming bracht Hitler tot ingrijpen; het Duitse leger trok op 12 maart 1938 Oostenrijk binnen, op 13 maart werd de aansluiting van Oostenrijk bij het Reich wet (op de kaart keren de ketens op 13 maart terug).", "75889d44"]},
"OLAYLAR_AVMAC_C_1029:1944-03-19:0":{"b": ["Duitsland bezet Hongarije (Operatie Margarethe)", "af09f10c"], "d": ["Op het zoeken van Hongarije naar een afzonderlijke vrede met de Geallieerden bezetten Duitse troepen op 19 maart 1944 het land; de regering van Sztójay werd gevormd en de deportatie van de Hongaarse Joden begon. Horthy werd op 15 oktober 1944 door zijn poging een wapenstilstand uit te roepen ten val gebracht, de Pijlkruisers kwamen aan de macht.", "929c43ce"]},
"OLAYLAR_AVMAC_C_1029:1945-04-04:0":{"b": ["Het Sovjetleger bevrijdt Hongarije van Duitse controle: de laatste Duitse troepen worden uit het land verdreven", "42677734"], "d": ["Het Sovjetleger, dat Hongarije was binnengetrokken, maakte op 4 april 1945 een einde aan de Duitse invloed. Hongarije bleef tot 1946 onder controle van de Geallieerde (Sovjet) Controlecommissie; de republiek werd op 1 februari 1946 uitgeroepen.", "889a06b4"]},
"OLAYLAR_AVMAC_C_1029:1945-04-13:0":{"b": ["Het Rode Leger neemt Wenen in: de Slag om Wenen eindigt", "6e2c5932"], "d": ["Het Rode Leger bereikte op 5 april 1945 de westrand van Wenen; op 13 april om 14 uur meldde het Sovjetcommando dat de strijd was beëindigd. De voorlopige regering van Renner verklaarde twee weken later, op 27 april, de onafhankelijkheid van Oostenrijk (op de kaart gaat de keten Wenen op 27 april van Duitsland over naar de Tweede Republiek).", "edda5e9f"]},
"OLAYLAR_AVMAC_C_1029:1945-07-09:0":{"b": ["Overeenkomst over de verdeling van Wenen in vier sectoren: de westerse geallieerden vestigen zich op 1 september in hun sectoren", "fde401dc"], "d": ["De overeenkomst over de bezettingszones (Besatzungszonen) en het bestuur van de stad Wenen dateert van 9 juli 1945; de Amerikaanse, Britse en Franse troepen kwamen op 1 september 1945 in hun sectoren, de Geallieerde Raad kwam op 11 september bijeen. De viermachtencontrole duurde tot 1955. Op de kaart is er geen afzonderlijke identiteit voor een bezettingszone (motorbevriezing: er is geen nieuwe BOYALAR-sleutel toegevoegd).", "84400060"]},
"OLAYLAR_AVMAC_C_1029:1949-08-20:0":{"b": ["De grondwet van de Hongaarse Volksrepubliek treedt in werking: eenpartijregime van Sovjettype", "7ae2e817"], "d": ["De grondwet van 20 augustus 1949 maakte Hongarije een Volksrepubliek. De kunye Hongarije-volk (1946-1989) houdt deze twee regimes als één polity; de kaartkleur verandert niet.", "5d0fed8b"]},
"OLAYLAR_AVMAC_C_1029:1955-05-15:0":{"b": ["Het Oostenrijkse Staatsverdrag wordt in Wenen getekend: de bezetting door de vier mogendheden eindigt", "24d4a84a"], "d": ["De VS, de USSR, Groot-Brittannië, Frankrijk en Oostenrijk tekenden op 15 mei 1955 in het Belvedere-paleis het Staatsverdrag; het verdrag trad op 27 juli 1955 in werking, de laatste bezettingstroepen vertrokken op 25 oktober 1955 en het Oostenrijkse parlement vaardigde op 26 oktober 1955 de grondwettelijke wet op de immerwaarende neutraliteit uit.", "bee39b98"]},
"OLAYLAR_AVMAC_C_1029:1956-10-23:0":{"b": ["De Hongaarse Opstand begint: de Sovjetinterventie slaat de opstand op 4 november neer", "1ee940b8"], "d": ["Buitensporige onderdrukking leidde op 23 oktober 1956 tot een volksopstand; Sovjettroepen grepen op 4 november in. Grondgebied en grenzen veranderden niet; het regime ging door onder Kádár (Hongarije-volk).", "2840fe28"]},
"OLAYLAR_AVMAC_C_1029:1995-01-01:0":{"b": ["Oostenrijk treedt toe tot de Europese Unie", "d0e82f3a"], "d": ["Oostenrijk werd op 1 januari 1995, samen met Zweden en Finland, lid van de EU. Staat en grenzen veranderden niet; de keten Oostenrijk-Tweede-Republiek gaat door.", "918c4a29"]},
"OLAYLAR_AVMAC_C_1029:2004-05-01:0":{"b": ["Hongarije treedt toe tot de Europese Unie", "3a28647d"], "d": ["Hongarije werd op 1 mei 2004, samen met negen landen, lid van de EU. Staat en grenzen veranderden niet; de keten Hongarije-republiek gaat door.", "89c56f8e"]},
"OLAYLAR_AVMAC_FINAL_1029:1703-01-01:0":{"b": ["De anti-Habsburgse Kuruc-opstand onder leiding van Ferenc II Rákóczi begint", "c7b4261d"], "d": ["Rákóczi's verklaring van Brezán (aangeduid als 6 mei 1703) en de ontmoeting van Tamás Esze met de Kuruc-troepen in juni 1703 begonnen de opstand; de oorlog eindigde met de Vrede van Szatmár van 1711. Alleen jaarprecisie: de dag van de verklaring/het begin wordt in secundaire bronnen verschillend gegeven als 6 mei, 21 mei, 15 juni; een academische dagbron werd niet gevonden (schuld).", "a9813686"]},
"OLAYLAR_AVMAC_FINAL_1029:1866-07-03:0":{"b": ["Slag bij Königgrätz (Sadowa): Pruisen verslaat Oostenrijk en Saksen", "ff3c7c9a"], "d": ["De beslissende slag van de Zevenwekenoorlog; het leiderschap van Oostenrijk in de Duitse Bond eindigde en de weg naar het Ausgleich van 1867 werd geopend.", "e3230571"]},
"OLAYLAR_AVMAC_FINAL_1029:1866-08-23:0":{"b": ["Vrede van Praag: Oostenrijk behoudt zijn gebieden behalve Venetië, Pruisen neemt Sleeswijk-Holstein", "d8dae04b"], "d": ["Het Verdrag van Praag van 23 augustus 1866 beëindigde de Zevenwekenoorlog; Oostenrijk werd niet bezet, zijn grens veranderde niet (Venetië werd bij het Verdrag van Wenen van 3 oktober 1866 aan Italië gelaten, zie afzonderlijk item).", "5d287a6a"]},
"OLAYLAR_AVUSTURYA_MACAR_1027:0455-01-01:0":{"b": ["Het Gepidische koninkrijk wordt gesticht: Ardarik verslaat de Hunnen, Tisza-Transsylvanië komt onder Gepidische heerschappij", "f67147d8"], "d": ["Bij de Nedao ondermijnde de opstand onder leiding van de Gepide Ardarik de Hunnische eenheid (Britannica 455, Maenchen-Helfen 454); Ardarik stichtte aan de Midden-Donau het Gepidische koninkrijk met Sirmium als centrum. Het koninkrijk werd in 567 door het Avaars-Longobardische bondgenootschap vernietigd (jaarprecisie).", "a478d0c6"]},
"OLAYLAR_AVUSTURYA_MACAR_1027:1523-01-01:0":{"b": ["Bregenz gaat over naar de Habsburgers: Hugo XVII verkoopt de rest van het bezit Montfort-Bregenz", "8571fa82"], "d": ["De helft van Bregenz werd in 1451 aan hertog Sigmund verkocht, de resterende helft in 1523 aan aartshertog Ferdinand I; de kaart zet de volledige heerschappij om in 1523, 1451-1523 is een verklaarde halve heerschappij (dag niet gevonden).", "b7bcbce4"]},
"OLAYLAR_AVUSTURYA_MACAR_1027:1918-11-16:0":{"b": ["De Hongaarse Volksrepubliek wordt uitgeroepen: de Grote Nationale Vergadering verklaart Hongarije een onafhankelijke volksrepubliek", "cbd2aeb9"], "d": ["Karel publiceerde op 13 november 1918 een verklaring van terugtrekking uit de Hongaarse politiek; op 16 november riep de Grote Nationale Vergadering van de Hongaarse Nationale Raad het 'Volksbesluit' uit en maakte Hongarije een onafhankelijke volksrepubliek, Károlyi werd premier en voorlopig president; de Habsburgse heerschappij van 400 jaar eindigde formeel. (De regering was op 31 oktober door de Asterrevolutie gevormd, de republiek werd op deze dag uitgeroepen.)", "3b6fc01d"]},
"OLAYLAR_CINHINDI1115B:0979-01-01:0":{"b": ["De dynastie Đinh eindigt; Lê Hoàn bestijgt de troon van Đại Cồ Việt (Hall: Đinh 968-79, Lê 979-1009)", "aee5ca3e"], "d": ["Volgens Hall ging het onafhankelijke koninkrijk Annam-Tonkin na de dynastie Ngô verder met de dynastie Đinh (968-79); de Đinh was zeer kortlevend. De vroege Lê-dynastie (979-1009) begon sterk; haar eerste koning Lê Hoàn viel in 982 Champa binnen. De hoofdstad is Hoa-lu.", "fc94ca4e"]},
"OLAYLAR_CINHINDI1115B:1404-01-01:0":{"b": ["Het Birmese (Ava) leger neemt Launggyet, de hoofdstad van Arakan, in; koning Narameikhla vlucht naar Bengalen", "17449f1b"], "d": ["De veldtocht van 1404 van prins Minrekyawswa namens koning Minhkaung van Ava trok Arakan binnen en bezette Launggyet; koning Narameikhla van Arakan vluchtte naar Bengalen (Gaur), de Birmanen lieten Anawrahtaminsaw achter in zijn plaats.", "558ec7e3"]},
"OLAYLAR_CINHINDI1115B:1430-01-01:0":{"b": ["Narameikhla keert met een door het sultanaat Gaur (Bengalen) verstrekte troepenmacht terug op de troon van Arakan; de koningen gaan moslimtitels gebruiken", "2de50176"], "d": ["Narameikhla, die vele jaren in ballingschap in Bengalen was gebleven, werd in 1430 met een door de koning van Gaur verstrekte troepenmacht op zijn troon hersteld. Harvey noteert dat de boeddhistische koningen van Arakan hierna naast hun eigen namen moslimtitels en munten met Perzische geloofsbelijdenis gebruikten.", "1b45fa30"]},
"OLAYLAR_CINHINDI1115B:1433-01-01:0":{"b": ["Narameikhla verplaatst de hoofdstad van Launggyet naar Mrohaung (Mrauk U); deze stad blijft vier eeuwen hoofdstad", "d24b8d43"], "d": ["Volgens Harvey hadden waarzeggers gezegd dat de koning binnen het jaar zou sterven als de hoofdstad werd verplaatst; Narameikhla stichtte Mrohaung toch in 1433 en stierf het jaar daarop. De stad was van 1433 tot 1785 de hoofdstad van Arakan (chronologie van Harvey: Launggyet 1237-1433, Mrohaung 1433-1785).", "6f658fb6"]},
"OLAYLAR_CINHINDI1115B:1459-01-01:0":{"b": ["De Arakanese koning Basawpyu neemt Chittagong in; de stad blijft tot 1666 grotendeels in Arakanese handen", "ebed3abb"], "d": ["Basawpyu (Kalima Shah, 1459-82), opvolger van Narameikhla, bezette Chittagong in 1459. Volgens Harvey was de stad tot 1666 meestal in handen van de Arakanezen; als Bengalen sterk was, betaalde Arakan tribuut aan Bengalen, als Arakan sterk was, ontving het tribuut van de Gangesdelta.", "a2258a32"]},
"OLAYLAR_CINHINDI1115B:1471-01-01:0":{"b": ["Lê Thánh Tông brengt Champa de doodsteek toe; Vijaya wordt bij Đại Việt gevoegd", "b7e2f51c"], "d": ["Volgens Hall hadden de Annamieten in 1446 gebruikgemaakt van de burgeroorlog en Vijaya kort bezet, waarna de Chams het heroverden; Lê Thánh Tông (1460-97), de grootste van de Lê-dynastie, bracht in 1471 het Chamse koninkrijk de doodsteek toe en maakte Champa tot een schakel in zijn heerschappijgebied.", "e2cbc8c0"]},
"OLAYLAR_CINHINDI1115B:1539-01-01:0":{"b": ["Tabinshwehti trekt zonder strijd Pegu (Bago) binnen; de Mon-hoofdstad komt in handen van de koning van Toungoo", "94c983ef"], "d": ["Het laten executeren van twee bevelhebbers van het Talaing (Mon) koninkrijk als verraders deed het leger zijn moreel en zijn bevelhebbers verliezen; de Mon-koning vluchtte naar Prome en Tabinshwehti trok in 1539 zonder strijd Pegu binnen en vestigde daar zijn paleis.", "6d2926cb"]},
"OLAYLAR_CINHINDI1115B:1591-01-01:0":{"b": ["Nokéo Koumane wordt in Vientiane tot koning uitgeroepen; het jaar daarop breekt hij het verzet van Luang Prabang en herenigt Lan Xang", "381a2f2c"], "d": ["Volgens Hall herwon Lan Xang (Laos) onder leiding van Nokéo Koumane zijn onafhankelijkheid terwijl het rijk van Bayinnaung uiteenviel; Koumane werd in 1591 in Vientiane tot koning uitgeroepen, onderwierp in 1592 ook Luang Prabang en verenigde het land; Tran Ninh betuigde hem trouw.", "4c065cea"]},
"OLAYLAR_CINHINDI1115B:1592-01-01:0":{"b": ["De heerschappij van de dynastie Mạc in Tonkin eindigt; de dynastie Lê keert terug naar Thăng Long (Hanoi)", "82865be2"], "d": ["Mạc Đăng Dung had in 1527 de troon geüsurpeerd, in 1533 was de Lê-dynastie via de familie Nguyễn hersteld (Nguyễn Kim had de Mạc uit Nghệ An en Thanh Hóa verdreven), maar Tonkin was in Mạc-handen gebleven. Volgens Hall regeerde de dynastie Mạc Tonkin tot 1592.", "7225b7df"]},
"OLAYLAR_CINHINDI1115B:1593-02-01:0":{"b": ["De Siamese koning Naresuan verslaat de Birmese kroonprins; de Siamese onafhankelijkheid wordt definitief", "44861a4e"], "d": ["Hall schrijft dat de pogingen van Nanda Bayin om de heerschappij over Siam te herstellen in 1593 door een beslissende nederlaag werden gestuit en dat vanaf dat moment de Siamese onafhankelijkheid was veiliggesteld; Pamaree Surakiat noteert dat Naresuan in 1593 bij Nong Sarai een grote overwinning behaalde op de Birmese kroonprins en daarna Tavoy en Tenasserim onder zijn controle bracht.", "6128c3fb"]},
"OLAYLAR_CINHINDI1115B:1594-07-01:0":{"b": ["Het Siamese leger neemt Lovek, de hoofdstad van Cambodja, in; koning Satha vlucht naar Luang Prabang", "96f68044"], "d": ["Nadat Naresuan Ayutthaya van de Birmese druk had bevrijd, trokken in 1593 drie Siamese legers Cambodja binnen; volgens Hall werd Lovek na een lang en moeizaam beleg in juli 1594 ingenomen. Het koninkrijk werd niet geannexeerd, duizenden gevangenen werden in de noordelijke provincies van Siam gevestigd. Hall merkt op dat, hoewel een inscriptie van 1587 de 'val' van Lovek gedenkt, er geen bewijs is dat Siam Lovek vóór 1594 innam.", "0f96082d"]},
"OLAYLAR_CINHINDI1115B:1707-01-01:0":{"b": ["Lan Xang wordt in tweeën gedeeld: Luang Prabang en Vientiane worden afzonderlijke koninkrijken", "fd170248"], "d": ["In 1700 nam Sai-Ong-Hué met Vietnamese steun Vientiane in en werd koning; de kleinzonen van Souligna-Vongsa, King-Kitsarat en Int'a-Som, zetten in 1707 met een in Sip-Song-Panas verzamelde macht van 6000 man T'ao-Nong, de broer van Sai-Ong-Hué, uit Luang Prabang, Kitsarat werd tot koning uitgeroepen en verklaarde het noorden van Chieng Khane een afzonderlijk onafhankelijk koninkrijk. Hall: vanaf 1707 zijn Luang Prabang en Vientiane de hoofdsteden van twee afzonderlijke en vijandige staten.", "4e9e45bf"]},
"OLAYLAR_CINHINDI1115B:1713-01-01:0":{"b": ["Chao Soi-Sisamout sticht in Bassak (Champasak) en de zuidelijke provincies een afzonderlijk koninkrijk", "4bbd3327"], "d": ["Volgens Hall slaagde Sai-Ong-Hué er niet in in Bassak en de provincies in het verre zuiden; Chao Soi-Sisamout regeerde daar vanaf 1713.", "8bea2ee8"]},
"OLAYLAR_CUKUROVA_0907:1919-02-22:0":{"b": ["Bezetting van Maraş door de Britten", "5c0faa70"], "d": ["Na de wapenstilstand van Moedros trokken Britse troepen Maraş binnen. De bezetting duurde acht maanden; krachtens de overeenkomst tussen Engeland en Frankrijk werd de stad op 29 oktober 1919 aan de Fransen overgedragen.", "bd1ef2bd"]},
"OLAYLAR_CUKUROVA_0907:1921-12-23:0":{"b": ["Bevrijding van Kilis - ontruiming door de Fransen", "d4cbc76b"], "d": ["Overeenkomstig het ontruimingsschema van het Akkoord van Ankara (20 oktober 1921) trokken de Franse troepen zich uit Kilis terug. De stad was drie jaar eerder, op 6 december 1918, door de Britten bezet en op 29 oktober 1919 aan de Fransen overgedragen.", "cafe0444"]},
"OLAYLAR_CUKUROVA_0907:1921-12-25:0":{"b": ["Bevrijding van Antep - ontruiming van de stad door de Fransen", "24b208f9"], "d": ["Na het Verdrag van Ankara ontruimden de Franse troepen Antep. De stad was op 17 december 1918 door de Britten bezet en op 5 november 1919 aan de Fransen overgelaten; de bevolking had van 1 april 1920 tot 7 februari 1921 een lange verdediging tegen de Franse troepen gevoerd.", "889e754b"]},
"OLAYLAR_CUKUROVA_0907:1921-12-27:0":{"b": ["Bevrijding van Tarsus - ontruiming van de stad door de Fransen", "398f47fb"], "d": ["De Franse troepen trokken zich krachtens het Verdrag van Ankara uit Tarsus terug; de stad was sinds 17 december 1918 bezet.", "c457bada"]},
"OLAYLAR_CUKUROVA_0907:1922-01-03:0":{"b": ["Bevrijding van Mersin - de nationale strijdkrachten trekken de stad binnen", "55ae8422"], "d": ["De nationale strijdkrachten trokken Mersin binnen; de laatste Franse eenheden verlieten de stad de volgende dag. De Franse landing had op 17 december 1918 over zee plaatsgevonden.", "c078a706"]},
"OLAYLAR_CUKUROVA_0907:1922-01-05:0":{"b": ["Bevrijding van Adana - de Fransen verlaten de stad", "07cf1e71"], "d": ["De Franse troepen verlieten Adana en de ontruiming van Çukurova was voltooid. De stad was sinds 24 december 1918 onder Franse bezetting. Deze datum wordt tegenwoordig gevierd als de bevrijdingsdag van Adana.", "db68016f"]},
"OLAYLAR_DUNYA_AVRUPA2:-0228-01-01:0":{"b": ["Eerste Romeinse veldtocht naar Illyrië: Korkyra geeft zich over aan Rome", "fffae4b7"], "d": ["De consuls trokken met vloot en leger uit om Illyrië te straffen; het garnizoen van Korkyra gaf zich over aan de Romeinen.", "41810771"]},
"OLAYLAR_DUNYA_AVRUPA2:0260-01-01:0":{"b": ["De Alemannen doorbreken de Germaans-Raetische limes en rukken op tot de Donau", "dd20a89f"], "d": ["De Alemannen doorbraken de Germaans-Raetische limes en bezetten het land tot aan de Donau en het gebied rond de benedenloop van de Main.", "71468d5c"]},
"OLAYLAR_DUNYA_AVRUPA2:0378-01-01:0":{"b": ["Slag bij Adrianopel: de Goten verslaan Valens, de keizer sneuvelt", "3e6e3307"], "d": ["De Goten van Fritigern versloegen in Thracië bij Edirne de Oost-Romeinse keizer Valens; Valens raakte gewond en kwam om.", "124cd050"]},
"OLAYLAR_DUNYA_AVRUPA2:0437-01-01:0":{"b": ["Aetius verslaat het Bourgondische koninkrijk; koning Gundicarius sneuvelt", "55e4c92e"], "d": ["Aetius versloeg de Bourgondiërs, die Belgica Prima waren binnengetrokken; koning Gundicarius viel en het eerste Bourgondische koninkrijk aan de Rijn eindigde.", "ffadfcb5"]},
"OLAYLAR_DUNYA_AVRUPA2:0443-01-01:0":{"b": ["De Bourgondiërs vestigen zich met Romeinse toestemming in Sapaudia", "9bd1ce5d"], "d": ["De overlevende Bourgondiërs werden als foederati in Sapaudia gevestigd; de kern van het latere Bourgondische koninkrijk.", "775c0cfa"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0504-01-01:0":{"b": ["Slag bij Aricia: de Etrusken worden verslagen door Aristodemus van Cumae", "a019f90f"], "d": ["Aristodemus van Cumae stuitte samen met de Latijnen de Etruskische opmars; de Etruskische heerschappij over Latium eindigde.", "9c00bf17"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0505-01-01:0":{"b": ["Athene wint van Chalcis en Boeotië en sticht een kleruchie in Chalcis", "46c2f3d5"], "d": ["De overwinning van Athene op het Peloponnesisch-Chalcidisch-Boeotische bondgenootschap; op het gebied van Chalcis werden 4000 kleruchen gevestigd.", "314bbc8a"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0544-01-01:0":{"b": ["De Phocaeërs stichten Elea (Velia)", "c3548bfc"], "d": ["Na het verlaten van Alalia stichtten de Phocaeërs Elea.", "3407a40f"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0545-01-01:0":{"b": ["Slag bij Pallene: Peisistratus vestigt in Athene een blijvende tirannie", "671f71c2"], "d": ["Bij de derde poging versloeg Peisistratus de Atheners bij Pallene en vestigde de tirannie blijvend (546/5); zij duurde tot 527.", "0647a94e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0545-01-01:1":{"b": ["Slag bij Thyrea (der Kampioenen): Sparta verslaat Argos, Kynouria blijft aan Sparta", "35b7197a"], "d": ["Elk 300 uitgelezen krijgers streden; Sparta verkreeg Thyreatis.", "8d9b3c39"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0549-01-01:0":{"b": ["Miltiades de Oudere vestigt zijn heerschappij op de Thracische Chersonesos", "6da9fbe4"], "d": ["Miltiades, van Atheense afkomst, vestigde op het schiereiland Gallipoli een halfonafhankelijk bestuur.", "88847c09"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0549-01-01:1":{"b": ["Carthago vestigt zich op Sardinië (Malchus, Mago)", "8b34c782"], "d": ["Carthago vestigde zijn heerschappij aan de kusten van Sardinië.", "d3e0f4fa"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0573-01-01:0":{"b": ["Emporion (Empúries) wordt door de Phocaeërs gesticht", "c4706f54"], "d": ["Een nederzetting van Massalia aan de Iberische kust; Griekse aanwezigheid in Hispania.", "525d2aff"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0593-01-01:0":{"b": ["Het archontaat van Solon en de seisachtheia-hervormingen", "705d0dbf"], "d": ["Hervormingen die de schuldslavernij afschaften; de burgerklassen werden opnieuw geordend.", "6d544b32"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0594-01-01:0":{"b": ["Eerste Heilige Oorlog: Kirrha wordt verwoest, Delphi komt onder controle van de Amfictyonie", "e01a15f5"], "d": ["Kirrha werd vernietigd voor de toegang tot Delphi.", "1ad355f7"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0597-01-01:0":{"b": ["Kamarina wordt door Syracuse gesticht", "47055e49"], "d": ["Syracuse stichtte een kolonie in het zuidoosten (135 jaar na Syracuse).", "40d8cb35"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0599-01-01:0":{"b": ["Poseidonia (Paestum) wordt door de Sybarieten gesticht", "5a2f0a73"], "d": ["Sybaris stichtte een kolonie aan de Tyrrheense kust.", "3a48417e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0631-01-01:0":{"b": ["De couppoging van Cylon in Athene", "32e4c5d1"], "d": ["Cylon probeerde de Akropolis in te nemen; zonder succes.", "ba8fedde"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0646-01-01:0":{"b": ["Olbia/Berezan wordt door Milete gesticht", "c05a7313"], "d": ["De eerste Griekse nederzetting aan de noordkust van de Zwarte Zee.", "5e2f8c3f"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0656-01-01:0":{"b": ["Cypselus vestigt de tirannie in Korinthe, de Bacchiaden worden ten val gebracht", "f4f32246"], "d": ["Cypselus wierp de oligarchie van de Bacchiaden omver en vestigde een langdurige tirannie.", "790b64e0"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0668-01-01:0":{"b": ["Slag bij Hysiae: Argos verslaat Sparta onder Pheidon", "47a0d03b"], "d": ["De superioriteit van Argos in de tijd van Pheidon (datum en historiciteit omstreden).", "c3d09b3d"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0672-01-01:0":{"b": ["Locri Epizephyrii (Zuid-Italië) wordt gesticht", "1ca3a23e"], "d": ["Een kolonie in Zuid-Italië.", "2471ca1e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0684-01-01:0":{"b": ["De Tweede Messenische Oorlog begint", "760d8edb"], "d": ["Sparta sloeg de Messenische opstand neer en versterkte het helotenstelsel.", "7f1466e7"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0687-01-01:0":{"b": ["Gela wordt gesticht", "a7aa747a"], "d": ["Gesticht 45 jaar na Syracuse.", "3d774871"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0699-01-01:0":{"b": ["Lelantijnse Oorlog: lange oorlog tussen Chalcis en Eretria", "ec4372c3"], "d": ["Oorlog tussen de twee grote steden van Euboea om de Lelantijnse vlakte; vele Griekse staten kozen partij.", "140a24c1"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0731-01-01:0":{"b": ["Rhegion wordt gesticht", "9b7b9f57"], "d": ["Een kolonie aan de zuidpunt van Italië.", "6de952a4"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0732-01-01:0":{"b": ["Korkyra (Kerkyra) wordt door de Korinthiërs gesticht", "6fb853e7"], "d": ["Een Korinthische kolonie aan de poort van de Adriatische Zee.", "b7b072be"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0733-01-01:0":{"b": ["Naxos (Sicilië) wordt gesticht: de eerste Griekse kolonie op Sicilië", "4850886a"], "d": ["Onder leiding van Theocles stichtten de Chalcidiërs de eerste Griekse kolonie in Oost-Sicilië.", "407aaab5"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0799-01-01:0":{"b": ["Gadir (Cádiz) wordt door de Feniciërs gesticht", "9409a8e5"], "d": ["De traditie geeft 1100 v.Chr. (Velleius 1.2.3), de archeologie de 9e-8e eeuw v.Chr.", "907f05f8"]},
"OLAYLAR_DUNYA_BOLGE_1109:1385-08-14:0":{"b": ["Unie van Krewo - de vereniging van Polen en Litouwen", "29f0d9ef"], "d": ["Jogaila, groothertog van Litouwen, nam het besluit te trouwen met Jadwiga, het christendom aan te nemen en Litouwen aan de Poolse kroon te binden. In het Poolse nationale verhaal is Krewo het stichtende document dat een van de grootste staten van Europa deed ontstaan; het wordt in het bijzonder benadrukt als een unie die niet door een oorlog maar door een huwelijksakte tot stand kwam.", "02686717"]},
"OLAYLAR_DUNYA_BOLGE_1109:1400-10-30:0":{"b": ["De val van Aleppo - het Mamelukse leger wordt verslagen", "77c7953d"], "d": ["Timoer, die terugkeerde van zijn Indiase veldtocht, trok in het kader van de westelijke operatie die de 'Zevenjarige Veldtocht' wordt genoemd Syrië binnen en versloeg voor Aleppo het Mamelukse leger; de stad werd drie dagen geplunderd en van schedels werden torens gemaakt. De val van Aleppo was de eerste grote slag die paniek veroorzaakte aan het Mamelukse hof in Caïro.", "eca82709"]},
"OLAYLAR_DUNYA_BOLGE_1109:1405-02-18:0":{"b": ["Timoer sterft", "1928b1f4"], "d": ["De dood van Timoer op weg naar zijn veldtocht naar China leidde tot de verdeling van zijn rijk onder zijn zonen en kleinzonen; het grootste deel van Iran werd uiteindelijk verenigd in de handen van zijn zoon Shahrukh en de hoofdstad werd verplaatst naar Herat.", "a94951bd"]},
"OLAYLAR_DUNYA_BOLGE_1109:1439-07-06:0":{"b": ["De Unie van Florence wordt uitgeroepen", "460f28e8"], "d": ["De vereniging van de orthodoxe en katholieke kerken werd uitgeroepen; de enige bisschop die niet tekende was Marcus van Efeze. In het Byzantijnse verhaal werd de unie ervaren als het verkopen van het geloof om de staat te redden en werd door het volk verworpen: de uitspraak \"liever de Turkse tulband dan de Latijnse mijter\" komt uit deze jaren.", "888920ab"]},
"OLAYLAR_DUNYA_BOLGE_1109:1458-01-24:0":{"b": ["Verkiezing van Matthias Hunyadi (Matthias Corvinus) tot koning", "f0c52c1a"], "d": ["De menigte van edelen en volk die op de bevroren Donau rond Boeda bijeenkwam, riep de vijftienjarige Matthias tot koning uit; dit was een uitzonderlijk moment waarop een 'inheemse' adellijke familie in plaats van een buitenlandse dynastie de troon besteeg. Zijn regering van tweeëndertig jaar zou Hongarije veranderen in een van de krachtigste staten van Midden-Europa.", "4f3e2558"]},
"OLAYLAR_DUNYA_BOLGE_1109:1480-11-11:0":{"b": ["De confrontatie aan de rivier de Oegra - het einde van het Tataarse juk", "0a1d84b3"], "d": ["De legers van Ivan III en de troepen van Akhmat, khan van de Gouden Horde, stonden maandenlang tegenover elkaar aan de oever van de rivier de Oegra; zonder gevecht trok Akhmat zich terug. De Russische geschiedschrijving beschouwt deze gebeurtenis als het officiële en definitieve einde van het \"Tataarse juk\" (dat sinds 1237 had geduurd) en de geboorte van Moskou als onafhankelijke macht - een keerpunt even groot als Koelikovo, volgens sommige historici zelfs groter.", "955810b6"]},
"OLAYLAR_DUNYA_BOLGE_1109:1490-04-06:0":{"b": ["Dood van Matthias Corvinus", "652fb823"], "d": ["Na de dood van Matthias, die geen wettige erfgenaam naliet, stortte zijn centralisatiepolitiek in; het Zwarte Leger werd ontbonden, de edelen herwonnen hun macht en de troon ging over naar een zwakke Jagiello-koning, Wladislaus II. Tijdgenoten herdachten deze dood als het einde van de 'gouden eeuw' van Hongarije.", "a20bdc7f"]},
"OLAYLAR_DUNYA_BOLGE_1109:1492-03-31:0":{"b": ["Edict van de Alhambra - verbanning van de Joden", "2a4e2686"], "d": ["Isabella en Ferdinand bevalen dat alle Joden die zich niet tot het christendom bekeerden binnen vier maanden het land moesten verlaten; tussen 40.000 en 100.000 mensen (de schattingen variëren) trokken naar Portugal, Noord-Afrika en Ottomaans gebied. Het verhaal dat sultan Bayezid II een vloot stuurde om de emigranten te vervoeren, behoort tot dezelfde golf als deze gebeurtenis.", "73ec3641"]},
"OLAYLAR_DUNYA_BOLGE_1109:1519-06-28:0":{"b": ["Karel V wordt tot keizer van het Heilige Roomse Rijk gekozen", "7806defb"], "d": ["Het college van keurvorsten in Frankfurt koos de Spaanse koning Karel V tot keizer, tegen de Franse koning Frans I; zo werd hij het centrum van een personele unie die Spanje, Duitsland, Nederland, Bourgondië en het grootste deel van Italië omvatte. De verkiezing leidde tot Karels langdurige afwezigheid uit Spanje en zware belastingeisen en lokte de opstand van de Comuneros uit.", "eb77afea"]},
"OLAYLAR_DUNYA_BOLGE_1109:1524-05-23:0":{"b": ["Sjah Ismail sterft, Tahmasp I bestijgt de troon", "a4edbd63"], "d": ["Met de dood van sjah Ismail, die zich na Çaldıran had teruggetrokken, besteeg zijn tienjarige zoon Tahmasp de troon; de eerste tien jaar gingen voorbij met regentschapsstrijd tussen de Qizilbash-stamleiders, maar zijn regering van 54 jaar werd een van de langste van de Safavidische staat.", "638c52e8"]},
"OLAYLAR_DUNYA_BOLGE_1109:1552-10-02:0":{"b": ["De val van Kazan - het einde van de Turkse heerschappij van negen eeuwen in het Midden-Wolgagebied", "e0d16f1c"], "d": ["Na bloedige gevechten die ongeveer twee maanden duurden, viel Kazan op 2 oktober 1552 (Juliaans; Gregoriaans 12 oktober - de «15 oktober» van TDV lijkt een verschil door een omrekening van 13 dagen) en eindigde de Turkse heerschappij in het Midden-Wolgagebied die sinds de 6e eeuw na Christus had geduurd. De kunst-, kalligrafie- en bouwwerken van de stad werden geplunderd; van de overgrote meerderheid bleef zelfs geen spoor over.", "d67d7483"]},
"OLAYLAR_DUNYA_BOLGE_1109:1556-01-01:0":{"b": ["Het Khanaat Astrachan wordt geannexeerd", "57d7fc0f"], "d": ["Vier jaar na de val van Kazan werd ook het Khanaat Astrachan geannexeerd; zo kwamen de hele Wolga en de toegang tot de Kaspische Zee in Russische handen. Deze twee veroveringen vormden de geografische sleutel tot de uitbreiding van Rusland naar het zuiden en oosten (Siberië).", "dde89031"]},
"OLAYLAR_DUNYA_BOLGE_1109:1556-01-16:0":{"b": ["Afstand van de troon door Karel V - de Spaanse kroon gaat naar Filips II", "b92cba1e"], "d": ["Karel V droeg met een plechtigheid in Brussel de Spaanse en Nederlandse kroon over aan zijn zoon Filips; de keizerlijke titel liet hij aan zijn broer Ferdinand. Deze scheiding was de verkondiging dat de Oostenrijkse en Spaanse takken van het huis Habsburg voortaan afzonderlijk zouden voortgaan.", "adb161a5"]},
"OLAYLAR_DUNYA_BOLGE_1109:1576-05-14:0":{"b": ["Tahmasp I sterft - de opvolgingscrisis begint", "aa20029c"], "d": ["Met de dood van Tahmasp I brak een bloedige troonstrijd uit tussen zijn zonen; deze tien jaar durende instabiliteit (de tijden van Ismail II en Muhammed Khodabanda) verdiepte de Qizilbash-twisten en gaf de Ottomanen een nieuwe kans op oorlog.", "5e55bbde"]},
"OLAYLAR_DUNYA_BOLGE_1109:1587-10-01:0":{"b": ["Abbas I de Grote bestijgt de troon", "724a0b0a"], "d": ["De zeventienjarige Abbas werd door de Qizilbash-emirs op de troon gezet in plaats van zijn vader Muhammed Khodabanda; zijn regering van 42 jaar zou het militaire, bestuurlijke en culturele hoogtepunt van de Safavidische staat zijn. In de Iraanse geschiedschrijving is het tijdperk van Sjah Abbas een referentiepunt van een \"gouden eeuw\" op het niveau van Peter van Rusland of Süleyman de Grote van de Ottomanen.", "7d5cb8fc"]},
"OLAYLAR_DUNYA_BOLGE_1109:1613-03-03:0":{"b": ["De dynastie Romanov bestijgt de troon", "9e4bcca4"], "d": ["De Zemski Sobor koos de zestienjarige Michaël Romanov tot tsaar; zo werd de Tijd der Troebelen van vijftien jaar formeel gesloten en begon de dynastie Romanov, die tot 1917 zou duren. In de Russische nationale geschiedschrijving is het de keerdatum van de herstichting van de staat en de maatschappelijke orde, van de afsluiting van de Smoeta.", "742c1b73"]},
"OLAYLAR_DUNYA_BOLGE_1109:1629-01-19:0":{"b": ["Sjah Abbas sterft", "5fc3247e"], "d": ["Na een regering van tweeënveertig jaar geldt de dood van Sjah Abbas als het einde van het hoogtepunt van de Safavidische staat; met de regering van zijn kleinzoon en opvolger Sjah Safi begon een langzaam maar ononderbroken verval.", "30118d02"]},
"OLAYLAR_DUNYA_BOLGE_1109:1648-05-16:0":{"b": ["De opstand van Chmelnytsky begint - Zhovti Vody", "e9ae726f"], "d": ["De opstand die de Kozakkenhetman Bohdan Chmelnytsky in bondgenootschap met de Krimtataren begon, vernietigde bij Zhovti Vody een Poolse macht en tien dagen later bij Korsun de hoofdmacht van het leger. De Poolse geschiedschrijving neemt deze datum als het moment waarop de gouden eeuw eindigde: de republiek keerde nooit meer terug tot haar vroegere kracht.", "ec8357e9"]},
"OLAYLAR_DUNYA_BOLGE_1109:1682-05-07:0":{"b": ["Fjodor III sterft, Peter I wordt tot tsaar uitgeroepen", "82534f8e"], "d": ["Na de dood van de kinderloos gestorven Fjodor III riepen de standenvertegenwoordigers die in het Kremlin bijeenkwamen de tienjarige Peter tot tsaar uit. Na de door de Miloslavski-partij aangezette opstand van de streltsy werden Peter en zijn oudere broer Ivan V gezamenlijk tsaar gemaakt en ging het bestuur naar regentes Sofia. Peter regeerde na 1696 alleen.", "dfa6a305"]},
"OLAYLAR_DUNYA_BOLGE_1109:1709-07-08:0":{"b": ["Poltava - Mazepa en Karel XII worden verslagen, het lot van het Hetmanaat bezegeld", "2497e53c"], "d": ["De Russisch-Zweedse oorlog van 1708-1709 op Oekraïens grondgebied eindigde bij Poltava met de nederlaag van de bondgenoten; Mazepa, Orlyk en hun Kozakken-aanhangers zochten met Karel XII toevlucht op Ottomaans gebied, in Bender. Volgens EoU bezegelde deze nederlaag het lot van Oekraïne; Peter beperkte daarna stap voor stap de autonomie van het Hetmanaat.", "3e9f9c5b"]},
"OLAYLAR_DUNYA_BOLGE_1109:1722-10-25:0":{"b": ["Mahmud Hotak wordt tot sjah uitgeroepen", "97cd2096"], "d": ["Direct na de overgave van Isfahan riep Mahmud zichzelf uit tot sjah van Iran; de troonsbestijging van een soennitische Afghaanse leider op de sjiitische Iraanse troon is het begin van de korte maar traumatische Hotaki-periode (1722-1729), die in de Iraanse geschiedschrijving als een \"buitenlandse bezetting\" van het land wordt aangeduid.", "478f1a45"]},
"OLAYLAR_DUNYA_BOLGE_1109:1762-07-09:0":{"b": ["Catharina II bestijgt door een staatsgreep de troon", "e29e31b3"], "d": ["De uit Duitsland afkomstige tsarina Catharina wierp met steun van de gardeofficieren (van wie enkelen haar minnaar waren) haar man Peter III omver en besteeg de troon; Peter werd enkele dagen later onder verdachte omstandigheden vermoord. Haar regering van 34 jaar was getuige van de grootste territoriale uitbreiding van Rusland en van het discours van de \"Verlichte Autocratie\".", "458add50"]},
"OLAYLAR_DUNYA_BOLGE_1109:1783-08-04:0":{"b": ["Verdrag van Georgievsk - Kartli-Kachetië komt onder Russische bescherming", "b5450242"], "d": ["Heraclius II sloot, op zoek naar garanties tegen de Ottomaanse en Perzische druk, een beschermingsverdrag met Rusland; Kartli-Kachetië droeg zijn buitenlands beleid over aan Rusland en kreeg in ruil een belofte van militaire bescherming. Dit verdrag bereidde de juridische basis voor van de volledige annexatie achttien jaar later.", "c7c6c8a1"]},
"OLAYLAR_DUNYA_BOLGE_1109:1805-12-02:0":{"b": ["Austerlitz - Slag der Drie Keizers", "b1ee0f76"], "d": ["De Russen en Oostenrijkers werden bij Austerlitz beslissend verslagen. De daarop volgende Vrede van Pressburg bracht zware gebiedsverliezen: Venetië, Istrië en Dalmatië gingen naar Frankrijk, heel Voor-Oostenrijk naar Beieren - ongeveer drie miljoen inwoners.", "cde24675"]},
"OLAYLAR_DUNYA_BOLGE_1109:1813-10-24:0":{"b": ["Verdrag van Gulistan - het grootste deel van de Kaukasus gaat verloren", "18c35598"], "d": ["Perzië zag af van zijn aanspraken op heel Georgië, Dagestan en Noord-Azerbeidzjan (Bakoe, Shirvan, Karabach en Ganja inbegrepen); het verloor ook het recht een vloot op de Kaspische Zee te hebben. In de Iraanse geschiedschrijving is dit verdrag het juridische begin van het nog steeds voelbare trauma van de \"verloren Kaukasus\" - op wereldschaal is het ook een verdrag dat de blijvende Russische heerschappij in Transkaukasië vestigde en de politieke kaart van de regio opnieuw tekende.", "8a41733e"]},
"OLAYLAR_DUNYA_BOLGE_1109:1815-09-26:0":{"b": ["De Heilige Alliantie - de heersers van Rusland, Oostenrijk en Pruisen verenigen zich in Parijs", "d4619104"], "d": ["Na de nederlaag van Napoleon ondertekenden de Russische tsaar Alexander I, de Oostenrijkse keizer Frans I en de Pruisische koning Frederik Willem III een verklaring waarin zij beloofden te besturen volgens christelijke beginselen en elkaar te helpen. De alliantie werd het conservatieve steunpunt van de orde van het Congres van Wenen.", "ec02bebb"]},
"OLAYLAR_DUNYA_BOLGE_1109:1879-10-07:0":{"b": ["Zweibund - het Duits-Oostenrijkse Bondgenootschap wordt in Wenen getekend", "ce79cc02"], "d": ["Na het Congres van Berlijn sloten Duitsland en Oostenrijk-Hongarije een defensief bondgenootschap tegen Rusland. Het geheime verdrag, ondertekend door Andrássy en prins Reuss, werd in 1882 met de toetreding van Italië de Triple Alliantie en duurde tot 1914.", "2f84b46e"]},
"OLAYLAR_DUNYA_BOLGE_1109:1881-06-18:0":{"b": ["Driekeizersbond (tweede) - geheime overeenkomst over de Zeestraten, Bosnië-Herzegovina en Oost-Roemelië", "532a98c2"], "d": ["Oostenrijk-Hongarije, Duitsland en Rusland tekenden in Berlijn een geheim verdrag. De partijen aanvaardden dat de territoriale status quo van 'Turkije in Europa' alleen met gezamenlijk besluit van de drie kon worden gewijzigd. Zij beschouwden het sluiten van de Zeestraten voor oorlogsschepen als gezamenlijk beginsel. Met een aanvullend protocol kreeg Oostenrijk-Hongarije het recht Bosnië-Herzegovina te annexeren wanneer het wilde; overeengekomen werd dat zij zich niet zouden verzetten tegen de vereniging van Bulgarije en Oost-Roemelië. Het verdrag verving de eerste bond van 1873, werd in 1884 verlengd en eindigde in 1887.", "c71c0cae"]},
"OLAYLAR_DUNYA_BOLGE_1109:1894-01-04:0":{"b": ["Het Frans-Russische Bondgenootschap wordt officieel", "4d616905"], "d": ["Frankrijk en Rusland sloten een geheim bondgenootschap door de bepalingen van het militaire verdrag van 1892 te bevestigen met een briefwisseling. Als Duitsland of een door Duitsland gesteunde staat een van de partijen zou aanvallen, zou de andere met al zijn kracht tegen Duitsland ten strijde trekken. Het bondgenootschap gold zolang de Triple Alliantie bestond en vestigde de blokordening van de Eerste Wereldoorlog.", "68fdddbe"]},
"OLAYLAR_DUNYA_BOLGE_1109:1905-01-22:0":{"b": ["Bloedige Zondag", "7d7c38e0"], "d": ["De menigte arbeiders die onder leiding van pope Gapon een vreedzame petitiemars hield, werd voor het Winterpaleis uiteengedreven door het vuren van de tsarengarde; honderden mensen kwamen om. In de Russische geschiedschrijving is deze slachting de datum waarop het traditionele vertrouwen van het volk in de \"tsaar-vadertje\" definitief werd gebroken en de Revolutie van 1905 feitelijk begon.", "6246c12c"]},
"OLAYLAR_DUNYA_BOLGE_1109:1906-08-05:0":{"b": ["Sjah Mozaffar ad-Din tekent de grondwet - het constitutionele stelsel wordt uitgeroepen", "b661df69"], "d": ["Enkele weken vóór zijn dood keurde sjah Mozaffar ad-Din de bijeenroeping van het eerste Nationale Parlement (Majlis-e Shura-ye Melli) en het opstellen van een grondwet goed; Iran begon zo, onafhankelijk van het Ottomaanse Rijk (1876/1908) en Rusland (1905), zijn eigen constitutionele ervaring. In de Iraanse geschiedschrijving is dit, hoewel minder dan de Revolutie van 1979, een van de meest ingrijpende keerpunten van de moderne Iraanse politieke geschiedenis - op wereldschaal weerspiegelt het, als onderdeel van de golf van constitutionalisme in Azië (Japan 1889, Ottomaanse Rijk 1908, Rusland 1905/1906), een regionale/globale systemische trend.", "25ff44af"]},
"OLAYLAR_DUNYA_BOLGE_1109:1907-08-31:0":{"b": ["Brits-Russische overeenkomst van 1907 - Iran wordt verdeeld in invloedssferen", "17c59cd8"], "d": ["Engeland en Rusland verdeelden Iran, zonder toestemming van Iran, feitelijk in drieën: een Russische invloedssfeer in het noorden, een Britse in het zuidoosten en een neutrale zone in het midden; deze overeenkomst geldt als het formele einde van het \"Grote Spel\" en als een van de zwaarste slagen voor de onafhankelijkheid van het land, omdat de Iraanse soevereiniteit openlijk door twee grote mogendheden werd genegeerd - het is tegelijk een regionale machtsevenwichtsovereenkomst die in het wereldsysteem de Brits-Russische rivaliteit verschoof naar de bondgenootschapsstructuur van vóór de Eerste Wereldoorlog (Frankrijk-Rusland-Engeland).", "137c9397"]},
"OLAYLAR_DUNYA_BOLGE_1109:1917-03-15:0":{"b": ["Nicolaas II treedt af, de dynastie Romanov eindigt", "0866a3ad"], "d": ["Nicolaas II verklaarde voor zichzelf en zijn zoon van de troon af te treden; doordat zijn broer Michaël de volgende dag ook weigerde de kroon te aanvaarden, eindigden de dynastie Romanov, die sinds 1613 304 jaar had geduurd, en de autocratische monarchie van drie eeuwen formeel. In de Russische geschiedschrijving is het, op hetzelfde niveau als Koelikovo, 1613, 1812 en 1861, de afsluitende datum van het keizerlijke tijdperk (zie [[rusya-gecici-hukumet]], [[sovyet-rusya]]).", "6a110185"]},
"OLAYLAR_DUNYA_BOLGE_1109:1917-11-02:0":{"b": ["De Balfour-verklaring wordt gepubliceerd", "d618cf61"], "d": ["Minister van Buitenlandse Zaken Arthur Balfour stuurde een brief aan Lord Rothschild waarin hij de steun van de Britse regering uitsprak voor de oprichting van een 'nationaal tehuis' voor de Joden in Palestina. De verklaring werd een belofte die de politieke geschiedenis van het Midden-Oosten een eeuw lang diepgaand zou vormen.", "d1b5d7de"]},
"OLAYLAR_DUNYA_BOLGE_1109:1917-11-07:0":{"b": ["Oktoberrevolutie - de bolsjewieken wierpen de Russische Voorlopige Regering omver", "a43063c1"], "d": ["De bolsjewieken onder leiding van Lenin namen de macht over door in Petrograd de Voorlopige Regering omver te werpen (25 oktober volgens de Juliaanse kalender, vandaar de \"Oktoberrevolutie\").", "30353579"]},
"OLAYLAR_DUNYA_BOLGE_1109:1921-02-21:0":{"b": ["De staatsgreep van Reza Khan", "dba4134e"], "d": ["Reza Khan, commandant van de Kozakkenbrigade, nam samen met de journalist Seyyed Zia'eddin Tabatabai Teheran in en vormde een nieuwe regering; hoewel hij in de eerste fase Ahmad Sjah op de troon liet, nam hij de feitelijke macht over. In de Iraanse geschiedschrijving is dit het begin van het feitelijke einde van de Qajar-dynastie en van de overgang naar het Pahlavi-tijdperk.", "8fa9e252"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Slaan van de eerste Osmaanse akçe", "38d2d638"], "d": ["De eerste zilveren akçe, geslagen in naam van Orhan Gazi, is de monetaire proclamatie van de onafhankelijke soevereiniteit van het beylik; de akçe bleef vijf eeuwen lang de basismunteenheid.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Oprichting van het beylerbeylik van Rumelië", "ffa16089"], "d": ["De veroveringen aan de Europese kant werden onder één militair-administratief dak verzameld; het beylerbeylik-stelsel werd de ruggengraat van de provinciale organisatie van het rijk.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Huwelijk van Yıldırım Bayezid en Despina Hatun", "4b10dc6c"], "d": ["De vazalliteit die na Kosovo met het Servische despotaat werd gevestigd, werd bezegeld met het huwelijk van Lazars dochter Olivera met Bayezid — een typisch voorbeeld van huwelijksdiplomatie uit de vroege periode.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Oprichting van het beylerbeylik van Anatolië", "5ef8d3a7"], "d": ["Voor het bestuur van de geannexeerde beylikgebieden werd het beylerbeylik van Anatolië georganiseerd; de tweevleugelige bestuursorde Rumelië–Anatolië was voltooid.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Voltooiing van de Ulu Camii van Bursa", "27bcc4a5"], "d": ["De grote moskee met twintig koepels, gebouwd met de buit van Nikopol, is een monumentaal voorbeeld van de vroege Osmaanse architectuur en een openluchtmuseum van de kalligrafie.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Afzetting en executie van Çandarlı Halil Pasja", "5e19438f"], "d": ["Na de verovering werd de grootvizier uit de oude familie Çandarlı, die afstand had genomen van het beleg, geëxecuteerd; voor het eerst werd een grootvizier op bevel van de sultan gedood en brak het tijdperk van viziers van devşirme-afkomst aan.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Moldavië schatplichtig gemaakt", "25bd3693"], "d": ["Het woiwodschap Moldavië aanvaardde schatting te betalen; samen met Walachije en Transsylvanië werd de drievoudige vazalgordel ten noorden van de Donau de noordelijke bufferzone van het rijk. Andere plaatsen die op dezelfde datum werden toegevoegd: Iași.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Schatting van Dubrovnik (Ragusa)", "d127c78a"], "d": ["De handelsrepubliek Ragusa verzekerde zich in ruil voor schatting van haar autonomie en handelsprivileges; zij werd rijk als het venster van de Osmanen op de Adriatische Zee. Ook het eiland Mljet (Mliyet), grondgebied van de republiek, deelde deze status.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Veldtocht naar Walachije: de Spietser", "fd4530bb"], "d": ["Met de veldtocht tegen Vlad Tepeş, die weigerde schatting te betalen en gezanten doodde, werd Walachije weer vazal; de nachtelijke overval en de gruwelijke scènes van spietsing werden in Europa legende. Andere plaatsen die op dezelfde datum werden toegevoegd: Boekarest.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Opening van het Fatih-complex", "a150ea55"], "d": ["Het complex met zijn acht madrasa's (Sahn-ı Semân) was de eerste grote stap in het programma om Constantinopel te veranderen in het wetenschappelijk centrum van de islamitische wereld.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu in Constantinopel", "8508229d"], "d": ["Ali Kuşçu, de laatste grote vertegenwoordiger van de sterrenwacht van Samarkand, werd op uitnodiging van de Veroveraar müderris aan de Hagia Sophia-madrasa; hij vestigde de wiskundig-astronomische traditie in Constantinopel.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunname van de Veroveraar", "b08944c9"], "d": ["De eerste omvattende kanunname die de staatsorganisatie, het protocol en de straffen codificeerde; hij blijft omstreden vanwege het beroemde artikel dat broedermoord 'voor de orde van de wereld' toestaat.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Eerste Osmaanse gouden munt (sultanî) geslagen", "2fd5c0dd"], "d": ["De eerste Osmaanse gouden munt, gelijk aan de Venetiaanse dukaat, werd geslagen; de rijksfinanciën sloten zich aan bij de internationale monetaire orde.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Verhuizing naar het Topkapı-paleis", "b9cd6a5e"], "d": ["Met de voltooiing van het Nieuwe Paleis (Topkapı) verhuisde het centrum van het staatsbestuur hierheen; het paleis bleef vier eeuwen lang het brein van het rijk.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Republiek Florence omgevormd tot hertogdom — Alessandro de' Medici", "c08764e1"], "d": ["Onder druk van paus Clemens VII nam de regeringscommissie (Balìa) van Florence een nieuwe grondwet aan; het vijf eeuwen oude republikeinse bewind werd afgeschaft en Alessandro de' Medici werd tot erfelijk hertog uitgeroepen en besteeg op 1 mei feitelijk de troon. Florence veranderde zo van een onafhankelijke stadsrepubliek in een erfelijk hertogdom van de dynastie Medici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Huwelijk van Süleyman de Wetgever en Hürrem Sultan", "abc05f26"], "d": ["Dat Süleyman officieel met Hürrem trouwde, veranderde de paleistraditie ingrijpend; de instelling 'Haseki Sultan' ontstond en de deur naar het tijdperk van vrouwen in de dynastieke politiek ging open.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Eerste uitgebreide capitulaties met Frankrijk", "e2264e48"], "d": ["Als onderdeel van het Franse bondgenootschap tegen de Habsburgse omsingeling werden handelsprivileges ondertekend tussen Jean de la Forest en Makbul İbrâhim Pasja; de capitulaties, die toen een diplomatiek instrument waren, zouden in de loop van de eeuwen de deur naar financiële afhankelijkheid worden.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Indische Oceaan-expeditie: beleg van Diu", "fcd1217a"], "d": ["De vloot die uit Suez vertrok, stak de Rode Zee over en belegerde Diu in Gujarat; hoewel de burcht niet werd ingenomen, reikte de Osmaanse macht voor het eerst tot in de Indische Oceaan en werd het Portugese monopolie aan het wankelen gebracht.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Reis van Seydi Ali Reis naar India", "e5da3b2c"], "d": ["Seydi Ali Reis, die de opdracht had de vloot in Basra naar Egypte te brengen, werd door stormen naar India gedreven; zijn Mir'âtü'l-memâlik, waarin hij zijn terugreis vertelt, is een van de eerste Osmaanse reisverslagen.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Executie van Pîrî Reis", "63026444"], "d": ["De grote zeevaarder en cartograaf, die van de Hormuz-campagne terugkeerde nadat hij de vloot in Basra had achtergelaten, werd op 84-jarige leeftijd geëxecuteerd — een van de meest omstreden beslissingen uit onze wetenschapsgeschiedenis.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Opening van het Süleymaniye-complex", "1c6458b2"], "d": ["Het complex dat architect Sinan 'mijn gezellenwerk' noemde; met zijn madrasa's, ziekenhuis en bibliotheek werd het het grootste onderwijs- en liefdadigheidscomplex van de klassieke periode.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Beleg van Malta", "f57f6a85"], "d": ["Malta, het slot van de Middellandse Zee, werd vier maanden belegerd; Turgut Reis sneuvelde en het beleg werd opgeheven. Het was de eerste grote stap terug van de Osmaanse zeevaart onder Süleyman.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Voltooiing van de Selimiye-moskee", "3b0484e1"], "d": ["De Selimiye, waarvan Sinan zei dat het zijn 'meesterwerk' was en waarin één koepel de ruimte beheerst, wordt beschouwd als het hoogtepunt van de klassieke Osmaanse architectuur (UNESCO-Werelderfgoed).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Oprichting van de Sterrenwacht van Constantinopel", "169bdf5d"], "d": ["De sterrenwacht van Takiyyüddin, een van de best uitgeruste observatoria van die tijd, werd in 1580 afgebroken na de discussies die ontstonden naar aanleiding van de komeet van 1577; de institutionele sterrenkunde liep drie eeuwen achter.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Overwinning bij Çıldır — oostelijke oorlog begon", "13125a54"], "d": ["Met de nederlaag van het Safawidische leger bij Çıldır gingen de poorten van de Kaukasus open; Tbilisi werd ingenomen en Georgië kwam onder Osmaanse heerschappij.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Slag van de Fakkels — Shirvan definitief Osmaans", "3bbc23bc"], "d": ["In de slag die zo wordt genoemd omdat zij ook 's nachts bij fakkellicht werd voortgezet, werden de Safawiden definitief verslagen; de Osmaanse heerschappij in Shirvan en Bakoe werd bezegeld.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Grote muntverslechtering — akçe-crisis", "9205c3d4"], "d": ["Onder druk van de lange oorlogen en het Amerikaanse zilver werd het zilvergehalte van de akçe gehalveerd; de prijsrevolutie voedde het uiteenvallen van het sipahi-stelsel en de Celali-onrust.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Verovering van Tabriz", "6506bdb9"], "d": ["Serdar Özdemiroğlu Osman Pasja trok Tabriz binnen; de oude hoofdstad van de Safawiden werd onder Osmaans bestuur gebracht. Osman Pasja stierf enkele weken later in het legerkamp.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Verdrag van Ferhad Pasja — grootste grenzen in het oosten", "c429972f"], "d": ["Met het verdrag dat werd gesloten na de aankomst in Constantinopel van Sjah Abbas' gezant Haydar Mirza (18 januari 1590), onder voorwaarde dat de veroverde plaatsen Osmaans bleven, en dat de twaalf jaar durende oorlog beëindigde, bleven Tabriz, Karabach, Shirvan, Georgië en Luristan Osmaans; het rijk bereikte in het oosten de grootste grenzen uit zijn geschiedenis.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Osmaans-Safawidische oorlog (1603-1612) begon — tegenoffensief van Sjah Abbas, verlies van Tabriz", "abf27dd8"], "d": ["Sjah Abbas, die zijn leger had gereorganiseerd, ging gebruik makend van de Celali-onrust over tot het offensief; Tabriz viel en de winsten in de Kaukasus gingen binnen enkele jaren verloren. Plaatsen die in dezelfde veldtocht en daarna verloren gingen: Nakhitsjevan, Khoy, Marand, Salmas; ook de beys van Karacadağ (Ahar) en Mukri keerden terug naar de Safawidische kant.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Evliya Çelebi geboren", "2b6051ff"], "d": ["Evliya Çelebi, die zijn reizen van meer dan vijftig jaar bijeenbracht in de tiendelige Seyahatnâme, liet een unieke panorama van de 17e-eeuwse Osmaanse wereld na.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Verdrag van Nasuh Pasja", "bb69e388"], "d": ["Met het verdrag dat de oorlog sinds 1603 beëindigde, werd afgezien van de winsten van 1590 en werd teruggekeerd naar de Amasya-grens van 1555; het evenwicht aan het oostfront was hersteld.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Opening van de Sultan Ahmed-moskee", "e39dfd43"], "d": ["Met haar zes minaretten en blauwe İznik-tegels is de 'Blauwe Moskee' het laatste grote sultanscomplex van de klassieke periode.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Moord op sultan İbrahim", "bc4eb452"], "d": ["Met als reden verkwisting en een bestuurscrisis zette een alliantie van korpsen en ulema İbrahim af; tien dagen later werd hij met een fatwa gewurgd. De zevenjarige Mehmed IV besteeg de troon; de macht kwam feitelijk in handen van de grote valide Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Overlijden van Kâtib Çelebi", "e167e89d"], "d": ["Hij is de topfiguur van de Osmaanse wetenschapsgeschiedenis met zijn bibliografie Keşfü'z-zunûn en zijn geografie Cihannümâ; hij staat bekend om zijn pioniersaanpak waarin hij Europese bronnen gebruikte.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Edirne-incident — afzetting van Mustafa II", "0291c1cd"], "d": ["De woede over het feit dat de sultan in Edirne verbleef en over de invloed van Feyzullah Efendi ontaardde in een grote opstand van leger en handelaren; de sjeik-ul-islam werd gelyncht, de sultan afgezet en het paleis keerde terug naar Constantinopel.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Ambassadeur naar Parijs: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["De grote ambassade die naar Frankrijk werd gezonden was de eerste systematische waarneming ter plaatse van het Westen; zijn Sefâretnâme inspireerde de vernieuwing in het Tulpentijdperk.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Eerste Osmaanse drukkerij opgericht", "4943f7e5"], "d": ["Er werd toestemming gegeven om Turkse boeken te drukken; het eerste werk, het Vankulu-woordenboek, werd in 1729 gedrukt. De drukkerij is de meest blijvende erfenis van de vernieuwing in het Tulpentijdperk.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Capitulaties permanent gemaakt", "d044a79e"], "d": ["De privileges die aan Frankrijk waren verleend, werden niet langer aan de persoon van de sultan gebonden maar aan een blijvend verdrag; het capitulatiestelsel, dat niet meer eenzijdig opgezegd kon worden, kon pas in Lausanne worden afgeschaft.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Mühendishâne-i Bahrî-i Hümâyun opgericht", "9bf3f439"], "d": ["De ingenieursschool, opgericht na de ramp bij Çeşme om moderne marineofficieren op te leiden, is de eerste blijvende instelling van technisch onderwijs naar westers model; de landingenieursschool volgde in 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Eerste permanente ambassade in Londen", "6b5630eb"], "d": ["Als onderdeel van het Nizâm-ı Cedîd-programma werden permanente ambassades in de Europese hoofdsteden geopend; de Osmaanse diplomatie ging over op het beginsel van wederkerigheid.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Overlijden van Alemdar Mustafa Pasja", "4426534e"], "d": ["In de janitsarenopstand die in de nacht van 15 november 1808 begon, stak de hervormingsgezinde grootvizier, die bij de Hoge Porte werd belegerd, toen de verwachte hulp uitbleef de volgende dag het munitiemagazijn in brand en stierf met honderden aanvallers; de orde van het Sened-i İttifak en de eerste hervormingspoging werden met hem begraven.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Eerste officiële krant: Takvîm-i Vekāyi", "c637f623"], "d": ["Het officiële staatsblad begon te verschijnen; het is het begin van de traditie van moderne publieke opinie en officiële mededelingen.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Handelsverdrag van Balta Limanı", "e790b383"], "d": ["Aan Engeland werd ook in de binnenlandse handel de meest bevoorrechte positie toegekend en het yed-i vahit-stelsel (monopolie) werd afgeschaft; terwijl de binnenlandse productie onbeschermd bleef, werd het verdrag het document van de volledige opening van de Osmaanse markt voor de vrijhandel.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Einde van het Emiraat Libanon — afzetting van Bashir III Shihab", "f85ae454"], "d": ["Emir Bashir II (III), die de christelijk-Druzische twist en de interne evenwichten in de Shouf-regio niet kon beheersen, werd in januari 1842 afgezet; de lokale emiraatsorde die sinds 1516 (door de Ma'noğulları en daarna de Shihabs) bestond, kwam ten einde en de regio kwam rechtstreeks onder Osmaans bestuur en daarna onder het systeem van dubbele kaymakamlik.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: het Mecidiye-stelsel", "c77be809"], "d": ["Met de muntherziening werden de verslechterde munten ingenomen; een stabiel bimetallisch stelsel op basis van de gouden lira (Mecidiye) werd gevestigd.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Einde van de lokale heerschappij van de familie Harfush in Baalbek", "8438f4ae"], "d": ["De invloed van de familie Harfush, die sinds 1521 (na de opstand van Canbirdi Gazâlî) in Baalbek als kleine lokale dynastie regeerde, kwam met de nieuwe administratieve regeling van de Hoge Porte ten einde; de stad werd een gewoon kaza-centrum van de provincie Damascus.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Oprichting van de Şirket-i Hayriyye", "462830e7"], "d": ["De maatschappij, opgericht om stoomboten op de Bosporus te exploiteren, geldt als de eerste Osmaanse naamloze vennootschap; de stoomboot-aanlegsteigers drukten hun stempel op het stadsleven.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Eerste buitenlandse leningsovereenkomst", "9017c579"], "d": ["Voor de financiering van de Krimoorlog werd op de Londense markt de eerste buitenlandse lening aangegaan; het punt dat in 21 jaar met 15 leningen werd bereikt, was het moratorium van 1875 en de Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Telegraaflijn in Constantinopel", "d320f39f"], "d": ["De eerste telegraaflijn, aangelegd vanwege de behoeften van de Krimoorlog, werd in gebruik genomen; het rijk kreeg in enkele decennia een van de grootste telegraafnetwerken ter wereld.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Land-kanunname (Arazi Kanunnâmesi)", "6bae243a"], "d": ["De kanunname die het landrecht moderniseerde, bond het feitelijke gebruiksrecht op staatsland (mîrî) aan de tapu (eigendomsakte); zij is een van de basisdocumenten van de eigendomsorde van het huidige Midden-Oosten.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Eerste lessen in de Dârülfünun", "08f74066"], "d": ["De Dârülfünun, die onderwijs op universitair niveau zou verzorgen, begon te werken met openbare lessen; de instelling, die met onderbrekingen voortbestond, werd in 1900 definitief geopend en werd de kern van de Universiteit van Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Vilayet-reglement (Vilâyet Nizamnâmesi)", "ad20853b"], "d": ["In plaats van het eyalet-stelsel werd een vilayet-organisatie naar Frans model gevestigd; naar het voorbeeld van de toepassing van Midhat Pasja in de Donau-vilayet werd zij over het hele land verspreid.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Europese reis van Abdülaziz", "9ff0fa1e"], "d": ["De eerste Europese reis van een Osmaanse sultan met vreedzame doeleinden; de wereldtentoonstelling van Parijs en de bezoeken aan Londen dienden zowel als diplomatie als als etalage van modernisering.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Opening van de Galatasaray Mekteb-i Sultânîsi", "f9688524"], "d": ["Het lyceum met Franstalig onderwijs werd met zijn leerlingenpopulatie zonder onderscheid van religie en gemeenschap het symbool van het ideaal van gelijkheid in het onderwijs van de Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Eerste boek van de Mecelle in werking", "6475461c"], "d": ["De Mecelle, die het verbintenissen- en zakenrecht van het islamitische recht met moderne wetgevingstechniek codificeerde, wordt beschouwd als het eerste islamitische burgerlijk wetboek; de commissie onder leiding van Cevdet Pasja voltooide de 16 boeken in 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Afzetting van Abdülaziz", "eb7397ea"], "d": ["Constitutionalistische staatslieden en militaire kopstukken zetten Abdülaziz met een stille staatsgreep af; zijn verdachte dood vijf dagen later en de daaropvolgende Çırağan-incidenten leidden tot afrekeningen die jarenlang zouden duren.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Overval op Çırağan (zaak Ali Suâvi)", "d2a9ac87"], "d": ["De journalist Ali Suâvi overviel Çırağan om Murad V weer op de troon te zetten; de overval werd bloedig neergeslagen en het regime van Abdülhamid verstrakte de veiligheidsring blijvend.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Oprichting van de Régie (tabaksmonopolie)", "bad9b030"], "d": ["De tabaksinkomsten werden overgedragen aan de Régie-maatschappij met buitenlands kapitaal binnen de Düyûn-ı Umûmiyye; de conflicten rond de 'Régie-smokkel' tussen boeren en bewakers duurden tientallen jaren. Andere plaatsen die op dezelfde datum verloren gingen: Zeila.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Bezoek van keizer Wilhelm II aan Constantinopel en Jeruzalem", "2988cd06"], "d": ["Het tweede bezoek van de Duitse keizer bezegelde de Osmaans-Duitse toenadering; de weg werd geopend voor de concessie van de Bagdadspoorweg en in Damascus werd de toespraak 'vriend van driehonderd miljoen moslims' gehouden.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Hidjaz-spoorlijn bereikt Medina", "95009b9c"], "d": ["De 1464 km lange lijn, gebouwd met uitsluitend moslimdonaties en lokale ingenieurskunst, bereikte Medina; de pelgrimsreis werd van weken tot dagen verkort. Het is het grootste infrastructuurwerk uit de tijd van Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Incident van 31 maart", "1d7c2bb2"], "d": ["Een grote anti-constitutionele opstand nam Constantinopel in; het Actieleger uit Thessaloniki sloeg de opstand neer en Abdülhamid II werd afgezet.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Beleg van Edirne begon", "234d9b28"], "d": ["De vijf maanden durende verdediging van Şükrü Pasja werd een heldenverhaal van verzet te midden van de Balkanramp; de stad viel door hongersnood en werd in juli 1913 teruggenomen.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Overval op de Hoge Porte (Bâb-ı Âli Baskını)", "b304d02d"], "d": ["De regering, die zich voorbereidde op de overgave van Edirne, werd door een gewapende overval van de Unionisten ten val gebracht; minister van Oorlog Nâzım Pasja werd gedood. De periode van volledige macht van het Comité voor Eenheid en Vooruitgang begon.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Afschaffing van het Mutasarrifaat Libanonberg", "b5639051"], "d": ["De autonome mutasarrifaatsorde, die was gesticht met het Règlement Organique van 1861 en berustte op het in 1864 vernieuwde internationale protocol, werd tijdens de Eerste Wereldoorlog eenzijdig door de Osmaanse staat ontbonden; het ministerie van Binnenlandse Zaken begon rechtstreeks moslim-mutasarrıfs in de regio te benoemen. De autonomieperiode van 1861-1915, waarin acht mutasarrıfs dienden, werd zo gesloten.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Verdeling van het land onder de prinsen", "82f26bfb"], "d": ["Na de nederlaag bij Ankara trok Süleyman Çelebi naar Rumelië en riep in Edirne het sultanaat uit; İsa Çelebi hield Bursa en Çelebi Mehmed het gebied Amasya-Tokat-Sivas in handen. Op de kaart worden deze drie delen in afzonderlijke kleuren weergegeven.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Verdrag van Gallipoli: Zwarte Zeekust tot Mesembria aan Byzantium gelaten", "a4164eca"], "d": ["Emir Süleyman, die zich na de nederlaag bij Ankara in Rumelië wilde handhaven, sloot in Gallipoli een verdrag met de Byzantijnse keizer Manuel. Hij liet Kartal, Pendik en Gebze met enkele eilanden, in Rumelië Thessaloniki en Thessalië en aan de Zwarte Zee de kuststrook tot Mesembria aan Byzantium; ook de belasting die Byzantium aan de Osmanen betaalde, werd afgeschaft. Ahtapolu, İğneada en Rezve aan de Istranca-kust bleven zo eenentwintig jaar onder Byzantijns bestuur; Murad II nam de meeste van deze plaatsen met de vrede van 1424 terug.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Dood van Yıldırım Bayezid in gevangenschap", "7e968d83"], "d": ["De sultan, die in handen van Timur gevangen zat, stierf in Akşehir; zijn lichaam werd naar Bursa gebracht en begraven. Zijn dood maakte de troonstrijd tussen de prinsen onomkeerbaar.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Verdrag van Gallipoli — toegevingen aan Byzantium", "dfacbd00"], "d": ["Süleyman Çelebi, die zijn positie in Rumelië wilde veiligstellen, gaf Thessaloniki, de kusten van de Zee van Marmara en enkele eilanden terug door overeenkomsten met de Byzantijnse en Latijnse staten; hij stemde zelfs in met het betalen van schatting.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Treffen bij Ulubat — nederlaag van İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, die Bursa in handen hield, werd bij Ulubat door zijn broer Mehmed verslagen; ook enkele pogingen tot herstel bleven zonder resultaat.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Verdwijnen van İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, die met steun van Süleyman Çelebi enkele malen naar Anatolië terugkeerde, verdween na zijn laatste nederlaag; zijn deel ging naar Çelebi Mehmed en op de kaart breidde het gebied van Mehmed zich naar het westen uit.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi trok naar Walachije", "8441267a"], "d": ["Çelebi Mehmed, die Bursa en Ankara aan Süleyman Çelebi had verloren en zich naar Tokat-Amasya had teruggetrokken, moedigde zijn broer Musa aan naar Rumelië te gaan. Musa aanvaardde de uitnodiging van de Walachijse woiwode Mircea en bereikte Walachije over zee; vanaf daar zou hij een strijd aangaan die Süleyman tussen twee fronten zou brengen.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed nam Bursa en Ankara opnieuw in — het Anatolische deel verliet Süleyman Çelebi", "bfb69f12"], "d": ["Na de successen van Mûsâ Çelebi in Rumelië (Yambol, 13 februari 1410) trok Emir Süleyman Çelebi, die zich in Anatolië bevond, naar Rumelië. Nadat Süleyman Anatolië had verlaten, nam Mehmed Çelebi het gebied rond Bursa, inclusief Ankara, opnieuw in en liet hij ten teken van zijn troonsbestijging munten van het jaar 813 slaan. Op de kaart gaat de Anatolische kant van de Zee van Marmara van het deel van Emir Süleyman over naar de kleur van Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Slag bij Kosmidion", "0efc2caa"], "d": ["In de slag voor de muren van Constantinopel, gevoerd met Byzantijnse steun, versloeg Süleyman Çelebi zijn broer Musa; maar zijn steun in Rumelië begon snel weg te smelten.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Beleg van Constantinopel door Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, die Byzantium wilde straffen voor zijn steun aan Süleyman, belegerde Constantinopel; dit beleg dreef Byzantium in een bondgenootschap met Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Dood van Emir Süleyman — Musa heerst over Rumelië", "325c1549"], "d": ["Süleyman Çelebi werd tijdens zijn vlucht uit Edirne gevangengenomen en gedood; heel Rumelië kwam in handen van Musa Çelebi. Op de kaart verandert Rumelië van blauw naar paars.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Slag bij Çamurlu — herstel van de eenheid", "0b23173e"], "d": ["Çelebi Mehmed, die de steun van Byzantium, het Servische despotaat en de beys van Rumelië had gekregen, bracht zijn broer Musa bij Çamurlu een beslissende nederlaag toe; Musa werd tijdens zijn vlucht gedood. Rumelië, dat in handen van Musa was, ging samen met Edirne naar Mehmed en Mehmed Çelebi riep zich in Edirne uit tot de enige heerser van de Osmaanse staat. Het elf jaar durende Interregnum eindigde, de delen van de prinsen op de kaart werden in één lichaam verenigd.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Besluit tot de veldtocht naar Wenen — vrede van Vasvár niet vernieuwd, doel verlegd van Győr naar Wenen", "1bf278f2"], "d": ["Keizer Leopold I wilde dat het Verdrag van Vasvár, waarvan de termijn nog niet verstreken was, werd vernieuwd, en ook Mehmed IV leek voor vrede. Grootvizier Merzifonlu Kara Mustafa Pasja liet de vrede echter niet vernieuwen met als reden de klachten van Imre Thököly, die hij tot koning van Midden-Hongarije had laten uitroepen; hij zette predikers met Vânî Mehmed Efendi voorop in beweging en overtuigde de sultan van de oorlog. In het overleg werd besloten dat de sultan in Belgrado zou blijven en de serdar-ı ekrem verder zou trekken om Győr (Yanıkkale) in te nemen; maar in het overleg in Székesfehérvár werd het doel, ondanks het bezwaar van de Krim-khan Murad Giray en de gouverneur van Boeda, Uzun İbrâhim Pasja, veranderd in het beleg van Wenen.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Tweede Beleg van Wenen begon — leger voor Wenen", "bb542e49"], "d": ["Het Osmaanse leger onder bevel van grootvizier Kara Mustafa Pasja kwam op 14 juli 1683 voor Wenen aan. Keizer Leopold I liet de verdediging van de stad over aan Starhemberg en trok zich terug in het binnenland van Oostenrijk. Dit tweede beleg, dat in tegenstelling tot het eerste rechtstreeks op Wenen werd voorbereid, zou tot 12 september duren.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Nederlaag bij Párkány en verlies van Esztergom", "a7366740"], "d": ["Het leger dat zich uit Wenen terugtrok werd bij Párkány voor de tweede keer verslagen; daarna viel Esztergom, een van de sleutelburchten van Hongarije. De terugtocht begon in een ineenstorting over te gaan.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Executie van Merzifonlu Kara Mustafa Pasja", "ce8b10ac"], "d": ["De grootvizier, die verantwoordelijk werd gehouden voor de nederlaag bij Wenen, werd in Belgrado gewurgd; maar zijn executie herstelde noch het front noch het aangetaste prestige van de staat.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Heilige Liga opgericht", "060280d0"], "d": ["Onder leiding van het pausdom werd tussen Oostenrijk, Polen en Venetië de Heilige Liga tegen de Osmanen gesloten; in 1686 trad ook Rusland toe. Het rijk raakte zo verwikkeld in een zestien jaar durende oorlog aan meerdere fronten.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Eerste verdediging van Boeda", "ccc43630"], "d": ["Het eerste beleg van Boeda door het leger van de Heilige Liga werd afgeslagen door de koppige verdediging van de burcht, die vier maanden duurde; maar de burchten in Hongarije bleven een voor een vallen.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Verlies van Uyvar", "689ab78c"], "d": ["De burcht Uyvar, die tweeëntwintig jaar in Osmaanse handen was gebleven en in Europa een spreekwoord was geworden, viel; de Osmaanse aanwezigheid in Boven-Hongarije viel uiteen.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Arrestatie van Thököly in Oradea — Koninkrijk Midden-Hongarije ontbonden, burchten van Boven-Hongarije gaven zich over", "1741aaaf"], "d": ["Na de nederlaag bij Wenen begonnen de Osmanen ook Thököly te zien als een van degenen die tot de oorlog en de nederlaag hadden geleid. Op 15 oktober 1685 liet de beylerbey van Varad, Ahmed Pasja, op bevel van serdar Melek İbrâhim Pasja Thököly, die kwam om te helpen, gevangennemen; men hoopte betere vredesvoorwaarden te verkrijgen door hem aan de Habsburgers over te leveren. Toen het nieuws van de arrestatie zich verspreidde, gaven alle burchten en steden van het Koninkrijk Midden-Hongarije zich over aan de Habsburgers, met uitzondering van Munkács, dat door zijn vrouw Ilona Zrínyi werd verdedigd; de meeste kurucen-soldaten liepen over naar het Habsburgse leger. Toen Thököly op 2 januari 1686 in Belgrado werd vrijgelaten, bestond het koninkrijk niet meer.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Verlies van Boeda — 145 jaar Hongaarse hoofdstad", "70800e2b"], "d": ["Na een beleg van achtenzeventig dagen viel Boeda; de laatste beylerbey Abdurrahman Abdi Pasja sneuvelde op de muren. Het verlies van de stad, die sinds 1541 onder Osmaans bestuur stond, geldt als het symbool van het verlies van Hongarije. Andere plaatsen die op dezelfde datum verloren gingen: Pest.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Tweede Mohács (Harsány) — verlies van Transsylvanië en Mohács", "a7922681"], "d": ["Op de vlakte waar in 1526 de grote overwinning was behaald, werd ditmaal een zware nederlaag geleden; het leger viel uiteen en de opstandige soldaten lieten de grootvizier afzetten. De nederlaag leidde ook tot het verlies van Transsylvanië.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Verlies van Athene en de Parthenon-explosie", "b6691730"], "d": ["Een bom van de Venetiaanse artillerie liet de Parthenon, die de Osmanen als munitiemagazijn gebruikten, de lucht in vliegen; de tweeduizend jaar oude tempel werd een ruïne. De stad kwam in Venetiaanse handen (zij zou in 1688 worden teruggenomen).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Afzetting van Mehmed IV en troonsbestijging van Süleyman II", "9f53037c"], "d": ["Na rampen aan het front en de opstand van het leger werd Mehmed IV na een regering van 39 jaar afgezet; in zijn plaats werd zijn broer Süleyman II, die veertig jaar in de kooi was gehouden, op de troon gezet.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Eerste verlies van Belgrado — beleg door de Heilige Liga", "c6b9b19a"], "d": ["Belgrado, dat sinds 1521 in Osmaanse handen was, gaf zich over aan het leger van de Heilige Liga; de poorten van Servië gingen open voor de vijand en het gevaar naderde de lijn Niš–Sofia. Andere plaats die op dezelfde datum in de atlas van de Osmanen naar de Habsburgers ging: Hisarcık (Grocka) — volgt de abi-centrumketen van Belgrado (TDV belgrad; verklaarde benadering).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden stak de Morava over bij Pasarofça — Pasarofça viel aan Oostenrijk", "bcf3fc59"], "d": ["Markgraaf Ludwig von Baden stak in augustus 1689 de Morava over bij Pasarofça en rukte op in de richting van Niš; de stad bleef tot de zomer van 1690 in Oostenrijkse handen (TDV suleyman-ii zegt dat Pasarofça in 1690 werd teruggenomen). De datum en de lezing van Röder werden in deze sessie niet opnieuw bevestigd.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Verlies van Niš — opmars van de Habsburgers (kroon van het Koninkrijk Hongarije), kritiekste jaar", "c5e27b3f"], "d": ["De opmars van de Habsburgers (kroon van het Koninkrijk Hongarije) nam ook Niš uit het Osmaanse bestuur; de strooptochten reikten tot Üsküp en Priština. Vidin viel hierna, in oktober 1689 (afzonderlijk item). In het donkerste jaar van de oorlog voelde de staat zelfs de hoofdstad bedreigd.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova en Fethülislâm kregen een Oostenrijks garnizoen", "ee8dd875"], "d": ["Na de overgave zonder strijd van Vidin (oktober 1689, TDV vidin) herstelde Baden op 25 oktober 1689 Orsova en Fethülislâm (Kladovo) en voorzag ze van een garnizoen; Orsova bleef tot de herfst van 1690 Oostenrijks. De datum berust op Bánlaky/Röder en werd in deze sessie niet opnieuw bevestigd.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš opnieuw Osmaans", "0c4f44eb"], "d": ["Fâzıl Mustafa Pasja trok in juli 1690 ten strijde; nadat Şehirköy, Pasarofça en Güvercinlik waren ingenomen, kwam het belegerde Niš op 27 september 1690 in Osmaanse handen (TDV semendire). Tegelijkertijd was ook Vidin teruggenomen. Andere plaatsen die op dezelfde datum in de atlas van de Habsburgers naar de Osmanen terugkeerden: Jagodina en Prokuplje (Ürküp) — omdat geen plaatsniveaudag kon worden gevonden, is de dag van Niš genomen (TDV semendire; verklaarde benadering; Röder 1842 schrijft dat de vizier tussen 8 en 24 september door Jagodina trok, de tegenspraak is niet opgelost).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Oostenrijkse troepen in Smederevo gaven zich over", "90da20c4"], "d": ["Na de inname van Niš op 27 september 1690 gaven de Oostenrijkse troepen in Smederevo zich na een beleg van vier dagen over (TDV semendire). Bánlaky/Röder noemt 24 september; de bronnen spreken elkaar tegen, de TDV is als basis genomen.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrado teruggenomen", "ab435838"], "d": ["Grootvizier Köprülüzâde Fâzıl Mustafa Pasja nam Belgrado op 8 oktober 1690 op Oostenrijk terug; de stad die in 1688 verloren was gegaan keerde zo terug naar de Osmanen (TDV suleyman-ii). Andere plaats die op dezelfde datum in de atlas van de Habsburgers naar de Osmanen terugkeerde: Hisarcık (Grocka) — volgt de abi-centrumketen van Belgrado (TDV suleyman-ii; verklaarde benadering).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Nederlaag bij Slankamen — Fâzıl Mustafa Pasja sneuvelde", "10d626f1"], "d": ["In een van de bloedigste veldslagen van de eeuw sneuvelde de grootvizier, in het voorhoofd getroffen; het leger viel uiteen. Met deze slag doofde de hoop op herstel.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Verlies van het eiland Chios", "07c084f8"], "d": ["De Venetiaanse vloot bezette Chios; de Osmaanse heerschappij in de Egeïsche Zee kwam onder dreiging. Het eiland zou het jaar daarop worden teruggenomen.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Besluit van Mustafa II om persoonlijk ten strijde te trekken", "61c3ba9c"], "d": ["De nieuwe sultan kondigde aan dat hij naar het voorbeeld van zijn voorouders aan het hoofd van het leger ten strijde zou trekken; dit besluit wekte moreel in het leger en leidde de periode van persoonlijke veldtochten in die twee jaar zou duren.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Herovering van Chios", "6b496fca"], "d": ["Mezomorto Hüseyin Pasja, die in de zeeslagen bij de Koyun-eilanden de Venetiaanse vloot versloeg, nam Chios terug; een teken van een korte opleving van de Osmaanse zeevaart.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Overwinning bij Lugoj — eerste Oostenrijkse veldtocht van Mustafa II", "d5ee9b34"], "d": ["In de eerste veldtocht waaraan de sultan persoonlijk deelnam werd Lipova teruggenomen en werden de Oostenrijkse strijdkrachten bij Lugoj verslagen; in de al jaren durende keten van nederlagen vond de eerste breuk plaats. De atlas beschouwt ook Caransebeș (Karánşebeş) in deze veldtocht als van de Habsburgers naar de Osmanen teruggekeerd; de bron geeft alleen september 1695 (TDV mustafa-ii), de atlasdag is overgenomen van de Lugoj-aantekening (verklaarde benadering).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Verlies van de burcht Azak", "2b78b5cd"], "d": ["Peter I, die ernaar streefde de Zwarte Zee te bereiken, nam Azak in tijdens zijn tweede beleg; Rusland vestigde zich voor het eerst blijvend in een Osmaanse burcht en zette zijn eerste stap op weg naar een zeemacht.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Overwinning bij Ulaş (Olașin)", "02ac9ca8"], "d": ["De overwinning die tijdens de tweede veldtocht van de sultan aan de oever van de Donau werd behaald, doorkruiste het Oostenrijkse plan om Temesvár in te nemen; maar zij veranderde het algemene evenwicht van de oorlog niet.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Nederlaag bij Zenta — het lot van de oorlog bepaald", "475c4a7b"], "d": ["Het leger werd bij het oversteken van de Tisza overvallen door prins Eugenius; de strijdkrachten, verdeeld over beide oevers van de rivier, werden binnen enkele uren vernietigd, en duizenden soldaten en staatslieden, onder wie grootvizier Elmas Mehmed Pasja, kwamen om. Zenta, een van de zwaarste nederlagen uit de Osmaanse geschiedenis, maakte de vredestafel onvermijdelijk.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Vredesonderhandelingen van Karlowitz begonnen", "1f395cf3"], "d": ["In de onderhandelingen die onder bemiddeling van Engeland en Nederland begonnen, moest de Osmaanse delegatie voor het eerst het beginsel van 'uti possidetis' (het behoud van het bezit) aanvaarden; de onderhandelingen, die tweeënzeventig zittingen duurden, worden beschouwd als de geboorte van de moderne Osmaanse diplomatie.", "1d41e9e8"]}
});
